    private static readonly string LegalTeacherModelLayerDigest = new('e', 64);

    [Fact]
    public void FileDpoPairStore_PersistsAndReopensTwoQwenAuthoredSidesWithOneBoundPassport()
    {
        var root = Path.Combine(
            Path.GetTempPath(),
            "translation-two-qwen-sides-" + Guid.NewGuid().ToString("N"));
        try
        {
            var bound = DpoPairTrainingContentAuthority.Bind(
                BuildTranslationTwoTeacherSidesPair(
                    OpenWeightTeacherFamily.Qwen));
            Assert.True(bound.IsSuccess, bound.ErrorMessage);
            var store = new FileDpoPairStore(root);

            var added = store.Add(bound.Value!);
            var reopened = store.GetAll();

            Assert.True(added.IsSuccess, added.ErrorMessage);
            Assert.True(reopened.IsSuccess, reopened.ErrorMessage);
            var pair = Assert.Single(reopened.Value!);
            Assert.Equal(
                DPO.Models.DpoPairSideAuthorKind.OpenTeacher,
                pair.ChosenAuthorship!.AuthorKind);
            Assert.Equal(
                DPO.Models.DpoPairSideAuthorKind.OpenTeacher,
                pair.RejectedAuthorship!.AuthorKind);
            Assert.Equal(
                pair.TeacherProvenance,
                pair.ChosenAuthorship.OpenTeacherPassport);
            Assert.Equal(
                pair.TeacherProvenance,
                pair.RejectedAuthorship.OpenTeacherPassport);
        }
        finally
        {
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }

    [Theory]
    [InlineData("mismatched-passport")]
    [InlineData("non-qwen")]
    [InlineData("unbound")]
    public void FileDpoPairStore_RejectsUnsafeTwoTeacherSidePassports(
        string failureMode)
    {
        var root = Path.Combine(
            Path.GetTempPath(),
            "translation-invalid-two-teacher-sides-" +
            Guid.NewGuid().ToString("N"));
        try
        {
            var unbound = BuildTranslationTwoTeacherSidesPair(
                OpenWeightTeacherFamily.Qwen);
            ContinuousLearning.DpoPair pair;
            if (failureMode == "unbound")
            {
                pair = unbound;
            }
            else
            {
                var bound = DpoPairTrainingContentAuthority.Bind(unbound);
                Assert.True(bound.IsSuccess, bound.ErrorMessage);
                pair = bound.Value!;
                if (failureMode == "non-qwen")
                {
                    // Публичный тип не даёт построить OpenTeacher-сторону с
                    // DeepSeek-паспортом. Подмена верхнего паспорта всё же
                    // доказывает, что файловая граница не примет такую пару.
                    pair = pair with
                    {
                        TeacherProvenance = pair.TeacherProvenance! with
                        {
                            Family = OpenWeightTeacherFamily.DeepSeek,
                            ModelId = "deepseek-r1:8b"
                        }
                    };
                }
                else if (failureMode == "mismatched-passport")
                {
                    pair = pair with
                    {
                        RejectedAuthorship =
                            new DpoPairSideAuthorship(
                                DPO.Models.DpoPairSideAuthorKind.OpenTeacher,
                                pair.TeacherProvenance! with
                                {
                                    RequestId = new string('f', 32)
                                })
                    };
                }
            }

            var added = new FileDpoPairStore(root).Add(pair);

            Assert.False(added.IsSuccess);
            Assert.Equal("INVALID_DPO_PAIR", added.ErrorCode);
            Assert.Empty(Directory.Exists(root)
                ? Directory.EnumerateFiles(root, "*.dpo-pair.json")
                : Array.Empty<string>());
        }
        finally
        {
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }

    private static ContinuousLearning.DpoPair
        BuildTranslationTwoTeacherSidesPair(OpenWeightTeacherFamily family)
    {
        var passport = new TrainingTeacherProvenance(
            TrainingTeacherSourceKind.ExternalTeacherOutput,
            family,
            TrainingTeacherAccessMode.LocalHostedOpenWeight,
            TrainingTeacherHostingProvider.Ollama,
            family is OpenWeightTeacherFamily.Qwen
                ? "qwen3.5:9b"
                : "deepseek-r1:8b",
            new string('c', 64),
            TrainingTeacherModelLicense.Apache20,
            ProviderTermsChecked: false,
            ProviderTermsAllowTraining: false,
            ClosedProprietaryModel: false,
            TeacherOutputUsedForTraining: true,
            new string('a', 32),
            InvocationCount: 1)
        {
            ModelArtifactDigestKind =
                LegalTrainingTeacherAdmissionAuthority
                    .OllamaModelLayerSha256DigestKind,
            ModelArtifactDigest = new string('d', 64)
        };
        return new ContinuousLearning.DpoPair(
            "Translate the input.",
            "open teacher good answer",
            "open teacher weaker answer",
            "translation-domain",
            DateTimeOffset.UnixEpoch)
        {
            TeacherProvenance = passport,
            GovernanceDecision = new TrainingDataGovernanceDecision(
                licenseAccepted: true,
                isQuarantined: false,
                evidenceRefs: ["sha256:" + new string('e', 64)]),
            ChosenAuthorship = new DpoPairSideAuthorship(
                DPO.Models.DpoPairSideAuthorKind.OpenTeacher,
                passport),
            RejectedAuthorship = new DpoPairSideAuthorship(
                DPO.Models.DpoPairSideAuthorKind.OpenTeacher,
                passport)
        };
    }

    [Fact]
    public void DpoCustodyFileDispositionContracts_UseOneByteNativeBoolean()
    {
        var trainerDisposition = typeof(DpoTrainer).GetNestedType(
            "FileDispositionInformation",
            BindingFlags.NonPublic);
        var bridgeDisposition =
            typeof(DesignConversionDpoPolicyCheckpointBridge).GetNestedType(
                "ScratchFileDispositionInfo",
                BindingFlags.NonPublic);

        Assert.NotNull(trainerDisposition);
        Assert.NotNull(bridgeDisposition);
        Assert.Equal(1, Marshal.SizeOf(trainerDisposition!));
        Assert.Equal(1, Marshal.SizeOf(bridgeDisposition!));
        Assert.Equal(
            typeof(byte),
            trainerDisposition.GetField(
                "DeleteFile",
                BindingFlags.Instance | BindingFlags.NonPublic)!.FieldType);
        Assert.Equal(
            typeof(byte),
            bridgeDisposition.GetField(
                "DeleteFile",
                BindingFlags.Instance | BindingFlags.NonPublic)!.FieldType);
    }

    private static bool CreateHardLinkForPublicationLease(
        string newFileName,
        string existingFileName,
        IntPtr securityAttributes)
    {
        if (OperatingSystem.IsWindows())
        {
            return CreateHardLinkWindowsForPublicationLease(
                newFileName,
                existingFileName,
                securityAttributes);
        }

        if (OperatingSystem.IsLinux())
            return CreateHardLinkLinuxForPublicationLease(existingFileName, newFileName) == 0;

        return false;
    }

    private static DesignConversionDeterministicMutationLease
        AcquireLocalPromotionJournalMutationLeaseForTesting(
            string root,
            string mutationLeaf)
        => DesignConversionDeterministicMutationLock.AcquireForTesting(
            Path.Combine(root, mutationLeaf));

    [DllImport("kernel32.dll", EntryPoint = "CreateHardLinkW", CharSet = CharSet.Unicode,
        SetLastError = true)]
    [return: MarshalAs(UnmanagedType.Bool)]
    private static extern bool CreateHardLinkWindowsForPublicationLease(
        string newFileName,
        string existingFileName,
        IntPtr securityAttributes);

    [DllImport("libc", EntryPoint = "link", SetLastError = true)]
    private static extern int CreateHardLinkLinuxForPublicationLease(
        [MarshalAs(UnmanagedType.LPUTF8Str)] string existingPath,
        [MarshalAs(UnmanagedType.LPUTF8Str)] string newPath);

    [DllImport("libc", EntryPoint = "flock", SetLastError = true)]
    private static extern int FlockLinuxForReservationTest(
        int fileDescriptor,
        int operation);

    private const int LinuxFlockExclusiveForTest = 0x02;
    private const int LinuxFlockNonBlockingForTest = 0x04;
    private const int LinuxFlockUnlockForTest = 0x08;

    [Fact]
