    [Theory]
    [InlineData("dpo_bridge:standalone:lora_attach", true)]
    [InlineData("dpo_bridge:standalone:dpo_step:1", false)]
    public async Task DpoPolicyBridge_RevocationAtTrainerMutationBoundariesBlocksUnauthorizedArtifacts(
        string revokedBoundary,
        bool trainerConstructionMustBeBlocked)
    {
        var root = Path.Combine(Path.GetTempPath(), $"bridge-trainer-boundary-{Guid.NewGuid():N}");
        var output = Path.Combine(root, "training");
        var runtimePath = Path.Combine(root, "runtime", "runtime.json");
        const string runId = "revoked-trainer-boundary";
        var policyCheckpointDirectory = Path.Combine(
            output,
            $"{runId}-dpo-policy-checkpoints");
        var authority = CreateEvaluatedLegalTeacherCapability();
        var provider = new DesignConversionDpoPolicyBaseTestProvider();
        var mutationBoundaries = new List<string>();
        var priorMutationObserver =
            DesignConversionDpoPolicyCheckpointBridge.MutationBoundaryObserverForTesting;
        try
        {
            DesignConversionDpoPolicyCheckpointBridge.MutationBoundaryObserverForTesting =
                boundary =>
                {
                    mutationBoundaries.Add(boundary);
                    if (boundary == revokedBoundary)
                        _ = authority.BeginRevocation();
                };

            var result = await DesignConversionDpoPolicyCheckpointBridge.ExecuteAndConvertAsync(
                authority,
                [
                    BuildTrainingRecord("revoked-trainer-improver", DesignConversionDpoUnits.ImproverUnit, 0.99),
                    BuildTrainingRecord("revoked-trainer-critic", DesignConversionDpoUnits.CriticUnit, 0.98)
                ],
                output,
                runId,
                runtimePath,
                provider,
                new DesignConversionDpoPolicyCheckpointBridgeOptions(2, 1));

            Assert.False(result.IsSuccess);
            Assert.Equal(
                ServerOwnedLegalTrainingTeacherAdmissionAuthority.AdmissionRevokedErrorCode,
                result.ErrorCode);
            Assert.Contains(revokedBoundary, mutationBoundaries);
            Assert.Equal(1, provider.InvocationCount);
            Assert.False(File.Exists(runtimePath));
            if (trainerConstructionMustBeBlocked)
                Assert.False(Directory.Exists(policyCheckpointDirectory));
            if (Directory.Exists(policyCheckpointDirectory))
            {
                Assert.Empty(Directory.EnumerateFiles(
                    policyCheckpointDirectory,
                    "*",
                    SearchOption.AllDirectories));
            }
        }
        finally
        {
            DesignConversionDpoPolicyCheckpointBridge.MutationBoundaryObserverForTesting =
                priorMutationObserver;
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public async Task DpoPolicyBridge_TerminalResultRevocationRollsBackProvisionalPublication(
        bool priorRuntimeExists)
    {
        var root = Path.Combine(Path.GetTempPath(), $"bridge-terminal-result-{Guid.NewGuid():N}");
        var output = Path.Combine(root, "training");
        var runtimePath = Path.Combine(root, "runtime", "runtime.json");
        const string runId = "revoked-terminal-result";
        var policyCheckpointDirectory = Path.Combine(
            output,
            $"{runId}-dpo-policy-checkpoints");
        var authority = CreateEvaluatedLegalTeacherCapability();
        var provider = new DesignConversionDpoPolicyBaseTestProvider();
        var stages = new List<string>();
        byte[] priorRuntimePayload = [
            0x70, 0x72, 0x69, 0x6f, 0x72, 0x2d, 0x72, 0x75,
            0x6e, 0x74, 0x69, 0x6d, 0x65, 0x2d, 0x70, 0x61,
            0x79, 0x6c, 0x6f, 0x61, 0x64
        ];
        var priorMutationObserver =
            DesignConversionDpoPolicyCheckpointBridge.MutationBoundaryObserverForTesting;
        var priorRuntimeObserver =
            DesignConversionDpoPolicyCheckpointBridge.RuntimeTransactionStageObserverForTesting;
        try
        {
            if (priorRuntimeExists)
            {
                Directory.CreateDirectory(Path.GetDirectoryName(runtimePath)!);
                await File.WriteAllBytesAsync(runtimePath, priorRuntimePayload);
            }

            DesignConversionDpoPolicyCheckpointBridge.RuntimeTransactionStageObserverForTesting =
                stages.Add;
            DesignConversionDpoPolicyCheckpointBridge.MutationBoundaryObserverForTesting =
                boundary =>
                {
                    if (boundary == "dpo_bridge:standalone:terminal_publication_result")
                        _ = authority.BeginRevocation();
                };

            var result = await DesignConversionDpoPolicyCheckpointBridge.ExecuteAndConvertAsync(
                authority,
                [
                    BuildTrainingRecord("revoked-terminal-improver", DesignConversionDpoUnits.ImproverUnit, 0.99),
                    BuildTrainingRecord("revoked-terminal-critic", DesignConversionDpoUnits.CriticUnit, 0.98)
                ],
                output,
                runId,
                runtimePath,
                provider,
                new DesignConversionDpoPolicyCheckpointBridgeOptions(2, 1));

            Assert.False(result.IsSuccess);
            Assert.Equal(
                ServerOwnedLegalTrainingTeacherAdmissionAuthority.AdmissionRevokedErrorCode,
                result.ErrorCode);
            Assert.DoesNotContain("before-runtime-commit", stages);
            Assert.DoesNotContain("mutex-release-failed", stages);
            if (priorRuntimeExists)
                Assert.Equal(priorRuntimePayload, await File.ReadAllBytesAsync(runtimePath));
            else
                Assert.False(File.Exists(runtimePath));

            var runtimeDirectory = Path.GetDirectoryName(runtimePath)!;
            if (Directory.Exists(runtimeDirectory))
            {
                var remainingRuntimeFiles = Directory.EnumerateFiles(
                        runtimeDirectory,
                        "*",
                        SearchOption.AllDirectories)
                    .Select(Path.GetFullPath)
                    .ToArray();
                if (priorRuntimeExists)
                    Assert.Equal([Path.GetFullPath(runtimePath)], remainingRuntimeFiles);
                else
                    Assert.Empty(remainingRuntimeFiles);
            }
            if (Directory.Exists(policyCheckpointDirectory))
            {
                Assert.Empty(Directory.EnumerateFiles(
                    policyCheckpointDirectory,
                    "*",
                    SearchOption.AllDirectories));
            }
        }
        finally
        {
            DesignConversionDpoPolicyCheckpointBridge.MutationBoundaryObserverForTesting =
                priorMutationObserver;
            DesignConversionDpoPolicyCheckpointBridge.RuntimeTransactionStageObserverForTesting =
                priorRuntimeObserver;
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }

    [Fact]
    public async Task DpoPolicyBridge_TerminalResultRollbackPreservesForeignHardLinkReplacement()
    {
        var root = Path.Combine(Path.GetTempPath(), $"bridge-terminal-hardlink-{Guid.NewGuid():N}");
        var output = Path.Combine(root, "training");
        var runtimeDirectory = Path.Combine(root, "runtime");
        var runtimePath = Path.Combine(runtimeDirectory, "runtime.json");
        var policyCheckpointDirectory = Path.Combine(
            output,
            "terminal-hardlink-dpo-policy-checkpoints");
        var sourcePolicyPath = Path.Combine(
            policyCheckpointDirectory,
            DpoTrainer.BuildPolicyCheckpointFileName(1));
        var siblingPath = Path.Combine(
            runtimeDirectory,
            DpoTrainer.BuildPolicyCheckpointFileName(1));
        var foreignBackingPath = Path.Combine(root, "foreign-policy-backing.bin");
        byte[] priorRuntimePayload = [0x70, 0x72, 0x69, 0x6f, 0x72];
        var authority = CreateEvaluatedLegalTeacherCapability();
        var stages = new List<string>();
        var priorMutationObserver =
            DesignConversionDpoPolicyCheckpointBridge.MutationBoundaryObserverForTesting;
        var priorRuntimeObserver =
            DesignConversionDpoPolicyCheckpointBridge.RuntimeTransactionStageObserverForTesting;
        try
        {
            Directory.CreateDirectory(runtimeDirectory);
            await File.WriteAllBytesAsync(runtimePath, priorRuntimePayload);
            DesignConversionDpoPolicyCheckpointBridge.RuntimeTransactionStageObserverForTesting =
                stages.Add;
            DesignConversionDpoPolicyCheckpointBridge.MutationBoundaryObserverForTesting =
                boundary =>
                {
                    if (boundary != "dpo_bridge:standalone:terminal_publication_result")
                        return;
                    File.Copy(sourcePolicyPath, foreignBackingPath, overwrite: false);
                    File.Delete(siblingPath);
                    Assert.True(CreateHardLinkForPublicationLease(
                        siblingPath,
                        foreignBackingPath,
                        IntPtr.Zero));
                    _ = authority.BeginRevocation();
                };

            var result = await DesignConversionDpoPolicyCheckpointBridge.ExecuteAndConvertAsync(
                authority,
                [
                    BuildTrainingRecord("terminal-hardlink-improver", DesignConversionDpoUnits.ImproverUnit, 0.99),
                    BuildTrainingRecord("terminal-hardlink-critic", DesignConversionDpoUnits.CriticUnit, 0.98)
                ],
                output,
                "terminal-hardlink",
                runtimePath,
                new DesignConversionDpoPolicyBaseTestProvider(),
                new DesignConversionDpoPolicyCheckpointBridgeOptions(2, 1));

            Assert.False(result.IsSuccess);
            Assert.Equal(
                DesignConversionDpoRuntimeCheckpointPublisher.PublicationStateUncertainErrorCode,
                result.ErrorCode);
            Assert.Equal(priorRuntimePayload, await File.ReadAllBytesAsync(runtimePath));
            Assert.True(File.Exists(foreignBackingPath));
            Assert.True(File.Exists(siblingPath));
            Assert.Equal(
                await File.ReadAllBytesAsync(foreignBackingPath),
                await File.ReadAllBytesAsync(siblingPath));
            Assert.False(File.Exists(sourcePolicyPath));
            Assert.DoesNotContain("before-runtime-commit", stages);
            Assert.DoesNotContain("mutex-release-failed", stages);
            Assert.Empty(Directory.EnumerateFiles(runtimeDirectory, "*.tmp", SearchOption.TopDirectoryOnly));
        }
        finally
        {
            DesignConversionDpoPolicyCheckpointBridge.MutationBoundaryObserverForTesting =
                priorMutationObserver;
            DesignConversionDpoPolicyCheckpointBridge.RuntimeTransactionStageObserverForTesting =
                priorRuntimeObserver;
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }

    [DesignConversionDpoStorageLinuxFact]
    public async Task DpoPolicyBridge_TerminalResultRollbackPreservesForeignSourceReplacementAndCleansOwnedLeaves()
    {
        var root = Path.Combine(Path.GetTempPath(), $"bridge-terminal-source-replacement-{Guid.NewGuid():N}");
        var output = Path.Combine(root, "training");
        var runtimeDirectory = Path.Combine(root, "runtime");
        var runtimePath = Path.Combine(runtimeDirectory, "runtime.json");
        const string runId = "terminal-source-replacement";
        var sourcePolicyLeaf = DpoTrainer.BuildPolicyCheckpointFileName(1);
        var policyCheckpointDirectory = Path.Combine(
            output,
            $"{runId}-dpo-policy-checkpoints");
        var sourcePolicyPath = Path.Combine(policyCheckpointDirectory, sourcePolicyLeaf);
        var foreignBackingPath = Path.Combine(root, "foreign-source-backing.bin");
        var authority = CreateEvaluatedLegalTeacherCapability();
        DesignConversionFileIdentity? originalSourceIdentity = null;
        DesignConversionFileIdentity? foreignSourceIdentity = null;
        var priorMutationObserver =
            DesignConversionDpoPolicyCheckpointBridge.MutationBoundaryObserverForTesting;
        try
        {
            Directory.CreateDirectory(runtimeDirectory);
            DesignConversionDpoPolicyCheckpointBridge.MutationBoundaryObserverForTesting =
                boundary =>
                {
                    if (boundary != "dpo_bridge:standalone:terminal_publication_result")
                        return;

                    using (var sourceDirectory =
                           DesignConversionHandleBoundDirectory.AcquireExisting(
                               policyCheckpointDirectory,
                               beforeIo: null))
                    using (var heldSource = sourceDirectory.TryOpenExisting(
                               sourcePolicyLeaf,
                               FileShare.Read | FileShare.Write | FileShare.Delete,
                               writeThrough: false))
                    {
                        Assert.NotNull(heldSource);
                        originalSourceIdentity = sourceDirectory.GetIdentity(
                            heldSource!,
                            sourcePolicyLeaf);
                    }

                    var sourcePayload = File.ReadAllBytes(sourcePolicyPath);
                    File.WriteAllBytes(foreignBackingPath, sourcePayload);
                    File.Delete(sourcePolicyPath);
                    // Подмена с теми же байтами не должна пройти как наш файл:
                    // мост должен удалить только прежний подтверждённый файл
                    // запуска и оставить чужой файл, занявший то же имя.
                    File.WriteAllBytes(sourcePolicyPath, sourcePayload);

                    using (var replacementDirectory =
                           DesignConversionHandleBoundDirectory.AcquireExisting(
                               policyCheckpointDirectory,
                               beforeIo: null))
                    using (var heldReplacement = replacementDirectory.TryOpenExisting(
                               sourcePolicyLeaf,
                               FileShare.Read | FileShare.Write | FileShare.Delete,
                               writeThrough: false))
                    {
                        Assert.NotNull(heldReplacement);
                        foreignSourceIdentity = replacementDirectory.GetIdentity(
                            heldReplacement!,
                            sourcePolicyLeaf);
                    }
                    Assert.NotNull(originalSourceIdentity);
                    Assert.NotNull(foreignSourceIdentity);
                    Assert.NotEqual(originalSourceIdentity.Value, foreignSourceIdentity.Value);
                    _ = authority.BeginRevocation();
                };

            var result = await DesignConversionDpoPolicyCheckpointBridge.ExecuteAndConvertAsync(
                authority,
                [
                    BuildTrainingRecord("terminal-source-replacement-improver", DesignConversionDpoUnits.ImproverUnit, 0.99),
                    BuildTrainingRecord("terminal-source-replacement-critic", DesignConversionDpoUnits.CriticUnit, 0.98)
                ],
                output,
                runId,
                runtimePath,
                new DesignConversionDpoPolicyBaseTestProvider(),
                new DesignConversionDpoPolicyCheckpointBridgeOptions(2, 1));

            Assert.False(result.IsSuccess);
            Assert.Equal(
                ServerOwnedLegalTrainingTeacherAdmissionAuthority.AdmissionRevokedErrorCode,
                result.ErrorCode);
            Assert.True(File.Exists(sourcePolicyPath));
            Assert.Equal(
                await File.ReadAllBytesAsync(foreignBackingPath),
                await File.ReadAllBytesAsync(sourcePolicyPath));
            using (var verificationDirectory =
                   DesignConversionHandleBoundDirectory.AcquireExisting(
                       policyCheckpointDirectory,
                       beforeIo: null))
            using (var heldForeign = verificationDirectory.TryOpenExisting(
                       sourcePolicyLeaf,
                       FileShare.Read | FileShare.Write | FileShare.Delete,
                       writeThrough: false))
            {
                Assert.NotNull(heldForeign);
                Assert.Equal(
                    foreignSourceIdentity,
                    verificationDirectory.GetIdentity(
                        heldForeign!,
                        sourcePolicyLeaf));
            }
            Assert.Equal(
                [Path.GetFullPath(sourcePolicyPath)],
                Directory.EnumerateFiles(
                        policyCheckpointDirectory,
                        "*",
                        SearchOption.AllDirectories)
                    .Select(Path.GetFullPath)
                    .Order(StringComparer.Ordinal)
                    .ToArray());
        }
        finally
        {
            DesignConversionDpoPolicyCheckpointBridge.MutationBoundaryObserverForTesting =
                priorMutationObserver;
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }

