        var authority = CreateEvaluatedLegalTeacherCapability();
        var prepared = await DesignConversionDpoPolicyCheckpointBridge
            .PrepareEvaluatedCompositeExecutionAsync(
                authority,
                partition,
                provider,
                options,
                continuationRequest: null,
                useContinuation: false,
                CancellationToken.None);
        Assert.True(prepared.IsSuccess, prepared.ErrorMessage);
        Assert.NotNull(prepared.Value);
        Assert.True(DesignConversionDpoConsumedPartitionProjectionContract.TryCreate(
            partition,
            maximumTrainRecords: 1,
            out var projection));
        Assert.NotNull(projection);
        var acquired = authority.AcquireTrainingLease(
            prepared.Value!.FinalOptimizer.Content,
            prepared.Value.FinalOptimizer.Provenance);
        Assert.True(acquired.IsSuccess, acquired.ErrorMessage);
        var trainingLease = acquired.Value!;
        var reacquisitions = new List<string>();
        var priorLeaseObserver =
            DesignConversionDpoPolicyCheckpointBridge.LeaseAcquisitionObserverForTesting;
        try
        {
            DesignConversionDpoPolicyCheckpointBridge.LeaseAcquisitionObserverForTesting =
                reacquisitions.Add;

