            Assert.True(result.IsSuccess, result.ErrorMessage);
            Assert.Empty(reacquisitions);
            var bridgeLease = Assert.IsType<DesignConversionDpoEvaluatedBridgeLease>(result.Value);
            var livePermit = bridgeLease.AcquireMutationPermit();
            Assert.True(livePermit.IsSuccess, livePermit.ErrorMessage);
            livePermit.Value!.Dispose();
            bridgeLease.Dispose();
            Assert.Equal(
                ServerOwnedLegalTrainingTeacherAdmissionAuthority.AdmissionRevokedErrorCode,
                trainingLease.AcquireMutationPermit().ErrorCode);
        }
        finally
        {
            DesignConversionDpoPolicyCheckpointBridge.LeaseAcquisitionObserverForTesting =
                priorLeaseObserver;
            trainingLease.Dispose();
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }

