                        DesignConversionDpoEvaluatedPackedBatch>(
                        Assert.Single(observation.AdmittedInputs));
                    var observedBatch = Assert.Single(observation.Batches);
                    Assert.Same(observedPacked.VectorBatch, observedBatch);
                    Assert.NotSame(preparedPacked, observedPacked);
                    Assert.NotSame(preparedPacked.VectorBatch, observedBatch);
                    Assert.NotSame(
                        preparedPacked.VectorBatch.Batch.ChosenIds,
                        observedBatch.Batch.ChosenIds);
                    Assert.NotSame(
                        preparedPacked.VectorBatch.Batch.ChosenMask,
                        observedBatch.Batch.ChosenMask);
                    Assert.NotSame(
                        preparedPacked.VectorBatch.Batch.RejectedIds,
                        observedBatch.Batch.RejectedIds);
                    Assert.NotSame(
                        preparedPacked.VectorBatch.Batch.RejectedMask,
                        observedBatch.Batch.RejectedMask);
                    Assert.NotSame(
                        preparedPacked.VectorBatch.TeachingVector,
                        observedBatch.TeachingVector);

                    Assert.Equal(expectedChosenIds, observedBatch.Batch.ChosenIds.Data);
                    Assert.Equal(expectedChosenMask, observedBatch.Batch.ChosenMask.Data);
                    Assert.Equal(expectedRejectedIds, observedBatch.Batch.RejectedIds.Data);
                    Assert.Equal(expectedRejectedMask, observedBatch.Batch.RejectedMask.Data);
                    Assert.Equal(expectedTeachingVector, observedBatch.TeachingVector);

                    if (observations.Count == 1)
                    {
                        firstObservedPacked = observedPacked;
                        firstObservedBatch = observedBatch;
                        Array.Fill(observedBatch.Batch.ChosenIds.Data, 101f);
                        Array.Fill(observedBatch.Batch.ChosenMask.Data, 102f);
                        Array.Fill(observedBatch.Batch.RejectedIds.Data, 103f);
                        Array.Fill(observedBatch.Batch.RejectedMask.Data, 104f);
                        Array.Fill(observedBatch.TeachingVector, 105f);
                    }
                    else
                    {
                        Assert.NotSame(firstObservedPacked, observedPacked);
                        Assert.NotSame(firstObservedBatch, observedBatch);
                        Assert.NotSame(
                            firstObservedBatch!.Batch.ChosenIds.Data,
                            observedBatch.Batch.ChosenIds.Data);
                        Assert.NotSame(
                            firstObservedBatch.TeachingVector,
                            observedBatch.TeachingVector);
                    }
                };

            var result = await DesignConversionDpoPolicyCheckpointBridge
                .ExecutePreparedEvaluatedCompositeWithTransferredLeaseAsync(
                    typed.ParentLease,
                    typed.Binding,
                    prepared.Value,
                    output,
                    "typed-composite-observer-detached",
                    runtimePath);

            Assert.True(result.IsSuccess, result.ErrorMessage);
            using var bridgeLease = result.Value!;
            Assert.Equal(2, bridgeLease.Result.DpoStepCount);
            Assert.Equal(2, observations.Count);
            Assert.False(Path.IsPathRooted(
                bridgeLease.Result.PolicyCheckpointPath));
            Assert.False(Path.IsPathRooted(
                bridgeLease.Result.RuntimeCheckpointPath));
            Assert.Equal(
                Path.GetFileName(bridgeLease.Result.PolicyCheckpointPath),
                bridgeLease.Result.PolicyCheckpointPath);
            Assert.Equal(
                Path.GetFileName(bridgeLease.Result.RuntimeCheckpointPath),
                bridgeLease.Result.RuntimeCheckpointPath);
            Assert.True(File.Exists(Path.Combine(
                output,
                bridgeLease.Result.PolicyCheckpointPath)));
            Assert.True(File.Exists(Path.Combine(
                output,
                bridgeLease.Result.RuntimeCheckpointPath)));
        }
        finally
        {
            DesignConversionDpoPolicyCheckpointBridge
                .OptimizerMutationSinkObserverForTesting = priorSink;
            typed.ParentLease.Dispose();
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }

