    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public async Task EvaluatedResolvedPartitionTransferredLeaseSeam_ValidationAndCancellationDisposeWithoutReacquisition(
        bool cancelBeforeEntry)
    {
        var root = Path.Combine(Path.GetTempPath(), $"evaluated-seam-stop-{Guid.NewGuid():N}");
        var output = Path.Combine(root, "output");
        var runtimePath = Path.Combine(output, "runtime.json");
        var partition = BuildEvaluatedPartitionForTests("evaluated-seam-stop", heldOutCount: 1);
        var provider = new DesignConversionDpoPolicyBaseTestProvider();
        var options = new DesignConversionDpoPolicyCheckpointBridgeOptions(1, 1);
        var authority = CreateEvaluatedLegalTeacherCapability();
        var prepared = await DesignConversionDpoPolicyCheckpointBridge
            .PrepareEvaluatedCompositeExecutionAsync(
                authority,
                partition,
                provider,
                options,
                continuationRequest: null,
                useContinuation: false,
                CancellationToken.None);
        Assert.True(prepared.IsSuccess, prepared.ErrorMessage);
        Assert.NotNull(prepared.Value);
        Assert.True(DesignConversionDpoConsumedPartitionProjectionContract.TryCreate(
            partition,
            maximumTrainRecords: 1,
            out var projection));
        Assert.NotNull(projection);
        var acquired = authority.AcquireTrainingLease(
            prepared.Value!.FinalOptimizer.Content,
            prepared.Value.FinalOptimizer.Provenance);
        Assert.True(acquired.IsSuccess, acquired.ErrorMessage);
        var trainingLease = acquired.Value!;
        using var cancellation = new CancellationTokenSource();
        if (cancelBeforeEntry)
            cancellation.Cancel();
        var reacquisitions = new List<string>();
        var priorLeaseObserver =
            DesignConversionDpoPolicyCheckpointBridge.LeaseAcquisitionObserverForTesting;
        try
        {
            DesignConversionDpoPolicyCheckpointBridge.LeaseAcquisitionObserverForTesting =
                reacquisitions.Add;

            var result = await DesignConversionDpoPolicyCheckpointBridge
                .ExecutePreparedEvaluatedCompositeWithTransferredLeaseAsync(
                    trainingLease,
                    prepared.Value,
                    output,
                    "evaluated-seam-stop",
                    cancelBeforeEntry
                        ? runtimePath
                        : Path.Combine(root, "outside", "runtime.json"),
                    ct: cancellation.Token);

            Assert.False(result.IsSuccess);
            Assert.Equal(
                cancelBeforeEntry
                    ? "CANCELLED"
                    : DesignConversionDpoPolicyCheckpointBridge.EvaluatedPackingInvalidErrorCode,
                result.ErrorCode);
            Assert.Empty(reacquisitions);
            Assert.Equal(
                ServerOwnedLegalTrainingTeacherAdmissionAuthority.AdmissionRevokedErrorCode,
                trainingLease.AcquireMutationPermit().ErrorCode);
        }
        finally
        {
            DesignConversionDpoPolicyCheckpointBridge.LeaseAcquisitionObserverForTesting =
                priorLeaseObserver;
            trainingLease.Dispose();
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }

