    [Fact]
    public void LocalPromotion_ContinuationOwnedResultPreservesOriginalAndAttemptsOrphanCleanup()
    {
        foreach (var original in new Exception[]
                 {
                     new OperationCanceledException("unrequested-continuation-cancellation"),
                     new OutOfMemoryException("continuation-invocation-fatal")
                 })
        {
            var orphan = new ContinuationOwnedValueProbe(
                new InvalidOperationException("orphan-cleanup-failure"));

            var observed = Record.Exception(() =>
                JsonlDesignConversionLocalArtifactDb.CompleteContinuationOwnedResult(
                    orphan,
                    returnedResult: null,
                    ExceptionDispatchInfo.Capture(original)));

            Assert.Same(original, observed);
            Assert.Equal(1, orphan.DisposeCount);
        }

        var cleanupFatal = new OutOfMemoryException("orphan-cleanup-fatal");
        var cleanupOnly = new ContinuationOwnedValueProbe(cleanupFatal);
        var cleanupObserved = Record.Exception(() =>
            JsonlDesignConversionLocalArtifactDb.CompleteContinuationOwnedResult(
                cleanupOnly,
                returnedResult: null,
                invocationException: null));
        Assert.Same(cleanupFatal, cleanupObserved);
        Assert.Equal(1, cleanupOnly.DisposeCount);

        var adopted = new ContinuationOwnedValueProbe(disposeException: null);
        JsonlDesignConversionLocalArtifactDb.CompleteContinuationOwnedResult(
            adopted,
            OperationResult<ContinuationOwnedValueProbe>.Ok(adopted),
            invocationException: null);
        Assert.Equal(0, adopted.DisposeCount);
        adopted.Dispose();
    }

