            recordsAuthorityRewriteObserverForTesting: () =>
                Interlocked.Increment(ref rewriteCount),
            postEvaluationStateStoreForTesting: countedStateStore);
        try
        {
            var savedRecords = new List<DesignConversionLocalArtifactDbRecord>();
            for (var sourceIndex = 0; sourceIndex < 100; sourceIndex++)
            {
                var critic = ToRuntimePendingCandidate(
                    BuildTrainingRecord($"batch-approval-{sourceIndex}-critic", DesignConversionDpoUnits.CriticUnit, usefulness: 0.93));
                var improver = ToRuntimePendingCandidate(
                    BuildTrainingRecord($"batch-approval-{sourceIndex}-improver", DesignConversionDpoUnits.ImproverUnit, usefulness: 0.94));
                savedRecords.Add(await Save(db, BuildArtifactRecord(
                    $"storage-record-batch-approval-{sourceIndex}",
                    $"job-batch-approval-{sourceIndex}",
                    $"request-batch-approval-{sourceIndex}",
                    DesignConversionVisualQaBoundaryPolicy.TestProviderOnlyMarker,
                    [critic, improver],
                    $"<main>batch approval {sourceIndex}</main>",
                    $".batch-approval-{sourceIndex}{{}}")));
            }

            var requests = savedRecords
                .SelectMany(record => record.DpoCandidates.Select(candidate =>
                    new DesignConversionDpoCandidateApprovalRequest(
                        record.RecordId,
                        candidate.CandidateId,
                        "reviewer:batch-approval",
                        "batch approval regression evidence",
                        DateTimeOffset.UnixEpoch.AddMinutes(170))))
                .ToArray();

            countedStateStore.ResetListCallCount();
            var approval = await db.ApproveRuntimeCreatedDpoCandidatesAsync(requests);
            Assert.Equal(1, countedStateStore.ListCallCount);
            var listed = await db.ListRecordsAsync();
            var index = JsonSerializer.Deserialize<DesignConversionLocalArtifactDbIndex>(
                await File.ReadAllTextAsync(
                    Path.Combine(root, "conversion-results.index.json")),
                DesignConversionCheckpointJsonOptions.Standard);

            Assert.True(approval.IsSuccess, approval.ErrorMessage);
            Assert.Equal(200, approval.Value!.Approvals.Count);
            Assert.Equal(1, Volatile.Read(ref rewriteCount));
            Assert.Equal(bool.TrueString, approval.Value.BoundaryMetadata["approval_batch_atomic"]);
            Assert.Equal("single_authority_rewrite", approval.Value.BoundaryMetadata["approval_batch_storage"]);
            Assert.True(listed.IsSuccess, listed.ErrorMessage);
            Assert.Equal(100, listed.Value!.Count);
            Assert.All(listed.Value!.SelectMany(record => record.DpoCandidates), candidate =>
            {
                Assert.Equal("approved", candidate.TrainingRecord.Provenance.Metadata["approval_status"]);
                Assert.Equal(bool.TrueString, candidate.TrainingRecord.Provenance.Metadata["approved_for_training"]);
            });
            Assert.NotNull(index);
            Assert.Equal(100, index!.RecordCount);
            Assert.Equal(200, index.ApprovedTrainingCandidateCount);
            Assert.Empty(EnumerateRecordsRewriteTempFiles(root));
        }
        finally
        {
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }

