    [Fact]
    public async Task LocalArtifactDb_BatchApprovalCancellationAfterAuthorityReplaceReturnsCommittedSuccessWithDeferredRepair()
    {
        var root = DesignConversionPostEvaluationEligibilityTestFixture
            .CreateHandleBoundTempRoot(
                "local-artifact-db-batch-approval-cancel-after-replace");
        using var cts = new CancellationTokenSource();
        var observeCommittedBoundary = false;
        var db = new JsonlDesignConversionLocalArtifactDb(
            root,
            createTrainingIntakeJournalWaitTaskObserverForTesting: null,
            createTrainingIntakeJournalGateAcquiredCallbackForTesting: null,
            recordsAuthorityReplacedObserverForTesting: () =>
            {
                if (!observeCommittedBoundary)
                    return;

                cts.Cancel();
                throw new IOException(
                    "Simulated derived-index repair failure after authority commit.");
            });
        try
        {
            var candidate = ToRuntimePendingCandidate(
                BuildTrainingRecord(
                    "batch-cancel-after-replace",
                    DesignConversionDpoUnits.CriticUnit,
                    usefulness: 0.93));
            var stored = await Save(db, BuildArtifactRecord(
                "storage-record-batch-cancel-after-replace",
                "job-batch-cancel-after-replace",
                "request-batch-cancel-after-replace",
                DesignConversionVisualQaBoundaryPolicy.TestProviderOnlyMarker,
                [candidate],
                "<main>batch cancel after replace</main>",
                ".batch-cancel-after-replace{}"));
            var authorityPath = Path.Combine(root, "conversion-results.jsonl");
            var authorityBefore = await File.ReadAllBytesAsync(authorityPath);

            observeCommittedBoundary = true;
            var committed = await db.ApproveRuntimeCreatedDpoCandidatesAsync(
            [
                new DesignConversionDpoCandidateApprovalRequest(
                    stored.RecordId,
                    stored.DpoCandidates[0].CandidateId,
                    "reviewer:batch-cancel-after-replace",
                    "caller cancellation after authority commit",
                    DateTimeOffset.UnixEpoch.AddMinutes(174))
            ],
            cts.Token);

            Assert.True(cts.IsCancellationRequested);
            Assert.True(committed.IsSuccess, committed.ErrorMessage);
            Assert.Equal(
                bool.FalseString,
                committed.Value!.BoundaryMetadata[
                    "approval_batch_derived_index_durable"]);
            var approval = Assert.Single(committed.Value.Approvals);
            Assert.Equal(
                bool.TrueString,
                approval.BoundaryMetadata[
                    "local_artifact_db_authority_record_committed"]);
            Assert.Equal(
                "deferred",
                approval.BoundaryMetadata[
                    "local_artifact_db_derived_index_update"]);
            Assert.False(
                authorityBefore.SequenceEqual(
                    await File.ReadAllBytesAsync(authorityPath)));
            Assert.Empty(EnumerateRecordsRewriteTempFiles(root));

            var freshDb = new JsonlDesignConversionLocalArtifactDb(root);
            var listed = await freshDb.ListRecordsAsync(
                new DesignConversionLocalArtifactDbQuery(JobId: stored.JobId));
            Assert.True(listed.IsSuccess, listed.ErrorMessage);
            var approvedCandidate = Assert.Single(
                Assert.Single(listed.Value!).DpoCandidates);
            Assert.Equal(
                JsonlDesignConversionLocalArtifactDb
                    .RuntimeCandidateReviewApprovedStatus,
                approvedCandidate.TrainingRecord.Provenance.Metadata[
                    "review_status"]);
        }
        finally
        {
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }

