    [Fact]
    public async Task LocalArtifactDb_BatchApprovalMetadataUtf8BoundaryAndInvalidElementsFailBeforeMutation()
    {
        var root = DesignConversionPostEvaluationEligibilityTestFixture
            .CreateHandleBoundTempRoot(
                "local-artifact-db-batch-approval-metadata-boundary");
        var rewriteCount = 0;
        var db = new JsonlDesignConversionLocalArtifactDb(
            root,
            createTrainingIntakeJournalWaitTaskObserverForTesting: null,
            createTrainingIntakeJournalGateAcquiredCallbackForTesting: null,
            recordsAuthorityRewriteObserverForTesting: () =>
                Interlocked.Increment(ref rewriteCount));
        try
        {
            var candidates = new[]
            {
                ToRuntimePendingCandidate(BuildTrainingRecord(
                    "batch-metadata-at-limit",
                    DesignConversionDpoUnits.CriticUnit,
                    usefulness: 0.93)),
                ToRuntimePendingCandidate(BuildTrainingRecord(
                    "batch-metadata-over-limit",
                    DesignConversionDpoUnits.ImproverUnit,
                    usefulness: 0.94)),
                ToRuntimePendingCandidate(BuildTrainingRecord(
                    "batch-metadata-unicode-over-limit",
                    DesignConversionDpoUnits.CriticUnit,
                    usefulness: 0.92))
            };
            var stored = await Save(db, BuildArtifactRecord(
                "storage-record-batch-metadata-boundary",
                "job-batch-metadata-boundary",
                "request-batch-metadata-boundary",
                DesignConversionVisualQaBoundaryPolicy.TestProviderOnlyMarker,
                candidates,
                "<main>batch metadata boundary</main>",
                ".batch-metadata-boundary{}"));
            var approvedAtUtc = DateTimeOffset.UnixEpoch.AddMinutes(175);
            var exactCandidate = stored.DpoCandidates[0];
            var exactTemplate = new DesignConversionDpoCandidateApprovalRequest(
                stored.RecordId,
                exactCandidate.CandidateId,
                "reviewer:batch-metadata-boundary",
                string.Empty,
                approvedAtUtc);
            var exactReasonLength = checked(
                JsonlDesignConversionLocalArtifactDb
                    .MaxRuntimeDpoCandidateApprovalBatchMetadataUtf8Bytes -
                SerializedApprovalRequestUtf8Bytes(exactTemplate));
            Assert.True(exactReasonLength > 0);
            var exactRequest = exactTemplate with
            {
                Reason = new string('a', exactReasonLength)
            };
            Assert.Equal(
                JsonlDesignConversionLocalArtifactDb
                    .MaxRuntimeDpoCandidateApprovalBatchMetadataUtf8Bytes,
                SerializedApprovalRequestUtf8Bytes(exactRequest));

            var atLimit = await db.ApproveRuntimeCreatedDpoCandidatesAsync(
                [exactRequest]);
            Assert.True(atLimit.IsSuccess, atLimit.ErrorMessage);
            Assert.Equal(1, Volatile.Read(ref rewriteCount));
            var authorityPath = Path.Combine(root, "conversion-results.jsonl");
            var committedAuthority = await File.ReadAllBytesAsync(authorityPath);

            var overCandidate = stored.DpoCandidates[1];
            var overTemplate = exactTemplate with
            {
                CandidateOrTrainingRecordId = overCandidate.CandidateId
            };
            var overReasonLength = checked(
                JsonlDesignConversionLocalArtifactDb
                    .MaxRuntimeDpoCandidateApprovalBatchMetadataUtf8Bytes -
                SerializedApprovalRequestUtf8Bytes(overTemplate) +
                1);
            var over = await db.ApproveRuntimeCreatedDpoCandidatesAsync(
            [
                overTemplate with
                {
                    Reason = new string('b', overReasonLength)
                }
            ]);
            Assert.False(over.IsSuccess);
            Assert.Equal(
                "DESIGN_CONVERSION_DPO_APPROVAL_BATCH_METADATA_TOO_LARGE",
                over.ErrorCode);
            Assert.Equal(committedAuthority, await File.ReadAllBytesAsync(authorityPath));

            var unicodeCandidate = stored.DpoCandidates[2];
            var unicodeTemplate = exactTemplate with
            {
                CandidateOrTrainingRecordId = unicodeCandidate.CandidateId
            };
            var unicodeCharacterCount = checked(
                JsonlDesignConversionLocalArtifactDb
                    .MaxRuntimeDpoCandidateApprovalBatchMetadataUtf8Bytes -
                SerializedApprovalRequestUtf8Bytes(unicodeTemplate));
            var unicodeRequest = unicodeTemplate with
            {
                Reason = new string('\u0416', unicodeCharacterCount)
            };
            Assert.True(
                SerializedApprovalRequestUtf8Bytes(unicodeRequest) >
                JsonlDesignConversionLocalArtifactDb
                    .MaxRuntimeDpoCandidateApprovalBatchMetadataUtf8Bytes);
            var unicode = await db.ApproveRuntimeCreatedDpoCandidatesAsync(
                [unicodeRequest]);
            Assert.False(unicode.IsSuccess);
            Assert.Equal(
                "DESIGN_CONVERSION_DPO_APPROVAL_BATCH_METADATA_TOO_LARGE",
                unicode.ErrorCode);
            Assert.Equal(committedAuthority, await File.ReadAllBytesAsync(authorityPath));

            var nullElement = await db.ApproveRuntimeCreatedDpoCandidatesAsync(
                [null!]);
            Assert.False(nullElement.IsSuccess);
            Assert.Equal(
                "DESIGN_CONVERSION_DPO_APPROVAL_BATCH_REQUEST_NULL",
                nullElement.ErrorCode);
            Assert.Equal(committedAuthority, await File.ReadAllBytesAsync(authorityPath));
            Assert.Equal(1, Volatile.Read(ref rewriteCount));
            Assert.Empty(EnumerateRecordsRewriteTempFiles(root));
        }
        finally
        {
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }

        static int SerializedApprovalRequestUtf8Bytes(
            DesignConversionDpoCandidateApprovalRequest request)
            => JsonSerializer.SerializeToUtf8Bytes(
                    request,
                    new JsonSerializerOptions(
                        DesignConversionCheckpointJsonOptions.Standard)
                    {
                        WriteIndented = false
                    })
                .Length;
    }

