        Assert.Equal(
            JsonlDesignConversionLocalArtifactDb.TrainingIntakeSchemaVersion,
            fixture.Intake.BoundaryMetadata["schema_version"]);
        var journalPath = Path.Combine(root, "training-intake-requests.jsonl");
        var journal = await File.ReadAllTextAsync(journalPath);
        var unknownSchema = journal.Replace(
            JsonlDesignConversionLocalArtifactDb.TrainingIntakeSchemaVersion,
            "design-conversion-training-intake-v999",
            StringComparison.Ordinal);
        Assert.NotEqual(journal, unknownSchema);
        await File.WriteAllTextAsync(journalPath, unknownSchema);

        var reconstructed = new JsonlDesignConversionLocalArtifactDb(root);
        var listed = await reconstructed.ListTrainingIntakeRequestsAsync();

        Assert.False(listed.IsSuccess);
        Assert.Equal("DESIGN_CONVERSION_TRAINING_INTAKE_SCHEMA_INVALID", listed.ErrorCode);
    }

    [Fact]
    public async Task LocalArtifactDb_PureV1AppendAndIntakeIgnoreUnrelatedCorruptCustodyState()
    {
        var root = Path.Combine(
            Path.GetTempPath(),
            Guid.NewGuid().ToString("N"),
            "local_artifact_db_v1_custody_isolation");
        var committedRoot = Path.Combine(
            root,
            DesignConversionCandidatePayloadCustodyStore.DirectoryName,
            "committed");
        Directory.CreateDirectory(committedRoot);
        var corruptPath = Path.Combine(
            committedRoot,
            new string('a', 64) + ".custody-committed.json");
        var corruptBytes = System.Text.Encoding.UTF8.GetBytes(
            "{\"unrelated\":\"corrupt-custody-state\"}");
        await File.WriteAllBytesAsync(corruptPath, corruptBytes);
        var db = new JsonlDesignConversionLocalArtifactDb(root);

        var fixture = await CreateApprovedRuntimeTrainingIntakeAsync(
            db,
            "v1-custody-isolation");

        Assert.Equal(
            JsonlDesignConversionLocalArtifactDb.TrainingIntakeSchemaVersion,
            fixture.Intake.BoundaryMetadata["schema_version"]);
        Assert.Equal(corruptBytes, await File.ReadAllBytesAsync(corruptPath));
    }

