    [Fact]
    public async Task LocalArtifactDb_RunTrainingIntakeAsync_PersistsApprovedPairsThroughDurableStoreBeforeRunner()
    {
        var root = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString("N"), "training_intake_dpo_pair_store");
        var db = new JsonlDesignConversionLocalArtifactDb(
            root,
            legalTeacherAdmissionAuthority: CreateEvaluatedLegalTeacherCapability());
        var fixture = await CreateOrdinaryApprovedRuntimeTrainingIntakeAsync(
            db,
            "pair-store-normal");
        var api = new DesignConversionDpoUsefulnessApi(db);

        var run = await api.RunTrainingIntakeAsync(
            fixture.Intake.IntakeId,
            Pass157LocalPromotionOptions(
                "pair-store-normal-run",
                BuildPassingMeasurementGateRequest("pair-store-normal-gate")));
        var pairStoreRoot = Path.Combine(
            root,
            JsonlDesignConversionLocalArtifactDb
                .TrainingIntakeDpoPairStoreDirectoryName);
        var store = ContinuousLearningDpoPairStores.CreateFileStore(pairStoreRoot);
        var firstRead = store.GetAll();

        Assert.True(run.IsSuccess, run.ErrorMessage);
        Assert.True(run.Value!.TrainingRunnerInvoked);
        Assert.True(firstRead.IsSuccess, firstRead.ErrorMessage);
        var persistedTrainPair = Assert.Single(firstRead.Value!);
        var (selectedRecord, excludedRecord) =
            ResolvePersistedFixtureRecord(persistedTrainPair, fixture);
        Assert.Equal(
            selectedRecord.TeacherProvenance?.RequestId,
            persistedTrainPair.TeacherProvenance?.RequestId);
        var expectedCustody = Assert.IsType<
            DesignConversionDpoPayloadCustodySecret>(
                selectedRecord.PayloadCustodySecret);
        Assert.Equal(expectedCustody.Prompt, persistedTrainPair.Prompt);
        Assert.Equal(
            expectedCustody.ChosenResponse,
            persistedTrainPair.Chosen);
        Assert.Equal(
            expectedCustody.RejectedResponse,
            persistedTrainPair.Rejected);
        Assert.Equal(
            selectedRecord.TeacherProvenance with
            {
                TrainingContentSha256 = persistedTrainPair
                    .TeacherProvenance!.TrainingContentSha256
            },
            persistedTrainPair.TeacherProvenance);
        Assert.True(persistedTrainPair.GovernanceDecision!.LicenseAccepted);
        Assert.False(persistedTrainPair.GovernanceDecision.IsQuarantined);
        Assert.NotEmpty(persistedTrainPair.GovernanceDecision.EvidenceRefs);
        Assert.Equal(
            selectedRecord.ChosenAuthorKind,
            persistedTrainPair.ChosenAuthorship!.AuthorKind);
        Assert.Equal(
            selectedRecord.RejectedAuthorKind,
            persistedTrainPair.RejectedAuthorship!.AuthorKind);
        Assert.Null(persistedTrainPair.ChosenAuthorship.OpenTeacherPassport);
        Assert.Null(persistedTrainPair.RejectedAuthorship.OpenTeacherPassport);
        using (var prompt = JsonDocument.Parse(persistedTrainPair.Prompt))
        {
            Assert.Equal(
                selectedRecord.UnitId,
                prompt.RootElement.GetProperty("unit_id").GetString());
            Assert.Equal(
                selectedRecord.Provenance.SourceKind.ToLowerInvariant(),
                prompt.RootElement
                    .GetProperty("source")
                    .GetProperty("kind")
                    .GetString());
            var persistedStructurePayload = prompt.RootElement
                .GetProperty("source")
                .GetProperty("structure_payload")
                .GetString();
            Assert.NotNull(persistedStructurePayload);
            using var persistedStructure = JsonDocument.Parse(
                persistedStructurePayload);
            Assert.Equal(
                "design-conversion-runtime-source-structure-v1",
                persistedStructure.RootElement.GetProperty("schema").GetString());
            Assert.Equal(
                new[] { "frame", "candidate" },
                persistedStructure.RootElement.GetProperty("tree")
                    .EnumerateArray()
                    .Select(value => value.GetString()));
            Assert.True(
                persistedStructure.RootElement.GetProperty("redacted").GetBoolean());
            Assert.Equal(
                "[redacted]",
                persistedStructure.RootElement
                    .GetProperty("generated_binding")
                    .GetString());
            Assert.Equal(
                "[redacted]",
                persistedStructure.RootElement
                    .GetProperty("incumbent_binding")
                    .GetString());
            Assert.DoesNotContain(
                selectedRecord.SourceStructurePayload,
                persistedStructurePayload,
                StringComparison.Ordinal);
        }
        Assert.Contains(
            $"\"unit_id\":\"{selectedRecord.UnitId}\"",
            persistedTrainPair.Prompt,
            StringComparison.Ordinal);
        Assert.DoesNotContain(
            firstRead.Value,
            pair => string.Equals(
                pair.TeacherProvenance?.RequestId,
                excludedRecord.TeacherProvenance?.RequestId,
                StringComparison.Ordinal));
        var persistedPairPath = Assert.Single(Directory.EnumerateFiles(
            pairStoreRoot,
            "*.dpo-pair.json",
            SearchOption.TopDirectoryOnly));
        using (var persistedPairDocument = JsonDocument.Parse(
                   File.ReadAllText(persistedPairPath)))
        {
            Assert.Equal(
                5,
                persistedPairDocument.RootElement
                    .GetProperty("schemaVersion")
                    .GetInt32());
            Assert.True(persistedPairDocument.RootElement
                .TryGetProperty("sideAuthorship", out _));
        }

        var replayOptions = Pass157LocalPromotionOptions(
            "pair-store-normal-run",
            BuildPassingMeasurementGateRequest("pair-store-normal-gate"));
        var replay = await api.RunTrainingIntakeAsync(
            fixture.Intake.IntakeId,
            replayOptions);
        var secondRead = store.GetAll();

        Assert.False(replay.IsSuccess);
        Assert.Null(replay.Value);
        Assert.Equal(
            LegalTrainingTeacherAdmissionAuthority.DuplicateRequestIdErrorCode,
            replay.ErrorCode);
        Assert.True(secondRead.IsSuccess, secondRead.ErrorMessage);
        Assert.Single(secondRead.Value!);
        Assert.Equal(
            firstRead.Value.Select(ToComparableDpoPair).OrderBy(value => value, StringComparer.Ordinal).ToArray(),
            secondRead.Value.Select(ToComparableDpoPair).OrderBy(value => value, StringComparer.Ordinal).ToArray());
    }

