    {
        var root = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString("N"), "training_intake_dpo_pair_store_local");
        var setupDb = new JsonlDesignConversionLocalArtifactDb(
            root,
            dpoPolicyBaseProvider: new DesignConversionDpoPolicyBaseTestProvider(),
            legalTeacherAdmissionAuthority: CreateEvaluatedLegalTeacherCapability());
        var fixture = await CreateOrdinaryApprovedRuntimeTrainingIntakeAsync(
            setupDb,
            "pair-store-local");
        var pairStore = new RecordingDpoPairStore();
        IReadOnlyList<DpoPair>? pairsObservedAtRunnerBoundary = null;
        var runnerInvoked = 0;
        var db = new JsonlDesignConversionLocalArtifactDb(
            root,
            createTrainingIntakeJournalWaitTaskObserverForTesting: null,
            createTrainingIntakeJournalGateAcquiredCallbackForTesting: null,
            runTrainingIntakeRunnerInvokedObserverForTesting: () =>
            {
                Interlocked.Increment(ref runnerInvoked);
                pairsObservedAtRunnerBoundary = pairStore.GetAll().Value?.ToArray();
            },
            dpoPolicyBaseProvider: new DesignConversionDpoPolicyBaseTestProvider(),
            legalTeacherAdmissionAuthority: CreateEvaluatedLegalTeacherCapability(),
            trainingIntakeDpoPairStoreForTesting: pairStore);

        var promoted = await DesignConversionTrainingIntakeRouteAdmissionContext
            .RunAsync(
                BuildLocalPromotionAdmission("pair-store-local"),
                () => new DesignConversionDpoUsefulnessApi(db)
                    .RunTrainingIntakeAndPromoteLocalAsync(
                        fixture.Intake.IntakeId,
                        Path.Combine(root, "pair-store-local-promotion"),
                        Pass157LocalPromotionOptions(
                            "pair-store-local-run",
                            BuildPassingMeasurementGateRequest(
                                "pair-store-local-gate"))));
        var finalRead = pairStore.GetAll();

        Assert.True(promoted.IsSuccess, promoted.ErrorMessage);
        Assert.Equal(1, runnerInvoked);
        Assert.NotNull(pairsObservedAtRunnerBoundary);
        var observedPair = Assert.Single(pairsObservedAtRunnerBoundary!);
        var (selectedRecord, excludedRecord) =
            ResolvePersistedFixtureRecord(observedPair, fixture);
        var expectedCustody = Assert.IsType<
            DesignConversionDpoPayloadCustodySecret>(
                selectedRecord.PayloadCustodySecret);
        Assert.Equal(expectedCustody.Prompt, observedPair.Prompt);
        Assert.Equal(expectedCustody.ChosenResponse, observedPair.Chosen);
        Assert.Equal(expectedCustody.RejectedResponse, observedPair.Rejected);
        Assert.Equal(
            selectedRecord.TeacherProvenance?.RequestId,
            observedPair.TeacherProvenance?.RequestId);
        Assert.DoesNotContain(
            pairsObservedAtRunnerBoundary,
            pair => string.Equals(
                pair.TeacherProvenance?.RequestId,
                excludedRecord.TeacherProvenance?.RequestId,
                StringComparison.Ordinal));
        Assert.True(finalRead.IsSuccess, finalRead.ErrorMessage);
        var finalPair = Assert.Single(finalRead.Value!);
        Assert.Equal(expectedCustody.Prompt, finalPair.Prompt);
        Assert.Equal(expectedCustody.ChosenResponse, finalPair.Chosen);
        Assert.Equal(expectedCustody.RejectedResponse, finalPair.Rejected);
        Assert.Equal(
            selectedRecord.TeacherProvenance?.RequestId,
            finalPair.TeacherProvenance?.RequestId);
        Assert.DoesNotContain(
            finalRead.Value,
            pair => string.Equals(
                pair.TeacherProvenance?.RequestId,
                excludedRecord.TeacherProvenance?.RequestId,
                StringComparison.Ordinal));
        Assert.Equal(
            pairsObservedAtRunnerBoundary.Select(ToComparableDpoPair).OrderBy(value => value, StringComparer.Ordinal).ToArray(),
            finalRead.Value.Select(ToComparableDpoPair).OrderBy(value => value, StringComparer.Ordinal).ToArray());
    }

