    [Fact]
    public async Task LocalArtifactDb_RunTrainingIntakeAsync_ExactDualTargetTeacherAggregate_CommitsOneAtomicExternalGroupAndReplaysWithoutSingletons()
    {
        using var corpus = Tests.DesignConversionDpoCorpusAdmissionTests.CreateFixture();
        var root = corpus.Root;
        var intake = await Tests.DesignConversionDpoCorpusAdmissionTests
            .SeedRealTrainingIntakeAsync(corpus);
        var request = new DesignConversionDpoCorpusAdmissionRequest(
            corpus.Pair,
            corpus.Receipt,
            corpus.SourceProof,
            corpus.ObservedAtUtc);
        var options = BuildPassingCallerAdmissionRunOptions(
            "dual-target-atomic-external",
            batchSize: 2);
        var runnerInvoked = 0;
        var db = new JsonlDesignConversionLocalArtifactDb(
            root,
            createTrainingIntakeJournalWaitTaskObserverForTesting: null,
            createTrainingIntakeJournalGateAcquiredCallbackForTesting: null,
            runTrainingIntakeRunnerInvokedObserverForTesting:
                () => Interlocked.Increment(ref runnerInvoked),
            legalTeacherAdmissionAuthority: corpus.LegalAuthority);

        var run = await db.RunTrainingIntakeWithCorpusAdmissionAsync(
            intake.IntakeId,
            request,
            options);

        Assert.True(run.IsSuccess, run.ErrorMessage);
        Assert.True(run.Value!.TrainingRunnerInvoked);
        Assert.Equal(1, runnerInvoked);
        // Windows-корень артефактов и каталог хранилища внутри Linux могут различаться.
        // Проверяем файлы именно того хранилища, которым реально пользовалась база.
        var pairRoot = db.TrainingIntakeDpoPairStoreRootResolutionForTesting
            .PairStoreRootDirectory;
        Assert.Empty(Directory.EnumerateFiles(
            pairRoot,
            "*.dpo-pair.json",
            SearchOption.TopDirectoryOnly));
        Assert.Empty(Directory.EnumerateFiles(
            pairRoot,
            "*.dpo-pair-group.json",
            SearchOption.TopDirectoryOnly));
        Assert.Empty(Directory.EnumerateFiles(
            pairRoot,
            "*.dpo-transaction.json",
            SearchOption.TopDirectoryOnly));
        Assert.Single(Directory.EnumerateFiles(
            pairRoot,
            "*.dpo-external-consumption.json",
            SearchOption.TopDirectoryOnly));
        Assert.True(File.Exists(Path.Combine(
            pairRoot,
            ".dpo-replay-ledger.json")));
        var compacted = ContinuousLearningDpoPairStores
            .CreateFileStore(pairRoot)
            .GetAll();
        Assert.True(compacted.IsSuccess, compacted.ErrorMessage);
        Assert.Empty(compacted.Value!);

        var replay = await db.RunTrainingIntakeWithCorpusAdmissionAsync(
            intake.IntakeId,
            request,
            options);

        Assert.False(replay.IsSuccess);
        Assert.Null(replay.Value);
        Assert.Equal(
            DesignConversionDpoCorpusAdmissionAuthority.ReplayErrorCode,
            replay.ErrorCode);
        Assert.Equal(1, runnerInvoked);
        Assert.Single(Directory.EnumerateFiles(
            pairRoot,
            "*.dpo-external-consumption.json",
            SearchOption.TopDirectoryOnly));
        Assert.Single(File.ReadLines(Path.Combine(
            root,
            "training-intake-runs.jsonl")));
    }

