    [Fact]
    public async Task LocalArtifactDb_RunTrainingIntakeAsync_ExactDualTargetTeacherAggregate_PersistsOnlyOrderedTrainChildrenBeforeCoordinatorFailure()
    {
        using var corpus = Tests.DesignConversionDpoCorpusAdmissionTests.CreateFixture();
        var root = corpus.Root;
        var intake = await Tests.DesignConversionDpoCorpusAdmissionTests
            .SeedRealTrainingIntakeAsync(corpus);
        var request = new DesignConversionDpoCorpusAdmissionRequest(
            corpus.Pair,
            corpus.Receipt,
            corpus.SourceProof,
            corpus.ObservedAtUtc);
        var options = BuildPassingCallerAdmissionRunOptions(
            "dual-target-coordinator-failure",
            batchSize: 2);
        var pairStore =
            new RecordingAtomicGroupThenFailingCoordinatorDpoPairStore();
        var runnerInvoked = 0;
        var db = new JsonlDesignConversionLocalArtifactDb(
            root,
            createTrainingIntakeJournalWaitTaskObserverForTesting: null,
            createTrainingIntakeJournalGateAcquiredCallbackForTesting: null,
            runTrainingIntakeRunnerInvokedObserverForTesting:
                () => Interlocked.Increment(ref runnerInvoked),
            legalTeacherAdmissionAuthority: corpus.LegalAuthority,
            trainingIntakeDpoPairStoreForTesting: pairStore);

        var run = await db.RunTrainingIntakeWithCorpusAdmissionAsync(
            intake.IntakeId,
            request,
            options);

        Assert.False(run.IsSuccess);
        Assert.Equal(
            RecordingAtomicGroupThenFailingCoordinatorDpoPairStore.ErrorCode,
            run.ErrorCode);
        Assert.Equal(0, runnerInvoked);
        Assert.Equal(0, pairStore.AddCallCount);
        Assert.Equal(1, pairStore.AddAtomicGroupCallCount);
        Assert.Equal(1, pairStore.PrepareExternalConsumptionCallCount);
        var group = Assert.IsType<DpoPairAtomicGroupEnvelope>(
            pairStore.Group);
        Assert.Equal(2, group.Children.Count);
        Assert.Equal(
            new[]
            {
                DpoPairAtomicGroupRole.CriticUnit,
                DpoPairAtomicGroupRole.ImproverUnit
            },
            group.Children.Select(static child => child.Role));
        Assert.Equal(
            new[] { 0, 1 },
            group.Children.Select(static child => child.Ordinal));
        Assert.All(group.Children, child => Assert.Equal(
            corpus.Records[0].TeacherProvenance!.RequestId,
            child.Pair.TeacherProvenance!.RequestId));
        Assert.DoesNotContain(group.Children, child => string.Equals(
            child.Pair.TeacherProvenance?.RequestId,
            corpus.WitnessRecords[0].TeacherProvenance?.RequestId,
            StringComparison.Ordinal));
        for (var index = 0; index < group.Children.Count; index++)
        {
            var child = group.Children[index];
            var record = corpus.Records[index];
            Assert.True(record.ChosenAuthorKind.HasValue);
            Assert.True(record.RejectedAuthorKind.HasValue);
            Assert.NotNull(child.Pair.ChosenAuthorship);
            Assert.NotNull(child.Pair.RejectedAuthorship);
            Assert.Equal(
                record.ChosenAuthorKind.Value,
                child.Pair.ChosenAuthorship!.AuthorKind);
            Assert.Equal(
                record.RejectedAuthorKind.Value,
                child.Pair.RejectedAuthorship!.AuthorKind);
            Assert.Equal(
                DPO.Models.DpoPairSideAuthorKind.OpenTeacher,
                child.Pair.ChosenAuthorship.AuthorKind);
            // Atomic intake обязан нести тот же v5 паспорт ребёнка; иначе
            // старое v4-сравнение могло бы спрятать неверную сторону автора.
            Assert.Equal(
                child.Pair.TeacherProvenance,
                child.Pair.ChosenAuthorship.OpenTeacherPassport);
            Assert.Null(child.Pair.RejectedAuthorship.OpenTeacherPassport);
            Assert.Equal(
                FileDpoPairStore.ComputeIdentity(child.Pair, schemaVersion: 5),
                child.PairId);
        }
    }

