    [Fact]
    public async Task LocalArtifactDb_RunTrainingIntakeAndPromoteLocalAsync_ExactDualTargetTeacherAggregate_CommitsExternalConsumptionAndPromotesLocalModel()
    {
        using var aggregate = Tests.DesignConversionDualTargetTeacherAdmissionTests
            .CreateFixture();
        var root = Path.Combine(
            Path.GetTempPath(),
            Guid.NewGuid().ToString("N"),
            "training-intake-dual-target-local-promotion");
        var output = Path.Combine(root, "promotion-output");
        var provider = new DesignConversionDpoPolicyBaseTestProvider();
        var uploader = new CountingLocalOnlyPromotionUploader();
        var promotionRunnerBoundary = 0;
        var runnerInvoked = 0;
        var publicationBoundary = 0;
        var activationInvoked = 0;
        var pathResolveBoundary = 0;
        var beforePreparedAppend = 0;
        var afterPairReservation = 0;
        var afterOutputReservation = 0;
        var observedOperationPhases =
            new List<JsonlDesignConversionLocalArtifactDb.LocalPromotionOperationPhase>();
        using var cancellation = new CancellationTokenSource();
        var db = new JsonlDesignConversionLocalArtifactDb(
            root,
            createTrainingIntakeJournalWaitTaskObserverForTesting: null,
            createTrainingIntakeJournalGateAcquiredCallbackForTesting: null,
            promotionUploader: uploader,
            localReceiptOnlyPromotionAuthority: uploader.Authority,
            runTrainingIntakeLocalPromotionRunnerBeforeInvokeObserverForTesting:
                () => Interlocked.Increment(ref promotionRunnerBoundary),
            runTrainingIntakeRunnerInvokedObserverForTesting:
                () => Interlocked.Increment(ref runnerInvoked),
            runTrainingIntakeLocalPromotionBeforePublicationObserverForTesting:
                () => Interlocked.Increment(ref publicationBoundary),
            runTrainingIntakeLocalPromotionActivationInvokedObserverForTesting:
                () => Interlocked.Increment(ref activationInvoked),
            runTrainingIntakeLocalPromotionBeforePolicyBridgePathResolveObserverForTesting:
                () => Interlocked.Increment(ref pathResolveBoundary),
            dpoPolicyBaseProvider: provider,
            legalTeacherAdmissionAuthority: aggregate.Authority,
            runTrainingIntakeLocalPromotionOperationPhaseObserverForTesting:
                phase => observedOperationPhases.Add(phase),
            runTrainingIntakeLocalPromotionBeforePreparedAppendObserverForTesting:
                () => Interlocked.Increment(ref beforePreparedAppend),
            runTrainingIntakeLocalPromotionAfterPairReservationObserverForTesting:
                () => Interlocked.Increment(ref afterPairReservation),
            runTrainingIntakeLocalPromotionAfterOutputReservationObserverForTesting:
                () => Interlocked.Increment(ref afterOutputReservation));
        var intake = await CreateDualTargetTeacherTrainingIntakeAsync(
            db,
            aggregate,
            "dual-target-local-promotion");
        var options = aggregate.Options with
        {
            RunId = "dual-target-local-promotion-run",
            MeasurementGateRequest = BuildPassingMeasurementGateRequest(
                "dual-target-local-promotion-gate")
        };
        var admission = new Dictionary<string, string>(
            BuildLocalPromotionAdmission("dual-target-local-promotion"),
            StringComparer.Ordinal)
        {
            ["dual_target_teacher_external_consumption_committed"] =
                bool.FalseString,
            ["dual_target_teacher_external_consumption_state"] =
                "ForgedReservedState",
            ["dual_target_teacher_external_server_owned_commit_v1"] =
                bool.FalseString,
            ["dual_target_teacher_external_group_commitment_sha256"] =
                "sha256:" + new string('0', 64),
            ["dual_target_teacher_external_injected_by_admission"] =
                "must_not_escape"
        };

        promotionRunnerBoundary = 0;
        runnerInvoked = 0;
        var promoted = await DesignConversionTrainingIntakeRouteAdmissionContext
            .RunAsync(
                admission,
                () => db.RunTrainingIntakeAndPromoteLocalAsync(
                    intake.IntakeId,
                    output,
                    options,
                    cancellation.Token));

        Assert.True(
            promoted.IsSuccess,
            string.Join(
                "|",
                promoted.ErrorCode,
                promoted.ErrorMessage,
                $"runner-boundary={promotionRunnerBoundary}",
                $"runner-invoked={runnerInvoked}",
                $"path-resolve={pathResolveBoundary}",
                $"publication={publicationBoundary}",
                $"activation={activationInvoked}",
                $"before-prepared-append={beforePreparedAppend}",
                $"after-pair-reservation={afterPairReservation}",
                $"after-output-reservation={afterOutputReservation}",
                $"phases={string.Join(",", observedOperationPhases)}"));
        Assert.False(cancellation.IsCancellationRequested);
        var result = promoted.Value!;
        Assert.True(result.TrainingRun.TrainingRunnerInvoked);
        Assert.True(
            result.LocalPromotionReady,
            string.Join("|", result.BlockReasons));
        Assert.NotNull(result.Publication);
        Assert.NotNull(result.PromotedLocalModel);
        Assert.True(File.Exists(result.PromotedCheckpointPath));
        var runnerEvidence = Assert.IsType<
            DesignConversionTrainingIntakeRunnerEvidence>(
            result.TrainingRun.RunnerEvidence);
        Assert.True(result.TrainingRun.CheckpointMutated);
        Assert.True(runnerEvidence.CheckpointMutationEvidenceProven);
        Assert.True(runnerEvidence.CheckpointContainsRealTrainedWeights);
        Assert.Equal(
            DesignConversionLocalContinueTrainingProbe.VerifiedStatus,
            runnerEvidence.ContinueTrainingStatus);
        Assert.Contains(
            "DESIGN_CONVERSION_LOCAL_CONTINUE_TRAINING_APPENDED_ONE_BATCH",
            runnerEvidence.EvidenceRefs);
        Assert.DoesNotContain(
            "checkpoint_mutation_not_proven",
            result.TrainingRun.BlockReasons);
        Assert.DoesNotContain(
            "checkpoint_mutation_not_proven",
            result.BlockReasons);
        var promotedCheckpointSha256 =
            await ReadSha256Async(result.PromotedCheckpointPath);
        Assert.Equal(
            promotedCheckpointSha256,
            result.PromotedLocalModel!.CheckpointSha256);
        Assert.DoesNotContain(
            "local_promotion_blocked_dual_target_teacher_external_consumption_bridge_contract_unavailable",
            result.BlockReasons);
        Assert.DoesNotContain(
            "DESIGN_CONVERSION_DUAL_TARGET_TEACHER_EXTERNAL_CONSUMPTION_COMMITTED_LOCAL_PROMOTION_BRIDGE_UNAVAILABLE",
            result.EvidenceRefs);
        Assert.Equal(
            bool.TrueString,
            result.BoundaryMetadata[
                "dual_target_teacher_external_consumption_committed"]);
        Assert.Equal(
            "Committed",
            result.BoundaryMetadata[
                "dual_target_teacher_external_consumption_state"]);
        Assert.Equal(
            bool.TrueString,
            result.BoundaryMetadata[
                "dual_target_teacher_external_server_owned_commit_v1"]);
        Assert.NotEqual(
            "sha256:" + new string('0', 64),
            result.BoundaryMetadata[
                "dual_target_teacher_external_group_commitment_sha256"]);
        Assert.DoesNotContain(
            "dual_target_teacher_external_injected_by_admission",
            result.BoundaryMetadata.Keys);
        Assert.Equal(
            bool.FalseString,
            result.BoundaryMetadata[
                "training_intake_promote_local_retry_may_repeat_training"]);
        Assert.Equal(
            bool.TrueString,
            result.BoundaryMetadata[
                "training_intake_promote_local_no_retrain_claimed"]);
        Assert.Matches(
            "^sha256:[0-9a-f]{64}$",
            result.BoundaryMetadata[
                "dual_target_teacher_external_transaction_id_sha256"]);
        Assert.All(
            new[]
            {
                "dual_target_teacher_external_group_commitment_sha256",
                "dual_target_teacher_external_result_sha256",
                "dual_target_teacher_external_checkpoint_sha256",
                "dual_target_teacher_external_manifest_sha256"
            },
            key => Assert.Matches(
                "^(sha256:)?[0-9a-f]{64}$",
                result.BoundaryMetadata[key]));
        var externalCheckpointSha256 = result.BoundaryMetadata[
            "dual_target_teacher_external_checkpoint_sha256"];
        if (externalCheckpointSha256.StartsWith(
                "sha256:",
                StringComparison.Ordinal))
        {
            externalCheckpointSha256 = externalCheckpointSha256[7..];
        }

        Assert.NotEqual(externalCheckpointSha256, promotedCheckpointSha256);
        Assert.Equal(1, provider.InvocationCount + provider.ContinuationInvocationCount);
        Assert.Equal(1, uploader.Count);
        Assert.Equal(2, promotionRunnerBoundary);
        Assert.Equal(2, runnerInvoked);
        Assert.Equal(1, publicationBoundary);
        Assert.Equal(1, activationInvoked);
        Assert.True(Directory.Exists(output));

        var pairRoot = Path.Combine(
            root,
            JsonlDesignConversionLocalArtifactDb
                .TrainingIntakeDpoPairStoreDirectoryName);
        var pairFiles = Directory.EnumerateFiles(
            pairRoot,
            "*.dpo-pair.json",
            SearchOption.TopDirectoryOnly)
            .Order(StringComparer.Ordinal)
            .ToArray();
        Assert.Equal(2, pairFiles.Length);
        var persistedPairRead = new FileDpoPairStore(pairRoot).GetAll();
        Assert.True(persistedPairRead.IsSuccess, persistedPairRead.ErrorMessage);
        var persistedLocalPairs = persistedPairRead.Value!.ToArray();
        Assert.Equal(2, persistedLocalPairs.Length);
        var externalConsumptionPath = Assert.Single(Directory.EnumerateFiles(
            pairRoot,
            "*.dpo-external-consumption.json",
            SearchOption.TopDirectoryOnly));
        using var externalConsumptionDocument = JsonDocument.Parse(
            File.ReadAllText(externalConsumptionPath));
        var externalConsumption = externalConsumptionDocument.RootElement;
        Assert.Equal(
            "teacher:one-real-invocation",
            externalConsumption.GetProperty("requestId").GetString());
        var transactionId = externalConsumption
            .GetProperty("transactionId")
            .GetString()!;
        var groupCommitmentSha256 = externalConsumption
            .GetProperty("groupCommitmentSha256")
            .GetString()!;
        var orderedPairIds = externalConsumption
            .GetProperty("orderedPairIds")
            .EnumerateArray()
            .Select(static value => value.GetString()!)
            .ToArray();
        var orderedContentSha256s = externalConsumption
            .GetProperty("orderedContentSha256s")
            .EnumerateArray()
            .Select(static value => value.GetString()!)
            .ToArray();
        Assert.Equal(2, orderedPairIds.Length);
        Assert.Equal(2, orderedContentSha256s.Length);
        var expectedSourcePairs = aggregate.Records
            .Take(2)
            .Select(record =>
            {
                var projected = DesignConversionTrainingIntakeDpoPairAuthority
                    .Project(record);
                Assert.True(projected.IsSuccess, projected.ErrorMessage);
                return projected.Value!;
            })
            .ToArray();
        var persistedByUnit = persistedLocalPairs.ToDictionary(
            ReadUnitIdFromPersistedPair,
            StringComparer.Ordinal);
        Assert.Equal(
            new[]
            {
                DesignConversionDpoUnits.CriticUnit,
                DesignConversionDpoUnits.ImproverUnit
            },
            persistedByUnit.Keys.Order(StringComparer.Ordinal));
        for (var index = 0; index < expectedSourcePairs.Length; index++)
        {
            var expectedUnit = index == 0
                ? DesignConversionDpoUnits.CriticUnit
                : DesignConversionDpoUnits.ImproverUnit;
            var actual = persistedByUnit[expectedUnit];
            var expected = expectedSourcePairs[index];
            Assert.NotNull(actual.TeacherProvenance);
            var actualTeacher = actual.TeacherProvenance!;
            var actualRequestId = actualTeacher.RequestId;
            var expectedRequestId = string.Concat(
                "committed-dual-target-teacher-child:",
                DesignConversionDpoGenerator.Sha256Ref(string.Join(
                    "\n",
                    [
                        transactionId,
                        groupCommitmentSha256,
                        orderedPairIds[index],
                        orderedContentSha256s[index],
                        index.ToString(CultureInfo.InvariantCulture)
                    ])));

            Assert.Equal(expected.Prompt, actual.Prompt);
            Assert.Equal(expected.Chosen, actual.Chosen);
            Assert.Equal(expected.Rejected, actual.Rejected);
            Assert.Equal(expected.Domain, actual.Domain);
            Assert.Equal(expected.CapturedAt, actual.CapturedAt);
            Assert.Equal(expectedRequestId, actualRequestId);
            Assert.NotEqual(
                expected.TeacherProvenance!.RequestId,
                actualRequestId);
            Assert.Equal(
                orderedContentSha256s[index],
                actualTeacher.TrainingContentSha256);
            Assert.Equal(
                expected.TeacherProvenance with
                {
                    RequestId = actualRequestId,
                    TrainingContentSha256 =
                        actualTeacher.TrainingContentSha256
                },
                actualTeacher);
            Assert.Equal(
                DPO.Models.DpoPairSideAuthorKind.OpenTeacher,
                actual.ChosenAuthorship!.AuthorKind);
            Assert.Equal(
                DPO.Models.DpoPairSideAuthorKind.LocalModel,
                actual.RejectedAuthorship!.AuthorKind);
            Assert.Equal(
                actualTeacher,
                actual.ChosenAuthorship.OpenTeacherPassport);
            Assert.Null(actual.RejectedAuthorship.OpenTeacherPassport);
            Assert.True(actual.GovernanceDecision!.LicenseAccepted);
            Assert.False(actual.GovernanceDecision.IsQuarantined);
            Assert.NotEmpty(actual.GovernanceDecision.EvidenceRefs);
            Assert.Contains(
                pairFiles,
                path => string.Equals(
                    Path.GetFileName(path),
                    FileDpoPairStore.ComputeIdentity(
                        actual,
                        schemaVersion: 5) + ".dpo-pair.json",
                    StringComparison.Ordinal));
        }
        foreach (var pairFile in pairFiles)
        {
            using var pairDocument = JsonDocument.Parse(File.ReadAllText(pairFile));
            Assert.Equal(
                5,
                pairDocument.RootElement
                    .GetProperty("schemaVersion")
                    .GetInt32());
            Assert.True(pairDocument.RootElement.TryGetProperty(
                "sideAuthorship",
                out _));
        }
        var journalPath = Path.Combine(
            root,
            "training-intake-local-promotions.jsonl");
        var persisted = JsonSerializer.Deserialize<
            DesignConversionTrainingIntakeLocalPromotionResult>(
                Assert.Single(File.ReadLines(journalPath)),
                DesignConversionCheckpointJsonOptions.Standard);
        Assert.NotNull(persisted);
        Assert.Equal(
            bool.TrueString,
            persisted.BoundaryMetadata[
                "dual_target_teacher_external_consumption_committed"]);
        Assert.Equal(
            bool.TrueString,
            persisted.BoundaryMetadata[
                "dual_target_teacher_external_server_owned_commit_v1"]);
        Assert.Equal(
            "Committed",
            persisted.BoundaryMetadata[
                "dual_target_teacher_external_consumption_state"]);
        Assert.Equal(
            bool.TrueString,
            persisted.BoundaryMetadata["local_promotion_ready"]);
        Assert.Equal(
            "committed_store_minted_child_transfer_to_composite_bridge",
            persisted.BoundaryMetadata[
                "dual_target_teacher_external_local_promotion_bridge_contract"]);
        Assert.NotEqual(
            "sha256:" + new string('0', 64),
            persisted.BoundaryMetadata[
                "dual_target_teacher_external_group_commitment_sha256"]);
        Assert.DoesNotContain(
            "dual_target_teacher_external_injected_by_admission",
            persisted.BoundaryMetadata.Keys);
        var journalBeforeReplay = await File.ReadAllBytesAsync(journalPath);
        Assert.Single(File.ReadLines(journalPath));
        var pairBytesBeforeReplay = await ReadFileSha256SnapshotAsync(pairRoot);

        var replay = await DesignConversionTrainingIntakeRouteAdmissionContext
            .RunAsync(
                admission,
                () => db.RunTrainingIntakeAndPromoteLocalAsync(
                    intake.IntakeId,
                    output,
                    options));

        Assert.True(replay.IsSuccess, replay.ErrorMessage);
        Assert.True(replay.Value!.LocalPromotionReady);
        Assert.Equal(
            bool.TrueString,
            replay.Value.BoundaryMetadata[
                "training_intake_idempotency_replay_hit"]);
        Assert.Equal(
            bool.TrueString,
            replay.Value.BoundaryMetadata[
                "training_intake_promote_local_no_retrain_claimed"]);
        Assert.Equal(journalBeforeReplay, await File.ReadAllBytesAsync(journalPath));
        Assert.Equal(pairBytesBeforeReplay, await ReadFileSha256SnapshotAsync(pairRoot));
        Assert.Equal(1, provider.InvocationCount + provider.ContinuationInvocationCount);
        Assert.Equal(1, uploader.Count);
        Assert.Equal(2, promotionRunnerBoundary);
        Assert.Equal(2, runnerInvoked);
        Assert.Equal(1, publicationBoundary);
        Assert.Equal(1, activationInvoked);
        Assert.True(Directory.Exists(output));
        AssertDoesNotContainRawPrivatePayload(
            JsonSerializer.Serialize(
                replay.Value,
                DesignConversionCheckpointJsonOptions.Standard));

        static string ReadUnitIdFromPersistedPair(ContinuousLearning.DpoPair pair)
        {
            using var promptDocument = JsonDocument.Parse(pair.Prompt);
            return promptDocument.RootElement
                .GetProperty("unit_id")
                .GetString()!;
        }
    }

    [Fact]
    public async Task LocalArtifactDb_RunTrainingIntakeAndPromoteLocalAsync_ExactDualTargetTeacherAggregate_RejectsLateHeldOutMutationBeforePublication()
    {
        using var aggregate = Tests.DesignConversionDualTargetTeacherAdmissionTests
            .CreateFixture();
        var root = Path.Combine(
            Path.GetTempPath(),
            Guid.NewGuid().ToString("N"),
            "training-intake-dual-target-late-heldout-mutation");
        var output = Path.Combine(root, "promotion-output");
        try
        {
        var provider = new DesignConversionDpoPolicyBaseTestProvider();
        var uploader = new CountingLocalOnlyPromotionUploader();
        var runnerInvoked = 0;
        var publicationBoundary = 0;
        var activationInvoked = 0;
        var mutateFreshResolvedRecords = 0;
        string? heldOutTrainingRecordId = null;
        var db = new JsonlDesignConversionLocalArtifactDb(
            root,
            createTrainingIntakeJournalWaitTaskObserverForTesting: null,
            createTrainingIntakeJournalGateAcquiredCallbackForTesting: null,
            promotionUploader: uploader,
            localReceiptOnlyPromotionAuthority: uploader.Authority,
            runTrainingIntakeRunnerInvokedObserverForTesting:
                () => Interlocked.Increment(ref runnerInvoked),
            runTrainingIntakeLocalPromotionBeforePublicationObserverForTesting:
                () =>
                {
                    Interlocked.Increment(ref publicationBoundary);
                    Interlocked.Exchange(ref mutateFreshResolvedRecords, 1);
                },
            runTrainingIntakeLocalPromotionActivationInvokedObserverForTesting:
                () => Interlocked.Increment(ref activationInvoked),
            dpoPolicyBaseProvider: provider,
            legalTeacherAdmissionAuthority: aggregate.Authority,
            runTrainingIntakeResolvedRecordsTransformerForTesting: records =>
                Volatile.Read(ref mutateFreshResolvedRecords) == 0
                    ? records
                    : MutateHeldOutSourceIdentityForFreshResolution(
                        records,
                        heldOutTrainingRecordId!));
        var intake = await CreateDualTargetTeacherTrainingIntakeAsync(
            db,
            aggregate,
            "dual-target-late-heldout-mutation");
        var heldOutRecord = Assert.Single(
            aggregate.Records,
            record => record.Provenance.Metadata.TryGetValue(
                    "split",
                    out var split) &&
                string.Equals(split, "heldout", StringComparison.Ordinal));
        Assert.Contains(
            intake.CandidateRefs,
            candidateRef => string.Equals(
                candidateRef.TrainingRecordId,
                heldOutRecord.RecordId,
                StringComparison.Ordinal));
        heldOutTrainingRecordId = heldOutRecord.RecordId;
        var options = aggregate.Options with
        {
            RunId = "dual-target-late-heldout-mutation-run",
            MeasurementGateRequest = BuildPassingMeasurementGateRequest(
                "dual-target-late-heldout-mutation-gate")
        };

        var promoted = await DesignConversionTrainingIntakeRouteAdmissionContext
            .RunAsync(
                BuildLocalPromotionAdmission(
                    "dual-target-late-heldout-mutation"),
                () => db.RunTrainingIntakeAndPromoteLocalAsync(
                    intake.IntakeId,
                    output,
                    options));

        Assert.False(promoted.IsSuccess);
        // Поздняя подмена held-out записи находится уже за durable Intent:
        // обучение и store-minted пары могли быть записаны, поэтому это
        // crash-safe indeterminate отказ, а не обычная pre-effect ошибка
        // разбиения train/held-out.
        Assert.Equal(
            "DESIGN_CONVERSION_TRAINING_INTAKE_PROMOTE_LOCAL_INDETERMINATE_AFTER_INTENT",
            promoted.ErrorCode);
        Assert.Equal(2, runnerInvoked);
        Assert.Equal(1, publicationBoundary);
        Assert.Equal(0, activationInvoked);
        Assert.Equal(1, provider.InvocationCount + provider.ContinuationInvocationCount);
        Assert.Equal(0, uploader.Count);
        var promotionsPath = Path.Combine(
            root,
            "training-intake-local-promotions.jsonl");
        Assert.False(File.Exists(promotionsPath));
        var pairRoot = Path.Combine(
            root,
            JsonlDesignConversionLocalArtifactDb
                .TrainingIntakeDpoPairStoreDirectoryName);
        var pairFiles = Directory.EnumerateFiles(
                pairRoot,
                "*.dpo-pair.json",
                SearchOption.TopDirectoryOnly)
            .ToArray();
        // Две пары здесь допустимы: обычный локальный runner уже дважды
        // отработал до поздней свежей held-out проверки; защита должна
        // остановить только публикацию/activation/uploader.
        Assert.Equal(2, pairFiles.Length);
        var externalConsumptionFiles = Directory.EnumerateFiles(
            pairRoot,
            "*.dpo-external-consumption.json",
            SearchOption.TopDirectoryOnly)
            .ToArray();
        Assert.Single(externalConsumptionFiles);

        static IReadOnlyList<DesignConversionDpoTrainingRecord>
            MutateHeldOutSourceIdentityForFreshResolution(
            IReadOnlyList<DesignConversionDpoTrainingRecord> records,
            string heldOutRecordId)
        {
            var mutatedCandidateCount = 0;
            var mutatedRecords = records
                .Select(record =>
                {
                    if (!string.Equals(
                            record.RecordId,
                            heldOutRecordId,
                            StringComparison.Ordinal))
                    {
                        return record;
                    }

                    mutatedCandidateCount++;
                    var metadata = new Dictionary<string, string>(
                        record.Provenance.Metadata,
                        StringComparer.Ordinal)
                    {
                        // После runner меняется только источник held-out
                        // экзамена. Сама запись остаётся валидной: это не
                        // порча payload, а проверка, что публикация сравнит
                        // свежий экзамен с тем, который реально оценивал
                        // checkpoint.
                        ["source_design_id"] =
                            "late-heldout-source-identity-before-publication"
                    };
                    return record with
                    {
                        Provenance = record.Provenance with
                        {
                            Metadata = metadata
                        }
                    };
                })
                .ToArray();
            Assert.Equal(1, mutatedCandidateCount);
            return mutatedRecords;
        }
        }
        finally
        {
            // Без очистки этот temp root копится между повторяемыми WSL-прогонами теста.
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }

    [Fact]
    public async Task LocalArtifactDb_RunTrainingIntakeAndPromoteLocalAsync_ExactDualTargetTeacherPair_InvokesBeforeObserverBeforeExternalRunner()
    {
        using var aggregate = Tests.DesignConversionDualTargetTeacherAdmissionTests
            .CreateFixture();
        var root = Path.Combine(
            Path.GetTempPath(),
            Guid.NewGuid().ToString("N"),
            "training-intake-dual-target-local-promotion-observer-order");
        var output = Path.Combine(root, "promotion-output");
        var runnerBefore = 0;
        var runnerInvoked = 0;
        var runnerEvents = new List<string>();
        var db = new JsonlDesignConversionLocalArtifactDb(
            root,
            createTrainingIntakeJournalWaitTaskObserverForTesting: null,
            createTrainingIntakeJournalGateAcquiredCallbackForTesting: null,
            runTrainingIntakeLocalPromotionRunnerBeforeInvokeObserverForTesting:
                () =>
                {
                    Interlocked.Increment(ref runnerBefore);
                    runnerEvents.Add("before");
                },
            runTrainingIntakeRunnerInvokedObserverForTesting:
                () =>
                {
                    Interlocked.Increment(ref runnerInvoked);
                    runnerEvents.Add("invoked");
                },
            dpoPolicyBaseProvider: new DesignConversionDpoPolicyBaseTestProvider(),
            legalTeacherAdmissionAuthority: aggregate.Authority);
        var intake = await CreateDualTargetTeacherTrainingIntakeAsync(
            db,
            aggregate,
            "dual-target-local-promotion-observer-order");
        var options = aggregate.Options with
        {
            RunId = "dual-target-local-promotion-observer-order-run",
            MeasurementGateRequest = BuildPassingMeasurementGateRequest(
                "dual-target-local-promotion-observer-order-gate")
        };

        runnerBefore = 0;
        runnerInvoked = 0;
        runnerEvents.Clear();
        var promoted = await DesignConversionTrainingIntakeRouteAdmissionContext
            .RunAsync(
                BuildLocalPromotionAdmission(
                    "dual-target-local-promotion-observer-order"),
                () => db.RunTrainingIntakeAndPromoteLocalAsync(
                    intake.IntakeId,
                    output,
                    options));

        Assert.True(promoted.IsSuccess, promoted.ErrorMessage);
        Assert.True(promoted.Value!.LocalPromotionReady);
        // Два запуска защищают новый маршрут: сначала фиксируем внешний эталон, затем отдельно доучиваем локальный чекпоинт.
        Assert.Equal(2, runnerBefore);
        Assert.Equal(2, runnerInvoked);
        Assert.Equal(["before", "invoked", "before", "invoked"], runnerEvents);
        Assert.Equal(
            bool.TrueString,
            promoted.Value.BoundaryMetadata[
                "dual_target_teacher_external_consumption_committed"]);
        Assert.True(Directory.Exists(output));
    }

    [Fact]
    public async Task LocalArtifactDb_RunTrainingIntakeAndPromoteLocalAsync_OrdinaryMetadataCannotForgeExternalAuthorityOrBypassOptimizerContentContract()
    {
        var observedBoundaries = new List<(
            string? ErrorCode,
            int ProviderCount,
            int RunnerCount,
            int MutationCount,
            int PublicationCount,
            int ActivationCount,
            int UploadCount,
            bool OutputExists,
            bool PromotionJournalExists)>();

        foreach (var forgeExternalMetadata in new[] { false, true })
        {
            var lane = forgeExternalMetadata ? "forged" : "clean";
            var root = Path.Combine(
                Path.GetTempPath(),
                Guid.NewGuid().ToString("N"),
                $"training-intake-ordinary-{lane}-metadata");
            var setupDb = new JsonlDesignConversionLocalArtifactDb(root);
            var fixture = await CreateApprovedRuntimeTrainingIntakeAsync(
                setupDb,
                $"ordinary-{lane}-metadata");
            Assert.False(DesignConversionDpoCorpusAdmissionRequirementPolicy
                .RequiresAdmission([fixture.TrainRecord, fixture.HeldOutRecord]));

            var provider = new DesignConversionDpoPolicyBaseTestProvider();
            var uploader = new CountingLocalOnlyPromotionUploader();
            var runnerCount = 0;
            var publicationCount = 0;
            var activationCount = 0;
            var mutationCount = 0;
            var db = new JsonlDesignConversionLocalArtifactDb(
                root,
                createTrainingIntakeJournalWaitTaskObserverForTesting: null,
                createTrainingIntakeJournalGateAcquiredCallbackForTesting: null,
                promotionUploader: uploader,
                runTrainingIntakeRunnerInvokedObserverForTesting: () =>
                    Interlocked.Increment(ref runnerCount),
                runTrainingIntakeLocalPromotionBeforePublicationObserverForTesting: () =>
                    Interlocked.Increment(ref publicationCount),
                runTrainingIntakeLocalPromotionActivationInvokedObserverForTesting: () =>
                    Interlocked.Increment(ref activationCount),
                dpoPolicyBaseProvider: provider,
                legalTeacherAdmissionAuthority: CreateEvaluatedLegalTeacherCapability());
            var output = Path.Combine(root, "promotion-output");
            var options = Pass157LocalPromotionOptions(
                $"ordinary-{lane}-metadata-run",
                BuildPassingMeasurementGateRequest(
                    $"ordinary-{lane}-metadata-gate"));
            var admission = new Dictionary<string, string>(StringComparer.Ordinal)
            {
                ["training_intake_tenant_id_ref"] =
                    $"tenant:ordinary-{lane}-metadata",
                ["training_intake_idempotency_key_ref"] =
                    $"idempotency:ordinary-{lane}-metadata"
            };
            if (forgeExternalMetadata)
            {
                admission["dual_target_teacher_external_consumption_committed"] =
                    bool.TrueString;
                admission["dual_target_teacher_external_consumption_state"] =
                    "Committed";
                admission["dual_target_teacher_external_server_owned_commit_v1"] =
                    bool.TrueString;
                admission["dual_target_teacher_external_group_commitment_sha256"] =
                    "sha256:" + new string('f', 64);
                admission["dual_target_teacher_external_result_sha256"] =
                    "sha256:" + new string('e', 64);
            }

            var filesBefore = (await ReadFileSha256SnapshotAsync(root))
                .Where(static pair => !pair.Key.EndsWith(
                    ".mutation.lock",
                    StringComparison.Ordinal))
                .ToArray();
            var previousMutationObserver = DesignConversionTrainingPipeline
                .OptimizerMutationSinkObserverForTesting;
            DesignConversionTrainingPipeline.OptimizerMutationSinkObserverForTesting =
                _ => Interlocked.Increment(ref mutationCount);
            OperationResult<DesignConversionTrainingIntakeLocalPromotionResult> promoted;
            try
            {
                promoted = await DesignConversionTrainingIntakeRouteAdmissionContext
                    .RunAsync(
                        admission,
                        () => db.RunTrainingIntakeAndPromoteLocalAsync(
                            fixture.Intake.IntakeId,
                            output,
                            options));
            }
            finally
            {
                DesignConversionTrainingPipeline.OptimizerMutationSinkObserverForTesting =
                    previousMutationObserver;
            }

            Assert.False(promoted.IsSuccess);
            Assert.Equal(
                DesignConversionDpoOptimizerSideContract.InvalidErrorCode,
                promoted.ErrorCode);
            Assert.Null(promoted.Value);
            Assert.Equal(0, provider.InvocationCount);
            Assert.Equal(0, Volatile.Read(ref runnerCount));
            Assert.Equal(0, Volatile.Read(ref mutationCount));
            Assert.Equal(0, Volatile.Read(ref publicationCount));
            Assert.Equal(0, Volatile.Read(ref activationCount));
            Assert.Equal(0, uploader.Count);
            Assert.False(Directory.Exists(output));
            var promotionJournalPath = Path.Combine(
                root,
                JsonlDesignConversionLocalArtifactDb
                    .TrainingIntakeLocalPromotionFileName);
            Assert.False(File.Exists(promotionJournalPath));
            Assert.False(File.Exists(Path.Combine(root, "training-intake-runs.jsonl")));
            Assert.Empty(Directory.EnumerateFiles(
                root,
                "*-promoted-checkpoint.json",
                SearchOption.AllDirectories));
            Assert.Empty(Directory.EnumerateFiles(
                root,
                "*promotion*receipt*.json",
                SearchOption.AllDirectories));
            Assert.Empty(Directory.EnumerateDirectories(
                root,
                "*-dpo-policy-checkpoints",
                SearchOption.AllDirectories));
            var pairRoot = Path.Combine(
                root,
                JsonlDesignConversionLocalArtifactDb
                    .TrainingIntakeDpoPairStoreDirectoryName);
            if (Directory.Exists(pairRoot))
            {
                Assert.Empty(Directory.EnumerateFiles(
                    pairRoot,
                    "*.dpo-pair.json",
                    SearchOption.AllDirectories));
                Assert.Empty(Directory.EnumerateFiles(
                    pairRoot,
                    "*.dpo-pair-group.json",
                    SearchOption.AllDirectories));
                Assert.Empty(Directory.EnumerateFiles(
                    pairRoot,
                    "*.dpo-external-consumption.json",
                    SearchOption.AllDirectories));
            }

            var filesAfter = (await ReadFileSha256SnapshotAsync(root))
                .Where(static pair => !pair.Key.EndsWith(
                    ".mutation.lock",
                    StringComparison.Ordinal))
                .ToArray();
            Assert.Equal(filesBefore, filesAfter);
            var publicFailure = JsonSerializer.Serialize(
                new { promoted.ErrorCode, promoted.ErrorMessage },
                DesignConversionCheckpointJsonOptions.Standard);
            AssertDoesNotContainRawPrivatePayload(publicFailure);
            Assert.DoesNotContain(
                "dual_target_teacher_external_",
                publicFailure,
                StringComparison.Ordinal);

            observedBoundaries.Add((
                promoted.ErrorCode,
                provider.InvocationCount,
                Volatile.Read(ref runnerCount),
                Volatile.Read(ref mutationCount),
                Volatile.Read(ref publicationCount),
                Volatile.Read(ref activationCount),
                uploader.Count,
                Directory.Exists(output),
                File.Exists(promotionJournalPath)));
        }

        Assert.Equal(2, observedBoundaries.Count);
        Assert.Equal(observedBoundaries[0], observedBoundaries[1]);
    }

