    [Fact]
    public async Task LocalArtifactDb_RunTrainingIntakeAndPromoteLocalAsync_ExactDualTargetTeacherAggregate_JournalFailureAfterCommitNeverRemutatesOrPublishes()
    {
        using var aggregate = Tests.DesignConversionDualTargetTeacherAdmissionTests
