                    Directory.CreateDirectory(promotionJournalPath);
                },
            legalTeacherAdmissionAuthority: aggregate.Authority);
        var intake = await CreateDualTargetTeacherTrainingIntakeAsync(
            db,
            aggregate,
            "dual-target-local-promotion-journal-failure");
        var options = aggregate.Options with
        {
            RunId = "dual-target-local-promotion-journal-failure-run",
            MeasurementGateRequest = BuildPassingMeasurementGateRequest(
                "dual-target-local-promotion-journal-failure-gate")
        };
        var admission = new Dictionary<string, string>(StringComparer.Ordinal)
        {
            ["training_intake_tenant_id_ref"] =
                "tenant:dual-target-local-promotion-journal-failure",
            ["training_intake_idempotency_key_ref"] =
                "idempotency:dual-target-local-promotion-journal-failure"
        };

        var failed = await DesignConversionTrainingIntakeRouteAdmissionContext
            .RunAsync(
                admission,
                () => db.RunTrainingIntakeAndPromoteLocalAsync(
                    intake.IntakeId,
                    output,
                    options));

        Assert.False(failed.IsSuccess);
        // Папка на месте защищённого построчного журнала в Linux отвергается
        // как нарушение вида файла; Windows получает обычный отказ чтения через
        // системное открытие "только обычный файл". В обоих случаях обработка
        // не доходит до локальной публикации.
        var expectedFailureCode = OperatingSystem.IsWindows()
            ? "DESIGN_CONVERSION_TRAINING_INTAKE_LOCAL_PROMOTION_READ_FAILED"
            : "DESIGN_CONVERSION_TRAINING_INTAKE_PROMOTE_LOCAL_OPERATION_STATE_INVALID";
        Assert.Equal(
            expectedFailureCode,
            failed.ErrorCode);
        Assert.Equal(1, appendBoundary);
        Assert.Equal(0, firstProvider.InvocationCount);
        Assert.False(File.Exists(promotionJournalPath));
        Assert.True(Directory.Exists(promotionJournalPath));
        Assert.False(Directory.Exists(output));
        var pairRoot = Path.Combine(
            root,
            JsonlDesignConversionLocalArtifactDb
                .TrainingIntakeDpoPairStoreDirectoryName);
        Assert.Single(Directory.EnumerateFiles(
            pairRoot,
            "*.dpo-external-consumption.json",
            SearchOption.TopDirectoryOnly));
        var committedBytes = await ReadFileSha256SnapshotAsync(pairRoot);
        Directory.Delete(promotionJournalPath);

        var retryProvider = new DesignConversionDpoPolicyBaseTestProvider();
        var retryRunnerInvoked = 0;
        var retry = await DesignConversionTrainingIntakeRouteAdmissionContext
            .RunAsync(
                admission,
                () => new JsonlDesignConversionLocalArtifactDb(
                        root,
                        createTrainingIntakeJournalWaitTaskObserverForTesting: null,
                        createTrainingIntakeJournalGateAcquiredCallbackForTesting: null,
                        dpoPolicyBaseProvider: retryProvider,
                        // Отдельно проверяем, что повтор не входит в исполнитель
                        // обучения и не добирается до новой мутации.
                        runTrainingIntakeRunnerInvokedObserverForTesting:
                            () => Interlocked.Increment(ref retryRunnerInvoked),
                        legalTeacherAdmissionAuthority: aggregate.Authority)
                    .RunTrainingIntakeAndPromoteLocalAsync(
                        intake.IntakeId,
                        output,
                        options));

        Assert.False(retry.IsSuccess);
        Assert.Equal("DPO_TRANSACTION_RECOVERY_REQUIRED", retry.ErrorCode);
        Assert.Equal(0, retryProvider.InvocationCount);
        Assert.Equal(0, retryRunnerInvoked);
        Assert.Equal(committedBytes, await ReadFileSha256SnapshotAsync(pairRoot));
        Assert.False(File.Exists(promotionJournalPath));
        Assert.False(Directory.Exists(output));
    }

