    [Fact]
    public void LocalArtifactDb_PublicConstructorSurface_PreservesQuotaPrefixesWithOptionalProviderTail()
    {
        var dbType = typeof(JsonlDesignConversionLocalArtifactDb);
        var constructors = dbType.GetConstructors(BindingFlags.Public | BindingFlags.Instance);
        var quotaPrefixTypes = new[]
        {
            new[] { typeof(string), typeof(IDesignConversionPromotionUploader), typeof(long), typeof(long) },
            new[] { typeof(string), typeof(IDesignConversionPromotionUploader), typeof(long), typeof(long), typeof(long) },
            new[] { typeof(string), typeof(IDesignConversionPromotionUploader), typeof(long), typeof(long), typeof(long), typeof(long) }
        };

        foreach (var prefix in quotaPrefixTypes)
        {
            var constructor = Assert.Single(constructors, candidate =>
            {
                var parameters = candidate.GetParameters();
                return parameters.Length == prefix.Length + 1 &&
                       parameters.Take(prefix.Length)
                           .Select(parameter => parameter.ParameterType)
                           .SequenceEqual(prefix) &&
                       parameters[^1].ParameterType == typeof(IDesignConversionDpoPolicyBaseProvider);
            });
            var provider = constructor.GetParameters()[^1];
            Assert.True(provider.HasDefaultValue);
            Assert.Null(provider.DefaultValue);
        }
    }

