                {
                    ["source_manifest_ref"] = "manifest://design-conversion/storage-authority-local-promotion",
                    ["source_kind"] = "figma",
                    ["design_tree_payload_ref"] = "sha256:design-tree-storage-authority-local-promotion",
                    ["original_tree_payload_ref"] = "sha256:original-tree-storage-authority-local-promotion",
                    ["source_artifact:expected_desktop"] = "sha256:storage-authority-expected-design-render",
                    ["source_artifact:actual_desktop"] = "sha256:storage-authority-actual-browser-render"
                }
