            Assert.True(handoff.IsSuccess, handoff.ErrorMessage);
            Assert.Equal(2, handoff.Value!.Rows.Count);

            var intake = await api.CreateTrainingIntakeAsync(
                handoff.Value,
                "architect:storage-authority-local",
                "Storage authority must flow into local promotion DPO policy bridge",
                DateTimeOffset.UnixEpoch.AddMinutes(262));
            Assert.True(intake.IsSuccess, intake.ErrorMessage);
            Assert.Equal(2, intake.Value!.AcceptedCandidateCount);

            var compatibilityProvider = new DesignConversionDpoPolicyBaseTestProvider();
            var compatibilityDb = new JsonlDesignConversionLocalArtifactDb(
                root,
                dpoPolicyBaseProvider: compatibilityProvider);
            var compatibility = await DesignConversionTrainingIntakeRouteAdmissionContext
                .RunAsync(
                    BuildLocalPromotionAdmission(
                        "storage-authority-compatibility-no-authority"),
                    () => new DesignConversionDpoUsefulnessApi(compatibilityDb)
                        .RunTrainingIntakeAndPromoteLocalAsync(
                            intake.Value.IntakeId,
                            Path.Combine(root, "compatibility-no-authority-promotion"),
                            Pass157LocalPromotionOptions(
                                "storage-authority-compatibility-no-authority",
                                BuildPassingMeasurementGateRequest(
                                    "storage-authority-compatibility-no-authority-gate"),
                                new DesignConversionDpoPolicyCheckpointBridgeOptions(
                                    DpoStepCount: 1))));
            Assert.False(compatibility.IsSuccess);
            Assert.Equal(
                LegalTrainingTeacherAdmissionAuthority.ConfigurationRequiredErrorCode,
                compatibility.ErrorCode);
            Assert.Equal(0, compatibilityProvider.InvocationCount);

            var promoted = await DesignConversionTrainingIntakeRouteAdmissionContext
                .RunAsync(
                    BuildLocalPromotionAdmission(
                        "storage-authority-local-promotion-pass"),
                    () => api.RunTrainingIntakeAndPromoteLocalAsync(
                        intake.Value.IntakeId,
                        Path.Combine(root, "authority-ready-promotion"),
                        Pass157LocalPromotionOptions(
                            "storage-authority-local-promotion-pass",
                            BuildPassingMeasurementGateRequest(
                                "storage-authority-local-promotion-pass-gate"),
                            new DesignConversionDpoPolicyCheckpointBridgeOptions(
                                DpoStepCount: 1))));
            Assert.True(promoted.IsSuccess, promoted.ErrorMessage);
            Assert.True(
                promoted.Value!.LocalPromotionReady,
                string.Join("|", promoted.Value.BlockReasons));
            Assert.Equal(
                1,
                provider.InvocationCount + provider.ContinuationInvocationCount);
            Assert.NotNull(provider.LastModelSet);
            Assert.True(File.Exists(promoted.Value!.PromotedCheckpointPath));
            Assert.True(promoted.Value.PromotedLocalModel!.CheckpointFreshLoadVerified);
            Assert.True(promoted.Value.PromotedLocalModel.CheckpointContainsRealTrainedWeights);

            var promotedCheckpoint = await DesignConversionMachine.LoadCheckpointAsync(
                promoted.Value.PromotedCheckpointPath);
            Assert.True(promotedCheckpoint.IsSuccess, promotedCheckpoint.ErrorMessage);
            Assert.NotNull(promotedCheckpoint.Value!.Checkpoint.DpoPolicyCheckpointRef);
            var typedRef = promotedCheckpoint.Value.Checkpoint.DpoPolicyCheckpointRef!;
            Assert.True(typedRef.FreshLoadVerified);
            Assert.True(typedRef.ConvertedToRuntimeWeights);
            Assert.Equal(2, typedRef.SourceRecordCount);
            Assert.Equal(1, typedRef.BridgePreferenceCount);
            Assert.True(typedRef.BridgePreferenceCount < typedRef.SourceRecordCount);
            Assert.Equal(1, typedRef.DpoStepCount);
            Assert.Contains("teacher_provenance:source_kind=ExternalTeacherOutput", typedRef.EvidenceRefs);
            Assert.Contains("teacher_provenance:family=Qwen", typedRef.EvidenceRefs);
            Assert.Contains("teacher_provenance:access_mode=LocalHostedOpenWeight", typedRef.EvidenceRefs);
            Assert.Contains("teacher_provenance:hosting_provider=Ollama", typedRef.EvidenceRefs);
            Assert.Contains("teacher_provenance:model_license=Apache20", typedRef.EvidenceRefs);
            Assert.Contains("teacher_provenance:output_used_for_training=True", typedRef.EvidenceRefs);
            Assert.Equal(
                2,
                typedRef.TrainingContext.LegalTeacherAdmissionCommitment?
                    .ExternalTeacherInvocationCount);
            Assert.Contains("legal_teacher_admission:max_teacher_calls=2", typedRef.EvidenceRefs);
            Assert.Contains("teacher_legal_evidence:mode=SELF_HOSTED_NO_PROVIDER_TERMS", typedRef.EvidenceRefs);
            Assert.True(DesignConversionDpoLegalTeacherAdmissionCommitmentCodec.Validate(
                typedRef.TrainingContext.LegalTeacherAdmissionCommitment));
            Assert.Equal(
                2,
                typedRef.TrainingContext.LegalTeacherAdmissionCommitment?.ReceiptCount);
            Assert.Contains(
                typedRef.EvidenceRefs,
                reference => reference.StartsWith("teacher_provenance:model_ref=sha256:", StringComparison.Ordinal));
            Assert.Contains(
                typedRef.EvidenceRefs,
                reference => reference.StartsWith("teacher_provenance:model_version_ref=sha256:", StringComparison.Ordinal));

            var publicEvidenceSurface = string.Join(
                "\n",
                promoted.Value.EvidenceRefs
                    .Concat(promotedCheckpoint.Value.Checkpoint.EvidenceRefs)
                    .Concat(typedRef.EvidenceRefs)
                    .Append(System.Text.Json.JsonSerializer.Serialize(typedRef))
                    .Append(await File.ReadAllTextAsync(promoted.Value.PromotedCheckpointPath)));
            Assert.Contains("sha256:", publicEvidenceSurface, StringComparison.Ordinal);
            AssertDoesNotContainRawTeacherIdentity(
                publicEvidenceSurface,
                privateTrainRequest,
                privateHeldOutRequest,
                privateModel,
                privateVersion);
            Assert.DoesNotContain(
                Path.GetFullPath(root),
                publicEvidenceSurface,
                StringComparison.OrdinalIgnoreCase);
        }
        finally
        {
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }

    [Fact]
    public void BuildOrdinaryExternalTeacherApprovedRuntimeRecord_CarriesOpenTeacherSideAuthorshipBeforeIntake()
    {
        var record = BuildOrdinaryExternalTeacherApprovedRuntimeRecord(
            "storage-authority-fixture-validity",
            DesignConversionDpoUnits.ImproverUnit,
            usefulness: 0.97,
            "storage-authority-fixture-request",
            DesignConversionLegalTeacherCapabilityTestFactory.DefaultModelId,
            DesignConversionLegalTeacherCapabilityTestFactory
                .DefaultExpectedOllamaManifestDigest,
            payloadId: "storage-authority-fixture-shared");

        Assert.Equal(
            TrainingTeacherSourceKind.ExternalTeacherOutput,
            record.TeacherProvenance?.SourceKind);
        Assert.Equal(
            DPO.Models.DpoPairSideAuthorKind.OpenTeacher,
            record.ChosenAuthorKind);
        Assert.Equal(
            DPO.Models.DpoPairSideAuthorKind.LocalModel,
            record.RejectedAuthorKind);
        Assert.Equal(
            DesignConversionDpoPolicyCheckpointBridge.PairSourceSideGenerated,
            record.Provenance.Metadata[
                DesignConversionDpoPolicyCheckpointBridge
                    .PairChosenSourceSideMetadataKey]);
        Assert.Equal(
            DesignConversionDpoPolicyCheckpointBridge.PairSourceSideIncumbent,
            record.Provenance.Metadata[
                DesignConversionDpoPolicyCheckpointBridge
                    .PairRejectedSourceSideMetadataKey]);
        Assert.Equal(
            "test-external-open-teacher",
            record.Provenance.Metadata[
                DesignConversionDpoPolicyCheckpointBridge
                    .PairAuthorshipSourceMetadataKey]);
        var config = DesignConversionDpoPolicyBaseTestProvider.CreateConfig();
        AssertOptimizerPayloadCustodyReady([record]);

        // Авторство сторон уже есть, но это ещё не проверенный кандидат на
        // обучение: допуск к обучению с измерением качества требует отдельное
        // доказательство предпочтения, а не один паспорт внешнего учителя.
        Assert.Equal(
            bool.TrueString,
            record.Provenance.Metadata["training_candidate_only"]);
        Assert.DoesNotContain(
            "independent_preference_proven",
            record.Provenance.Metadata.Keys);

        var packed = DesignConversionDpoPolicyCheckpointBridge
            .BuildEvaluatedPackedBatchPreviewForTests(record, config);
        Assert.False(packed.IsSuccess);
        Assert.Equal(
            DesignConversionDpoPolicyCheckpointBridge
                .PairAuthorshipMissingOrInvalidErrorCode,
            packed.ErrorCode);
    }

