                blockedPolicyContract!.Evaluation!.Accuracy,
                double.Parse(
                    blocked.Value.TrainingRun.BoundaryMetadata["evaluated_dpo_accuracy"],
                    System.Globalization.CultureInfo.InvariantCulture),
