            var bridgeOptions = new DesignConversionDpoPolicyCheckpointBridgeOptions(DpoStepCount: 2);
            var promoted = await DesignConversionTrainingIntakeRouteAdmissionContext
                .RunAsync(
                    BuildLocalPromotionAdmission(
                        "pass157-local-promotion-measurement-pass"),
