    [Fact]
    public async Task LocalArtifactDb_EvaluatedPromotionUsesExactCappedProjectionAndDoesNotAdmitDroppedTrainRow()
    {
        const int maximumBridgePreferences = 2;
        const string id = "jsonl-capped-consumed-projection";
        var root = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString("N"), id);
        var provider = new DesignConversionDpoPolicyBaseTestProvider();
        var datasetOptions = new DesignConversionDpoDatasetOptions(
            DatasetId: id,
            MinimumTrainRecords: 1,
            MinimumHeldOutRecords: 1,
            Preflight: DesignConversionDpoDatasetPreflight
                .LocalTrainingIntakeSourceManifestDisjointProof(
                    [$"{id}:controlled-source-disjoint-intake"]));
        var options = new DesignConversionTrainingPipelineOptions(
            RunId: $"{id}-run",
            BatchSize: 1,
            DatasetOptions: datasetOptions,
            MeasurementGateRequest: BuildPassingMeasurementGateRequest($"{id}-gate"),
            DpoPolicyBridgeOptions: new DesignConversionDpoPolicyCheckpointBridgeOptions(
                MaxBridgePreferenceCount: maximumBridgePreferences,
                DpoStepCount: 1));
        var records = Enumerable.Range(0, 4)
            .Select(index => WithRuntimeArtifactProofRefs(
                ToRuntimeApprovedCandidate(
                    WithSourceIdentity(
                        BuildTrainingRecord(
                            $"{id}-record-{index:00}",
                            DesignConversionDpoUnits.ImproverUnit,
                            usefulness: 0.99 - index * 0.001),
                        $"{id}-source-{index:00}")),
                $"{id}-artifact-{index:00}"))
            .Select((record, index) => AttachInlineOptimizerPayloadCustody(
                record,
                $"{id}-record-{index:00}"))
            .ToArray();
        AssertOptimizerPayloadCustodyReady(records);
        DesignConversionDpoResolvedPartition? authoritativePartition = null;
        var db = new JsonlDesignConversionLocalArtifactDb(
            root,
            createTrainingIntakeJournalWaitTaskObserverForTesting: null,
            createTrainingIntakeJournalGateAcquiredCallbackForTesting: null,
            dpoPolicyBaseProvider: provider,
            runTrainingIntakeLocalPromotionPostBridgePartitionTransformerForTesting:
                partition =>
                {
                    authoritativePartition = partition;
                    return partition;
                },
            legalTeacherAdmissionAuthority: CreateEvaluatedLegalTeacherCapability());
        try
        {
            var artifactRecord = BuildArtifactRecord(
                $"{id}-storage-record",
                $"{id}-job",
                $"{id}-request",
                DesignConversionVisualQaBoundaryPolicy.TestProviderOnlyMarker,
                records,
                "<main>private capped projection setup</main>",
                ".private-capped-projection{color:red;}") with
            {
                SanitizedSourceRefs = new Dictionary<string, string>(StringComparer.Ordinal)
                {
                    ["source_manifest_ref"] = $"manifest://design-conversion/{id}",
                    ["source_kind"] = "figma",
                    ["design_tree_payload_ref"] = $"sha256:{id}-design-tree",
                    ["original_tree_payload_ref"] = $"sha256:{id}-original-tree",
                    ["source_artifact:expected_desktop"] = $"sha256:{id}-expected",
                    ["source_artifact:actual_desktop"] = $"sha256:{id}-actual"
                }
            };
            var stored = await Save(db, artifactRecord);
            await ApproveRuntimeCreatedDpoCandidatesAsync(
                db,
                stored.RecordId,
                records,
                id,
                259);
            var api = new DesignConversionDpoUsefulnessApi(db);
            var handoff = await api.ExportApprovedRuntimeDpoCandidatesAsync(
                new DesignConversionLocalArtifactDbQuery(JobId: $"{id}-job"),
                DateTimeOffset.UnixEpoch.AddMinutes(260));
            Assert.True(handoff.IsSuccess, handoff.ErrorMessage);
            Assert.Equal(records.Length, handoff.Value!.ApprovedCandidateCount);
            var approvedRecords = await db.QueryApprovedTrainingCandidatesAsync(
                new DesignConversionLocalArtifactDbQuery(JobId: $"{id}-job"));
            Assert.True(approvedRecords.IsSuccess, approvedRecords.ErrorMessage);
            Assert.Equal(records.Length, approvedRecords.Value!.Count);
            var dataset = new DesignConversionDpoDatasetBuilder()
                .BuildDataset(approvedRecords.Value, datasetOptions);
            Assert.True(dataset.IsSuccess, dataset.ErrorMessage);
            Assert.True(
                dataset.Value!.TrainRows.Count > maximumBridgePreferences,
                "The genuine Jsonl fixture must have a train partition larger than the bridge cap.");
            var intake = await api.CreateTrainingIntakeAsync(
                handoff.Value,
                $"requester:{id}",
                "genuine Jsonl capped consumed projection admission proof",
                DateTimeOffset.UnixEpoch.AddMinutes(261));
            Assert.True(intake.IsSuccess, intake.ErrorMessage);

            var promoted = await DesignConversionTrainingIntakeRouteAdmissionContext
                .RunAsync(
                    BuildLocalPromotionAdmission(id),
                    () => api.RunTrainingIntakeAndPromoteLocalAsync(
                        intake.Value!.IntakeId,
                        Path.Combine(root, "output"),
                        options));

            Assert.True(promoted.IsSuccess, promoted.ErrorMessage);
            Assert.Equal(1, provider.InvocationCount);
            Assert.NotNull(authoritativePartition);
            Assert.True(
                authoritativePartition!.TrainRecords.Count >
                    maximumBridgePreferences);
            var droppedRecordId = authoritativePartition
                .TrainRecords[maximumBridgePreferences]
                .RecordId;
            Assert.True(DesignConversionDpoConsumedPartitionProjectionContract.TryCreate(
                authoritativePartition!,
                maximumBridgePreferences,
                out var consumed));
            Assert.NotNull(consumed);
            Assert.DoesNotContain(
                consumed!.TrainRecords,
                record => string.Equals(record.RecordId, droppedRecordId, StringComparison.Ordinal));
            Assert.Contains(
                authoritativePartition!.TrainRecords,
                record => string.Equals(record.RecordId, droppedRecordId, StringComparison.Ordinal));
            Assert.NotEqual(
                authoritativePartition.TrainRecordSetSha256,
                consumed.TrainRecordSetSha256);
            Assert.NotEqual(
                authoritativePartition.PartitionSnapshotSha256,
                consumed.PartitionSnapshotSha256);
            var runnerEvidence = Assert.IsType<DesignConversionTrainingIntakeRunnerEvidence>(
                promoted.Value!.TrainingRun.RunnerEvidence);
            Assert.Equal(maximumBridgePreferences, runnerEvidence.ActualTrainRecords);
            var artifacts = Assert.IsType<DesignConversionTrainingManifestArtifacts>(
                promoted.Value.Publication!.Manifest.PromotionArtifacts);
            var policyContractText = await File.ReadAllTextAsync(artifacts.PolicyPath);
            var policyContract = System.Text.Json.JsonSerializer.Deserialize<
                DesignConversionDpoPolicyCheckpointContract>(
                policyContractText,
                DesignConversionCheckpointJsonOptions.Standard);
            Assert.NotNull(policyContract);
            Assert.Equal(
                maximumBridgePreferences + consumed.HeldOutRecords.Count,
                policyContract!.SourceRecordCount);
            Assert.Equal(maximumBridgePreferences, policyContract.BridgePreferenceCount);
            var evaluation = Assert.IsType<DesignConversionDpoHeldOutEvaluation>(
                policyContract.Evaluation);
            Assert.Equal(maximumBridgePreferences, evaluation.TrainRecordCount);
            Assert.Equal(consumed.HeldOutRecords.Count, evaluation.HeldOutRecordCount);
            Assert.Equal(consumed.TrainRecordSetSha256, evaluation.TrainRecordSetSha256);
            Assert.Equal(consumed.HeldOutRecordSetSha256, evaluation.HeldOutRecordSetSha256);
            Assert.Equal(consumed.TrainSourceSetSha256, evaluation.TrainSourceSetSha256);
            Assert.Equal(consumed.HeldOutSourceSetSha256, evaluation.HeldOutSourceSetSha256);
            Assert.Equal(consumed.PartitionSnapshotSha256, evaluation.PartitionSnapshotSha256);
            Assert.DoesNotContain(droppedRecordId, policyContractText, StringComparison.Ordinal);
        }
        finally
        {
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }

