    [Fact]
    public async Task LocalArtifactDb_EvaluatedPromotionAcceptsConvergedActualStepAndPublishesConsistentContracts()
    {
        const int requestedMaxStepCount = 5;
        const int expectedActualStepCount = 3;
        var root = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString("N"), "local-promotion-converged-actual");
        try
        {
            var fixture = await BuildW085DeterministicPromotionReadyIntakeFixtureAsync(
                root,
                "local-promotion-converged-actual");
            var provider = new DesignConversionDpoPolicyBaseTestProvider();
            var db = new JsonlDesignConversionLocalArtifactDb(
                root,
                dpoPolicyBaseProvider: provider,
                legalTeacherAdmissionAuthority: CreateEvaluatedLegalTeacherCapability());
            var options = fixture.Options with
            {
                DpoPolicyBridgeOptions = new DesignConversionDpoPolicyCheckpointBridgeOptions(
                    MaxBridgePreferenceCount: 1,
                    DpoStepCount: requestedMaxStepCount)
                {
                    DpoConvergenceThreshold = float.MaxValue,
                    DpoConvergenceWindowSteps = 1
                }
            };

            var promoted = await DesignConversionTrainingIntakeRouteAdmissionContext
                .RunAsync(
                    BuildLocalPromotionAdmission("local-promotion-converged-actual"),
                    () => db.RunTrainingIntakeAndPromoteLocalAsync(
                        fixture.Intake.IntakeId,
                        Path.Combine(root, "output"),
                        options));

            Assert.True(promoted.IsSuccess, promoted.ErrorMessage);
            Assert.Equal(1, provider.InvocationCount);
            Assert.NotNull(promoted.Value!.Publication);
            Assert.Equal(
                DesignConversionPromotionDecisionKind.Promote,
                promoted.Value.Publication.Decision.Kind);
            Assert.Equal(
                DesignConversionPromotionPublicationKind.LocalOnlyNoRemoteAttempt,
                promoted.Value.Publication.PublicationKind);
            Assert.True(promoted.Value.LocalPromotionReady);
            Assert.True(File.Exists(promoted.Value.PromotedCheckpointPath));
            var promotedLoad = await DesignConversionPromotedLocalModelLoader.LoadAsync(
                promoted.Value.Publication!,
                promoted.Value.PromotedCheckpointPath);
            Assert.True(promotedLoad.IsSuccess, promotedLoad.ErrorMessage);
            await AssertPromotedDpoPolicyCheckpointUsesProviderAsync(
                promoted.Value.PromotedCheckpointPath,
                promotedLoad.Value!,
                promoted.Value,
                provider,
                expectedActualStepCount);

            var typedRef = promotedLoad.Value!.Checkpoint.DpoPolicyCheckpointRef!;
            var expectedPolicyFileName = DpoTrainer.BuildPolicyCheckpointFileName(expectedActualStepCount);
            var rejectedMaxPolicyFileName = DpoTrainer.BuildPolicyCheckpointFileName(requestedMaxStepCount);
            Assert.Equal(expectedActualStepCount, typedRef.DpoStepCount);
            Assert.Equal(expectedPolicyFileName, typedRef.PolicyCheckpointFileName);
            Assert.Equal(expectedActualStepCount, promotedLoad.Value.Checkpoint.DpoPolicyCheckpointRef?.DpoStepCount);
            Assert.Equal($"dpo_policy_checkpoint_file:{expectedPolicyFileName}", promoted.Value.PromotedLocalModel!.DpoPolicyCheckpointFileRef);
            Assert.Equal($"dpo_policy_checkpoint_sha256:{typedRef.Sha256}", promoted.Value.PromotedLocalModel.DpoPolicyCheckpointSha256Ref);

            var artifacts = Assert.IsType<DesignConversionTrainingManifestArtifacts>(
                promoted.Value.Publication!.Manifest.PromotionArtifacts);
            var policyContract = System.Text.Json.JsonSerializer.Deserialize<
                DesignConversionDpoPolicyCheckpointContract>(
                await File.ReadAllBytesAsync(artifacts.PolicyPath),
                DesignConversionCheckpointJsonOptions.Standard);
            Assert.NotNull(policyContract);
            var evaluation = Assert.IsType<DesignConversionDpoHeldOutEvaluation>(
                policyContract!.Evaluation);
            Assert.Equal(expectedActualStepCount, policyContract.DpoStepCount);
            Assert.Equal(expectedActualStepCount, evaluation.DpoStepCount);
            Assert.Equal(typedRef.DpoStepCount, policyContract.DpoStepCount);
            Assert.Equal(typedRef.TrainingContext.SchemaVersion, policyContract.TrainingContext.SchemaVersion);
            Assert.Equal(typedRef.PolicyCheckpointFileName, policyContract.Binding.PolicyCheckpointFileName);
            Assert.Equal(typedRef.Sha256, evaluation.ChildPolicyCheckpointSha256);
            Assert.Contains($"dpo_policy_step_count:{expectedActualStepCount}", typedRef.EvidenceRefs);
            Assert.DoesNotContain($"dpo_policy_step_count:{requestedMaxStepCount}", typedRef.EvidenceRefs);
            Assert.True(File.Exists(Path.Combine(Path.GetDirectoryName(promoted.Value.PromotedCheckpointPath)!, expectedPolicyFileName)));
            Assert.False(File.Exists(Path.Combine(Path.GetDirectoryName(promoted.Value.PromotedCheckpointPath)!, rejectedMaxPolicyFileName)));
        }
        finally
        {
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }

    [Fact]
    public async Task PromotedLocalModelLoader_EvaluatedPromotionRequiresSourceEncoderPathAndFileBeforeRuntimeCreation()
    {
        var root = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString("N"), "local-promotion-source-required");
        try
        {
            var fixture = await BuildValidatedEvaluatedLocalLoaderPublicationAsync(
                root,
                "source-required");
            var artifacts = Assert.IsType<DesignConversionTrainingManifestArtifacts>(
                fixture.Publication.Manifest.PromotionArtifacts);
            Assert.Contains(
                "DESIGN_CONVERSION_PROMOTION_GATE_FROM_VALIDATED_EVALUATED_DPO_CONTRACT",
                fixture.Publication.Manifest.EvidenceRefs);
            Assert.False(string.IsNullOrWhiteSpace(artifacts.SourceEncoderPath));
            var sourcePath = artifacts.SourceEncoderPath!;
            Assert.True(File.Exists(sourcePath));
            var sourceBytes = await File.ReadAllBytesAsync(sourcePath);

            var baselineLoad = await DesignConversionPromotedLocalModelLoader.LoadAsync(
                fixture.Publication,
                fixture.CheckpointPath);
            Assert.True(baselineLoad.IsSuccess, baselineLoad.ErrorMessage);

            var missingSourcePathPublication = fixture.Publication with
            {
                Manifest = fixture.Publication.Manifest with
                {
                    PromotionArtifacts = artifacts with { SourceEncoderPath = null }
                }
            };
            var missingSourcePathLoad = await DesignConversionPromotedLocalModelLoader.LoadAsync(
                missingSourcePathPublication,
                fixture.CheckpointPath);

            File.Delete(sourcePath);
            Assert.False(File.Exists(sourcePath));
            var deletedSourceLoad = await DesignConversionPromotedLocalModelLoader.LoadAsync(
                fixture.Publication,
                fixture.CheckpointPath);
            Assert.False(
                missingSourcePathLoad.IsSuccess || deletedSourceLoad.IsSuccess,
                $"Old loader accepted evaluated source mutations. nullPathSuccess={missingSourcePathLoad.IsSuccess}; deletedFileSuccess={deletedSourceLoad.IsSuccess}");
            Assert.Equal(
                "DESIGN_CONVERSION_PROMOTED_SOURCE_ENCODER_ARTIFACT_REQUIRED",
                missingSourcePathLoad.ErrorCode);
            Assert.False(deletedSourceLoad.IsSuccess);
            Assert.Equal(
                "DESIGN_CONVERSION_PROMOTED_SOURCE_ENCODER_ARTIFACT_NOT_FOUND",
                deletedSourceLoad.ErrorCode);
            Assert.DoesNotContain(sourcePath, deletedSourceLoad.ErrorMessage, StringComparison.OrdinalIgnoreCase);

            await File.WriteAllBytesAsync(sourcePath, sourceBytes);
            var restoredSourceLoad = await DesignConversionPromotedLocalModelLoader.LoadAsync(
                fixture.Publication,
                fixture.CheckpointPath);
            Assert.True(restoredSourceLoad.IsSuccess, restoredSourceLoad.ErrorMessage);
        }
        finally
        {
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }

    [Fact]
    public async Task PromotedLocalModelLoader_EvaluatedPromotionRejectsIncompatibleSourceEncoderContractBeforeRuntimeCreation()
    {
        var root = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString("N"), "local-promotion-source-incompatible");
        try
        {
            var fixture = await BuildValidatedEvaluatedLocalLoaderPublicationAsync(
                root,
                "source-incompatible");
            var artifacts = Assert.IsType<DesignConversionTrainingManifestArtifacts>(
                fixture.Publication.Manifest.PromotionArtifacts);
            Assert.False(string.IsNullOrWhiteSpace(artifacts.SourceEncoderPath));
            var sourcePath = artifacts.SourceEncoderPath!;
            Assert.True(File.Exists(sourcePath));

            var baselineLoad = await DesignConversionPromotedLocalModelLoader.LoadAsync(
                fixture.Publication,
                fixture.CheckpointPath);
            Assert.True(baselineLoad.IsSuccess, baselineLoad.ErrorMessage);

            var sourceContract = JsonSerializer.Deserialize<DesignConversionDpoSourceEncoderContract>(
                await File.ReadAllBytesAsync(sourcePath),
                DesignConversionCheckpointJsonOptions.Standard);
            Assert.NotNull(sourceContract);
            var incompatibleSource = sourceContract! with
            {
                Binding = sourceContract.Binding with
                {
                    PolicyCheckpointSha256 = new string('0', 64)
                }
            };
            await File.WriteAllBytesAsync(
                sourcePath,
                JsonSerializer.SerializeToUtf8Bytes(
                    incompatibleSource,
                    new JsonSerializerOptions(DesignConversionCheckpointJsonOptions.Standard)
                    {
                        WriteIndented = false
                    }));

            var incompatibleSourceLoad = await DesignConversionPromotedLocalModelLoader.LoadAsync(
                fixture.Publication,
                fixture.CheckpointPath);
            Assert.False(incompatibleSourceLoad.IsSuccess);
            Assert.Equal(
                "DESIGN_CONVERSION_PROMOTED_SOURCE_ENCODER_CONTRACT_INVALID",
                incompatibleSourceLoad.ErrorCode);
            Assert.DoesNotContain(sourcePath, incompatibleSourceLoad.ErrorMessage, StringComparison.OrdinalIgnoreCase);
        }
        finally
        {
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }

    [Fact]
    public async Task PromotedLocalModelLoader_EvaluatedPromotionRejectsAliasedAndNonCanonicalSourceEncoderPaths()
    {
        var root = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString("N"), "local-promotion-source-path-identity");
        try
        {
            var fixture = await BuildValidatedEvaluatedLocalLoaderPublicationAsync(
                root,
                "source-path-identity");
            var artifacts = Assert.IsType<DesignConversionTrainingManifestArtifacts>(
                fixture.Publication.Manifest.PromotionArtifacts);
            Assert.False(string.IsNullOrWhiteSpace(artifacts.CheckpointPath));
            Assert.False(string.IsNullOrWhiteSpace(artifacts.TokenizerPath));
            Assert.False(string.IsNullOrWhiteSpace(artifacts.PolicyPath));
            Assert.False(string.IsNullOrWhiteSpace(artifacts.SourceEncoderPath));

            var baselineLoad = await DesignConversionPromotedLocalModelLoader.LoadAsync(
                fixture.Publication,
                fixture.CheckpointPath);
            Assert.True(baselineLoad.IsSuccess, baselineLoad.ErrorMessage);

            var canonicalSourcePath = artifacts.SourceEncoderPath!;
            var policyDirectory = Path.GetDirectoryName(artifacts.PolicyPath);
            Assert.False(string.IsNullOrWhiteSpace(policyDirectory));
            var copiedSourcePath = Path.Combine(
                policyDirectory!,
                $"{Path.GetFileNameWithoutExtension(canonicalSourcePath)}.noncanonical-copy.json");
            await File.WriteAllBytesAsync(
                copiedSourcePath,
                await File.ReadAllBytesAsync(canonicalSourcePath));
            Assert.True(File.Exists(copiedSourcePath));

            DesignConversionPromotionPublicationResult WithSourceEncoderPath(string sourceEncoderPath)
                => fixture.Publication with
                {
                    Manifest = fixture.Publication.Manifest with
                    {
                        PromotionArtifacts = artifacts with { SourceEncoderPath = sourceEncoderPath }
                    }
                };

            var checkpointAliasLoad = await DesignConversionPromotedLocalModelLoader.LoadAsync(
                WithSourceEncoderPath(artifacts.CheckpointPath),
                fixture.CheckpointPath);
            var tokenizerAliasLoad = await DesignConversionPromotedLocalModelLoader.LoadAsync(
                WithSourceEncoderPath(artifacts.TokenizerPath),
                fixture.CheckpointPath);
            var policyAliasLoad = await DesignConversionPromotedLocalModelLoader.LoadAsync(
                WithSourceEncoderPath(artifacts.PolicyPath),
                fixture.CheckpointPath);
            var nonCanonicalCopyLoad = await DesignConversionPromotedLocalModelLoader.LoadAsync(
                WithSourceEncoderPath(copiedSourcePath),
                fixture.CheckpointPath);

            const string expectedErrorCode = "DESIGN_CONVERSION_PROMOTED_SOURCE_ENCODER_PATH_INVALID";
            Assert.False(
                checkpointAliasLoad.IsSuccess || checkpointAliasLoad.ErrorCode != expectedErrorCode ||
                tokenizerAliasLoad.IsSuccess || tokenizerAliasLoad.ErrorCode != expectedErrorCode ||
                policyAliasLoad.IsSuccess || policyAliasLoad.ErrorCode != expectedErrorCode ||
                nonCanonicalCopyLoad.IsSuccess || nonCanonicalCopyLoad.ErrorCode != expectedErrorCode,
                $"Evaluated source path identity was accepted or misclassified. " +
                $"checkpoint=(success:{checkpointAliasLoad.IsSuccess},code:{checkpointAliasLoad.ErrorCode}); " +
                $"tokenizer=(success:{tokenizerAliasLoad.IsSuccess},code:{tokenizerAliasLoad.ErrorCode}); " +
                $"policy=(success:{policyAliasLoad.IsSuccess},code:{policyAliasLoad.ErrorCode}); " +
                $"nonCanonical=(success:{nonCanonicalCopyLoad.IsSuccess},code:{nonCanonicalCopyLoad.ErrorCode})");

            Assert.False(checkpointAliasLoad.IsSuccess);
            Assert.Equal(expectedErrorCode, checkpointAliasLoad.ErrorCode);
            Assert.DoesNotContain(
                artifacts.CheckpointPath,
                checkpointAliasLoad.ErrorMessage,
                StringComparison.OrdinalIgnoreCase);
            Assert.False(tokenizerAliasLoad.IsSuccess);
            Assert.Equal(expectedErrorCode, tokenizerAliasLoad.ErrorCode);
            Assert.DoesNotContain(
                artifacts.TokenizerPath,
                tokenizerAliasLoad.ErrorMessage,
                StringComparison.OrdinalIgnoreCase);
            Assert.False(policyAliasLoad.IsSuccess);
            Assert.Equal(expectedErrorCode, policyAliasLoad.ErrorCode);
            Assert.DoesNotContain(
                artifacts.PolicyPath,
                policyAliasLoad.ErrorMessage,
                StringComparison.OrdinalIgnoreCase);
            Assert.False(nonCanonicalCopyLoad.IsSuccess);
            Assert.Equal(expectedErrorCode, nonCanonicalCopyLoad.ErrorCode);
            Assert.DoesNotContain(
                copiedSourcePath,
                nonCanonicalCopyLoad.ErrorMessage,
                StringComparison.OrdinalIgnoreCase);
        }
        finally
        {
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }

