        await Save(db, BuildArtifactRecord(
            "storage-record-same-manifest-different-structure",
            "job-same-manifest-different-structure",
            "request-same-manifest-different-structure",
            DesignConversionVisualQaBoundaryPolicy.TestProviderOnlyMarker,
            [firstApprovedRuntime, secondApprovedRuntime],
            "<main data-user-id=\"user-luba\">exact_prompt private html</main>",
            ".private-user{background:url('C:/Users/lubao/private.png');}") with
        {
            SanitizedSourceRefs = new Dictionary<string, string>(StringComparer.Ordinal)
            {
                ["source_manifest_ref"] = "manifest://design-conversion/pass112-same-manifest",
                ["source_kind"] = "figma",
                ["design_tree_payload_ref"] = "sha256:design-tree-pass112-same-manifest",
                ["original_tree_payload_ref"] = "sha256:original-tree-pass112-same-manifest",
                ["source_artifact:expected_desktop"] = "sha256:pass112-same-manifest-expected-design-render",
                ["source_artifact:actual_desktop"] = "sha256:pass112-same-manifest-actual-browser-render"
            }
        });
        var handoff = await db.ExportApprovedRuntimeDpoCandidatesAsync(
            new DesignConversionLocalArtifactDbQuery(JobId: "job-same-manifest-different-structure"),
            DateTimeOffset.UnixEpoch.AddMinutes(112));
        Assert.True(handoff.IsSuccess, handoff.ErrorMessage);
        var intake = await db.CreateTrainingIntakeAsync(
            handoff.Value!,
            "requester:pass112-local",
            "same source manifest proof negative",
            DateTimeOffset.UnixEpoch.AddMinutes(112));

        Assert.True(intake.IsSuccess, intake.ErrorMessage);
        Assert.Equal(2, intake.Value!.CandidateRefs.Count);
        Assert.Equal(
            intake.Value.CandidateRefs[0].SourceManifestRef,
            intake.Value.CandidateRefs[1].SourceManifestRef);
        Assert.NotEqual(
            intake.Value.CandidateRefs[0].SourceStructureHash,
            intake.Value.CandidateRefs[1].SourceStructureHash);
        Assert.Equal(
            intake.Value.CandidateRefs[0].SourceIdentityHash,
            intake.Value.CandidateRefs[1].SourceIdentityHash);

        var preflight = await db.RunTrainingIntakePreflightAsync(intake.Value.IntakeId);
        var run = await db.RunTrainingIntakeAsync(
            intake.Value.IntakeId,
            BuildPassingCallerAdmissionRunOptions(
                "training-intake-same-manifest-different-structure",
                batchSize: intake.Value.AcceptedCandidateCount));

        Assert.True(preflight.IsSuccess, preflight.ErrorMessage);
        Assert.False(preflight.Value!.MayStartTraining);
        Assert.Equal("proven", preflight.Value.SourceManifestStatus);
        Assert.Equal("blocked_same_source", preflight.Value.SourceDisjointStatus);
        Assert.Contains(
            "source_disjoint_blocked_same_source",
            preflight.Value.BlockReasons);
        Assert.Equal(
            bool.FalseString,
            preflight.Value.BoundaryMetadata["may_start_training"]);

        Assert.True(run.IsSuccess, run.ErrorMessage);
        Assert.False(run.Value!.MayStartTraining);
        Assert.Equal("proven", run.Value.SourceManifestStatus);
        Assert.Equal("blocked_same_source", run.Value.SourceDisjointStatus);
        Assert.False(run.Value.TrainingRunnerInvoked);
        Assert.False(run.Value.TrainingStarted);
        Assert.False(run.Value.CheckpointMutated);
        Assert.False(run.Value.WeightsProduced);
        Assert.False(run.Value.ModelUploadReady);
        Assert.Contains("source_disjoint_blocked_same_source", run.Value.BlockReasons);
        Assert.Equal(
            "blocked_before_runner_by_training_intake_preflight",
            run.Value.TrainingExecutionBoundary);
    }

    [Fact]
    public void DpoPromotionSourceEncoderDescriptor_UsesOnlySelectedRowsAndSharedSignalBuilder()
    {
        var selectedA = BuildTrainingRecord(
            "descriptor-selected-a",
            DesignConversionDpoUnits.ImproverUnit,
            usefulness: 0.99);
        var selectedB = BuildTrainingRecord(
            "descriptor-selected-b",
            DesignConversionDpoUnits.CriticUnit,
            usefulness: 0.98);
        var beyondMaximum = BuildTrainingRecord(
            "descriptor-beyond-maximum",
            DesignConversionDpoUnits.ImproverUnit,
            usefulness: 0.97);
        var privateRow = BuildTrainingRecord(
            "descriptor-private",
            DesignConversionDpoUnits.ImproverUnit,
            usefulness: 1.0) with
        {
            License = selectedA.License with { ContainsUserPrivateData = true }
        };
        var untrainable = BuildTrainingRecord(
            "descriptor-untrainable",
            DesignConversionDpoUnits.ImproverUnit,
            usefulness: 1.0) with
        {
            License = selectedA.License with { AllowsTraining = false }
        };
        var quarantined = BuildTrainingRecord(
            "descriptor-quarantined",
            DesignConversionDpoUnits.CriticUnit,
            usefulness: 1.0) with
        {
            Quarantine = new DesignConversionQuarantineState(
                true,
                "descriptor-test-quarantine",
                ["descriptor-test-quarantine"])
        };
        var records = new[]
        {
            beyondMaximum,
            privateRow,
            selectedB,
            quarantined,
            selectedA,
            untrainable
        };
        var options = new DesignConversionDpoPolicyCheckpointBridgeOptions(
            MaxBridgePreferenceCount: 2,
            DpoStepCount: 1);
        var config = DesignConversionDpoPolicyBaseTestProvider.CreateConfig();

        var baseline = DesignConversionDpoPolicyCheckpointBridge
            .BuildSourceEncoderDescriptorPreviewForTests(records, config, options);

        Assert.True(baseline.IsSuccess, baseline.ErrorMessage);
        Assert.Equal(2, baseline.Value!.BridgePreferenceCount);
        Assert.Equal(13, baseline.Value.VectorDimension);
        Assert.Equal(config.VocabSize - 1, baseline.Value.TokenIdMaximum);
        Assert.Equal(config.ContextLen, baseline.Value.ContextLength);

        var excludedMetadata = new Dictionary<string, string>(
            beyondMaximum.Provenance.Metadata,
            StringComparer.Ordinal)
        {
            ["source_encoder_vector_hash"] = "excluded-row-mutation"
        };
        var excludedMutation = beyondMaximum with
        {
            Provenance = beyondMaximum.Provenance with { Metadata = excludedMetadata }
        };
        var excludedResult = DesignConversionDpoPolicyCheckpointBridge
            .BuildSourceEncoderDescriptorPreviewForTests(
                records.Select(row => ReferenceEquals(row, beyondMaximum)
                    ? excludedMutation
                    : row).ToArray(),
                config,
                options);
        Assert.True(excludedResult.IsSuccess, excludedResult.ErrorMessage);
        Assert.Equal(
            baseline.Value.SourceSignalSetSha256,
            excludedResult.Value!.SourceSignalSetSha256);

        var selectedMetadata = new Dictionary<string, string>(
            selectedA.Provenance.Metadata,
            StringComparer.Ordinal)
        {
            ["source_encoder_vector_hash"] = "selected-row-mutation"
        };
        var selectedMutation = selectedA with
        {
            Provenance = selectedA.Provenance with { Metadata = selectedMetadata }
        };
        var selectedRecords = records.Select(row => ReferenceEquals(row, selectedA)
            ? selectedMutation
            : row).ToArray();
        var selectedResult = DesignConversionDpoPolicyCheckpointBridge
            .BuildSourceEncoderDescriptorPreviewForTests(
                selectedRecords,
                config,
                options);
        Assert.True(selectedResult.IsSuccess, selectedResult.ErrorMessage);
        Assert.NotEqual(
            baseline.Value.SourceSignalSetSha256,
            selectedResult.Value!.SourceSignalSetSha256);
        Assert.DoesNotContain(
            "selected-row-mutation",
            DesignConversionDpoPolicyCheckpointBridge
                .BuildPolicyPromptPreviewForTests(selectedMutation),
            StringComparison.Ordinal);
        Assert.Contains(
            DesignConversionDpoPolicyCheckpointBridge
                .BuildSourceSignalSourceIdsPreviewForTests(selectedMutation),
            sourceId => sourceId.EndsWith(
                "selected-row-mutation",
                StringComparison.Ordinal));

        var structureMetadata = new Dictionary<string, string>(
            selectedA.Provenance.Metadata,
            StringComparer.Ordinal)
        {
            ["source_structure_signal_summary"] = "structure-only-mutation"
        };
        var structureMutation = selectedA with
        {
            Provenance = selectedA.Provenance with { Metadata = structureMetadata }
        };
        var structureResult = DesignConversionDpoPolicyCheckpointBridge
            .BuildSourceEncoderDescriptorPreviewForTests(
                records.Select(row => ReferenceEquals(row, selectedA)
                    ? structureMutation
                    : row).ToArray(),
                config,
                options);
        Assert.True(structureResult.IsSuccess, structureResult.ErrorMessage);
        Assert.NotEqual(
            baseline.Value.SourceSignalSetSha256,
            structureResult.Value!.SourceSignalSetSha256);

        var opaqueManifestMutation = selectedA with
        {
            Provenance = selectedA.Provenance with
            {
                SourceManifestRef = selectedA.Provenance.SourceManifestRef + "-opaque-mutation"
            }
        };
        var opaqueManifestResult = DesignConversionDpoPolicyCheckpointBridge
            .BuildSourceEncoderDescriptorPreviewForTests(
                records.Select(row => ReferenceEquals(row, selectedA)
                    ? opaqueManifestMutation
                    : row).ToArray(),
                config,
                options);
        Assert.True(opaqueManifestResult.IsSuccess, opaqueManifestResult.ErrorMessage);
        Assert.Equal(
            DesignConversionDpoPolicyCheckpointBridge.BuildPolicyPromptPreviewForTests(selectedA),
            DesignConversionDpoPolicyCheckpointBridge.BuildPolicyPromptPreviewForTests(opaqueManifestMutation));
        Assert.NotEqual(
            baseline.Value.SourceSignalSetSha256,
            opaqueManifestResult.Value!.SourceSignalSetSha256);

        var opaqueStructurePayloadMutation = selectedA with
        {
            SourceStructurePayload = selectedA.SourceStructurePayload + "-opaque-mutation"
        };
        var opaqueStructurePayloadResult = DesignConversionDpoPolicyCheckpointBridge
            .BuildSourceEncoderDescriptorPreviewForTests(
                records.Select(row => ReferenceEquals(row, selectedA)
                    ? opaqueStructurePayloadMutation
                    : row).ToArray(),
                config,
                options);
        Assert.True(opaqueStructurePayloadResult.IsSuccess, opaqueStructurePayloadResult.ErrorMessage);
        Assert.Equal(
            DesignConversionDpoPolicyCheckpointBridge.BuildPolicyPromptPreviewForTests(selectedA),
            DesignConversionDpoPolicyCheckpointBridge.BuildPolicyPromptPreviewForTests(opaqueStructurePayloadMutation));
        Assert.NotEqual(
            baseline.Value.SourceSignalSetSha256,
            opaqueStructurePayloadResult.Value!.SourceSignalSetSha256);

        var vectorMutation = selectedA with
        {
            InternalVectorPayload = selectedA.InternalVectorPayload
                .Select((value, index) => index == 0 ? value + 0.125 : value)
                .ToArray()
        };
        Assert.Equal(
            selectedA.Provenance.Metadata["source_encoder_vector_hash"],
            vectorMutation.Provenance.Metadata["source_encoder_vector_hash"]);
        Assert.Equal(
            selectedA.Provenance.Metadata["source_encoder_feature_map_hash"],
            vectorMutation.Provenance.Metadata["source_encoder_feature_map_hash"]);
        var vectorResult = DesignConversionDpoPolicyCheckpointBridge
            .BuildSourceEncoderDescriptorPreviewForTests(
                records.Select(row => ReferenceEquals(row, selectedA)
                    ? vectorMutation
                    : row).ToArray(),
                config,
                options);
        Assert.True(vectorResult.IsSuccess, vectorResult.ErrorMessage);
        Assert.NotEqual(
            baseline.Value.SourceSignalSetSha256,
            vectorResult.Value!.SourceSignalSetSha256);

        var identityMutation = selectedA with
        {
            RecordId = selectedA.RecordId + "-different-identity"
        };
        var identityResult = DesignConversionDpoPolicyCheckpointBridge
            .BuildSourceEncoderDescriptorPreviewForTests(
                records.Select(row => ReferenceEquals(row, selectedA)
                    ? identityMutation
                    : row).ToArray(),
                config,
                options);
        Assert.True(identityResult.IsSuccess, identityResult.ErrorMessage);
        Assert.NotEqual(
            baseline.Value.SourceSignalSetSha256,
            identityResult.Value!.SourceSignalSetSha256);

        var forward = DesignConversionDpoSourceEncoderContractBuilder.BuildDescriptor(
            [selectedA, selectedB],
            config);
        var reversed = DesignConversionDpoSourceEncoderContractBuilder.BuildDescriptor(
            [selectedB, selectedA],
            config);
        Assert.True(forward.IsSuccess, forward.ErrorMessage);
        Assert.True(reversed.IsSuccess, reversed.ErrorMessage);
        Assert.NotEqual(
            forward.Value!.SourceSignalSetSha256,
            reversed.Value!.SourceSignalSetSha256);
    }

    [Fact]
    public void EvaluatedPairPacking_IsFixedMaskedPairAwareAndRejectsIdentityOnlyLabels()
    {
        var baseline = BuildTrainingRecord(
            "evaluated-packing",
            DesignConversionDpoUnits.ImproverUnit,
            usefulness: 0.99);
        var row = baseline with
        {
            Chosen = baseline.Chosen with
            {
                Html = new string('a', 256) + "chosen-tail",
                Css = ".same{color:black}"
            },
            Rejected = baseline.Rejected with
            {
                Html = new string('a', 256) + "rejected-tail",
                Css = ".same{color:black}"
            }
        };
        var config = DesignConversionDpoPolicyBaseTestProvider.CreateConfig() with
        {
            VocabSize = 256,
            ContextLen = 17
        };

        var packed = DesignConversionDpoPolicyCheckpointBridge
            .BuildEvaluatedPackedBatchPreviewForTests(row, config);

        Assert.True(packed.IsSuccess, packed.ErrorMessage);
        var batch = packed.Value!.VectorBatch.Batch;
        Assert.Equal(17, batch.ChosenIds.Data.Length);
        Assert.Equal(17, batch.RejectedIds.Data.Length);
        Assert.False(batch.ChosenIds.Data.SequenceEqual(batch.RejectedIds.Data));
        Assert.All(batch.ChosenIds.Data, value => Assert.InRange(value, 0f, 255f));
        Assert.All(batch.RejectedIds.Data, value => Assert.InRange(value, 0f, 255f));
        Assert.All(batch.ChosenMask.Data.Take(5), value => Assert.Equal(0f, value));
        Assert.All(batch.RejectedMask.Data.Take(5), value => Assert.Equal(0f, value));
        Assert.Contains(1f, batch.ChosenMask.Data);
        Assert.Contains(1f, batch.RejectedMask.Data);
        Assert.Equal(
            packed.Value.InputSha256,
            DesignConversionDpoPolicyCheckpointBridge.RecomputeEvaluatedInputFingerprint(
                [row],
                [packed.Value.VectorBatch],
                config,
                includeTrainingVectorAndWeight: true));
        Assert.NotEqual(
            packed.Value.InputSha256,
            DesignConversionDpoPolicyCheckpointBridge.RecomputeEvaluatedInputFingerprint(
                [row],
                [packed.Value.VectorBatch with
                {
                    TeachingVector = packed.Value.VectorBatch.TeachingVector
                        .Append(0.125f)
                        .ToArray()
                }],
                config,
                includeTrainingVectorAndWeight: true));

        var contextTwo = DesignConversionDpoPolicyCheckpointBridge
            .BuildEvaluatedPackedBatchPreviewForTests(
                row,
                config with { ContextLen = 2 });
        Assert.True(contextTwo.IsSuccess, contextTwo.ErrorMessage);
        Assert.Equal(2, contextTwo.Value!.VectorBatch.Batch.ChosenIds.Data.Length);

        var firstByteDivergence = DesignConversionDpoPolicyCheckpointBridge
            .BuildEvaluatedPackedUtf8PreviewForTests(
                row,
                config with { ContextLen = 2 },
                "p",
                "a",
                "b");
        Assert.True(firstByteDivergence.IsSuccess, firstByteDivergence.ErrorMessage);
        var firstByteBatch = firstByteDivergence.Value!.VectorBatch.Batch;
        Assert.Equal(new[] { (float)'p', (float)'a' }, firstByteBatch.ChosenIds.Data);
        Assert.Equal(new[] { (float)'p', (float)'b' }, firstByteBatch.RejectedIds.Data);
        Assert.Equal(new[] { 0f, 1f }, firstByteBatch.ChosenMask.Data);
        Assert.Equal(new[] { 0f, 1f }, firstByteBatch.RejectedMask.Data);

        var strictPrefix = DesignConversionDpoPolicyCheckpointBridge
            .BuildEvaluatedPackedUtf8PreviewForTests(
                row,
                config with { ContextLen = 2 },
                "p",
                "a",
                "ab");
        Assert.True(strictPrefix.IsSuccess, strictPrefix.ErrorMessage);
        var strictPrefixBatch = strictPrefix.Value!.VectorBatch.Batch;
        Assert.Equal(new[] { (float)'p', 0f }, strictPrefixBatch.ChosenIds.Data);
        Assert.Equal(new[] { (float)'p', (float)'b' }, strictPrefixBatch.RejectedIds.Data);
        Assert.Equal(new[] { 0f, 0f }, strictPrefixBatch.ChosenMask.Data);
        Assert.Equal(new[] { 0f, 1f }, strictPrefixBatch.RejectedMask.Data);

        var tooShort = DesignConversionDpoPolicyCheckpointBridge
            .BuildEvaluatedPackedBatchPreviewForTests(
                row,
                config with { ContextLen = 1 });
        var lossyVocabulary = DesignConversionDpoPolicyCheckpointBridge
            .BuildEvaluatedPackedBatchPreviewForTests(
                row,
                config with { VocabSize = 255 });
        Assert.False(tooShort.IsSuccess);
        Assert.False(lossyVocabulary.IsSuccess);
        Assert.Equal(
            DesignConversionDpoPolicyCheckpointBridge.EvaluatedPackingInvalidErrorCode,
            tooShort.ErrorCode);
        Assert.Equal(
            DesignConversionDpoPolicyCheckpointBridge.EvaluatedPackingInvalidErrorCode,
            lossyVocabulary.ErrorCode);

        var identityOnly = baseline with
        {
            Rejected = baseline.Chosen with
            {
                OutputId = baseline.Chosen.OutputId + "-rejected-label",
                CandidateId = baseline.Chosen.CandidateId + "-rejected-label",
                Accepted = !baseline.Chosen.Accepted,
                Verdict = baseline.Chosen.Verdict with
                {
                    VerdictId = baseline.Chosen.Verdict.VerdictId + "-rejected-label",
                    EvidenceRefs = ["rejected-label-only"]
                },
                EvidenceRefs = ["rejected-label-only"]
            }
        };
        var identityOnlyPacked = DesignConversionDpoPolicyCheckpointBridge
            .BuildEvaluatedPackedBatchPreviewForTests(identityOnly, config);
        Assert.False(identityOnlyPacked.IsSuccess);
        Assert.Equal(
            DesignConversionDpoPolicyCheckpointBridge.EvaluatedPackingInvalidErrorCode,
            identityOnlyPacked.ErrorCode);
    }

    [Fact]
    public void EvaluatedBridge_AddsNoPublicLegacyBridgeOverloadOrResultMember()
    {
        var publicExecuteOverloads = typeof(DesignConversionDpoPolicyCheckpointBridge)
            .GetMethods(BindingFlags.Public | BindingFlags.Static)
            .Where(method => string.Equals(
                method.Name,
                nameof(DesignConversionDpoPolicyCheckpointBridge.ExecuteAndConvertAsync),
                StringComparison.Ordinal))
            .ToArray();
        Assert.Equal(6, publicExecuteOverloads.Length);
        Assert.Equal(
            3,
            publicExecuteOverloads.Count(method =>
                method.GetParameters()[0].ParameterType ==
                typeof(ServerOwnedLegalTrainingTeacherAdmissionAuthority)));
        Assert.Equal(
            3,
            publicExecuteOverloads.Count(method =>
                method.GetCustomAttribute<ObsoleteAttribute>() is not null));
        Assert.DoesNotContain(
            typeof(DesignConversionDomain.DesignConversionDpoPolicyRuntimeCheckpointBridgeResult).GetProperties(),
            property => string.Equals(property.Name, "Evaluation", StringComparison.Ordinal));
        var deconstruct = Assert.Single(
            typeof(DesignConversionDomain.DesignConversionDpoPolicyRuntimeCheckpointBridgeResult)
                .GetMethods(BindingFlags.Public | BindingFlags.Instance),
            method => string.Equals(method.Name, "Deconstruct", StringComparison.Ordinal));
        Assert.Equal(14, deconstruct.GetParameters().Length);
        var resultType = typeof(DesignConversionDomain
            .DesignConversionDpoPolicyRuntimeCheckpointBridgeResult);
        Assert.DoesNotContain(
            resultType.GetProperties(BindingFlags.Public | BindingFlags.Instance),
            property => string.Equals(
                property.Name,
                nameof(DesignConversionDomain
                    .DesignConversionDpoPolicyRuntimeCheckpointBridgeResult
                    .CanonicalBpeTokenizerSnapshot),
                StringComparison.Ordinal));
        Assert.Contains(
            resultType.GetProperties(BindingFlags.NonPublic | BindingFlags.Instance),
            property => string.Equals(
                property.Name,
                nameof(DesignConversionDomain
                    .DesignConversionDpoPolicyRuntimeCheckpointBridgeResult
                    .CanonicalBpeTokenizerSnapshot),
                StringComparison.Ordinal));
        var evaluatedOverloads = typeof(DesignConversionDpoPolicyCheckpointBridge)
            .GetMethods(BindingFlags.NonPublic | BindingFlags.Static)
            .Where(method => string.Equals(
                method.Name,
                "ExecuteEvaluatedAndConvertAsync",
                StringComparison.Ordinal))
            .ToArray();
        Assert.Equal(2, evaluatedOverloads.Length);
        Assert.All(
            evaluatedOverloads,
            method => Assert.Equal(
                typeof(ServerOwnedLegalTrainingTeacherAdmissionAuthority),
                method.GetParameters()[0].ParameterType));
        var transferredLeaseSeams = typeof(DesignConversionDpoPolicyCheckpointBridge)
            .GetMethods(BindingFlags.NonPublic | BindingFlags.Static)
            .Where(method => method.Name is
                "ExecuteEvaluatedSnapshotWithTransferredLeaseAsync" or
                "ExecuteEvaluatedContinuationSnapshotWithTransferredLeaseAsync")
            .ToArray();
        Assert.Equal(2, transferredLeaseSeams.Length);
        Assert.All(
            transferredLeaseSeams,
            method =>
            {
                Assert.Equal(
                    typeof(ServerOwnedLegalTrainingTeacherAdmissionLease),
                    method.GetParameters()[0].ParameterType);
                Assert.Equal(
                    typeof(DesignConversionDpoConsumedPartitionProjection),
                    method.GetParameters()[1].ParameterType);
            });
        var resolvedPartitionTransferredLeaseSeams =
            typeof(DesignConversionDpoPolicyCheckpointBridge)
                .GetMethods(BindingFlags.NonPublic | BindingFlags.Static)
                .Where(method => string.Equals(
                    method.Name,
                    "ExecuteEvaluatedAndConvertWithTransferredLeaseAsync",
                    StringComparison.Ordinal))
                .ToArray();
        Assert.Equal(2, resolvedPartitionTransferredLeaseSeams.Length);
        Assert.All(
            resolvedPartitionTransferredLeaseSeams,
            method =>
            {
                Assert.Equal(
                    typeof(ServerOwnedLegalTrainingTeacherAdmissionLease),
                    method.GetParameters()[0].ParameterType);
                Assert.Equal(
                    typeof(DesignConversionDpoResolvedPartition),
                    method.GetParameters()[1].ParameterType);
            });
        var preparedTransferredLeaseSeams =
            typeof(DesignConversionDpoPolicyCheckpointBridge)
                .GetMethods(BindingFlags.NonPublic | BindingFlags.Static)
                .Where(method => string.Equals(
                    method.Name,
                    "ExecutePreparedEvaluatedCompositeWithTransferredLeaseAsync",
                    StringComparison.Ordinal))
                .ToArray();
        Assert.Equal(2, preparedTransferredLeaseSeams.Length);
        var compositeBoundPreparedSeam = Assert.Single(
            preparedTransferredLeaseSeams,
            method => method.GetParameters().Length > 2 &&
                      method.GetParameters()[1].ParameterType ==
                      typeof(DesignConversionPipelineTrainingBinding));
        Assert.Equal(
            typeof(DesignConversionDpoPolicyCheckpointBridge
                .PreparedEvaluatedCompositeExecution),
            compositeBoundPreparedSeam.GetParameters()[2].ParameterType);
        Assert.DoesNotContain(
            preparedTransferredLeaseSeams.SelectMany(
                static method => method.GetParameters()),
            parameter => typeof(IDesignConversionDpoPolicyBaseProvider)
                .IsAssignableFrom(parameter.ParameterType));
    }

    [Fact]
    public async Task LocalPromotion_FreshPathUsesOneLeaseAndRevocationAfterBridgePermitDrainsAfterTerminalJournal()
    {
        var root = Path.Combine(
            Path.GetTempPath(),
            Guid.NewGuid().ToString("N"),
            "local-promotion-continuous-permit");
        var output = Path.Combine(root, "output");
        // Здесь важен срок жизни серверного разрешения, а не внешний учитель.
        // Заранее заданные проверочные пары позволяют дойти до участка с
        // разрешением и отзывом без обхода защиты отдельного допуска набора
        // данных.
        var fixture = await BuildW085DeterministicPromotionReadyIntakeFixtureAsync(
            root,
            "local-promotion-continuous-permit");
        var revocable = DesignConversionLegalTeacherCapabilityTestFactory.CreateRevocable(
            expectedOllamaModelLayerDigest: LegalTeacherModelLayerDigest);
        var observedLeases = new List<ServerOwnedLegalTrainingTeacherAdmissionLease>();
        var bridgeAcquisitions = new List<string>();
        var mutationBoundaries = new List<string>();
        var terminalStages = new List<string>();
        Task? revocation = null;
        var priorTrainingLeaseObserver =
            DesignConversionTrainingPipeline.TrainingLeaseObserverForTesting;
        var priorPipelineBoundaryObserver =
            DesignConversionTrainingPipeline.MutationBoundaryObserverForTesting;
        var priorBridgeLeaseObserver =
            DesignConversionDpoPolicyCheckpointBridge.LeaseAcquisitionObserverForTesting;
        try
        {
            DesignConversionTrainingPipeline.TrainingLeaseObserverForTesting =
                observedLeases.Add;
            DesignConversionTrainingPipeline.MutationBoundaryObserverForTesting =
                mutationBoundaries.Add;
            DesignConversionDpoPolicyCheckpointBridge.LeaseAcquisitionObserverForTesting =
                bridgeAcquisitions.Add;
            var uploader = new CountingLocalOnlyPromotionUploader();
            var db = new JsonlDesignConversionLocalArtifactDb(
                root,
                createTrainingIntakeJournalWaitTaskObserverForTesting: null,
                createTrainingIntakeJournalGateAcquiredCallbackForTesting: null,
                promotionUploader: uploader,
                runTrainingIntakeLocalPromotionBeforePublicationObserverForTesting: () =>
                {
                    Assert.Single(observedLeases);
                    var stillOwnedByBridge = observedLeases[0].AcquireMutationPermit();
                    Assert.True(stillOwnedByBridge.IsSuccess, stillOwnedByBridge.ErrorMessage);
                    stillOwnedByBridge.Value!.Dispose();
                    revocation ??= revocable.BeginRevocationAsync();
                    Assert.False(revocation.IsCompleted);
                    terminalStages.Add("before-publication");
                },
                runTrainingIntakeLocalPromotionBeforeActivationObserverForTesting: () =>
                {
                    Assert.NotNull(revocation);
                    Assert.False(revocation!.IsCompleted);
                    terminalStages.Add("before-activation");
                },
                runTrainingIntakeLocalPromotionActivationInvokedObserverForTesting: () =>
                    terminalStages.Add("activation-invoked"),
                runTrainingIntakeLocalPromotionBeforeIdempotencyAppendCallbackForTesting: _ =>
                {
                    Assert.NotNull(revocation);
                    Assert.False(revocation!.IsCompleted);
                    terminalStages.Add("before-terminal-journal");
                    return Task.CompletedTask;
                },
                promotionBeforeTerminalReturnObserverForTesting: _ =>
                {
                    Assert.NotNull(revocation);
                    Assert.False(revocation!.IsCompleted);
                    terminalStages.Add("publisher-terminal-return");
                },
                dpoPolicyBaseProvider: CreateW085DeterministicPromotionProvider(),
                legalTeacherAdmissionAuthority: revocable.Authority,
                localReceiptOnlyPromotionAuthority: uploader.Authority);

            var promoted = await DesignConversionTrainingIntakeRouteAdmissionContext.RunAsync(
                new Dictionary<string, string>(StringComparer.Ordinal)
                {
                    ["training_intake_tenant_id_ref"] = "tenant:local-promotion-continuous-permit",
                    ["training_intake_idempotency_key_ref"] = "idempotency:local-promotion-continuous-permit"
                },
                () => db.RunTrainingIntakeAndPromoteLocalAsync(
                    fixture.Intake.IntakeId,
                    output,
                    fixture.Options));

            Assert.True(promoted.IsSuccess, promoted.ErrorMessage);
            Assert.True(
                promoted.Value!.LocalPromotionReady,
                DescribeLocalPromotionReadiness(promoted.Value));
            Assert.Single(observedLeases);
            Assert.Empty(bridgeAcquisitions);
            Assert.Equal(
                1,
                mutationBoundaries.Count(boundary => string.Equals(
                    boundary,
                    "local_promotion:bridge_result",
                    StringComparison.Ordinal)));
            Assert.Equal(
                [
                    "before-publication",
                    "publisher-terminal-return",
                    "before-activation",
                    "activation-invoked",
                    "before-terminal-journal"
                ],
                terminalStages);
            Assert.NotNull(revocation);
            await revocation!;
            Assert.True(File.Exists(Path.Combine(
                root,
                "training-intake-local-promotions.jsonl")));
            Assert.Equal(
                ServerOwnedLegalTrainingTeacherAdmissionAuthority.AdmissionRevokedErrorCode,
                observedLeases[0].AcquireMutationPermit().ErrorCode);
        }
        finally
        {
            DesignConversionTrainingPipeline.TrainingLeaseObserverForTesting =
                priorTrainingLeaseObserver;
            DesignConversionTrainingPipeline.MutationBoundaryObserverForTesting =
                priorPipelineBoundaryObserver;
            DesignConversionDpoPolicyCheckpointBridge.LeaseAcquisitionObserverForTesting =
                priorBridgeLeaseObserver;
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }

    [Fact]
    public async Task LocalPromotion_ContinuationTransfersSameSingleLeaseWithoutBridgeReacquisition()
    {
        var root = Path.Combine(
            Path.GetTempPath(),
            Guid.NewGuid().ToString("N"),
            "local-promotion-continuation-single-lease");
        var provider = new RecordingEvaluatedContinuationProvider();
        var authority = CreateEvaluatedLegalTeacherCapability();
        var uploader = new CountingLocalOnlyPromotionUploader();
        var db = new JsonlDesignConversionLocalArtifactDb(
            root,
            authority,
            dpoPolicyBaseProvider: provider,
            promotionUploader: uploader,
            localReceiptOnlyPromotionAuthority: uploader.Authority);
        // Продолжение обучения проверяет перенос одного серверного разрешения
        // между двумя публикациями. Обе заявки используют заранее заданные
        // проверочные пары, чтобы проверка не останавливалась на отдельном
        // допуске набора данных.
        var parentFixture = await BuildW085DeterministicPromotionReadyIntakeFixtureAsync(
            root,
            "local-promotion-parent");
        var childFixture = await BuildW085DeterministicPromotionReadyIntakeFixtureAsync(
            root,
            "local-promotion-child");
        var parentOutput = Path.Combine(root, "parent-output");
        var childOutput = Path.Combine(root, "child-output");

        var parent = await DesignConversionTrainingIntakeRouteAdmissionContext.RunAsync(
            new Dictionary<string, string>(StringComparer.Ordinal)
            {
                ["training_intake_tenant_id_ref"] = "tenant:local-promotion-single-lease-parent",
                ["training_intake_idempotency_key_ref"] = "idempotency:local-promotion-single-lease-parent"
            },
            () => db.RunTrainingIntakeAndPromoteLocalAsync(
                parentFixture.Intake.IntakeId,
                parentOutput,
                parentFixture.Options));
        Assert.True(parent.IsSuccess, parent.ErrorMessage);
        Assert.True(
            parent.Value!.LocalPromotionReady,
            DescribeLocalPromotionReadiness(parent.Value));

        var observedLeases = new List<ServerOwnedLegalTrainingTeacherAdmissionLease>();
        var bridgeAcquisitions = new List<string>();
        var priorTrainingLeaseObserver =
            DesignConversionTrainingPipeline.TrainingLeaseObserverForTesting;
        var priorBridgeLeaseObserver =
            DesignConversionDpoPolicyCheckpointBridge.LeaseAcquisitionObserverForTesting;
        try
        {
            DesignConversionTrainingPipeline.TrainingLeaseObserverForTesting =
                observedLeases.Add;
            DesignConversionDpoPolicyCheckpointBridge.LeaseAcquisitionObserverForTesting =
                bridgeAcquisitions.Add;

            var child = await DesignConversionTrainingIntakeRouteAdmissionContext.RunAsync(
                new Dictionary<string, string>(StringComparer.Ordinal)
                {
                    ["training_intake_tenant_id_ref"] = "tenant:local-promotion-single-lease-child",
                    ["training_intake_idempotency_key_ref"] = "idempotency:local-promotion-single-lease-child"
                },
                () => db.RunTrainingIntakeAndPromoteLocalAsync(
                    childFixture.Intake.IntakeId,
                    childOutput,
                    childFixture.Options));

            Assert.True(child.IsSuccess, child.ErrorMessage);
            Assert.Single(observedLeases);
            Assert.Empty(bridgeAcquisitions);
            Assert.Equal(1, provider.ContinuationInvocationCount);
            Assert.Contains(
                child.Value!.TrainingRun.BoundaryMetadata,
                pair => pair.Key.Contains("continuation", StringComparison.OrdinalIgnoreCase));
            Assert.Equal(
                ServerOwnedLegalTrainingTeacherAdmissionAuthority.AdmissionRevokedErrorCode,
                observedLeases[0].AcquireMutationPermit().ErrorCode);
        }
        finally
        {
            DesignConversionTrainingPipeline.TrainingLeaseObserverForTesting =
                priorTrainingLeaseObserver;
            DesignConversionDpoPolicyCheckpointBridge.LeaseAcquisitionObserverForTesting =
                priorBridgeLeaseObserver;
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }

    [Fact]
    public async Task LocalPromotion_RevocationBeforePostBridgePermitFailsAndCleansUncommittedBridgeFinals()
    {
        var root = Path.Combine(
            Path.GetTempPath(),
            Guid.NewGuid().ToString("N"),
            "local-promotion-revoke-before-permit");
        var output = Path.Combine(root, "output");
        // Отзыв после результата промежуточной проверки должен проверить
        // очистку незавершённой публикации. Заранее заданные проверочные пары
        // сохраняют этот смысл и не превращают тест в проверку отдельного
        // допуска набора данных.
        var fixture = await BuildW085DeterministicPromotionReadyIntakeFixtureAsync(
            root,
            "local-promotion-revoke-before-permit");
        var paths = DesignConversionDpoPromotionArtifactContractCodec.ResolvePaths(
            root,
            output,
            fixture.Options.RunId);
        Assert.True(paths.IsSuccess, paths.ErrorMessage);
        var revocable = DesignConversionLegalTeacherCapabilityTestFactory.CreateRevocable(
            expectedOllamaModelLayerDigest: LegalTeacherModelLayerDigest);
        var bridgeResultBoundaryCount = 0;
        var priorBoundaryObserver =
            DesignConversionTrainingPipeline.MutationBoundaryObserverForTesting;
        try
        {
            DesignConversionTrainingPipeline.MutationBoundaryObserverForTesting =
                boundary =>
                {
                    if (!string.Equals(
                            boundary,
                            "local_promotion:bridge_result",
                            StringComparison.Ordinal))
                    {
                        return;
                    }

                    bridgeResultBoundaryCount++;
                    revocable.BeginRevocationAsync().GetAwaiter().GetResult();
                };
            var db = new JsonlDesignConversionLocalArtifactDb(
                root,
                revocable.Authority,
                dpoPolicyBaseProvider: CreateW085DeterministicPromotionProvider());

            var promoted = await DesignConversionTrainingIntakeRouteAdmissionContext
                .RunAsync(
                    BuildLocalPromotionAdmission(
                        "local-promotion-revoke-before-permit"),
                    () => db.RunTrainingIntakeAndPromoteLocalAsync(
                        fixture.Intake.IntakeId,
                        output,
                        fixture.Options));

            Assert.False(promoted.IsSuccess);
            Assert.Equal(
                "DESIGN_CONVERSION_TRAINING_INTAKE_PROMOTE_LOCAL_INDETERMINATE_AFTER_INTENT",
                promoted.ErrorCode);
            Assert.Equal(1, bridgeResultBoundaryCount);
            Assert.False(File.Exists(paths.Value!.RuntimeCheckpointPath));
            Assert.False(File.Exists(Path.Combine(
                paths.Value.OutputDirectory,
                DpoTrainer.BuildPolicyCheckpointFileName(1))));
            Assert.False(File.Exists(Path.Combine(
                root,
                "training-intake-local-promotions.jsonl")));
        }
        finally
        {
            DesignConversionTrainingPipeline.MutationBoundaryObserverForTesting =
                priorBoundaryObserver;
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }

    [Fact]
    public async Task LocalPromotion_ContractFailureCleansBridgeFinalsAndPreservesOnlyForeignCollision()
    {
        var root = Path.Combine(
            Path.GetTempPath(),
            Guid.NewGuid().ToString("N"),
            "local-promotion-contract-failure-cleanup");
        var output = Path.Combine(root, "output");
        var fixture = await BuildPromotionReadyIntakeFixtureAsync(
            root,
            "local-promotion-contract-failure-cleanup");
        var requestedPaths = DesignConversionDpoPromotionArtifactContractCodec.ResolvePaths(
            root,
            output,
            fixture.Options.RunId);
        Assert.True(requestedPaths.IsSuccess, requestedPaths.ErrorMessage);
        var nestedOutput = Path.Combine(
            requestedPaths.Value!.OutputDirectory,
            $"dpo-{Sha256Text(fixture.Options.RunId)[..12]}-dpo-policy-checkpoints");
        var paths = DesignConversionDpoPromotionArtifactContractCodec.ResolvePaths(
            root,
            nestedOutput,
            fixture.Options.RunId);
        Assert.True(paths.IsSuccess, paths.ErrorMessage);
        var collisionCreated = 0;
        var foreignCollisionBytes = System.Text.Encoding.UTF8.GetBytes(
            "foreign source encoder contract owned outside this publication");
        var db = new JsonlDesignConversionLocalArtifactDb(
            root,
            createTrainingIntakeJournalWaitTaskObserverForTesting: null,
            createTrainingIntakeJournalGateAcquiredCallbackForTesting: null,
            runTrainingIntakeLocalPromotionBeforePublicationObserverForTesting: () =>
            {
                Directory.CreateDirectory(paths.Value!.OutputDirectory);
                File.WriteAllBytes(
                    paths.Value.SourceEncoderContractPath,
                    foreignCollisionBytes);
                collisionCreated++;
            },
            dpoPolicyBaseProvider: CreateW085DeterministicPromotionProvider(),
            legalTeacherAdmissionAuthority: CreateEvaluatedLegalTeacherCapability());

        try
        {
            var promoted = await RunLocalPromotionWithAdmissionAsync(
                db,
                fixture,
                output,
                BuildLocalPromotionAdmission(
                    "local-promotion-contract-failure-cleanup"));

            Assert.Equal(1, collisionCreated);
            Assert.False(
                promoted.IsSuccess,
                promoted.IsSuccess
                    ? string.Join("|", promoted.Value!.BlockReasons)
                    : promoted.ErrorMessage);
            Assert.Equal(
                foreignCollisionBytes,
                File.ReadAllBytes(paths.Value!.SourceEncoderContractPath));
            Assert.False(File.Exists(paths.Value.RuntimeCheckpointPath));
            Assert.False(File.Exists(Path.Combine(
                paths.Value.OutputDirectory,
                DpoTrainer.BuildPolicyCheckpointFileName(1))));
            Assert.False(File.Exists(Path.Combine(
                root,
                "training-intake-local-promotions.jsonl")));
        }
        finally
        {
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }

