    [Fact]
    public void EvaluatedMetrics_UseStrictPositiveRelativeMarginExactMeansAndRejectNonFinite()
    {
        var summary = DesignConversionDpoPolicyCheckpointBridge
            .ComputeEvaluatedMetricSummaryForTests(
            [
                (ChildChosen: 4f, ChildRejected: 1f,
                    ReferenceChosen: 2f, ReferenceRejected: 1f),
                (ChildChosen: 2f, ChildRejected: 1f,
                    ReferenceChosen: 3f, ReferenceRejected: 2f)
            ]);

        Assert.True(summary.IsSuccess, summary.ErrorMessage);
        Assert.Equal(1, summary.Value!.CorrectCount);
        Assert.Equal(0.5d, summary.Value.Accuracy);
        Assert.Equal(1d, summary.Value.MeanRelativeMargin);
        Assert.Equal(2d, summary.Value.MeanChildMargin);
        Assert.Equal(1d, summary.Value.MeanReferenceMargin);

        var nonFinite = DesignConversionDpoPolicyCheckpointBridge
            .ComputeEvaluatedMetricSummaryForTests(
            [
                (ChildChosen: float.NaN, ChildRejected: 0f,
                    ReferenceChosen: 0f, ReferenceRejected: 0f)
            ]);
        Assert.False(nonFinite.IsSuccess);
        Assert.Equal(
            "DESIGN_CONVERSION_DPO_EVALUATED_METRICS_NON_FINITE",
            nonFinite.ErrorCode);
    }

    [Theory]
    [InlineData("duplicate-mismatch", LegalTrainingTeacherAdmissionAuthority.ProvenanceInvalidErrorCode)]
    [InlineData("closed", LegalTrainingTeacherAdmissionAuthority.ClosedProprietaryDeniedErrorCode)]
    [InlineData("terms-invalid", LegalTrainingTeacherAdmissionAuthority.TermsNotApprovedErrorCode)]
    [InlineData("not-allowlisted", LegalTrainingTeacherAdmissionAuthority.NotAllowlistedErrorCode)]
    [InlineData("aggregate-budget", LegalTrainingTeacherAdmissionAuthority.CallBudgetExceededErrorCode)]
    public async Task EvaluatedBridge_InvalidHeldOutTeacherFailsBeforeProviderIoOrForward(
        string failureKind,
        string expectedErrorCode)
    {
        var root = Path.Combine(
            Path.GetTempPath(),
            $"evaluated-heldout-legal-{failureKind}-{Guid.NewGuid():N}");
        var output = Path.Combine(root, "output");
        var provider = new DesignConversionDpoPolicyBaseTestProvider();
        var observations = new List<DesignConversionDpoEvaluatedForwardObservation>();
        var partition = BuildEvaluatedPartitionForTests(failureKind, heldOutCount: 1);
        var trainProvenance = ValidExternalTeacherProvenance($"{failureKind}-train");
        var heldOutProvenance = failureKind switch
        {
            "duplicate-mismatch" => trainProvenance with { InvocationCount = 2 },
            "closed" => ValidExternalTeacherProvenance($"{failureKind}-heldout") with
            {
                ClosedProprietaryModel = true
            },
            "terms-invalid" => ValidExternalTeacherProvenance($"{failureKind}-heldout") with
            {
                TeacherOutputUsedForTraining = false
            },
            "not-allowlisted" => ValidExternalTeacherProvenance($"{failureKind}-heldout") with
            {
                ModelVersion = new string('e', 64)
            },
            "aggregate-budget" => ValidExternalTeacherProvenance($"{failureKind}-heldout"),
            _ => throw new InvalidOperationException("Unknown legal-teacher failure case.")
        };
        if (failureKind == "duplicate-mismatch")
            trainProvenance = trainProvenance with { RequestId = heldOutProvenance.RequestId };
        partition = partition with
        {
            TrainRecords =
            [partition.TrainRecords[0] with { TeacherProvenance = trainProvenance }],
            HeldOutRecords =
            [partition.HeldOutRecords[0] with { TeacherProvenance = heldOutProvenance }]
        };
        var capability = CreateEvaluatedLegalTeacherCapability(
            maxTeacherCalls: failureKind == "aggregate-budget" ? 1 : 10);
        if (failureKind == "aggregate-budget")
        {
            Assert.True(capability.ValidateBatch([trainProvenance]).IsSuccess);
            Assert.True(capability.ValidateBatch([heldOutProvenance]).IsSuccess);
        }

        var evaluated = await DesignConversionDpoPolicyCheckpointBridge
            .ExecuteEvaluatedAndConvertAsync(
                capability,
                partition,
                output,
                failureKind,
                Path.Combine(output, "runtime.json"),
                provider,
                new DesignConversionDpoPolicyCheckpointBridgeOptions(
                    MaxBridgePreferenceCount: 1,
                    DpoStepCount: 1),
                forwardObserverForTesting: observations.Add,
                ct: CancellationToken.None);

        Assert.False(evaluated.IsSuccess);
        Assert.Equal(expectedErrorCode, evaluated.ErrorCode);
        Assert.Equal(0, provider.InvocationCount);
        Assert.Null(provider.LastModelSet);
        Assert.Empty(observations);
        Assert.False(Directory.Exists(root));
    }

