    [Fact]
    public async Task EvaluatedBridge_ContinuationWithValidExternalTeacherUsesContinuationProviderAndSucceeds()
    {
        var root = Path.Combine(
            Path.GetTempPath(),
            $"evaluated-external-continuation-{Guid.NewGuid():N}");
        var output = Path.Combine(root, "output");
        var provider = new RecordingEvaluatedContinuationProvider();
        var partition = BuildEvaluatedPartitionForTests("external-continuation", heldOutCount: 1);
        Directory.CreateDirectory(root);
        partition = partition with
        {
            TrainRecords =
            [
                WithExternalTeacherAuthorship(
                    partition.TrainRecords[0],
                    ValidExternalTeacherProvenance("continuation-train"))
            ],
            HeldOutRecords =
            [
                WithExternalTeacherAuthorship(
                    partition.HeldOutRecords[0],
                    ValidExternalTeacherProvenance("continuation-heldout"))
            ]
        };
        partition = CanonicalizeFullEvaluatedPartition(partition);

        try
        {
            var parentPaths = DesignConversionDpoPromotionArtifactContractCodec
                .ResolvePaths(
                    root,
                    Path.Combine(root, "parent"),
                    "external-continuation-parent");
            Assert.True(parentPaths.IsSuccess, parentPaths.ErrorMessage);
            var parentBridge = await DesignConversionDpoPolicyCheckpointBridge
                .ExecuteEvaluatedAndConvertAsync(
                    CreateEvaluatedLegalTeacherCapability(),
                    BuildEvaluatedPartitionForTests(
                        "external-continuation-parent",
                        heldOutCount: 1),
                    parentPaths.Value!.OutputDirectory,
                    "external-continuation-parent",
                    parentPaths.Value.RuntimeCheckpointPath,
                    new DesignConversionDpoPolicyBaseTestProvider(),
                    new DesignConversionDpoPolicyCheckpointBridgeOptions(1, 1),
                    ct: CancellationToken.None);
            Assert.True(parentBridge.IsSuccess, parentBridge.ErrorMessage);
            using var parentLease = parentBridge.Value!;
            var parentPublication = await DesignConversionDpoPromotionArtifactContractCodec
                .PublishEvaluatedAsync(
                    parentPaths.Value,
                    parentLease.Result,
                    parentLease.Evaluation,
                    CancellationToken.None);
            Assert.True(parentPublication.IsSuccess, parentPublication.ErrorMessage);
            parentLease.CommitPublishedArtifacts();
            var checkpointSource = new RecordingEvaluatedCheckpointSource(
                Path.Combine(
                    parentPaths.Value.OutputDirectory,
                    parentLease.Result.PolicyCheckpointPath));
            var bridgeProofSource = new RecordingEvaluatedCheckpointSource(
                Path.Combine(
                    parentPaths.Value.OutputDirectory,
                    parentLease.Result.PolicyCheckpointPath));
            var continuation = CreateLineageContinuationRequest(
                checkpointSource,
                bridgeProofSource,
                parentPublication.Value!);

            var continuationOptions = new DesignConversionDpoPolicyCheckpointBridgeOptions(
                MaxBridgePreferenceCount: 1,
                DpoStepCount: 1);
            var continuationAuthority =
                CreateEvaluatedLegalTeacherCapability(maxTeacherCalls: 2);
            var preparedContinuation = await DesignConversionDpoPolicyCheckpointBridge
                .PrepareEvaluatedCompositeExecutionAsync(
                    continuationAuthority,
                    partition,
                    provider,
                    continuationOptions,
                    continuation,
                    useContinuation: true,
                    CancellationToken.None);
            Assert.True(
                preparedContinuation.IsSuccess,
                preparedContinuation.ErrorMessage);
            Assert.NotNull(preparedContinuation.Value);

            var acquiredContinuationLease = continuationAuthority.AcquireTrainingLease(
                preparedContinuation.Value!.FinalOptimizer.Content,
                preparedContinuation.Value.FinalOptimizer.Provenance);
            Assert.True(
                acquiredContinuationLease.IsSuccess,
                acquiredContinuationLease.ErrorMessage);
            var continuationLease = acquiredContinuationLease.Value!;
            var bridgeReacquisitions = new List<string>();
            var priorLeaseObserver =
                DesignConversionDpoPolicyCheckpointBridge
                    .LeaseAcquisitionObserverForTesting;
            DesignConversionDpoPolicyCheckpointBridge.LeaseAcquisitionObserverForTesting =
                bridgeReacquisitions.Add;
            OperationResult<DesignConversionDpoEvaluatedBridgeLease> evaluated;
            try
            {
                evaluated = await DesignConversionDpoPolicyCheckpointBridge
                    .ExecutePreparedEvaluatedCompositeWithTransferredLeaseAsync(
                        continuationLease,
                        preparedContinuation.Value,
                        output,
                        "external-continuation",
                        Path.Combine(output, "runtime.json"),
                        ct: CancellationToken.None);
            }
            finally
            {
                DesignConversionDpoPolicyCheckpointBridge
                    .LeaseAcquisitionObserverForTesting = priorLeaseObserver;
            }

            Assert.True(evaluated.IsSuccess, evaluated.ErrorMessage);
            using var lease = evaluated.Value!;
            Assert.Empty(bridgeReacquisitions);
            Assert.Equal(0, provider.FreshInvocationCount);
            Assert.Equal(1, provider.ContinuationInvocationCount);
            Assert.NotSame(continuation, provider.LastContinuationRequest);
            Assert.Same(
                continuation.CheckpointSource,
                provider.LastContinuationRequest!.CheckpointSource);
            Assert.NotSame(
                continuation.SourceEncoderContract,
                provider.LastContinuationRequest.SourceEncoderContract);
            Assert.NotSame(
                continuation.PolicyCheckpointContract,
                provider.LastContinuationRequest.PolicyCheckpointContract);
            Assert.Equal(1, bridgeProofSource.OpenCount);
            Assert.Equal(1, checkpointSource.OpenCount);
            Assert.Equal("immediate_parent", lease.Evaluation.ReferenceMode);
            Assert.Contains(
                "legal_teacher_admission:external_invocation_count=1",
                lease.Result.EvidenceRefs);
        }
        finally
        {
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }

    [Fact]
    public async Task EvaluatedBridge_TypedContinuationProviderForeignActualWeightsFailsBeforeAnyRealPermitOrArtifacts()
    {
        var root = Path.Combine(
            Path.GetTempPath(),
            $"evaluated-foreign-continuation-{Guid.NewGuid():N}");
        var output = Path.Combine(root, "output");
        var runtimeCheckpointPath = Path.Combine(output, "runtime.json");
        var provider = new RecordingEvaluatedContinuationProvider(modelSet =>
        {
            PerturbEvaluatedContinuationModelSetWeightsInLockstep(modelSet);
            return OperationResult<DesignConversionDpoPolicyBaseModelSet>.Ok(
                modelSet);
        });
        var partition = BuildEvaluatedPartitionForTests(
            "external-continuation-foreign",
            heldOutCount: 1);
        Directory.CreateDirectory(root);
        partition = partition with
        {
            TrainRecords =
            [
                WithExternalTeacherAuthorship(
                    partition.TrainRecords[0],
                    ValidExternalTeacherProvenance("continuation-foreign-train"))
            ],
            HeldOutRecords =
            [
                WithExternalTeacherAuthorship(
                    partition.HeldOutRecords[0],
                    ValidExternalTeacherProvenance("continuation-foreign-heldout"))
            ]
        };
        partition = CanonicalizeFullEvaluatedPartition(partition);

        var proofObservations = new List<
            DesignConversionDpoContinuationMutationProofObservation>();
        var mutationBoundaries = new List<string>();
        var previousProofObserver = DesignConversionDpoPolicyCheckpointBridge
            .ContinuationMutationProofObserverForTesting;
        var previousBoundaryObserver = DesignConversionDpoPolicyCheckpointBridge
            .MutationBoundaryObserverForTesting;
        TypedCompositeBridgeAuthorityFixture? typed = null;

        try
        {
            var parentPaths = DesignConversionDpoPromotionArtifactContractCodec
                .ResolvePaths(
                    root,
                    Path.Combine(root, "parent"),
                    "external-continuation-foreign-parent");
            Assert.True(parentPaths.IsSuccess, parentPaths.ErrorMessage);
            var parentBridge = await DesignConversionDpoPolicyCheckpointBridge
                .ExecuteEvaluatedAndConvertAsync(
                    CreateEvaluatedLegalTeacherCapability(),
                    BuildEvaluatedPartitionForTests(
                        "external-continuation-foreign-parent",
                        heldOutCount: 1),
                    parentPaths.Value!.OutputDirectory,
                    "external-continuation-foreign-parent",
                    parentPaths.Value.RuntimeCheckpointPath,
                    new DesignConversionDpoPolicyBaseTestProvider(),
                    new DesignConversionDpoPolicyCheckpointBridgeOptions(1, 1),
                    ct: CancellationToken.None);
            Assert.True(parentBridge.IsSuccess, parentBridge.ErrorMessage);
            using var parentLease = parentBridge.Value!;
            var parentPublication = await DesignConversionDpoPromotionArtifactContractCodec
                .PublishEvaluatedAsync(
                    parentPaths.Value,
                    parentLease.Result,
                    parentLease.Evaluation,
                    CancellationToken.None);
            Assert.True(parentPublication.IsSuccess, parentPublication.ErrorMessage);
            parentLease.CommitPublishedArtifacts();
            var checkpointSource = new RecordingEvaluatedCheckpointSource(
                Path.Combine(
                    parentPaths.Value.OutputDirectory,
                    parentLease.Result.PolicyCheckpointPath));
            var bridgeProofSource = new RecordingEvaluatedCheckpointSource(
                Path.Combine(
                    parentPaths.Value.OutputDirectory,
                    parentLease.Result.PolicyCheckpointPath));
            var continuation = CreateLineageContinuationRequest(
                checkpointSource,
                bridgeProofSource,
                parentPublication.Value!);

            DesignConversionDpoPolicyCheckpointBridge
                .ContinuationMutationProofObserverForTesting =
                proofObservations.Add;
            DesignConversionDpoPolicyCheckpointBridge
                .MutationBoundaryObserverForTesting =
                mutationBoundaries.Add;

            var continuationOptions = new DesignConversionDpoPolicyCheckpointBridgeOptions(
                MaxBridgePreferenceCount: 1,
                DpoStepCount: 1);
            var permitObserver =
                new DesignConversionLegalTeacherCapabilityTestFactory
                    .PermitCountingObserverForTesting();
            var continuationAuthority = DesignConversionLegalTeacherCapabilityTestFactory
                .CreateAdmittedWithPermitObserver(
                    permitObserver,
                    maxTeacherCalls: 2,
                    expectedOllamaModelLayerDigest:
                        LegalTeacherModelLayerDigest);
            var preparedContinuation = await DesignConversionDpoPolicyCheckpointBridge
                .PrepareEvaluatedCompositeExecutionAsync(
                    continuationAuthority,
                    partition,
                    provider,
                    continuationOptions,
                    continuation,
                    useContinuation: true,
                    CancellationToken.None);
            Assert.True(
                preparedContinuation.IsSuccess,
                preparedContinuation.ErrorMessage);
            Assert.NotNull(preparedContinuation.Value);

            typed = CreateTypedCompositeBridgeAuthority(
                continuationAuthority,
                preparedContinuation.Value!,
                "external-continuation-foreign");

            var evaluated = await DesignConversionDpoPolicyCheckpointBridge
                .ExecutePreparedEvaluatedCompositeWithTransferredLeaseAsync(
                    typed.ParentLease,
                    typed.Binding,
                    preparedContinuation.Value,
                    output,
                    "external-continuation-foreign",
                    runtimeCheckpointPath,
                    ct: CancellationToken.None);

            Assert.False(evaluated.IsSuccess);
            Assert.Equal(
                DesignConversionDpoCheckpointMutationAdmission.MismatchErrorCode,
                evaluated.ErrorCode);
            Assert.Equal(0, provider.FreshInvocationCount);
            Assert.Equal(1, provider.ContinuationInvocationCount);
            Assert.Equal(1, bridgeProofSource.OpenCount);
            Assert.Equal(1, checkpointSource.OpenCount);
            Assert.Empty(mutationBoundaries);
            Assert.Equal(0, permitObserver.GrantCount);
            Assert.Empty(permitObserver.ActivePermitCountTransitions);
            // Failure path возвращает custody lease через cleanup guard. Это
            // не mutation permit; real grants и active transitions выше
            // обязаны остаться нулевыми до fingerprint mismatch.
            Assert.Equal(1, permitObserver.LeaseDisposeAttemptCount);
            Assert.DoesNotContain(
                mutationBoundaries,
                static boundary => boundary.Contains(
                    ":policy_provider",
                    StringComparison.Ordinal));
            Assert.Collection(
                proofObservations,
                expected =>
                {
                    Assert.Equal("expected", expected.Phase);
                    Assert.Null(expected.ActualModelSetStateFingerprint);
                },
                actual =>
                {
                    Assert.Equal("actual", actual.Phase);
                    Assert.NotEqual(
                        actual.ExpectedModelSetStateFingerprint,
                        actual.ActualModelSetStateFingerprint);
                });
            Assert.False(Directory.Exists(output));
            Assert.False(File.Exists(runtimeCheckpointPath));
        }
        finally
        {
            DesignConversionDpoPolicyCheckpointBridge
                .ContinuationMutationProofObserverForTesting =
                previousProofObserver;
            DesignConversionDpoPolicyCheckpointBridge
                .MutationBoundaryObserverForTesting =
                previousBoundaryObserver;
            typed?.ParentLease.Dispose();
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }

