    [Fact]
    public void DesignConversionDpoConsumedPartitionProjection_RejectsCrossPartitionRecordIdentityOverlap()
    {
        var partition = BuildEvaluatedPartitionForTests(
            "projection-record-overlap",
            heldOutCount: 1);
        var overlappingHeldOut = WithSourceIdentity(
            partition.HeldOutRecords[0] with
            {
                RecordId = partition.TrainRecords[0].RecordId,
                UnitId = partition.TrainRecords[0].UnitId
            },
            "projection-record-overlap-distinct-heldout-source");

        Assert.Equal(
            DesignConversionDpoDatasetBuilder.ComputeRecordIdentityHash(partition.TrainRecords[0]),
            DesignConversionDpoDatasetBuilder.ComputeRecordIdentityHash(overlappingHeldOut));
        Assert.NotEqual(
            DesignConversionDpoDatasetBuilder.ComputeSourceIdentityHash(partition.TrainRecords[0]),
            DesignConversionDpoDatasetBuilder.ComputeSourceIdentityHash(overlappingHeldOut));

        var rejected = DesignConversionDpoConsumedPartitionProjectionContract.TryCreate(
            partition with { HeldOutRecords = [overlappingHeldOut] },
            maximumTrainRecords: 1,
