    [Fact]
    public async Task EvaluatedBridge_ForwardsEachHeldOutPairExactlyFourTimesFromCachedInputs()
    {
        var root = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString("N"));
        var output = Path.Combine(root, "forward-count");
        var provider = new DesignConversionDpoPolicyBaseTestProvider();
        var observations = new List<DesignConversionDpoEvaluatedForwardObservation>();
        var partition = BuildEvaluatedPartitionForTests("forward-count", heldOutCount: 2);

        var evaluated = await DesignConversionDpoPolicyCheckpointBridge
            .ExecuteEvaluatedAndConvertAsync(
                CreateEvaluatedLegalTeacherCapability(),
                partition,
                output,
                "forward-count",
                Path.Combine(output, "runtime.json"),
                provider,
                new DesignConversionDpoPolicyCheckpointBridgeOptions(
                    MaxBridgePreferenceCount: 1,
                    DpoStepCount: 1),
                forwardObserverForTesting: observations.Add,
                ct: CancellationToken.None);

        Assert.True(evaluated.IsSuccess, evaluated.ErrorMessage);
        using var lease = evaluated.Value!;
        Assert.Equal(3, lease.Result.SourceRecordCount);
        Assert.Equal(2, lease.Evaluation.EvaluatedHeldOutRecordCount);
        Assert.Equal("provider_fresh_step_zero", lease.Evaluation.ReferenceMode);
        Assert.Equal(
            provider.LastModelSet!.Identity.BaseCheckpointSha256,
            lease.Evaluation.ReferencePolicyCheckpointSha256);
        Assert.NotEqual(
            lease.Evaluation.ReferencePolicyCheckpointSha256,
            lease.Evaluation.ChildPolicyCheckpointSha256);
        var byRecord = observations.GroupBy(value => value.RecordIdentitySha256).ToArray();
        Assert.Equal(2, byRecord.Length);
        Assert.All(byRecord, group =>
        {
            Assert.Equal(8, group.Count());
            Assert.Equal(4, group.Count(value => value.Phase is
                DesignConversionDpoEvaluatedForwardPhase.BeforeChildChosen or
                DesignConversionDpoEvaluatedForwardPhase.BeforeChildRejected or
                DesignConversionDpoEvaluatedForwardPhase.BeforeReferenceChosen or
                DesignConversionDpoEvaluatedForwardPhase.BeforeReferenceRejected));
            Assert.Single(group.Select(value => value.InputSha256).Distinct(StringComparer.Ordinal));
        });
    }

    [Fact]
