    [Fact]
    public async Task EvaluatedContractValidationRejectsMissingOrEvaluationUnboundG3Metrics()
    {
        var root = Path.Combine(
            Path.GetTempPath(),
            $"evaluated-contract-g3-binding-{Guid.NewGuid():N}");
        try
        {
            var published = await PublishEvaluatedLineageCycleAsync(
                root,
                "evaluated-contract-g3-binding",
                BuildEvaluatedPartitionForTests(
                    "evaluated-contract-g3-binding",
                    heldOutCount: 2),
                new DesignConversionDpoPolicyBaseTestProvider());
            var evaluation = published.Evaluation;
            var metrics = Assert.IsType<DesignConversionG3AcceptanceMetrics>(
                evaluation.G3Metrics);
            var mismatchedHeldOutCount = metrics.HeldOutCount + 1;
            var heldOutMismatchMetrics = metrics with
            {
                HeldOutCount = mismatchedHeldOutCount,
                BaselineWinRate =
                    (double)metrics.BaselineWinCount / mismatchedHeldOutCount,
                AbsoluteChildPreferenceAccuracy =
                    (double)metrics.AbsoluteChildPreferenceCorrectCount /
                    mismatchedHeldOutCount
            };
            var mismatchedBaselineWins = metrics.BaselineWinCount == 0 ? 1 : 0;
            var baselineMismatchMetrics = metrics with
            {
                BaselineWinCount = mismatchedBaselineWins,
                BaselineWinRate =
                    (double)mismatchedBaselineWins / metrics.HeldOutCount
            };
            Assert.True(DesignConversionG3AcceptancePolicy.MetricsAreValid(
                heldOutMismatchMetrics));
            Assert.True(DesignConversionG3AcceptancePolicy.MetricsAreValid(
                baselineMismatchMetrics));
            var foreignScorerPassport = MeasurementNoisePolicy.BuildPassport(
                DesignConversionDpoPolicyCheckpointBridge
                    .EvaluatedMeasurementNoiseScorerIdentity with
                {
                    ScorerId = "foreign-dpo-heldout-g3-scorer"
                },
                evaluation.DatasetId,
                evaluation.EvaluatedHeldOutRecordCount,
                Enumerable.Repeat(
                    evaluation.Accuracy,
                    MeasurementNoisePolicyConfig.DefaultRepeatCount).ToArray(),
                MeasurementNoisePolicyConfig.Canonical,
                DateTimeOffset.UnixEpoch);
            var thresholdResolver = typeof(JsonlDesignConversionLocalArtifactDb)
                .GetMethod(
                    "ResolveRequiredEvaluatedAccuracy",
                    BindingFlags.Static | BindingFlags.NonPublic);
            Assert.NotNull(thresholdResolver);
            var promotionOptions = Pass157LocalPromotionOptions(
                "evaluated-contract-g3-binding-run",
                BuildPassingMeasurementGateRequest(
                    "evaluated-contract-g3-binding-gate"));

            var invalidEvaluations = new (string Name,
                DesignConversionDpoHeldOutEvaluation Evaluation)[]
            {
                ("missing-g3-metrics", evaluation with { G3Metrics = null }),
                ("heldout-count-unbound", evaluation with
                {
                    G3Metrics = heldOutMismatchMetrics
                }),
                ("baseline-win-count-and-rate-unbound", evaluation with
                {
                    G3Metrics = baselineMismatchMetrics
                }),
                ("measurement-noise-scope-missing", evaluation with
                {
                    G3Metrics = metrics with
                    {
                        MeasurementNoiseScorerIdentity = null
                    }
                }),
                ("measurement-noise-passport-foreign-scorer", evaluation with
                {
                    MeasurementNoisePassport = foreignScorerPassport,
                    MeasurementNoiseStatus = MeasurementNoisePolicy
                        .ClassifyDifference(
                            metrics.BaselineWinRate -
                            DesignConversionG3AcceptancePolicyConfig
                                .Canonical.MinimumBaselineWinRate,
                            foreignScorerPassport)
                        .Status
                })
            };

            foreach (var invalid in invalidEvaluations)
            {
                var tampered = WithEvaluationAndRecomputedBinding(
                    published.Publication,
                    invalid.Evaluation);
                Assert.False(
                    DesignConversionDpoPromotionArtifactContractCodec
                        .ValidateEvaluatedContractPair(
                            tampered.SourceEncoderContract,
                            tampered.PolicyCheckpointContract),
                    invalid.Name);
                Assert.False(
                    DesignConversionDpoPromotionArtifactContractCodec
                        .ValidateEvaluatedArtifactPublication(tampered),
                    invalid.Name);
                var acquired = DesignConversionDpoPromotionArtifactContractCodec
                    .AcquireValidatedEvaluatedArtifactPublication(tampered);
                Assert.False(acquired.IsSuccess);
                Assert.Equal(
                    DesignConversionDpoPromotionArtifactContractCodec
                        .ContractInvalidErrorCode,
                    acquired.ErrorCode);
                var threshold = Assert.IsType<OperationResult<double>>(
                    thresholdResolver!.Invoke(
                        null,
                        [promotionOptions, invalid.Evaluation]));
                Assert.False(threshold.IsSuccess, invalid.Name);
                Assert.Equal(
                    DesignConversionDpoPromotionArtifactContractCodec
                        .ContractInvalidErrorCode,
                    threshold.ErrorCode);
            }
        }
        finally
        {
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }

    [Fact]
    public async Task EvaluatedContractValidationRejectsTrainRecordCountAboveBridgePreferenceCount()
    {
        var root = Path.Combine(
            Path.GetTempPath(),
            $"evaluated-contract-train-count-tamper-{Guid.NewGuid():N}");

        try
        {
            var published = await PublishEvaluatedLineageCycleAsync(
                root,
                "evaluated-contract-train-count-tamper",
                BuildEvaluatedPartitionForTests("evaluated-contract-train-count-tamper", heldOutCount: 2),
                new DesignConversionDpoPolicyBaseTestProvider());
            var policyContract = published.Publication.PolicyCheckpointContract;
            var validEvaluation = published.Evaluation;
            var validLineage = Assert.IsType<DesignConversionDpoHeldOutCycleAccuracyLineage>(
                validEvaluation.CycleAccuracyLineage);
            var tamperedTrainRecordCount = policyContract.BridgePreferenceCount + 1;
            var tamperedHeldOutRecordCount =
                policyContract.SourceRecordCount - tamperedTrainRecordCount;
            const double tamperedAccuracy = 1d;

            Assert.True(DesignConversionDpoPromotionArtifactContractCodec
                .ValidateEvaluatedContractPair(
                    published.Publication.SourceEncoderContract,
                    policyContract));
            Assert.NotEqual(policyContract.BridgePreferenceCount, tamperedTrainRecordCount);
            Assert.True(tamperedHeldOutRecordCount > 0);
            Assert.Equal(
                policyContract.SourceRecordCount,
                tamperedTrainRecordCount + tamperedHeldOutRecordCount);

            var tamperedEvaluation = validEvaluation with
            {
                MaxBridgePreferenceCount = tamperedTrainRecordCount,
                TrainRecordCount = tamperedTrainRecordCount,
                HeldOutRecordCount = tamperedHeldOutRecordCount,
                EvaluatedHeldOutRecordCount = tamperedHeldOutRecordCount,
                CorrectCount = tamperedHeldOutRecordCount,
                Accuracy = tamperedAccuracy,
                CycleAccuracyLineage = validLineage with
                {
                    CurrentMeasuredAccuracy = tamperedAccuracy
                }
            };
            var tamperedPublication = WithEvaluationAndRecomputedBinding(
                published.Publication,
                tamperedEvaluation);

            Assert.False(
                DesignConversionDpoPromotionArtifactContractCodec
                    .ValidateEvaluatedContractPair(
                        tamperedPublication.SourceEncoderContract,
                        tamperedPublication.PolicyCheckpointContract),
                "evaluated promotion artifacts must bind TrainRecordCount exactly to BridgePreferenceCount");
            Assert.False(
                DesignConversionDpoPromotionArtifactContractCodec
                    .ValidateEvaluatedArtifactPublication(tamperedPublication),
                "evaluated promotion artifact publication validation must reject the same count tamper");
        }
        finally
        {
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }

