    [Fact]
    public async Task EvaluatedBridge_LegacyV1ParentFailsPreflightBeforeProviderTrainingOrPublication()
    {
        var root = Path.Combine(
            Path.GetTempPath(),
            $"cycle-lineage-legacy-{Guid.NewGuid():N}");
        var partition = BuildEvaluatedPartitionForTests("cycle-lineage-legacy", heldOutCount: 1);
        var previousSinkObserver = DesignConversionDpoPolicyCheckpointBridge
            .OptimizerMutationSinkObserverForTesting;

        try
        {
            var parent = await PublishEvaluatedLineageCycleAsync(
                root,
                "cycle-lineage-legacy-parent",
                partition,
                new DesignConversionDpoPolicyBaseTestProvider());
            var legacyParentEvaluation = parent.Evaluation with
            {
                Schema = DesignConversionDpoPolicyCheckpointBridge.LegacyEvaluatedSchema,
                G3Metrics = null,
                CycleAccuracyLineage = null
            };
            var legacyParentPublication = WithEvaluationAndRecomputedBinding(
                parent.Publication,
                legacyParentEvaluation);
            Assert.True(DesignConversionDpoPromotionArtifactContractCodec
                .ValidateEvaluatedContractPair(
                    legacyParentPublication.SourceEncoderContract,
                    legacyParentPublication.PolicyCheckpointContract));

            var continuation = CreateLineageContinuationRequest(
                parent.PolicyCheckpointPath,
                legacyParentPublication);
            var childProvider = new DesignConversionDpoPolicyBaseTestProvider();
            var mutationSinks = new List<
                DesignConversionDpoOptimizerMutationSinkObservation>();
            var forwardObservations = new List<
                DesignConversionDpoEvaluatedForwardObservation>();
            var ownershipObservations = new List<
                DesignConversionDpoEvaluatedOwnershipObservation>();
            var childOutput = Path.Combine(root, "legacy-child-output");
            var childRuntimeCheckpoint = Path.Combine(
                childOutput,
                "legacy-child-runtime.json");
            var beforeFiles = Directory
                .GetFiles(root, "*", SearchOption.AllDirectories)
                .OrderBy(static path => path, StringComparer.Ordinal)
                .ToArray();
            DesignConversionDpoPolicyCheckpointBridge
                .OptimizerMutationSinkObserverForTesting = mutationSinks.Add;

            var actual = await DesignConversionDpoPolicyCheckpointBridge
                .ExecuteEvaluatedAndConvertAsync(
                    CreateEvaluatedLegalTeacherCapability(),
                    partition,
                    childOutput,
                    "cycle-lineage-legacy-child",
                    childRuntimeCheckpoint,
                    childProvider,
                    new DesignConversionDpoPolicyCheckpointBridgeOptions(1, 1),
                    continuation,
                    forwardObserverForTesting: forwardObservations.Add,
                    ownershipObserverForTesting: ownershipObservations.Add,
                    ct: CancellationToken.None);
            using var unexpectedLease = actual.Value;
            var afterFiles = Directory
                .GetFiles(root, "*", SearchOption.AllDirectories)
                .OrderBy(static path => path, StringComparer.Ordinal)
                .ToArray();

            Assert.False(actual.IsSuccess);
            Assert.Equal(
                DesignConversionCheckpointBackedDpoPolicyBaseProvider
                    .ContinuationContractInvalidErrorCode,
                actual.ErrorCode);
            Assert.Equal(0, childProvider.InvocationCount);
            Assert.Equal(0, childProvider.ContinuationInvocationCount);
            Assert.Empty(mutationSinks);
            Assert.Empty(forwardObservations);
            Assert.Empty(ownershipObservations);
            Assert.False(Directory.Exists(childOutput));
            Assert.Equal(beforeFiles, afterFiles);
        }
        finally
        {
            DesignConversionDpoPolicyCheckpointBridge
                .OptimizerMutationSinkObserverForTesting = previousSinkObserver;
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }

