                    "parent-lineage-with-provider-fresh-reference-mode",
                    child.Publication,
                    validEvaluation with { ReferenceMode = "provider_fresh_step_zero" }),
                (
                    "ordinal",
                    child.Publication,
                    validEvaluation with
                    {
                        CycleAccuracyLineage = validLineage with
                        {
                            CycleOrdinal = validLineage.CycleOrdinal + 1
                        }
                    }),
                (
                    "current-accuracy",
                    child.Publication,
                    validEvaluation with
                    {
                        CycleAccuracyLineage = validLineage with
                        {
                            CurrentMeasuredAccuracy = validLineage.CurrentMeasuredAccuracy == 1d
                                ? 0d
                                : 1d
                        }
                    }),
                (
                    "delta",
                    child.Publication,
                    validEvaluation with
                    {
                        CycleAccuracyLineage = validLineage with
                        {
                            AccuracyDelta = validLineage.AccuracyDelta.GetValueOrDefault() + 0.25d
                        }
                    }),
                (
                    "parent-hash",
                    child.Publication,
                    validEvaluation with
                    {
                        CycleAccuracyLineage = validLineage with
                        {
                            ParentPolicyCheckpointSha256 = Sha256Text("mutated-parent-policy")
                        }
                    })
            };

            foreach (var invalidCase in invalidCases)
            {
                var publication = WithEvaluationAndRecomputedBinding(
                    invalidCase.BasePublication,
                    invalidCase.Evaluation);
                Assert.False(
                    DesignConversionDpoPromotionArtifactContractCodec
                        .ValidateContractPair(
                            publication.SourceEncoderContract,
                            publication.PolicyCheckpointContract),
                    invalidCase.Name);
                Assert.False(
                    DesignConversionDpoPromotionArtifactContractCodec
                        .ValidateEvaluatedArtifactPublication(publication),
                    invalidCase.Name);
                var acquired = DesignConversionDpoPromotionArtifactContractCodec
                    .AcquireValidatedEvaluatedArtifactPublication(publication);
                Assert.False(acquired.IsSuccess);
                Assert.Equal(
                    DesignConversionDpoPromotionArtifactContractCodec.ContractInvalidErrorCode,
                    acquired.ErrorCode);
            }
        }
        finally
        {
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }

    [Fact]
    public async Task EvaluatedBridge_PersistsHeldOutAccuracyIntoRuntimeCheckpointExportMachineAndReload()
    {
        const string heldOutAccuracyEvidence =
            "DESIGN_CONVERSION_DPO_RUNTIME_CHECKPOINT_ACCURACY_FROM_HELDOUT_EVALUATION";
        const string heldOutAccuracyScopeEvidence =
            "DESIGN_CONVERSION_DPO_RUNTIME_CHECKPOINT_ACCURACY_SCOPE_CURRENT_CYCLE_HELDOUT_EVALUATION";
        var root = Path.Combine(
            AppContext.BaseDirectory,
            $"heldout-runtime-accuracy-{Guid.NewGuid():N}");
        var output = Path.Combine(root, "heldout-runtime-accuracy");
        var runtimePath = Path.Combine(output, "runtime.json");
        var ownershipObservations = new List<DesignConversionDpoEvaluatedOwnershipObservation>();
        var partition = BuildEvaluatedPartitionForTests(
            "heldout-runtime-accuracy",
            heldOutCount: 2);

        try
        {
            var evaluated = await DesignConversionDpoPolicyCheckpointBridge
                .ExecuteEvaluatedAndConvertAsync(
                    CreateEvaluatedLegalTeacherCapability(),
                    partition,
                    output,
                    "heldout-runtime-accuracy",
                    runtimePath,
                    new DesignConversionDpoPolicyBaseTestProvider(),
                    new DesignConversionDpoPolicyCheckpointBridgeOptions(1, 1),
                    ownershipObserverForTesting: ownershipObservations.Add,
                    ct: CancellationToken.None);

            Assert.True(
                evaluated.IsSuccess,
                $"{evaluated.ErrorCode}: {evaluated.ErrorMessage}; phases={string.Join(",", ownershipObservations.Select(value => value.Phase))}");
            using var lease = evaluated.Value!;
            var bridge = lease.Result;
            var expectedAccuracy = lease.Evaluation.Accuracy;
            var persistedRuntimePath = Path.Combine(output, bridge.RuntimeCheckpointPath);
            var persistedJson = await File.ReadAllTextAsync(persistedRuntimePath);
            var persistedCheckpoint = JsonSerializer.Deserialize<DesignConversionMachineCheckpoint>(
                persistedJson,
                DesignConversionCheckpointJsonOptions.Standard);
            var reloaded = await DesignConversionMachine.LoadCheckpointAsync(
                persistedRuntimePath,
                CancellationToken.None);
            Assert.True(reloaded.IsSuccess, reloaded.ErrorMessage);
            Assert.Empty(bridge.RuntimeCheckpoint.TrainingHistory);
            Assert.False(DesignConversionMachine.CheckpointHasRealLearnedWeights(
                bridge.RuntimeCheckpoint));
            Assert.Equal(
                0,
                DesignConversionMachine.CountRealLearnedWeightArtifacts(
                    bridge.RuntimeCheckpoint));
            var loadedWeightAuthority = reloaded.Value!.Machine
                .GetLoadedLearnedWeightAuthoritySummary();
            Assert.True(loadedWeightAuthority.DpoPolicyAuthorityLoaded);
            Assert.Equal(0, loadedWeightAuthority.EmbeddedLearnedWeightArtifactCount);
            Assert.Equal(1, loadedWeightAuthority.DpoPolicyLearnedWeightArtifactCount);
            Assert.Equal(
                bridge.BridgePreferenceCount,
                loadedWeightAuthority.DpoPolicyLearnedWeightObservationCount);
            var freshLoadProbe = await DesignConversionLocalFreshLoadProbe
                .VerifyCheckpointFileAsync(persistedRuntimePath);
            Assert.True(freshLoadProbe.IsSuccess, freshLoadProbe.ErrorMessage);
            Assert.True(freshLoadProbe.Value!.MetadataContinuityVerified);
            Assert.False(freshLoadProbe.Value.CheckpointContainsRealTrainedWeights);
            Assert.DoesNotContain(
                "DESIGN_CONVERSION_LOCAL_FRESH_LOAD_REAL_TRAINED_WEIGHTS_VERIFIED",
                freshLoadProbe.Value.EvidenceRefs);
            Assert.Contains(
                "DESIGN_CONVERSION_LOCAL_FRESH_LOAD_DOES_NOT_PROVE_TRAINED_WEIGHTS",
                freshLoadProbe.Value.EvidenceRefs);

            var noLearnedWeightDeltaRecord = Assert.Single(partition.TrainRecords);
            var noLearnedWeightDeltaBatch = new DesignConversionTrainingBatch(
                BatchId: "heldout-runtime-accuracy-no-learned-weight-delta",
                UnitId: noLearnedWeightDeltaRecord.UnitId,
                Records: [noLearnedWeightDeltaRecord],
                TrainingItems:
                [
                     new LearningTrainingItem(
                         ItemId: noLearnedWeightDeltaRecord.RecordId,
                         Prompt: "intentionally-not-json",
                         ChosenResponse: JsonSerializer.Serialize(
                             new Dictionary<string, string>(StringComparer.Ordinal)
                             {
                                 ["html"] = "<main class=\"continued-variant-a\">Continued variant A</main>",
                                 ["css"] = ".continued-variant-a{display:grid;gap:12px;}"
                             }),
                         RejectedResponse: JsonSerializer.Serialize(
                             new Dictionary<string, string>(StringComparer.Ordinal)
                             {
                                 ["html"] = "<main class=\"continued-variant-b\">Continued variant B</main>",
                                 ["css"] = ".continued-variant-b{display:block;}"
                             }))
                ],
                SourceIds: [noLearnedWeightDeltaRecord.Provenance.SourceManifestRef]);
            var continuedProbe = await DesignConversionLegalTeacherCapabilityTestFactory
                .ContinueTrainingStrictAsync(
                    freshLoadProbe.Value,
                    noLearnedWeightDeltaBatch,
                    heldOutRecordIdentityHashes: [],
                    Path.Combine(output, "runtime-no-learned-weight-delta.json"),
                    datasetCountGatePassed: true);
            Assert.True(continuedProbe.IsSuccess, continuedProbe.ErrorMessage);
            Assert.False(continuedProbe.Value!.RealTrainedWeightsContinued);
            Assert.True(continuedProbe.Value.ContinueTrainingMetadataLocalProbeOnly);
            Assert.DoesNotContain(
                "DESIGN_CONVERSION_LOCAL_CONTINUE_TRAINING_LOCAL_LEARNED_WEIGHT_ARTIFACT_UPDATED",
                continuedProbe.Value.EvidenceRefs);
            Assert.Contains(
                "DESIGN_CONVERSION_LOCAL_CONTINUE_TRAINING_REAL_TRAINED_WEIGHTS_NOT_PROVEN",
                continuedProbe.Value.EvidenceRefs);
            var expectedAccuracyValueEvidence =
                $"dpo_runtime_checkpoint_accuracy_value:{expectedAccuracy.ToString("R", System.Globalization.CultureInfo.InvariantCulture)}";
            var expectedHeldOutCountEvidence =
                $"dpo_runtime_checkpoint_accuracy_evaluated_heldout_count:{lease.Evaluation.EvaluatedHeldOutRecordCount.ToString(System.Globalization.CultureInfo.InvariantCulture)}";
            var expectedInputEvidence =
                $"dpo_runtime_checkpoint_accuracy_input_sha256:{lease.Evaluation.HeldOutEvaluationInputSha256}";

            Assert.NotNull(persistedCheckpoint);
            var exportedFromRuntimeMachine = bridge.RuntimeMachine.ExportCheckpoint();
            var exportedFromReloadedMachine = reloaded.Value!.Machine.ExportCheckpoint();
            Assert.True(exportedFromRuntimeMachine.IsSuccess, exportedFromRuntimeMachine.ErrorMessage);
            Assert.True(exportedFromReloadedMachine.IsSuccess, exportedFromReloadedMachine.ErrorMessage);
            Assert.Equal(expectedAccuracy, bridge.RuntimeCheckpoint.AccuracyAfterLastBatch);
            Assert.Equal(expectedAccuracy, bridge.RuntimeExport.AccuracyAtExport);
            Assert.Equal(expectedAccuracy, exportedFromRuntimeMachine.Value!.AccuracyAfterLastBatch);
            Assert.Equal(expectedAccuracy, persistedCheckpoint!.AccuracyAfterLastBatch);
            Assert.Equal(expectedAccuracy, reloaded.Value.Checkpoint.AccuracyAfterLastBatch);
            Assert.Equal(expectedAccuracy, exportedFromReloadedMachine.Value!.AccuracyAfterLastBatch);

            var requiredRuntimeAccuracyEvidence = new[]
            {
                heldOutAccuracyEvidence,
                heldOutAccuracyScopeEvidence,
                expectedAccuracyValueEvidence,
                expectedHeldOutCountEvidence,
                expectedInputEvidence
            };
            var runtimeEvidenceSurfaces = new IReadOnlyList<string>[]
            {
                bridge.RuntimeCheckpoint.EvidenceRefs,
                bridge.EvidenceRefs,
                persistedCheckpoint.EvidenceRefs,
                reloaded.Value.Checkpoint.EvidenceRefs,
                exportedFromRuntimeMachine.Value.EvidenceRefs,
                exportedFromReloadedMachine.Value!.EvidenceRefs
            };
            Assert.All(requiredRuntimeAccuracyEvidence, evidence =>
                Assert.All(runtimeEvidenceSurfaces, evidenceRefs =>
                    Assert.Contains(evidence, evidenceRefs)));
            Assert.All(runtimeEvidenceSurfaces, AssertNoTrainBatchOnlyRuntimeAccuracyEvidence);
            Assert.NotNull(bridge.PolicyCheckpointRef);
            AssertNoHeldOutRuntimeAccuracyEvidence(bridge.PolicyCheckpointRef!.EvidenceRefs);
        }
        finally
        {
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }

    [Fact]
    public async Task ImportedEvaluatedRuntimeEvidence_IsSnapshotAndClearsAfterTrainBatch()
    {
        const string heldOutAccuracyEvidence =
            "DESIGN_CONVERSION_DPO_RUNTIME_CHECKPOINT_ACCURACY_FROM_HELDOUT_EVALUATION";
        const string mutatedEvidenceRef =
            "MUTATED_IMPORTED_EVIDENCE_REF_SHOULD_NOT_EXPORT";
        var root = Path.Combine(
            AppContext.BaseDirectory,
            $"heldout-runtime-accuracy-reset-{Guid.NewGuid():N}");
        var output = Path.Combine(root, "heldout-runtime-accuracy-reset");
        var runtimePath = Path.Combine(output, "runtime.json");

        try
        {
            var evaluated = await DesignConversionDpoPolicyCheckpointBridge
                .ExecuteEvaluatedAndConvertAsync(
                    CreateEvaluatedLegalTeacherCapability(),
                    BuildEvaluatedPartitionForTests("heldout-runtime-accuracy-reset", heldOutCount: 2),
                    output,
                    "heldout-runtime-accuracy-reset",
                    runtimePath,
                    new DesignConversionDpoPolicyBaseTestProvider(),
                    new DesignConversionDpoPolicyCheckpointBridgeOptions(1, 1),
                    ct: CancellationToken.None);

            Assert.True(evaluated.IsSuccess, evaluated.ErrorMessage);
            using var lease = evaluated.Value!;
            var bridge = lease.Result;
            var persistedRuntimePath = Path.Combine(output, bridge.RuntimeCheckpointPath);
            var reloaded = await DesignConversionMachine.LoadCheckpointAsync(
                persistedRuntimePath,
                CancellationToken.None);
            Assert.True(reloaded.IsSuccess, reloaded.ErrorMessage);
            Assert.Contains(heldOutAccuracyEvidence, reloaded.Value!.Checkpoint.EvidenceRefs);

            var mutableSourceEvidence =
                Assert.IsAssignableFrom<IList<string>>(reloaded.Value.Checkpoint.EvidenceRefs);
            var originalFirstEvidenceRef = mutableSourceEvidence[0];
            mutableSourceEvidence[0] = mutatedEvidenceRef;
            var exportedAfterSourceMutation = reloaded.Value.Machine.ExportCheckpoint();
            Assert.True(exportedAfterSourceMutation.IsSuccess, exportedAfterSourceMutation.ErrorMessage);
            Assert.DoesNotContain(mutatedEvidenceRef, exportedAfterSourceMutation.Value!.EvidenceRefs);
            Assert.Contains(originalFirstEvidenceRef, exportedAfterSourceMutation.Value.EvidenceRefs);
            Assert.Contains(heldOutAccuracyEvidence, exportedAfterSourceMutation.Value.EvidenceRefs);

            var train = await DesignConversionLegalTeacherCapabilityTestFactory
                .TrainMachineStrictAsync(
                reloaded.Value.Machine,
                CreateMachineTrainingBatch("heldout-runtime-accuracy-reset-batch"),
                CancellationToken.None);
            Assert.True(train.IsSuccess, train.ErrorMessage);
            var exportedAfterTrain = reloaded.Value.Machine.ExportCheckpoint();
            Assert.True(exportedAfterTrain.IsSuccess, exportedAfterTrain.ErrorMessage);
            Assert.Contains(
                DesignConversionMachine.HeldOutAccuracyNotMeasuredEvidence,
                exportedAfterTrain.Value!.EvidenceRefs);
            Assert.Contains(
                DesignConversionMachine.LocalPreferenceFitSignalOnlyEvidence,
                exportedAfterTrain.Value.EvidenceRefs);
            AssertNoHeldOutRuntimeAccuracyEvidence(exportedAfterTrain.Value.EvidenceRefs);
        }
        finally
        {
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }

    [Fact]
    public async Task ImportedEvaluatedRuntimeEvidence_ClearsAfterSuccessfulEvaluateAsync()
    {
        const string heldOutAccuracyEvidence =
