            Assert.True(evaluate.IsSuccess, evaluate.ErrorMessage);
            var evaluation = evaluate.Value!;
            Assert.Equal(1, evaluation.RowsEvaluated);

            var exportedAfterEvaluate = reloaded.Value.Machine.ExportCheckpoint();
            Assert.True(exportedAfterEvaluate.IsSuccess, exportedAfterEvaluate.ErrorMessage);
            Assert.Contains(
                DesignConversionMachine.EvaluateAsyncHeldOutAccuracyMeasuredEvidence,
                exportedAfterEvaluate.Value!.EvidenceRefs);
            Assert.Contains(
                DesignConversionMachine.EvaluateAsyncSanitizedLocalCheckpointFeatureFitEvidence,
                exportedAfterEvaluate.Value.EvidenceRefs);
            Assert.Contains(
                DesignConversionMachine.EvaluateAsyncNotTrainedVisualQaAuthorityEvidence,
                exportedAfterEvaluate.Value.EvidenceRefs);
            Assert.Contains(
                DesignConversionMachine.DpoPolicyDirectInferenceConfiguredEvidence,
                exportedAfterEvaluate.Value.EvidenceRefs);
            Assert.Contains(
                DesignConversionMachine.DpoPolicyDirectInferenceNoRawPayloadEvidence,
                exportedAfterEvaluate.Value.EvidenceRefs);
            Assert.Equal(evaluation.Accuracy, exportedAfterEvaluate.Value.AccuracyAfterLastBatch);
            Assert.DoesNotContain(
                DesignConversionMachine.HeldOutAccuracyNotMeasuredEvidence,
                exportedAfterEvaluate.Value.EvidenceRefs);
            Assert.DoesNotContain(
                DesignConversionMachine.LocalPreferenceFitSignalOnlyEvidence,
                exportedAfterEvaluate.Value.EvidenceRefs);
            Assert.DoesNotContain(heldOutAccuracyEvidence, exportedAfterEvaluate.Value.EvidenceRefs);
            Assert.DoesNotContain(heldOutAccuracyScopeEvidence, exportedAfterEvaluate.Value.EvidenceRefs);
            AssertNoHeldOutRuntimeAccuracyEvidence(exportedAfterEvaluate.Value.EvidenceRefs);
        }
        finally
        {
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }

    [Fact]
    public async Task DirectBridge_UsesExactDpoInputsWithoutSecondRuntimeOptimizerMutation()
    {

        var root = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString("N"));
        var mutationBoundaries = new List<string>();
        var mutationSinks = new List<
            DesignConversionDpoOptimizerMutationSinkObservation>();
        var previousBoundaryObserver =
            DesignConversionDpoPolicyCheckpointBridge
                .MutationBoundaryObserverForTesting;
        var previousSinkObserver =
            DesignConversionDpoPolicyCheckpointBridge
                .OptimizerMutationSinkObserverForTesting;

        try
        {
            DesignConversionDpoPolicyCheckpointBridge
                .MutationBoundaryObserverForTesting =
                mutationBoundaries.Add;
            DesignConversionDpoPolicyCheckpointBridge
                .OptimizerMutationSinkObserverForTesting = mutationSinks.Add;
            var fixture = await BuildDpoPromotionContractFixtureAsync(
                root,
                "direct-runtime-accuracy-negative");
            var bridge = fixture.Bridge;
            var persistedJson = await File.ReadAllTextAsync(fixture.Paths.RuntimeCheckpointPath);
            var persistedCheckpoint = JsonSerializer.Deserialize<DesignConversionMachineCheckpoint>(
                persistedJson,
                DesignConversionCheckpointJsonOptions.Standard);
            var reloaded = await DesignConversionMachine.LoadCheckpointAsync(
                fixture.Paths.RuntimeCheckpointPath,
                CancellationToken.None);
            var exportedFromRuntimeMachine = bridge.RuntimeMachine.ExportCheckpoint();
            var runtimeAccuracy = bridge.RuntimeCheckpoint.AccuracyAfterLastBatch;

            Assert.NotNull(persistedCheckpoint);
            Assert.True(reloaded.IsSuccess, reloaded.ErrorMessage);
            var exportedFromReloadedMachine = reloaded.Value!.Machine.ExportCheckpoint();
            Assert.True(exportedFromRuntimeMachine.IsSuccess, exportedFromRuntimeMachine.ErrorMessage);
            Assert.True(exportedFromReloadedMachine.IsSuccess, exportedFromReloadedMachine.ErrorMessage);
            Assert.Empty(bridge.RuntimeCheckpoint.TrainingHistory);
            Assert.Equal(runtimeAccuracy, bridge.RuntimeExport.AccuracyAtExport);
            Assert.Equal(runtimeAccuracy, persistedCheckpoint!.AccuracyAfterLastBatch);
            Assert.Equal(runtimeAccuracy, reloaded.Value.Checkpoint.AccuracyAfterLastBatch);
            Assert.Equal(runtimeAccuracy, exportedFromRuntimeMachine.Value!.AccuracyAfterLastBatch);
            Assert.Equal(runtimeAccuracy, exportedFromReloadedMachine.Value!.AccuracyAfterLastBatch);
            Assert.DoesNotContain(
                mutationBoundaries,
                static boundary => boundary.Contains(
                    "runtime_train",
                    StringComparison.Ordinal));
            Assert.Contains(
                mutationSinks,
                static sink => sink.Stage == "standalone_dpo");
            var dpoSink = mutationSinks.Last(
                static sink => sink.Stage == "standalone_dpo");
            Assert.Equal(dpoSink.AdmittedInputs.Count, dpoSink.Batches.Count);
            for (var index = 0; index < dpoSink.Batches.Count; index++)
            {
                var batchProperty = dpoSink.AdmittedInputs[index]
                    .GetType()
                    .GetProperty("Batch");
                Assert.NotNull(batchProperty);
                Assert.Same(
                    dpoSink.Batches[index],
                    batchProperty!.GetValue(dpoSink.AdmittedInputs[index]));
            }
            Assert.Contains(
                DesignConversionMachine.HeldOutAccuracyNotMeasuredEvidence,
                bridge.RuntimeCheckpoint.EvidenceRefs);
            Assert.Contains(
                DesignConversionMachine.LocalPreferenceFitSignalOnlyEvidence,
                bridge.RuntimeCheckpoint.EvidenceRefs);
            AssertNoHeldOutRuntimeAccuracyEvidence(bridge.RuntimeCheckpoint.EvidenceRefs);
            AssertNoHeldOutRuntimeAccuracyEvidence(bridge.EvidenceRefs);
            AssertNoHeldOutRuntimeAccuracyEvidence(bridge.PolicyCheckpointRef!.EvidenceRefs);
            AssertNoHeldOutRuntimeAccuracyEvidence(persistedCheckpoint.EvidenceRefs);
            AssertNoHeldOutRuntimeAccuracyEvidence(reloaded.Value.Checkpoint.EvidenceRefs);
            AssertNoHeldOutRuntimeAccuracyEvidence(exportedFromRuntimeMachine.Value.EvidenceRefs);
            AssertNoHeldOutRuntimeAccuracyEvidence(exportedFromReloadedMachine.Value.EvidenceRefs);
        }
        finally
        {
            DesignConversionDpoPolicyCheckpointBridge
                .MutationBoundaryObserverForTesting = previousBoundaryObserver;
            DesignConversionDpoPolicyCheckpointBridge
                .OptimizerMutationSinkObserverForTesting =
                previousSinkObserver;
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }

    [Theory]
    [InlineData("after-policy")]
    [InlineData("before-runtime-commit")]
    [InlineData("before-load-gate")]
    public async Task DpoPolicyBridge_RuntimePublicationFaultRestoresPriorPointerAndDeletesOwnedSibling(
        string faultStage)
    {
        var root = Path.Combine(Path.GetTempPath(), $"domain-publish-fault-{Guid.NewGuid():N}");
        var output = Path.Combine(root, "training");
        var runtimeDirectory = Path.Combine(root, "runtime");
        var runtimePath = Path.Combine(runtimeDirectory, "runtime.json");
        var priorRuntime = System.Text.Encoding.UTF8.GetBytes("prior-runtime-pointer");
        var records = new[]
        {
            BuildTrainingRecord("publish-fault-improver", DesignConversionDpoUnits.ImproverUnit, 0.99),
            BuildTrainingRecord("publish-fault-critic", DesignConversionDpoUnits.CriticUnit, 0.98)
        };
        try
        {
            Directory.CreateDirectory(runtimeDirectory);
            await File.WriteAllBytesAsync(runtimePath, priorRuntime);
            bool? publicPointerHadPriorBytesAtFault = null;
            DesignConversionDpoPolicyCheckpointBridge.RuntimeTransactionStageObserverForTesting = stage =>
            {
                if (string.Equals(stage, faultStage, StringComparison.Ordinal))
                {
                    var visibleRuntime = File.ReadAllBytes(runtimePath);
                    publicPointerHadPriorBytesAtFault =
                        priorRuntime.AsSpan().SequenceEqual(visibleRuntime);
                    throw new IOException($"injected-{faultStage}");
                }
            };

            var result = await DesignConversionDpoPolicyCheckpointBridge.ExecuteAndConvertAsync(
                CreateEvaluatedLegalTeacherCapability(),
                records, output, "publish-fault", runtimePath,
                new DesignConversionDpoPolicyBaseTestProvider(),
                new DesignConversionDpoPolicyCheckpointBridgeOptions(2, 1));

            Assert.False(result.IsSuccess);
            Assert.Equal("DESIGN_CONVERSION_RUNTIME_CHECKPOINT_WRITE_FAILED", result.ErrorCode);
            Assert.True(publicPointerHadPriorBytesAtFault);
            Assert.Equal(priorRuntime, await File.ReadAllBytesAsync(runtimePath));
            Assert.Empty(Directory.EnumerateFiles(
                output, DpoTrainer.BuildPolicyCheckpointFileName(1), SearchOption.AllDirectories));
            Assert.False(File.Exists(Path.Combine(
                runtimeDirectory,
                DpoTrainer.BuildPolicyCheckpointFileName(1))));
            Assert.Empty(Directory.EnumerateFiles(runtimeDirectory, "*.tmp", SearchOption.TopDirectoryOnly));
        }
        finally
        {
            DesignConversionDpoPolicyCheckpointBridge.RuntimeTransactionStageObserverForTesting = null;
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }

    [Fact]
    public async Task DpoPolicyBridge_RuntimePublicationRejectsImmutableSiblingCollisionWithoutMutation()
    {
        var root = Path.Combine(Path.GetTempPath(), $"domain-publish-collision-{Guid.NewGuid():N}");
        var output = Path.Combine(root, "training");
        var runtimeDirectory = Path.Combine(root, "runtime");
        var runtimePath = Path.Combine(runtimeDirectory, "runtime.json");
        var priorRuntime = System.Text.Encoding.UTF8.GetBytes("prior-runtime-pointer");
        var foreignPolicy = new byte[] { 9, 8, 7, 6 };
        try
        {
            Directory.CreateDirectory(runtimeDirectory);
            await File.WriteAllBytesAsync(runtimePath, priorRuntime);
            var siblingPath = Path.Combine(runtimeDirectory, DpoTrainer.BuildPolicyCheckpointFileName(1));
            await File.WriteAllBytesAsync(siblingPath, foreignPolicy);
            var result = await DesignConversionDpoPolicyCheckpointBridge.ExecuteAndConvertAsync(
                CreateEvaluatedLegalTeacherCapability(),
                [
                    BuildTrainingRecord("collision-improver", DesignConversionDpoUnits.ImproverUnit, 0.99),
                    BuildTrainingRecord("collision-critic", DesignConversionDpoUnits.CriticUnit, 0.98)
                ],
                output, "collision", runtimePath,
                new DesignConversionDpoPolicyBaseTestProvider(),
                new DesignConversionDpoPolicyCheckpointBridgeOptions(2, 1));

            Assert.False(result.IsSuccess);
            Assert.Equal("DESIGN_CONVERSION_DPO_POLICY_CHECKPOINT_COLLISION", result.ErrorCode);
            Assert.Equal(foreignPolicy, await File.ReadAllBytesAsync(siblingPath));
            Assert.Equal(priorRuntime, await File.ReadAllBytesAsync(runtimePath));
            Assert.Empty(Directory.EnumerateFiles(runtimeDirectory, "*.tmp", SearchOption.TopDirectoryOnly));
        }
        finally
        {
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }

    [Fact]
    public async Task DpoPolicyBridge_RuntimePublicationSourceSiblingAliasCleansOwnedSourceOnFailure()
    {
        var root = Path.Combine(Path.GetTempPath(), $"domain-publish-alias-{Guid.NewGuid():N}");
        const string runId = "source-sibling-alias";
        var output = Path.Combine(root, "training");
        var policyDirectory = Path.Combine(output, $"{runId}-dpo-policy-checkpoints");
