        try
        {
            DesignConversionDpoPolicyCheckpointBridge.RuntimeTransactionStageObserverForTesting = stage =>
            {
                if (stage == "after-policy") throw new IOException("injected-alias-failure");
            };
            var result = await DesignConversionDpoPolicyCheckpointBridge.ExecuteAndConvertAsync(
                CreateEvaluatedLegalTeacherCapability(),
                [
                    BuildTrainingRecord("alias-improver", DesignConversionDpoUnits.ImproverUnit, 0.99),
                    BuildTrainingRecord("alias-critic", DesignConversionDpoUnits.CriticUnit, 0.98)
                ],
                output, runId, runtimePath,
