    [DesignConversionDpoRuntimeLeafReparseTheory]
    [InlineData("symlink", "DESIGN_CONVERSION_RUNTIME_PUBLICATION_STATE_UNCERTAIN")]
    [InlineData("identical-physical-replacement", "DESIGN_CONVERSION_RUNTIME_PUBLICATION_STATE_UNCERTAIN")]
    public async Task DpoPolicyBridge_FinalPrecommitIdentityCheckRejectsMutatedRuntimeLeaf(
        string mutation,
        string expectedErrorCode)
    {
        var root = Path.Combine(Path.GetTempPath(), $"domain-runtime-precommit-mutation-{mutation}-{Guid.NewGuid():N}");
        var output = Path.Combine(root, "training");
        var runtimeDirectory = Path.Combine(root, "runtime");
        var runtimePath = Path.Combine(runtimeDirectory, "runtime.json");
        var priorRuntime = System.Text.Encoding.UTF8.GetBytes("prior-runtime-pointer");
        var foreignTargetPath = Path.Combine(root, "foreign-runtime-target.json");
        var replacementPath = Path.Combine(root, "replacement-runtime.json");
        var foreignTarget = System.Text.Encoding.UTF8.GetBytes("foreign-runtime-target");
        try
        {
            Directory.CreateDirectory(runtimeDirectory);
            await File.WriteAllBytesAsync(runtimePath, priorRuntime);
            if (mutation == "symlink")
                await File.WriteAllBytesAsync(foreignTargetPath, foreignTarget);
            else
                await File.WriteAllBytesAsync(replacementPath, priorRuntime);

            DesignConversionDpoPolicyCheckpointBridge.RuntimeTransactionStageObserverForTesting = stage =>
            {
                if (stage != "before-runtime-commit")
                    return;
                File.Delete(runtimePath);
                if (mutation == "symlink")
                    File.CreateSymbolicLink(runtimePath, foreignTargetPath);
                else
                    File.Move(replacementPath, runtimePath);
            };

            var result = await DesignConversionDpoPolicyCheckpointBridge.ExecuteAndConvertAsync(
                CreateEvaluatedLegalTeacherCapability(),
                [
                    BuildTrainingRecord($"{mutation}-improver", DesignConversionDpoUnits.ImproverUnit, 0.99),
                    BuildTrainingRecord($"{mutation}-critic", DesignConversionDpoUnits.CriticUnit, 0.98)
                ],
                output, $"precommit-{mutation}", runtimePath,
                new DesignConversionDpoPolicyBaseTestProvider(),
                new DesignConversionDpoPolicyCheckpointBridgeOptions(2, 1));

            Assert.False(result.IsSuccess);
            // При подмене содержимое осталось прежним, но операционная система сообщает уже
            // о другом файле. Поэтому безопасно считать итог неизвестным: программа не может
            // доказать, что сохранила первоначальный файл.
            Assert.Equal(expectedErrorCode, result.ErrorCode);
            if (mutation == "symlink")
            {
                Assert.True((File.GetAttributes(runtimePath) & FileAttributes.ReparsePoint) != 0);
                Assert.Equal(foreignTarget, await File.ReadAllBytesAsync(foreignTargetPath));
            }
            else
            {
                Assert.Equal(priorRuntime, await File.ReadAllBytesAsync(runtimePath));
                Assert.False(File.Exists(replacementPath));
            }
            Assert.False(File.Exists(Path.Combine(
                runtimeDirectory, DpoTrainer.BuildPolicyCheckpointFileName(1))));
            Assert.Empty(Directory.EnumerateFiles(runtimeDirectory, "*.tmp", SearchOption.TopDirectoryOnly));
        }
        finally
        {
            DesignConversionDpoPolicyCheckpointBridge.RuntimeTransactionStageObserverForTesting = null;
            try { File.Delete(runtimePath); }
            catch (FileNotFoundException) { }
            if (Directory.Exists(root)) Directory.Delete(root, recursive: true);
        }
    }

