    [Fact]
    public async Task DpoPolicyBridge_RuntimePublicationSerializesConcurrentWritersForSamePointer()
    {
        var root = Path.Combine(Path.GetTempPath(), $"domain-publish-concurrent-{Guid.NewGuid():N}");
        var runtimeDirectory = Path.Combine(root, "runtime");
        var runtimePath = Path.Combine(runtimeDirectory, "runtime.json");
        using var releaseFirst = new ManualResetEventSlim(false);
        var firstReached = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
        var secondLockAttempted = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
        var arrivals = 0;
        var lockAttempts = 0;
        var locksAcquired = 0;
        var stages = new ConcurrentQueue<string>();
        var mutexThreadBalance = new ConcurrentDictionary<int, int>();
        var priorRuntimeObserver =
            DesignConversionDpoPolicyCheckpointBridge.RuntimeTransactionStageObserverForTesting;
        var records = new[]
        {
            BuildTrainingRecord("concurrent-improver", DesignConversionDpoUnits.ImproverUnit, 0.99),
            BuildTrainingRecord("concurrent-critic", DesignConversionDpoUnits.CriticUnit, 0.98)
        };
        try
        {
            DesignConversionDpoPolicyCheckpointBridge.RuntimeTransactionStageObserverForTesting = stage =>
            {
                stages.Enqueue(stage);
                if (stage == "before-lock-attempt" &&
                    Interlocked.Increment(ref lockAttempts) == 2)
                    secondLockAttempted.TrySetResult();
                if (stage == "lock-acquired")
                {
                    Interlocked.Increment(ref locksAcquired);
                    mutexThreadBalance.AddOrUpdate(
                        Environment.CurrentManagedThreadId,
                        1,
                        static (_, value) => value + 1);
                }
                if (stage == "before-lock-release")
                {
                    mutexThreadBalance.AddOrUpdate(
                        Environment.CurrentManagedThreadId,
                        -1,
                        static (_, value) => value - 1);
                }
                if (stage == "after-policy" && Interlocked.Increment(ref arrivals) == 1)
                {
                    firstReached.TrySetResult();
                    releaseFirst.Wait(TimeSpan.FromSeconds(10));
                }
            };
            Task<OperationResult<DesignConversionDomain.DesignConversionDpoPolicyRuntimeCheckpointBridgeResult>> StartWriter(
                string writerId) => Task.Run(() =>
                    DesignConversionDpoPolicyCheckpointBridge.ExecuteAndConvertAsync(
                        CreateEvaluatedLegalTeacherCapability(),
                        records,
                        Path.Combine(root, writerId),
                        writerId,
                        runtimePath,
                        new DesignConversionDpoPolicyBaseTestProvider(),
                        new DesignConversionDpoPolicyCheckpointBridgeOptions(2, 1)));

            var first = StartWriter("writer-one");
            await firstReached.Task.WaitAsync(TimeSpan.FromSeconds(10));
            var second = StartWriter("writer-two");
            await secondLockAttempted.Task.WaitAsync(TimeSpan.FromSeconds(10));
            Assert.Equal(1, Volatile.Read(ref arrivals));
            Assert.Equal(1, Volatile.Read(ref locksAcquired));
            Assert.False(second.IsCompleted);
            releaseFirst.Set();
            var results = await Task.WhenAll(first, second).WaitAsync(TimeSpan.FromSeconds(20));

            Assert.True(results[0].IsSuccess, results[0].ErrorMessage);
            // Первая запись завершается до второй. Обе записывают одинаковые данные, поэтому
            // вторая — безопасное повторение. Попытка записать иное содержимое проверяется
            // соседним тестом.
            Assert.True(results[1].IsSuccess, results[1].ErrorMessage);
            Assert.Equal(2, arrivals);
            Assert.Equal(2, locksAcquired);
            Assert.DoesNotContain("mutex-release-failed", stages);
            Assert.NotEmpty(mutexThreadBalance);
            Assert.All(mutexThreadBalance.Values, balance => Assert.Equal(0, balance));
            Assert.True(File.Exists(runtimePath));
            var loaded = await DesignConversionMachine.LoadCheckpointAsync(runtimePath);
            Assert.True(loaded.IsSuccess, loaded.ErrorMessage);
            var checkpointRef = Assert.IsType<DesignConversionDpoPolicyCheckpointRef>(
                loaded.Value!.Checkpoint.DpoPolicyCheckpointRef);
            var siblingPath = Path.Combine(runtimeDirectory, checkpointRef.PolicyCheckpointFileName);
            var siblingBytes = await File.ReadAllBytesAsync(siblingPath);
            Assert.Equal(checkpointRef.PolicyCheckpointByteLength, siblingBytes.LongLength);
            Assert.Equal(
                checkpointRef.Sha256,
                Convert.ToHexString(SHA256.HashData(siblingBytes)).ToLowerInvariant());
            var gate = DesignConversionDpoTrainerRouteBGate.ValidateTypedRuntimeCheckpoint(
                checkpointRef, 1, loaded.Value.Checkpoint.EvidenceRefs, callerFreshLoadVerified: true);
            Assert.True(gate.IsSuccess, gate.ErrorMessage);
            Assert.Empty(Directory.EnumerateFiles(runtimeDirectory, "*.tmp", SearchOption.TopDirectoryOnly));
        }
        finally
        {
            releaseFirst.Set();
            DesignConversionDpoPolicyCheckpointBridge.RuntimeTransactionStageObserverForTesting =
                priorRuntimeObserver;
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }

    [Fact]
    public async Task EvaluatedBridge_CancellationIsObservedBetweenEveryChildAndReferenceForward()
    {
        foreach (var phase in Enum.GetValues<DesignConversionDpoEvaluatedForwardPhase>())
        {
            var root = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString("N"));
            var output = Path.Combine(root, phase.ToString());
            var runtimePath = Path.Combine(output, "runtime.json");
            var observedPhases = new List<DesignConversionDpoEvaluatedForwardPhase>();
            var ownershipPhases = new List<DesignConversionDpoEvaluatedOwnershipPhase>();
            using var cancellation = new CancellationTokenSource();
            var reached = false;
            var evaluated = await DesignConversionDpoPolicyCheckpointBridge
                .ExecuteEvaluatedAndConvertAsync(
                    CreateEvaluatedLegalTeacherCapability(),
                    BuildEvaluatedPartitionForTests($"cancel-{phase}", heldOutCount: 1),
                    output,
                    $"cancel-{phase}",
                    runtimePath,
                    new DesignConversionDpoPolicyBaseTestProvider(),
                    new DesignConversionDpoPolicyCheckpointBridgeOptions(1, 1),
                    forwardObserverForTesting: observation =>
                    {
                        observedPhases.Add(observation.Phase);
                        if (!reached && observation.Phase == phase)
                        {
                            reached = true;
                            cancellation.Cancel();
                        }
                    },
                    ownershipObserverForTesting: observation =>
                    {
                        ownershipPhases.Add(observation.Phase);
                    },
                    ct: cancellation.Token);

            var diagnostic =
                $"phase={phase}; reached={reached}; result_success={evaluated.IsSuccess}; " +
                $"error_code={evaluated.ErrorCode}; error_message={evaluated.ErrorMessage}; " +
                $"observed_phases=[{string.Join(",", observedPhases)}]; " +
                $"ownership_phases=[{string.Join(",", ownershipPhases)}]; output={output}; " +
                $"runtime_path={runtimePath}; runtime_exists={File.Exists(runtimePath)}";
            Assert.True(reached, diagnostic);
            Assert.False(evaluated.IsSuccess, diagnostic);
            Assert.Equal("CANCELLED", evaluated.ErrorCode);
            Assert.False(File.Exists(runtimePath), diagnostic);
        }
    }

    [Fact]
