    [Fact]
    public async Task EvaluatedBridge_PreLeaseAndScratchReplacementCleanupPreservesUnknownIdentity()
    {
        var finalRoot = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString("N"));
        var finalOutput = Path.Combine(finalRoot, "final-replacement");
        byte[]? finalReplacement = null;
        string? finalReplacementPath = null;
        var finalFailure = await DesignConversionDpoPolicyCheckpointBridge
            .ExecuteEvaluatedAndConvertAsync(
                CreateEvaluatedLegalTeacherCapability(),
                BuildEvaluatedPartitionForTests("final-replacement", 1),
                finalOutput,
                "final-replacement",
                Path.Combine(finalOutput, "runtime.json"),
                new DesignConversionDpoPolicyBaseTestProvider(),
                new DesignConversionDpoPolicyCheckpointBridgeOptions(1, 1),
                ownershipObserverForTesting: observation =>
                {
                    if (observation.Phase != DesignConversionDpoEvaluatedOwnershipPhase.AfterFinalPolicyRetained)
                        return;
                    finalReplacementPath = observation.ArtifactPath!;
                    finalReplacement = File.ReadAllBytes(finalReplacementPath);
                    File.Delete(finalReplacementPath);
                    File.WriteAllBytes(finalReplacementPath, finalReplacement);
                },
                ct: CancellationToken.None);
        Assert.False(finalFailure.IsSuccess);
        Assert.NotNull(finalReplacementPath);
        Assert.Equal(finalReplacement, await File.ReadAllBytesAsync(finalReplacementPath!));
        Assert.False(File.Exists(Path.Combine(finalOutput, "runtime.json")));

        var scratchFileRoot = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString("N"));
        string? scratchFileDirectory = null;
        string? scratchReplacementPath = null;
        byte[]? scratchReplacement = null;
        var scratchFileFailure = await DesignConversionDpoPolicyCheckpointBridge
            .ExecuteEvaluatedAndConvertAsync(
                CreateEvaluatedLegalTeacherCapability(),
                BuildEvaluatedPartitionForTests("scratch-file-replacement", 1),
                scratchFileRoot,
                "scratch-file-replacement",
                Path.Combine(scratchFileRoot, "runtime.json"),
                new DesignConversionDpoPolicyBaseTestProvider(),
                new DesignConversionDpoPolicyCheckpointBridgeOptions(1, 1),
                ownershipObserverForTesting: observation =>
                {
                    if (observation.Phase != DesignConversionDpoEvaluatedOwnershipPhase.AfterScratchPolicyRetained)
                        return;
                    scratchFileDirectory = observation.ScratchDirectory;
                    scratchReplacementPath = observation.ArtifactPath!;
                    scratchReplacement = File.ReadAllBytes(scratchReplacementPath);
                    File.Delete(scratchReplacementPath);
                    File.WriteAllBytes(scratchReplacementPath, scratchReplacement);
                },
                ct: CancellationToken.None);
        Assert.False(scratchFileFailure.IsSuccess);
        Assert.True(Directory.Exists(scratchFileDirectory));
        Assert.Equal(scratchReplacement, await File.ReadAllBytesAsync(scratchReplacementPath!));

        var scratchDirectoryRoot = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString("N"));
        string? replacementDirectory = null;
        string? unknownReplacementFile = null;
        var scratchDirectoryFailure = await DesignConversionDpoPolicyCheckpointBridge
            .ExecuteEvaluatedAndConvertAsync(
                CreateEvaluatedLegalTeacherCapability(),
                BuildEvaluatedPartitionForTests("scratch-directory-replacement", 1),
                scratchDirectoryRoot,
                "scratch-directory-replacement",
                Path.Combine(scratchDirectoryRoot, "runtime.json"),
                new DesignConversionDpoPolicyBaseTestProvider(),
                new DesignConversionDpoPolicyCheckpointBridgeOptions(1, 1),
                ownershipObserverForTesting: observation =>
                {
                    if (observation.Phase != DesignConversionDpoEvaluatedOwnershipPhase.AfterScratchPolicyRetained)
                        return;
                    replacementDirectory = observation.ScratchDirectory;
                    Directory.Move(
                        replacementDirectory,
                        replacementDirectory + ".original-owned");
                    Directory.CreateDirectory(replacementDirectory);
                    unknownReplacementFile = Path.Combine(replacementDirectory, "unknown-owner.bin");
                    File.WriteAllBytes(unknownReplacementFile, [9, 8, 7, 6]);
                    throw new IOException("fail after scratch namespace replacement");
                },
                ct: CancellationToken.None);
        Assert.False(scratchDirectoryFailure.IsSuccess);
        Assert.True(Directory.Exists(replacementDirectory));
        Assert.Equal(new byte[] { 9, 8, 7, 6 }, await File.ReadAllBytesAsync(unknownReplacementFile!));
    }

    [Theory]
    [InlineData(1)]
    [InlineData(3)]
    [InlineData(LogicalDpoTrainingUnit.MaximumSupportedMaxStepCount)]
    public async Task EvaluatedBridge_AdoptsEveryTrainerStepArtifactAndRemovesOwnedScratch(int stepCount)
    {
        var root = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString("N"));
        var runtimePath = Path.Combine(root, "runtime.json");
        string? scratchDirectory = null;
        var retainedSteps = new List<int>();
        var evaluated = await DesignConversionDpoPolicyCheckpointBridge
            .ExecuteEvaluatedAndConvertAsync(
                CreateEvaluatedLegalTeacherCapability(),
                BuildEvaluatedPartitionForTests($"scratch-adoption-{stepCount}", 1),
                root,
                $"scratch-adoption-{stepCount}",
                runtimePath,
                new DesignConversionDpoPolicyBaseTestProvider(),
                new DesignConversionDpoPolicyCheckpointBridgeOptions(1, stepCount)
                {
                    DpoConvergenceThreshold = 0f
                },
                ownershipObserverForTesting: observation =>
                {
                    scratchDirectory = observation.ScratchDirectory;
                    if (observation.Phase ==
                        DesignConversionDpoEvaluatedOwnershipPhase.AfterTrainerStepRetained)
                    {
                        retainedSteps.Add(observation.Step);
                    }
                },
                ct: CancellationToken.None);

        Assert.True(evaluated.IsSuccess, evaluated.ErrorMessage);
        using var lease = evaluated.Value!;
        var bridge = lease.Result;
        var finalPolicyFileName = DpoTrainer.BuildPolicyCheckpointFileName(stepCount);
        var finalPolicyPath = Path.Combine(root, finalPolicyFileName);
        Assert.Equal(stepCount, bridge.DpoStepCount);
        Assert.Equal(finalPolicyFileName, bridge.PolicyCheckpointPath);
        Assert.Equal(Path.GetFileName(runtimePath), bridge.RuntimeCheckpointPath);
        Assert.Equal(stepCount, bridge.PolicyCheckpointRef?.DpoStepCount);
        Assert.Equal(finalPolicyFileName, bridge.PolicyCheckpointRef?.PolicyCheckpointFileName);
        Assert.Contains($"dpo_policy_step_count:{stepCount}", bridge.EvidenceRefs);
        Assert.True(File.Exists(finalPolicyPath));
        Assert.True(File.Exists(runtimePath));
        Assert.Equal(Enumerable.Range(1, stepCount), retainedSteps);
        Assert.NotNull(scratchDirectory);
        Assert.False(Directory.Exists(scratchDirectory));
        lease.Dispose();
        Assert.False(File.Exists(finalPolicyPath));
        Assert.False(File.Exists(runtimePath));
    }

    [Fact]
    public async Task EvaluatedBridge_ConvergenceStopsAtActualStepAndBindsFinalArtifacts()
    {
        const int requestedMaxStepCount = 5;
        const int expectedActualStepCount = 3;
        var root = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString("N"));
        var runtimePath = Path.Combine(root, "runtime.json");
        var retainedSteps = new List<int>();
        try
        {
            var evaluated = await DesignConversionDpoPolicyCheckpointBridge
                .ExecuteEvaluatedAndConvertAsync(
                    CreateEvaluatedLegalTeacherCapability(),
                    BuildEvaluatedPartitionForTests("converged-direct-step", 1),
                    root,
                    "converged-direct-step",
                    runtimePath,
                    new DesignConversionDpoPolicyBaseTestProvider(),
                    new DesignConversionDpoPolicyCheckpointBridgeOptions(1, requestedMaxStepCount)
                    {
                        DpoConvergenceThreshold = float.MaxValue,
                        DpoConvergenceWindowSteps = 1
                    },
                    ownershipObserverForTesting: observation =>
                    {
                        if (observation.Phase ==
                            DesignConversionDpoEvaluatedOwnershipPhase.AfterTrainerStepRetained)
                        {
                            retainedSteps.Add(observation.Step);
                        }
                    },
                    ct: CancellationToken.None);

            Assert.True(evaluated.IsSuccess, evaluated.ErrorMessage);
            using var lease = evaluated.Value!;
            var bridge = lease.Result;
            var expectedPolicyFileName = DpoTrainer.BuildPolicyCheckpointFileName(expectedActualStepCount);
            var rejectedMaxPolicyFileName = DpoTrainer.BuildPolicyCheckpointFileName(requestedMaxStepCount);
            Assert.Equal(expectedActualStepCount, bridge.DpoStepCount);
            Assert.Equal(expectedActualStepCount, lease.Evaluation.DpoStepCount);
            Assert.Equal(expectedActualStepCount, bridge.PolicyCheckpointRef?.DpoStepCount);
            Assert.Equal(expectedActualStepCount, bridge.RuntimeCheckpoint.DpoPolicyCheckpointRef?.DpoStepCount);
            Assert.Equal(expectedPolicyFileName, bridge.PolicyCheckpointPath);
            Assert.Equal(expectedPolicyFileName, bridge.PolicyCheckpointRef?.PolicyCheckpointFileName);
            Assert.Equal(expectedPolicyFileName, bridge.RuntimeCheckpoint.DpoPolicyCheckpointRef?.PolicyCheckpointFileName);
            Assert.Equal(bridge.PolicyCheckpointSha256, lease.Evaluation.ChildPolicyCheckpointSha256);
            Assert.Contains($"dpo_policy_step_count:{expectedActualStepCount}", bridge.EvidenceRefs);
            Assert.Contains($"dpo_policy_step_count:{expectedActualStepCount}", bridge.PolicyCheckpointRef!.EvidenceRefs);
            Assert.DoesNotContain($"dpo_policy_step_count:{requestedMaxStepCount}", bridge.EvidenceRefs);
            Assert.DoesNotContain($"dpo_policy_step_count:{requestedMaxStepCount}", bridge.PolicyCheckpointRef.EvidenceRefs);
            Assert.True(File.Exists(Path.Combine(root, expectedPolicyFileName)));
            Assert.False(File.Exists(Path.Combine(root, rejectedMaxPolicyFileName)));
            Assert.True(File.Exists(runtimePath));
            Assert.Equal(Enumerable.Range(1, expectedActualStepCount), retainedSteps);
        }
        finally
        {
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }

