    [Fact]
    public async Task EvaluatedBridge_ScratchReplacementDuringDeleteIsBlockedAndLaterReplacementSurvives()
    {
        var root = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString("N"));
        string? scratchDirectory = null;
        string? replacementFile = null;
        Task? replacementTask = null;
        var replacementWasBlocked = false;
        var evaluated = await DesignConversionDpoPolicyCheckpointBridge
            .ExecuteEvaluatedAndConvertAsync(
                CreateEvaluatedLegalTeacherCapability(),
                BuildEvaluatedPartitionForTests("scratch-delete-race", 1),
                root,
                "scratch-delete-race",
                Path.Combine(root, "runtime.json"),
                new DesignConversionDpoPolicyBaseTestProvider(),
                new DesignConversionDpoPolicyCheckpointBridgeOptions(1, 1),
                ownershipObserverForTesting: observation =>
                {
                    scratchDirectory = observation.ScratchDirectory;
                    if (observation.Phase !=
                        DesignConversionDpoEvaluatedOwnershipPhase.AfterScratchOwnershipCheckBeforeDelete)
                    {
                        return;
                    }

                    try
                    {
                        Directory.Move(observation.ScratchDirectory, observation.ScratchDirectory + ".race-move");
                    }
                    catch (IOException)
                    {
                        replacementWasBlocked = true;
                    }
                    catch (UnauthorizedAccessException)
                    {
                        replacementWasBlocked = true;
                    }

                    replacementTask = Task.Run(async () =>
                    {
                        using var timeout = new CancellationTokenSource(TimeSpan.FromSeconds(10));
                        while (Directory.Exists(observation.ScratchDirectory))
                            await Task.Delay(1, timeout.Token);
                        Directory.CreateDirectory(observation.ScratchDirectory);
                        replacementFile = Path.Combine(observation.ScratchDirectory, "unknown-owner.bin");
                        await File.WriteAllBytesAsync(replacementFile, [4, 3, 2, 1], timeout.Token);
                    });
                },
                ct: CancellationToken.None);

        if (OperatingSystem.IsWindows())
        {
            Assert.True(evaluated.IsSuccess, evaluated.ErrorMessage);
            using var lease = evaluated.Value!;
            Assert.True(replacementWasBlocked);
        }
        else if (OperatingSystem.IsLinux())
        {
            // Linux разрешает переименовать открытый каталог. В таком случае
            // мост обязан отказаться от успеха и сохранить новый чужой каталог,
            // а не удалять его только из-за совпавшего строкового пути.
            Assert.False(evaluated.IsSuccess);
            Assert.False(replacementWasBlocked);
        }
        Assert.NotNull(replacementTask);
        await replacementTask!;
        Assert.NotNull(replacementFile);
        Assert.Equal(new byte[] { 4, 3, 2, 1 }, await File.ReadAllBytesAsync(replacementFile!));
    }

