    [Fact]
    public async Task EvaluatedBridge_AcceptsExplicitSameIdentityStagingToFinalTransitions()
    {
        var root = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString("N"));
        var proofs = new List<DpoTrainerArtifactOwnershipProof>();
        var observations = new List<DesignConversionDpoEvaluatedOwnershipObservation>();
        string? scratchDirectory = null;
        var evaluated = await DesignConversionDpoPolicyCheckpointBridge
            .ExecuteEvaluatedAndConvertAsync(
                CreateEvaluatedLegalTeacherCapability(),
                BuildEvaluatedPartitionForTests("explicit-identity-transition", 1),
                root,
                "explicit-identity-transition",
                Path.Combine(root, "runtime.json"),
                new DesignConversionDpoPolicyBaseTestProvider(),
                new DesignConversionDpoPolicyCheckpointBridgeOptions(1, 1),
                ownershipObserverForTesting: observation =>
                {
                    observations.Add(observation);
                    scratchDirectory = observation.ScratchDirectory;
                    if (observation.TrainerArtifactProof is not null)
                        proofs.Add(observation.TrainerArtifactProof);
                },
                ct: CancellationToken.None);

        Assert.True(
            evaluated.IsSuccess,
            $"{evaluated.ErrorCode}: {evaluated.ErrorMessage}; phases: " +
            string.Join(", ", observations.Select(static observation =>
                $"{observation.Phase}:{Path.GetFileName(observation.ArtifactPath)}:{observation.TrainerArtifactProof?.Kind}")));
        using var lease = evaluated.Value!;
        foreach (var transition in new[]
                 {
                     (Staging: DpoTrainerArtifactKind.PolicyStaging,
                         Final: DpoTrainerArtifactKind.PolicyFinal),
                     (Staging: DpoTrainerArtifactKind.MetricsStaging,
                         Final: DpoTrainerArtifactKind.MetricsFinal)
                 })
        {
            var staging = Assert.Single(proofs, proof => proof.Kind == transition.Staging);
            var final = Assert.Single(proofs, proof => proof.Kind == transition.Final);
            Assert.Equal(staging.Identity, final.Identity);
            Assert.Equal(staging.Length, final.Length);
            Assert.Equal(staging.Sha256, final.Sha256);
            Assert.Equal(staging.Kind, final.TransitionFromKind);
            Assert.Equal(staging.Path, final.TransitionFromPath);
            Assert.Equal(staging.Identity, final.TransitionFromIdentity);
            Assert.NotEqual(staging.Path, final.Path);
        }
        Assert.NotNull(scratchDirectory);
        Assert.False(Directory.Exists(scratchDirectory));
    }

