    [Fact]
    public async Task DpoTrainer_DirectSerializerRetainsTargetAndCreatesNoInnerTemporaryArtifact()
    {
        var inputs = await BuildDirectDpoTrainerInputsAsync("direct-handle-serializer");
        var root = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(root);
        var retainedTargetObserved = false;
        var observedProofs = new List<DpoTrainerArtifactOwnershipProof>();
        var acceptedProofs = new List<DpoTrainerArtifactOwnershipProof>();
        var observer = new DpoTrainerPublicationObserver
        {
            AfterPolicySerializationBeforeProof = stream =>
            {
                retainedTargetObserved = true;
                Assert.Empty(Directory.EnumerateFiles(root, "*.tmp", SearchOption.TopDirectoryOnly));
                Assert.Empty(Directory.EnumerateFiles(root, "*.serialization", SearchOption.TopDirectoryOnly));
                if (OperatingSystem.IsWindows())
                {
                    Assert.ThrowsAny<Exception>(() => File.Delete(stream.Name));
                    Assert.ThrowsAny<Exception>(() => File.Move(stream.Name, stream.Name + ".replacement"));
                    Assert.ThrowsAny<Exception>(() => File.WriteAllBytes(stream.Name, [0xde, 0xad]));
                }
            },
            ArtifactOwnershipProven = proof => observedProofs.Add(proof),
            TryAcceptArtifactOwnership = proof =>
            {
                acceptedProofs.Add(proof);
                return true;
            }
        };
        var trainer = CreateAdmittedTrainer(inputs.Policy, inputs.Reference, root, 1e-5f, observer);

        trainer.StepVector([inputs.Batch], 1);

        Assert.True(retainedTargetObserved);
        Assert.Contains(observedProofs,
            proof => proof.Kind == DpoTrainerArtifactKind.PolicyStaging);
        Assert.Contains(observedProofs,
            proof => proof.Kind == DpoTrainerArtifactKind.PolicyFinal);
        Assert.DoesNotContain(acceptedProofs, proof => proof.Kind is
            DpoTrainerArtifactKind.PolicyStaging or
            DpoTrainerArtifactKind.MetricsStaging);
        Assert.Equal(2, acceptedProofs.Count);
        Assert.Contains(acceptedProofs,
            proof => proof.Kind == DpoTrainerArtifactKind.PolicyFinal);
        Assert.Contains(acceptedProofs,
            proof => proof.Kind == DpoTrainerArtifactKind.MetricsFinal);
        Assert.Empty(Directory.EnumerateFiles(root, "*.tmp", SearchOption.TopDirectoryOnly));
        Assert.Empty(Directory.EnumerateFiles(root, "*.serialization", SearchOption.TopDirectoryOnly));
    }

    [Fact]
    public async Task DpoTrainer_ArtifactOwnershipProofUsesPlatformTaggedHandleIdentity()
    {
        var inputs = await BuildDirectDpoTrainerInputsAsync(
            "platform-tagged-handle-identity");
        var root = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(root);
        var observedProofs = new List<DpoTrainerArtifactOwnershipProof>();
        var acceptedProofs = new List<DpoTrainerArtifactOwnershipProof>();
        var expectedPlatform = OperatingSystem.IsWindows()
            ? DpoTrainerArtifactIdentityPlatform.Windows
            : OperatingSystem.IsLinux()
                ? DpoTrainerArtifactIdentityPlatform.Linux
                : (DpoTrainerArtifactIdentityPlatform?)null;
        var observer = new DpoTrainerPublicationObserver
        {
            ArtifactOwnershipProven = proof => observedProofs.Add(proof),
            TryAcceptArtifactOwnership = proof =>
            {
                acceptedProofs.Add(proof);
                return true;
            }
        };
        var trainer = CreateAdmittedTrainer(
            inputs.Policy,
            inputs.Reference,
            root,
            1e-5f,
            observer);

        if (expectedPlatform is null)
        {
            Assert.Throws<IOException>(() => trainer.StepVector([inputs.Batch], 1));
            return;
        }

        trainer.StepVector([inputs.Batch], 1);

        Assert.All(observedProofs, proof =>
        {
            Assert.Equal(expectedPlatform.Value, proof.Identity.Platform);
            Assert.Equal(1u, proof.LinkCount);
            if (proof.Kind != DpoTrainerArtifactKind.ReservationLock)
                Assert.True(proof.Length > 0);
            Assert.Matches("^[0-9a-f]{64}$", proof.Sha256);
        });
        foreach (var transition in new[]
                 {
                     (Staging: DpoTrainerArtifactKind.PolicyStaging,
                         Final: DpoTrainerArtifactKind.PolicyFinal),
                     (Staging: DpoTrainerArtifactKind.MetricsStaging,
                         Final: DpoTrainerArtifactKind.MetricsFinal)
                 })
        {
            var staging = Assert.Single(
                observedProofs,
                proof => proof.Kind == transition.Staging);
            var final = Assert.Single(
                observedProofs,
                proof => proof.Kind == transition.Final);
            Assert.Equal(staging.Identity, final.Identity);
            Assert.Equal(staging.Sha256, final.Sha256);
            Assert.Equal(staging.Length, final.Length);
            Assert.Equal(staging.Identity, final.TransitionFromIdentity);
        }
        Assert.Equal(
            [DpoTrainerArtifactKind.PolicyFinal,
             DpoTrainerArtifactKind.MetricsFinal],
            acceptedProofs.Select(proof => proof.Kind).ToArray());
    }

    [DesignConversionDpoStorageLinuxFact]
    public async Task DpoTrainer_LinuxNoReplacePublicationKeepsFinalOpenWithRetainedStagingProof()
    {
        var inputs = await BuildDirectDpoTrainerInputsAsync(
            "linux-retained-staging-proof-final-open");
        var root = CreateDpoCheckpointPublicationRootOnTestVolume(
            "linux-retained-staging-proof-final-open");
        var retainedStagingStreams = new List<FileStream>();
        var observedProofs = new List<DpoTrainerArtifactOwnershipProof>();
        var acceptedProofs = new List<DpoTrainerArtifactOwnershipProof>();
        var observer = new DpoTrainerPublicationObserver
        {
            ArtifactOwnershipProven = proof =>
            {
                observedProofs.Add(proof);
                if (proof.Kind is DpoTrainerArtifactKind.PolicyStaging or
                    DpoTrainerArtifactKind.MetricsStaging)
                {
                    // Мост удерживает второй read-дескриптор staging для
                    // доказательства владения; регрессия проверяет именно этот
                    // живой дескриптор, из-за которого File.Move на /mnt/c
                    // делал final-имя временно нечитаемым.
                    retainedStagingStreams.Add(new FileStream(
                        proof.Path,
                        FileMode.Open,
                        FileAccess.Read,
                        FileShare.ReadWrite | FileShare.Delete));
                }
            },
            TryAcceptArtifactOwnership = proof =>
            {
                acceptedProofs.Add(proof);
                return true;
            }
        };
        var trainer = CreateAdmittedTrainer(
            inputs.Policy,
            inputs.Reference,
            root,
            1e-5f,
            observer);

        try
        {
            trainer.StepVector([inputs.Batch], 1);

            Assert.Equal(2, retainedStagingStreams.Count);
            foreach (var transition in new[]
                     {
                         (Staging: DpoTrainerArtifactKind.PolicyStaging,
                             Final: DpoTrainerArtifactKind.PolicyFinal),
                         (Staging: DpoTrainerArtifactKind.MetricsStaging,
                             Final: DpoTrainerArtifactKind.MetricsFinal)
                     })
            {
                var staging = Assert.Single(
                    observedProofs,
                    proof => proof.Kind == transition.Staging);
                var final = Assert.Single(
                    observedProofs,
                    proof => proof.Kind == transition.Final);
                Assert.Equal(staging.Identity, final.Identity);
                Assert.Equal(staging.Sha256, final.Sha256);
                Assert.Equal(staging.Length, final.Length);
                Assert.Equal(staging.Kind, final.TransitionFromKind);
                Assert.Equal(staging.Path, final.TransitionFromPath);
                Assert.Equal(staging.Identity, final.TransitionFromIdentity);
                Assert.Equal(1u, final.LinkCount);
                Assert.False(File.Exists(staging.Path));
                Assert.True(File.Exists(final.Path));
                using var readableFinal = new FileStream(
                    final.Path,
                    FileMode.Open,
                    FileAccess.Read,
                    FileShare.ReadWrite | FileShare.Delete);
                Assert.Equal(final.Length, readableFinal.Length);
            }

            Assert.Equal(
                [DpoTrainerArtifactKind.PolicyFinal,
                 DpoTrainerArtifactKind.MetricsFinal],
                acceptedProofs.Select(proof => proof.Kind).ToArray());
        }
        finally
        {
            foreach (var stream in retainedStagingStreams)
                stream.Dispose();
        }
    }

    [DesignConversionDpoStorageLinuxFact]
    public async Task DpoTrainer_LinuxExistingFinalDestinationFailsClosedAndPreservesForeignBytes()
    {
        var inputs = await BuildDirectDpoTrainerInputsAsync(
            "linux-existing-final-preserved");
        var root = CreateDpoCheckpointPublicationRootOnTestVolume(
            "linux-existing-final-preserved");
        var finalPolicyPath = Path.Combine(
            root,
            DpoTrainer.BuildPolicyCheckpointFileName(1));
        var finalMetricsPath = Path.Combine(
            root,
            DpoTrainer.BuildMetricsFileName(1));
        var foreignBytes = Encoding.UTF8.GetBytes(
            "foreign policy destination must survive no-replace publication");
        var conflictCreatedInsidePublication = false;
        var acceptedProofs = new List<DpoTrainerArtifactOwnershipProof>();
        var observedProofs = new List<DpoTrainerArtifactOwnershipProof>();
        var observer = new DpoTrainerPublicationObserver
        {
            AfterPolicySerializationBeforeProof = _ =>
            {
                // Чужое final-имя появляется после начала шага, чтобы тест
                // попадал в настоящий helper публикации, а не в раннюю подготовку
                // каталога или тестовый MoveArtifactForTesting.
                File.WriteAllBytes(finalPolicyPath, foreignBytes);
                conflictCreatedInsidePublication = true;
            },
            ArtifactOwnershipProven = proof => observedProofs.Add(proof),
            TryAcceptArtifactOwnership = proof =>
            {
                acceptedProofs.Add(proof);
                return true;
            }
        };
        var trainer = CreateAdmittedTrainer(
            inputs.Policy,
            inputs.Reference,
            root,
            1e-5f,
            observer);

        var failure = Assert.Throws<IOException>(() =>
            trainer.StepVector([inputs.Batch], 1));

        Assert.True(conflictCreatedInsidePublication);
        Assert.Contains(
            "DPO_ARTIFACT_PUBLICATION_DESTINATION_EXISTS",
            failure.Message,
            StringComparison.Ordinal);
        Assert.Equal(foreignBytes, await File.ReadAllBytesAsync(finalPolicyPath));
        Assert.False(File.Exists(finalMetricsPath));
        Assert.Contains(
            observedProofs,
            proof => proof.Kind == DpoTrainerArtifactKind.PolicyStaging);
        Assert.DoesNotContain(acceptedProofs, proof => proof.Kind is
            DpoTrainerArtifactKind.PolicyFinal or
            DpoTrainerArtifactKind.MetricsFinal);
    }

