        var trainer = CreateAdmittedTrainer(inputs.Policy, inputs.Reference, root, 1e-5f, observer);

        var failure = Record.Exception(() =>
            trainer.StepVector([inputs.Batch], 1));

        Assert.NotNull(failure);
        Assert.Equal("CheckpointValidationException", failure.GetType().Name);
        Assert.StartsWith(
            "LLM_CHECKPOINT_INCOMPLETE:",
            failure.Message,
            StringComparison.Ordinal);
        Assert.IsType<ObjectDisposedException>(failure.InnerException);
        Assert.Empty(Directory.EnumerateFiles(root, "*.staging", SearchOption.TopDirectoryOnly));
        Assert.Empty(Directory.EnumerateFiles(root, "*.serialization", SearchOption.TopDirectoryOnly));
        Assert.Empty(Directory.EnumerateFiles(root, "*.tmp", SearchOption.TopDirectoryOnly));
        Assert.False(File.Exists(Path.Combine(root, DpoTrainer.BuildPolicyCheckpointFileName(1))));
        Assert.False(File.Exists(Path.Combine(root, DpoTrainer.BuildMetricsFileName(1))));
    }

