    [Theory]
    [InlineData("policy")]
    [InlineData("metrics")]
    public async Task DpoTrainer_RecreatedForeignStagingAfterMoveDoesNotRedirectFinalCustody(
        string artifact)
    {
        if (!OperatingSystem.IsWindows())
            return;
        var inputs = await BuildDirectDpoTrainerInputsAsync(
            $"recreated-{artifact}-staging-after-move");
        var root = Path.Combine(
            Path.GetTempPath(),
            Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(root);
        string? movedStagingPath = null;
        byte[]? byteIdenticalForeign = null;
        var exactFailure = $"fatal after recreating {artifact} staging";
        Action recreateThenFail = () =>
        {
            Assert.NotNull(movedStagingPath);
            var finalPath = Path.Combine(
                root,
                artifact == "policy"
                    ? DpoTrainer.BuildPolicyCheckpointFileName(1)
                    : DpoTrainer.BuildMetricsFileName(1));
            byteIdenticalForeign = File.ReadAllBytes(finalPath);
            File.WriteAllBytes(movedStagingPath!, byteIdenticalForeign);
            throw new OutOfMemoryException(exactFailure);
        };
        var observer = new DpoTrainerPublicationObserver
        {
            ArtifactOwnershipProven = proof =>
            {
                if ((artifact == "policy" &&
                     proof.Kind == DpoTrainerArtifactKind.PolicyStaging) ||
                    (artifact == "metrics" &&
                     proof.Kind == DpoTrainerArtifactKind.MetricsStaging))
                {
                    movedStagingPath = proof.Path;
                }
            },
            AfterPolicyFinalMoveBeforeProofForTesting = artifact == "policy"
                ? recreateThenFail
                : null,
            AfterMetricsFinalMoveBeforeProofForTesting = artifact == "metrics"
                ? recreateThenFail
                : null
        };

        try
        {
            var trainer = CreateAdmittedTrainer(
                inputs.Policy,
                inputs.Reference,
                root,
                1e-5f,
                observer);

            var failure = Assert.Throws<OutOfMemoryException>(() =>
                trainer.StepVector([inputs.Batch], 1));

            Assert.Equal(exactFailure, failure.Message);
            Assert.NotNull(movedStagingPath);
            Assert.NotNull(byteIdenticalForeign);
            Assert.Equal(
                byteIdenticalForeign,
                File.ReadAllBytes(movedStagingPath!));
            Assert.Equal(
                [movedStagingPath!],
                Directory.EnumerateFileSystemEntries(
                        root,
                        "*",
                        SearchOption.TopDirectoryOnly)
                    .ToArray());
        }
        finally
        {
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }

