    [Fact]
    public async Task DpoTrainer_FallbackCleanupDeniesWriterAfterIdentityValidation()
    {
        if (!OperatingSystem.IsWindows())
            return;
        var inputs = await BuildDirectDpoTrainerInputsAsync(
            "fallback-cleanup-writer-denied");
        var root = Path.Combine(
            Path.GetTempPath(),
            Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(root);
        var writerEntered = false;
        var validationObserved = false;
        string? policyStagingPath = null;
        var observer = new DpoTrainerPublicationObserver
        {
            ArtifactOwnershipProven = proof =>
            {
                if (proof.Kind == DpoTrainerArtifactKind.PolicyStaging)
                    policyStagingPath = proof.Path;
            },
            TryAcceptArtifactOwnership = proof =>
                proof.Kind is DpoTrainerArtifactKind.PolicyFinal or
                    DpoTrainerArtifactKind.MetricsFinal,
            MoveArtifactForTesting = (_, _) =>
                throw new IOException("injected move failure"),
            AfterFallbackProofValidationBeforeDeleteForTesting = proof =>
            {
                if (proof.Kind != DpoTrainerArtifactKind.PolicyStaging)
                    return;
                validationObserved = true;
                try
                {
                    using var writer = new FileStream(
                        proof.Path,
                        FileMode.Open,
                        FileAccess.Write,
                        FileShare.Read | FileShare.Write | FileShare.Delete);
                    writerEntered = true;
                }
                catch (IOException)
                {
                }
                catch (UnauthorizedAccessException)
                {
                }
            }
        };

        try
        {
            var trainer = CreateAdmittedTrainer(
                inputs.Policy,
                inputs.Reference,
                root,
                1e-5f,
                observer);

            Assert.Throws<IOException>(() =>
                trainer.StepVector([inputs.Batch], 1));

            Assert.NotNull(policyStagingPath);
            Assert.True(validationObserved);
            Assert.False(writerEntered);
            Assert.Empty(Directory.EnumerateFileSystemEntries(
                root,
                "*",
                SearchOption.TopDirectoryOnly));
        }
        finally
        {
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }

    [Theory]
    [InlineData(DpoTrainerArtifactKind.PolicyStaging)]
    [InlineData(DpoTrainerArtifactKind.ReservationLock)]
    public async Task DefaultTrainer_ProofOnlyCleanupDeniesWriterAfterIdentityValidation(
        DpoTrainerArtifactKind cleanupKind)
    {
        if (!OperatingSystem.IsWindows())
            return;
        var inputs = await BuildDirectDpoTrainerInputsAsync(
            $"proof-only-{cleanupKind}");
        var root = Path.Combine(
            Path.GetTempPath(),
            Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(root);
        var proofs = new List<DpoTrainerArtifactOwnershipProof>();
        var observer = new DpoTrainerPublicationObserver
        {
            TryAcceptArtifactOwnership = proof =>
            {
                proofs.Add(proof);
                return true;
            }
        };
        var priorCleanupObserver = DefaultLogicalCapabilityTrainer
            .DpoProofOnlyCleanupAfterValidationObserverForTesting;

        try
        {
            CreateAdmittedTrainer(
                    inputs.Policy,
                    inputs.Reference,
                    root,
                    1e-5f,
                    observer)
                .StepVector([inputs.Batch], 1);
            var finalProof = Assert.Single(proofs.Where(
                proof => proof.Kind == DpoTrainerArtifactKind.PolicyFinal));
            var cleanupPath = cleanupKind ==
                DpoTrainerArtifactKind.ReservationLock
                ? Path.Combine(root, ".dpo_step_000001.lock")
                : Path.Combine(root, ".policy_step_000001.cleanup.staging");
            File.Move(finalProof.Path, cleanupPath, overwrite: false);
            var cleanupProof = finalProof with
            {
                Kind = cleanupKind,
                Path = cleanupPath
            };
            var writerEntered = false;
            var validationObserved = false;
            DefaultLogicalCapabilityTrainer
                .DpoProofOnlyCleanupAfterValidationObserverForTesting = proof =>
                {
                    Assert.Equal(cleanupPath, proof.Path);
                    validationObserved = true;
                    try
                    {
                        using var writer = new FileStream(
                            proof.Path,
                            FileMode.Open,
                            FileAccess.Write,
                            FileShare.Read | FileShare.Write | FileShare.Delete);
                        writerEntered = true;
                    }
                    catch (IOException)
                    {
                    }
                    catch (UnauthorizedAccessException)
                    {
                    }
                };

            var deleted = DefaultLogicalCapabilityTrainer
                .TryDeleteDpoProofOnlyArtifactForTesting(cleanupProof);

            Assert.True(validationObserved);
            Assert.False(writerEntered);
            Assert.True(deleted);
            Assert.False(File.Exists(cleanupPath));
        }
        finally
        {
            DefaultLogicalCapabilityTrainer
                .DpoProofOnlyCleanupAfterValidationObserverForTesting =
                priorCleanupObserver;
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }

