        Directory.CreateDirectory(root);
        var lockPath = Path.Combine(
            root,
            $".{DpoTrainer.MetricsFilePrefix}000001.lock");
        var identities = new List<DpoTrainerArtifactIdentity>();

        for (var attempt = 0; attempt < 2; attempt++)
        {
            var trainer = CreateAdmittedTrainer(
                inputs.Policy,
                inputs.Reference,
                root,
                1e-5f,
                new DpoTrainerPublicationObserver
                {
                    ArtifactOwnershipProven = proof =>
                    {
                        if (proof.Kind == DpoTrainerArtifactKind.ReservationLock)
                            identities.Add(proof.Identity);
                    },
                    AfterReservationAcquired = () =>
                        throw new IOException("stop after retained reservation proof")
                });

            Assert.Throws<IOException>(() => trainer.StepVector([inputs.Batch], 1));
            Assert.True(File.Exists(lockPath));
        }

        Assert.Equal(2, identities.Count);
        Assert.Equal(identities[0], identities[1]);
        Assert.Equal(DpoTrainerArtifactIdentityPlatform.Linux, identities[0].Platform);
    }

