    [Fact]
    public async Task DpoTrainer_RealByteRangeCollisionRemainsReservationActiveAndReleasesGate()
    {
        if (OperatingSystem.IsMacOS())
            return;
        var inputs = await BuildDirectDpoTrainerInputsAsync("reservation-real-collision");
        var root = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(root);
        var lockPath = Path.Combine(root, $".{DpoTrainer.MetricsFilePrefix}000001.lock");
        using (var external = new FileStream(
                   lockPath,
                   FileMode.OpenOrCreate,
                   FileAccess.ReadWrite,
                   FileShare.ReadWrite | FileShare.Delete))
        {
            if (OperatingSystem.IsLinux())
            {
                // Блокировка `FileStream` внутри одного процесса не доказывает
                // межпроцессную защиту Linux. Поэтому второй независимый
                // дескриптор запрашивает настоящую системную блокировку `flock`.
                var descriptor = checked((int)external.SafeFileHandle
                    .DangerousGetHandle().ToInt64());
                Assert.Equal(
                    0,
                    FlockLinuxForReservationTest(
                        descriptor,
                        LinuxFlockExclusiveForTest |
                        LinuxFlockNonBlockingForTest));
            }
            else
            {
                external.Lock(0, 1);
            }
            var trainer = CreateAdmittedTrainer(inputs.Policy, inputs.Reference, root);

            var failure = Assert.Throws<InvalidOperationException>(() =>
                trainer.StepVector([inputs.Batch], 1));

            Assert.StartsWith(
                DpoTrainer.CheckpointReservationActiveErrorCode,
                failure.Message,
                StringComparison.Ordinal);
            if (OperatingSystem.IsLinux())
            {
                var descriptor = checked((int)external.SafeFileHandle
                    .DangerousGetHandle().ToInt64());
                Assert.Equal(
                    0,
                    FlockLinuxForReservationTest(
                        descriptor,
                        LinuxFlockUnlockForTest));
            }
            else
            {
                external.Unlock(0, 1);
            }
        }

        var retry = CreateAdmittedTrainer(inputs.Policy, inputs.Reference, root);
        retry.StepVector([inputs.Batch], 1);
        if (OperatingSystem.IsLinux())
            Assert.True(File.Exists(lockPath));
    }

    [Theory]
    [InlineData("symlink")]
    [InlineData("hardlink")]
    [InlineData("directory")]
    public async Task DpoTrainer_LinuxReservationSubstitutionFailsClosedAndIsPreserved(
        string substitution)
    {
        if (!OperatingSystem.IsLinux() ||
            RuntimeInformation.ProcessArchitecture != Architecture.X64)
        {
            return;
        }

        var inputs = await BuildDirectDpoTrainerInputsAsync(
            $"linux-reservation-{substitution}");
        var root = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(root);
        var lockPath = Path.Combine(
            root,
            $".{DpoTrainer.MetricsFilePrefix}000001.lock");
        var backingPath = Path.Combine(root, $"{substitution}-foreign.bin");
        var foreignBytes = new byte[] { 0x31, 0x41, 0x59 };

        switch (substitution)
        {
            case "symlink":
                await File.WriteAllBytesAsync(backingPath, foreignBytes);
                File.CreateSymbolicLink(lockPath, backingPath);
                break;
            case "hardlink":
                await File.WriteAllBytesAsync(backingPath, foreignBytes);
                Assert.True(CreateHardLinkForPublicationLease(
                    lockPath,
                    backingPath,
                    IntPtr.Zero));
                break;
            case "directory":
                Directory.CreateDirectory(lockPath);
                break;
            default:
                throw new ArgumentOutOfRangeException(nameof(substitution));
        }

        var trainer = CreateAdmittedTrainer(inputs.Policy, inputs.Reference, root);
        var failure = Assert.Throws<IOException>(() =>
            trainer.StepVector([inputs.Batch], 1));

        Assert.StartsWith(
            DpoTrainer.CheckpointReservationCreateFailedErrorCode,
            failure.Message,
            StringComparison.Ordinal);
        if (substitution == "directory")
        {
            Assert.True(Directory.Exists(lockPath));
        }
        else
        {
            Assert.True(File.Exists(lockPath));
            Assert.Equal(foreignBytes, await File.ReadAllBytesAsync(backingPath));
        }
    }

    [Fact]
    public async Task DpoTrainer_ReservationReleaseFailuresPreservePrimaryAndReleaseGate()
    {
        const string primaryFailure = "primary reservation observer failure";
        var inputs = await BuildDirectDpoTrainerInputsAsync("reservation-release-errors");
        var root = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(root);
        var trainer = CreateAdmittedTrainer(
            inputs.Policy,
            inputs.Reference,
            root,
            1e-5f,
            new DpoTrainerPublicationObserver
            {
                ArtifactOwnershipProven = proof =>
                {
                    if (proof.Kind == DpoTrainerArtifactKind.PolicyStaging)
                        throw new IOException(primaryFailure);
                },
                TryAcceptArtifactOwnership = _ => true,
                BeforeReservationUnlockForTesting = () =>
                    throw new IOException("injected unlock failure"),
                BeforeReservationStreamDisposeForTesting = () =>
                    throw new IOException("injected dispose failure")
            });

        var failure = Assert.Throws<IOException>(() => trainer.StepVector([inputs.Batch], 1));

        Assert.Equal(primaryFailure, failure.Message);
        var cleanupFailure = Assert.IsType<IOException>(
            failure.Data["DPO_CLEANUP_FAILURE"]);
        Assert.StartsWith(
            DpoTrainer.CheckpointReservationReleaseFailedErrorCode,
            cleanupFailure.Message,
            StringComparison.Ordinal);
        var retry = CreateAdmittedTrainer(inputs.Policy, inputs.Reference, root);
        retry.StepVector([inputs.Batch], 1);
    }

    [Theory]
    [InlineData("unlock")]
    [InlineData("dispose")]
    public async Task DpoTrainer_SuccessfulPublicationReleaseFailureFailsStepAndReleasesGate(
        string failingPhase)
    {
        var inputs = await BuildDirectDpoTrainerInputsAsync($"successful-release-{failingPhase}");
        var root = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(root);
        var observer = new DpoTrainerPublicationObserver
        {
            BeforeReservationUnlockForTesting = failingPhase == "unlock"
                ? () => throw new IOException("injected successful unlock failure")
                : null,
            BeforeReservationStreamDisposeForTesting = failingPhase == "dispose"
                ? () => throw new IOException("injected successful dispose failure")
                : null
        };
        var trainer = CreateAdmittedTrainer(inputs.Policy, inputs.Reference, root, 1e-5f, observer);

        var failure = Assert.Throws<IOException>(() => trainer.StepVector([inputs.Batch], 1));

        Assert.StartsWith(
            DpoTrainer.CheckpointReservationReleaseFailedErrorCode,
            failure.Message,
            StringComparison.Ordinal);
        Assert.True(File.Exists(Path.Combine(root, DpoTrainer.BuildPolicyCheckpointFileName(1))));
        Assert.True(File.Exists(Path.Combine(root, DpoTrainer.BuildMetricsFileName(1))));
        var retry = CreateAdmittedTrainer(inputs.Policy, inputs.Reference, root);
        var collision = Assert.Throws<InvalidOperationException>(() =>
            retry.StepVector([inputs.Batch], 1));
        Assert.StartsWith(
            DpoTrainer.CheckpointCollisionErrorCode,
            collision.Message,
            StringComparison.Ordinal);
        Assert.DoesNotContain(
            DpoTrainer.CheckpointReservationActiveErrorCode,
            collision.Message,
            StringComparison.Ordinal);
    }

    [Fact]
    public async Task EvaluatedBridge_ExcessUnknownInventoryCannotPreventOwnedLeafCleanup()
    {
        var root = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString("N"));
        string? scratchDirectory = null;
        var injected = false;
        var evaluated = await DesignConversionDpoPolicyCheckpointBridge
            .ExecuteEvaluatedAndConvertAsync(
                CreateEvaluatedLegalTeacherCapability(),
                BuildEvaluatedPartitionForTests("excess-unknown-inventory", 1),
                root,
                "excess-unknown-inventory",
                Path.Combine(root, "runtime.json"),
                new DesignConversionDpoPolicyBaseTestProvider(),
                new DesignConversionDpoPolicyCheckpointBridgeOptions(1, 1),
                ownershipObserverForTesting: observation =>
                {
                    if (injected || observation.Phase !=
                        DesignConversionDpoEvaluatedOwnershipPhase.AfterTrainerStepRetained)
                        return;
                    injected = true;
                    scratchDirectory = observation.ScratchDirectory;
                    for (var index = 0; index < 6000; index++)
                        File.WriteAllBytes(
                            Path.Combine(observation.ScratchDirectory, $"unknown-{index:D5}.bin"),
                            [1]);
                    throw new IOException("stop after excessive unknown inventory");
                },
                ct: CancellationToken.None);

        Assert.False(evaluated.IsSuccess);
        Assert.NotNull(scratchDirectory);
        Assert.Equal(6000, Directory.EnumerateFiles(scratchDirectory!, "unknown-*.bin").Count());
        Assert.Empty(Directory.EnumerateFiles(scratchDirectory!, "dpo_*", SearchOption.TopDirectoryOnly));
        Assert.Empty(Directory.EnumerateFiles(scratchDirectory!, "*.lock", SearchOption.TopDirectoryOnly));
        Assert.Empty(Directory.EnumerateFiles(scratchDirectory!, "*.serialization", SearchOption.TopDirectoryOnly));
        Assert.Empty(Directory.EnumerateFiles(scratchDirectory!, "*.staging", SearchOption.TopDirectoryOnly));
    }

