    [Fact]
    public async Task CanonicalComparativeFloorCannotBeLoweredAndStricterConfiguredThresholdOnlyVetoes()
    {
        const double canonicalComparativeThreshold = 0.55d;
        const string thresholdAuthority =
            "canonical_g3_baseline_win_rate_floor";
        const string thresholdEvidence =
            "DESIGN_CONVERSION_EVALUATED_DPO_PROMOTION_THRESHOLD_FROM_CANONICAL_G3_BASELINE_WIN_RATE";
        var callerThresholds = new[] { 0.10d, 0.95d };

        foreach (var callerThreshold in callerThresholds)
        {
            var thresholdToken = callerThreshold.ToString(
                "0.00",
                System.Globalization.CultureInfo.InvariantCulture).Replace('.', '-');
            var id = $"evaluated-promotion-threshold-{thresholdToken}";
            var root = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString("N"), id);
            Directory.CreateDirectory(root);
            try
            {
                var fixture = await BuildW085DeterministicPromotionReadyIntakeFixtureAsync(
                    root,
                    id);
                var baseCallerRequest = BuildPassingMeasurementGateRequest($"{id}-gate");
                var callerRequest = baseCallerRequest with
                {
                    HeldOutMetrics = baseCallerRequest.HeldOutMetrics with
                    {
                        HeldOutQualityScore = 1d
                    },
                    Thresholds = baseCallerRequest.Thresholds with
                    {
                        RequiredHeldOutQualityScore = callerThreshold
                    }
                };
                var options = fixture.Options with
                {
                    RunId = $"{id}-run",
                    MeasurementGateRequest = callerRequest
                };
                var callerRequestBefore = System.Text.Json.JsonSerializer.Serialize(
                    callerRequest,
                    DesignConversionCheckpointJsonOptions.Standard);
                var uploader = new CountingLocalOnlyPromotionUploader();
                var db = new JsonlDesignConversionLocalArtifactDb(
                    root,
                    CreateEvaluatedLegalTeacherCapability(),
                    CreateW085DeterministicPromotionProvider(),
                    uploader,
                    uploader.Authority);

                var promoted = await DesignConversionTrainingIntakeRouteAdmissionContext.RunAsync(
                    BuildLocalPromotionAdmission(id),
                    () => db.RunTrainingIntakeAndPromoteLocalAsync(
                        fixture.Intake.IntakeId,
                        Path.Combine(root, "promotion"),
                        options));

                Assert.True(promoted.IsSuccess, promoted.ErrorMessage);
                var value = promoted.Value!;
                var report = Assert.IsType<DesignConversionPromotionGateReport>(
                    uploader.LastGateReport);
                var callerRequestAfter = System.Text.Json.JsonSerializer.Serialize(
                    callerRequest,
                    DesignConversionCheckpointJsonOptions.Standard);
                Assert.Equal(callerRequestBefore, callerRequestAfter);
                Assert.Equal(callerThreshold, callerRequest.Thresholds.RequiredHeldOutQualityScore);
                Assert.Equal(1, uploader.Count);
                Assert.NotNull(value.Publication);
                Assert.True(value.LocalPromotionReady);
                Assert.Equal(1d, report.HeldOutScore);
                Assert.Equal(
                    1d,
                    double.Parse(
                        value.TrainingRun.BoundaryMetadata["evaluated_dpo_accuracy"],
                        System.Globalization.CultureInfo.InvariantCulture));
                var expectedEffectiveThreshold = Math.Max(
                    callerThreshold,
                    canonicalComparativeThreshold);
                Assert.Equal(expectedEffectiveThreshold, report.RequiredHeldOutScore);
                Assert.Equal(
                    expectedEffectiveThreshold,
                    double.Parse(
                        value.TrainingRun.BoundaryMetadata["evaluated_dpo_required_accuracy"],
                        System.Globalization.CultureInfo.InvariantCulture));
                Assert.Equal(
                    expectedEffectiveThreshold.ToString(
                        "0.######",
                        System.Globalization.CultureInfo.InvariantCulture),
                    value.TrainingRun.BoundaryMetadata["evaluated_dpo_required_accuracy"]);
                Assert.Equal(
                    thresholdAuthority,
                    value.TrainingRun.BoundaryMetadata["evaluated_dpo_required_accuracy_authority"]);
                Assert.Equal(
                    report.HeldOutScore,
                    double.Parse(
                        value.TrainingRun.BoundaryMetadata["evaluated_dpo_accuracy"],
                        System.Globalization.CultureInfo.InvariantCulture));
                Assert.Contains(thresholdEvidence, report.EvidenceRefs);
                Assert.Contains(thresholdEvidence, value.EvidenceRefs);
                Assert.Contains(thresholdEvidence, value.TrainingRun.RunnerEvidence!.EvidenceRefs);
                Assert.Equal(
                    bool.FalseString,
                    value.TrainingRun.BoundaryMetadata["product_ready"]);
                var authoritySurface = string.Join(
                    "\n",
                    value.EvidenceRefs
                        .Concat(value.TrainingRun.RunnerEvidence.EvidenceRefs)
                        .Concat(report.EvidenceRefs)
                        .Concat(value.TrainingRun.BoundaryMetadata
                            .Select(entry => $"{entry.Key}={entry.Value}")));
                Assert.DoesNotContain("g3_active", authoritySurface, StringComparison.OrdinalIgnoreCase);
                Assert.DoesNotContain(
                    DesignConversionG3AcceptancePolicy.EligibleReason,
                    authoritySurface,
                    StringComparison.OrdinalIgnoreCase);
                Assert.DoesNotContain("product_ready=true", authoritySurface, StringComparison.OrdinalIgnoreCase);
            }
            finally
            {
                if (Directory.Exists(root))
                    Directory.Delete(root, recursive: true);
            }
        }
    }

