                BoundaryMetadata = legacyMetadata
            };
            var legacySha = JsonlDesignConversionLocalArtifactDb
                .BuildLocalPromotionFinalResultSha256(legacyRecord);
            legacyMetadata["local_promotion_committed_snapshot_sha256"] =
                legacySha;
            legacyRecord = legacyRecord with
            {
                BoundaryMetadata = legacyMetadata
            };
            operationRecords[preparedIndex] = prepared with
            {
                FinalResult = legacyRecord,
                FinalResultSha256 = legacySha
            };
            operationRecords[committedIndex] = operationRecords[committedIndex] with
            {
                FinalResultSha256 = legacySha
            };
            operationRecords =
                RelinkLocalPromotionOperationRecords(operationRecords).ToArray();
            await WriteLocalPromotionOperationRecordsAsync(
                operationPath,
