                admission,
                () => replayDb.RunTrainingIntakeAndPromoteLocalAsync(
                    fixture.Intake.IntakeId,
                    output,
                    options));

            Assert.False(replay.IsSuccess);
            Assert.Equal(replayConflictCode, replay.ErrorCode);
            Assert.Equal(0, replayProvider.InvocationCount);
            Assert.Equal(0, replayActivationCount);
            Assert.Equal(
                legacyJournalBeforeReplay,
                await File.ReadAllBytesAsync(journalPath));
            Assert.Equal(
                legacyOperationJournalBeforeReplay,
                await File.ReadAllBytesAsync(operationPath));
            Assert.Equal(
                artifactsBeforeReplay,
                await ReadFileSha256SnapshotAsync(output));
        }
        finally
        {
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }

    [Fact]
    public async Task EvaluatedTrainingState_RemovesOnlyRegisteredProjectionAndPreservesAuthoritativeBlockers()
    {
        var root = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString("N"));
        var fixture = await BuildInlineContentPromotionReadyIntakeFixtureAsync(
            root,
            "current-threshold-policy-replay");
        var baseline = await new JsonlDesignConversionLocalArtifactDb(
                root,
                legalTeacherAdmissionAuthority: CreateEvaluatedLegalTeacherCapability())
            .RunTrainingIntakeAsync(fixture.Intake.IntakeId, fixture.Options);
        Assert.True(baseline.IsSuccess, baseline.ErrorMessage);
        var original = baseline.Value!;
        var authoritativeCompositeFailures = new[]
        {
            "HELD_OUT_PRIVACY_FAILURE",
            "SOURCE_DISJOINT_LEAKAGE_DETECTED",
            "FRESH_LOAD_CHECKPOINT_INTEGRITY_FAILED",
            "HELD_OUT_TRAINING_FAILURE",
            "FRESH_LOAD_FATAL",
            "MODEL_UPLOAD_FAILED",
            "DESIGN_CONVERSION_CONTINUE_TRAINING_HELD_OUT_RECORD_USAGE_DETECTED",
            "DESIGN_CONVERSION_CONTINUE_TRAINING_FRESH_LOAD_METADATA_MISMATCH",
            "DESIGN_CONVERSION_PROMOTION_UPLOAD_TIMEOUT",
            "DESIGN_CONVERSION_PROMOTION_UPLOAD_ABORTED",
            "CHECKPOINT_BINDING_MISMATCH",
            "PRIVACY_SIGNAL_DETECTED",
            "HELD_OUT_SCORE:PRIVACY_FAILURE",
            "source-disjoint-proof-missing",
            "held out score",
            "runner-blocked-reason",
            "HELD_OUT_SCORE:-",
            "HELD_OUT_RECORD_COUNT:<>",
            "HELD_OUT_SCORE:/",
            "HELD_OUT_SCORE:...",
            " HELD_OUT_SCORE:0.5",
            "held_OUT_SCORE:0.5",
            "UNREGISTERED_HELD_OUT_HINT"
        };
        var validNumericProjections = new[]
        {
            "held_out_score:0.01",
            "HELD_OUT_SCORE:-1.25e-2",
            "HELD_OUT_SCORE:>=+1.2E3",
            "HELD_OUT_SCORE:-1..+2",
            "HELD_OUT_RECORD_COUNT:1/2"
        };
        var staleMetadata = new Dictionary<string, string>(
            original.BoundaryMetadata,
            StringComparer.Ordinal)
        {
            ["held_out_score"] = "0.01",
            ["held_out_quality_score"] = "0.01",
            ["held_out_record_count"] = "0",
            ["source_disjoint_proof"] = "missing",
            ["training_execution_status"] = "caller-low-status",
            ["runner_blocked_reason"] = "HELD_OUT_RECORD_COUNT_BELOW_MINIMUM",
            ["block_reason_count"] = "999"
        };
        var staleLow = original with
        {
            ModelUploadReady = false,
            MeasurementGateStatus = DesignConversionMeasurementGateStatus.Failed,
            TrainingExecutionStatus = "caller-low-status",
            RunnerBlockedReason = "HELD_OUT_QUALITY_SCORE_BELOW_THRESHOLD",
            BlockReasons = (original.BlockReasons ?? [])
                .Append("HELD_OUT_QUALITY_SCORE_BELOW_THRESHOLD:0.01<0.9")
                .Append("HELD_OUT_RECORD_COUNT_BELOW_MINIMUM:0<1")
                .Append("SOURCE_DISJOINT_PROOF_MISSING")
                .Concat(authoritativeCompositeFailures)
                .ToArray(),
            Warnings = (original.Warnings ?? [])
                .Concat(validNumericProjections)
                .Append("HELD_OUT_MEASUREMENT_NOT_RUN")
                .Append("SOURCE_DISJOINT_PROOF_MISSING")
                .Append("training_execution_status:caller-low-status")
                .ToArray(),
            RunnerEvidence = original.RunnerEvidence! with
            {
                MeasurementGateStatus = DesignConversionMeasurementGateStatus.Failed,
                PromotionUploadAllowed = false,
                FailureReasons = (original.RunnerEvidence.FailureReasons ?? [])
                    .Append("HELD_OUT_QUALITY_SCORE_BELOW_THRESHOLD:0.01<0.9")
                    .Append("HELD_OUT_RECORD_COUNT_BELOW_MINIMUM:0<1")
                    .Append("SOURCE_DISJOINT_PROOF_MISSING")
                    .ToArray(),
                Warnings = (original.RunnerEvidence.Warnings ?? [])
                    .Concat(validNumericProjections)
                    .Append("HELD_OUT_MEASUREMENT_NOT_RUN")
                    .ToArray()
            },
            BoundaryMetadata = staleMetadata
        };

        var actualPass = JsonlDesignConversionLocalArtifactDb.ApplyEvaluatedTrainingRun(
            staleLow,
            BuildHeldOutEvaluationForTests("stale-low-actual-pass", correctCount: 1, heldOutCount: 1),
            requiredAccuracy: 0.9d);
        var passText = System.Text.Json.JsonSerializer.Serialize(actualPass);
        Assert.False(actualPass.ModelUploadReady);
        Assert.NotEqual("none", actualPass.RunnerBlockedReason);
        Assert.Equal(DesignConversionMeasurementGateStatus.Failed, actualPass.MeasurementGateStatus);
        Assert.Equal("False", actualPass.BoundaryMetadata["model_upload_ready"]);
        Assert.Equal("True", actualPass.BoundaryMetadata["model_upload_not_ready"]);
        Assert.Equal(
            actualPass.BlockReasons.Count.ToString(System.Globalization.CultureInfo.InvariantCulture),
            actualPass.BoundaryMetadata["block_reason_count"]);
        Assert.DoesNotContain("HELD_OUT_QUALITY_SCORE_BELOW_THRESHOLD", passText, StringComparison.OrdinalIgnoreCase);
        Assert.DoesNotContain("HELD_OUT_RECORD_COUNT_BELOW_MINIMUM", passText, StringComparison.OrdinalIgnoreCase);
        Assert.DoesNotContain("HELD_OUT_MEASUREMENT_NOT_RUN", passText, StringComparison.OrdinalIgnoreCase);
        Assert.DoesNotContain("SOURCE_DISJOINT_PROOF_MISSING", passText, StringComparison.OrdinalIgnoreCase);
        foreach (var projection in validNumericProjections)
            Assert.DoesNotContain(projection, passText, StringComparison.Ordinal);
        foreach (var composite in authoritativeCompositeFailures)
            Assert.Contains(composite, actualPass.BlockReasons);
        Assert.Equal(
            actualPass.TrainingExecutionStatus,
            actualPass.RunnerEvidence!.TrainingExecutionStatus);
        Assert.Equal(actualPass.RunnerBlockedReason, actualPass.RunnerEvidence.RunnerBlockedReason);

        var staleHighMetadata = new Dictionary<string, string>(
            original.BoundaryMetadata,
            StringComparer.Ordinal)
        {
            ["held_out_score"] = "1",
            ["heldout_quality"] = "1",
            ["held_out_record_count"] = "999",
            ["source_disjoint_proof"] = "passed"
        };
        var staleHigh = original with
        {
            ModelUploadReady = true,
            MeasurementGateStatus = DesignConversionMeasurementGateStatus.Passed,
            BlockReasons = [],
            Warnings = (original.Warnings ?? [])
                .Append("held_out_score:1")
                .Append("HELD_OUT_RECORD_COUNT_PASSED:999")
                .Append("SOURCE_DISJOINT_PROOF_PASSED")
                .ToArray(),
            BoundaryMetadata = staleHighMetadata
        };
        var actualFail = JsonlDesignConversionLocalArtifactDb.ApplyEvaluatedTrainingRun(
            staleHigh,
            BuildHeldOutEvaluationForTests("stale-high-actual-fail", correctCount: 0, heldOutCount: 1),
            requiredAccuracy: 0.9d);
        Assert.False(actualFail.ModelUploadReady);
        Assert.Equal(DesignConversionMeasurementGateStatus.Failed, actualFail.MeasurementGateStatus);
        Assert.Contains("evaluated_dpo_heldout_accuracy_below_threshold", actualFail.BlockReasons);
        Assert.Equal("0", actualFail.BoundaryMetadata["evaluated_dpo_accuracy"]);
        var failText = System.Text.Json.JsonSerializer.Serialize(actualFail);
        Assert.DoesNotContain("held_out_score", failText, StringComparison.OrdinalIgnoreCase);
        Assert.DoesNotContain("HELD_OUT_RECORD_COUNT_PASSED", failText, StringComparison.OrdinalIgnoreCase);
        Assert.DoesNotContain("SOURCE_DISJOINT_PROOF_PASSED", failText, StringComparison.OrdinalIgnoreCase);
    }

    [Fact]
    public async Task EvaluatedTrainingState_ProjectsAuthoritativeCycleLineageAndClearsForgedCallerState()
    {
        var root = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString("N"));
        var fixture = await BuildPromotionReadyIntakeFixtureAsync(root, "cycle-lineage-state");
        var baseline = await new JsonlDesignConversionLocalArtifactDb(
                root,
                legalTeacherAdmissionAuthority: CreateEvaluatedLegalTeacherCapability())
            .RunTrainingIntakeAsync(fixture.Intake.IntakeId, fixture.Options);
        Assert.True(baseline.IsSuccess, baseline.ErrorMessage);
        var original = baseline.Value!;
        var parentEvaluation = BuildHeldOutEvaluationForTests(
            "cycle-lineage-parent",
            correctCount: 1,
            heldOutCount: 1);

        var cold = JsonlDesignConversionLocalArtifactDb.ApplyEvaluatedTrainingRun(
            WithForgedCycleCallerState(original),
            parentEvaluation,
            requiredAccuracy: 0.9d);
        AssertNoForgedCycleProjection(cold);
        Assert.Equal("1", cold.BoundaryMetadata["evaluated_dpo_cycle_ordinal"]);
        Assert.Equal("1", cold.BoundaryMetadata["evaluated_dpo_cycle_current_measured_accuracy"]);
        Assert.Equal(bool.FalseString, cold.BoundaryMetadata["evaluated_dpo_cycle_has_parent"]);
        Assert.Equal("cold_baseline", cold.BoundaryMetadata["evaluated_dpo_cycle_comparison_status"]);
        Assert.False(cold.BoundaryMetadata.ContainsKey("evaluated_dpo_cycle_parent_ordinal"));
        Assert.False(cold.BoundaryMetadata.ContainsKey("evaluated_dpo_cycle_parent_measured_accuracy"));
        Assert.False(cold.BoundaryMetadata.ContainsKey("evaluated_dpo_cycle_parent_policy_checkpoint_sha256"));
        Assert.False(cold.BoundaryMetadata.ContainsKey("evaluated_dpo_cycle_parent_dataset_id"));
        Assert.False(cold.BoundaryMetadata.ContainsKey("evaluated_dpo_cycle_parent_heldout_record_set_sha256"));
        Assert.False(cold.BoundaryMetadata.ContainsKey("evaluated_dpo_cycle_parent_heldout_source_set_sha256"));
        Assert.False(cold.BoundaryMetadata.ContainsKey("evaluated_dpo_cycle_parent_heldout_evaluation_input_sha256"));
        Assert.False(cold.BoundaryMetadata.ContainsKey("evaluated_dpo_cycle_accuracy_delta"));
        Assert.Contains(
            "evaluated_dpo_cycle_comparison_status:cold_baseline",
            cold.Warnings);
        Assert.Contains(
            "DESIGN_CONVERSION_DPO_CYCLE_COLD_BASELINE",
            cold.RunnerEvidence!.EvidenceRefs);

        var comparableEvaluation = BuildContinuationEvaluation(
            "cycle-lineage-comparable-child",
            parentEvaluation,
            comparableHeldOut: true,
            mutateHeldOutFingerprints: false,
            suppliedDelta: -0.5d);
        var comparable = JsonlDesignConversionLocalArtifactDb.ApplyEvaluatedTrainingRun(
            WithForgedCycleCallerState(original),
            comparableEvaluation,
            requiredAccuracy: 0d);
        AssertNoForgedCycleProjection(comparable);
        Assert.Equal("2", comparable.BoundaryMetadata["evaluated_dpo_cycle_ordinal"]);
        Assert.Equal("0.5", comparable.BoundaryMetadata["evaluated_dpo_cycle_current_measured_accuracy"]);
        Assert.Equal(bool.TrueString, comparable.BoundaryMetadata["evaluated_dpo_cycle_has_parent"]);
        Assert.Equal("comparable_continuation", comparable.BoundaryMetadata["evaluated_dpo_cycle_comparison_status"]);
        Assert.Equal("1", comparable.BoundaryMetadata["evaluated_dpo_cycle_parent_ordinal"]);
        Assert.Equal("1", comparable.BoundaryMetadata["evaluated_dpo_cycle_parent_measured_accuracy"]);
        Assert.Equal(
            parentEvaluation.ChildPolicyCheckpointSha256,
            comparable.BoundaryMetadata["evaluated_dpo_cycle_parent_policy_checkpoint_sha256"]);
        Assert.Equal(
            parentEvaluation.DatasetId,
            comparable.BoundaryMetadata["evaluated_dpo_cycle_parent_dataset_id"]);
        Assert.Equal(
            parentEvaluation.HeldOutRecordSetSha256,
            comparable.BoundaryMetadata["evaluated_dpo_cycle_parent_heldout_record_set_sha256"]);
        Assert.Equal(
            parentEvaluation.HeldOutSourceSetSha256,
            comparable.BoundaryMetadata["evaluated_dpo_cycle_parent_heldout_source_set_sha256"]);
        Assert.Equal(
            parentEvaluation.HeldOutEvaluationInputSha256,
            comparable.BoundaryMetadata["evaluated_dpo_cycle_parent_heldout_evaluation_input_sha256"]);
        Assert.Equal("-0.5", comparable.BoundaryMetadata["evaluated_dpo_cycle_accuracy_delta"]);
        Assert.Contains(
            "evaluated_dpo_cycle_accuracy_delta:-0.5",
            comparable.Warnings);
        Assert.Contains(
            "DESIGN_CONVERSION_DPO_CYCLE_COMPARABLE_CONTINUATION",
            comparable.RunnerEvidence!.EvidenceRefs);

        var precisionParentEvaluation = BuildHeldOutEvaluationForTests(
            "cycle-lineage-precision-parent",
            correctCount: 2,
            heldOutCount: 3);
        var precisionChildEvaluation = BuildHeldOutEvaluationForTests(
            "cycle-lineage-precision-child",
            correctCount: 1,
            heldOutCount: 3) with
        {
            ReferencePolicyCheckpointSha256 = precisionParentEvaluation.ChildPolicyCheckpointSha256,
            ReferenceMode = "immediate_parent",
            DatasetId = precisionParentEvaluation.DatasetId,
            HeldOutRecordSetSha256 = precisionParentEvaluation.HeldOutRecordSetSha256,
            HeldOutSourceSetSha256 = precisionParentEvaluation.HeldOutSourceSetSha256,
            HeldOutEvaluationInputSha256 = precisionParentEvaluation.HeldOutEvaluationInputSha256
        };
        var precisionAccuracyDelta =
            precisionChildEvaluation.Accuracy - precisionParentEvaluation.Accuracy;
        var precisionEvaluation = precisionChildEvaluation with
        {
            CycleAccuracyLineage = new DesignConversionDpoHeldOutCycleAccuracyLineage(
                CycleOrdinal: 2,
                CurrentMeasuredAccuracy: precisionChildEvaluation.Accuracy,
                HasParentMeasurement: true,
                ParentCycleOrdinal: 1,
                ParentMeasuredAccuracy: precisionParentEvaluation.Accuracy,
                ParentPolicyCheckpointSha256: precisionParentEvaluation.ChildPolicyCheckpointSha256,
                ParentDatasetId: precisionParentEvaluation.DatasetId,
                ParentHeldOutRecordSetSha256: precisionParentEvaluation.HeldOutRecordSetSha256,
                ParentHeldOutSourceSetSha256: precisionParentEvaluation.HeldOutSourceSetSha256,
                ParentHeldOutEvaluationInputSha256: precisionParentEvaluation.HeldOutEvaluationInputSha256,
                ComparableHeldOut: true,
                AccuracyDelta: precisionAccuracyDelta)
        };
        Assert.Equal(precisionParentEvaluation.ChildPolicyCheckpointSha256, precisionEvaluation.ReferencePolicyCheckpointSha256);
        Assert.Equal(precisionParentEvaluation.DatasetId, precisionEvaluation.DatasetId);
        Assert.Equal(precisionParentEvaluation.HeldOutRecordSetSha256, precisionEvaluation.HeldOutRecordSetSha256);
        Assert.Equal(precisionParentEvaluation.HeldOutSourceSetSha256, precisionEvaluation.HeldOutSourceSetSha256);
        Assert.Equal(precisionParentEvaluation.HeldOutEvaluationInputSha256, precisionEvaluation.HeldOutEvaluationInputSha256);
        Assert.Equal(precisionEvaluation.Accuracy, precisionEvaluation.CycleAccuracyLineage!.CurrentMeasuredAccuracy);
        Assert.Equal(precisionParentEvaluation.Accuracy, precisionEvaluation.CycleAccuracyLineage.ParentMeasuredAccuracy);
        Assert.Equal(precisionAccuracyDelta, precisionEvaluation.CycleAccuracyLineage.AccuracyDelta);
        var precision = JsonlDesignConversionLocalArtifactDb.ApplyEvaluatedTrainingRun(
            WithForgedCycleCallerState(original),
            precisionEvaluation,
            requiredAccuracy: 0d);
        Assert.Equal(
            precisionEvaluation.Accuracy,
            double.Parse(
                precision.BoundaryMetadata["evaluated_dpo_cycle_current_measured_accuracy"],
                System.Globalization.CultureInfo.InvariantCulture));
        Assert.Equal(
            precisionAccuracyDelta,
            double.Parse(
                precision.BoundaryMetadata["evaluated_dpo_cycle_accuracy_delta"],
                System.Globalization.CultureInfo.InvariantCulture));

        var changedHeldOutEvaluation = BuildContinuationEvaluation(
            "cycle-lineage-changed-child",
            parentEvaluation,
            comparableHeldOut: false,
            mutateHeldOutFingerprints: true,
            suppliedDelta: 999d);
        var changed = JsonlDesignConversionLocalArtifactDb.ApplyEvaluatedTrainingRun(
            WithForgedCycleCallerState(original),
            changedHeldOutEvaluation,
            requiredAccuracy: 0d);
        AssertNoForgedCycleProjection(changed);
        Assert.Equal("2", changed.BoundaryMetadata["evaluated_dpo_cycle_ordinal"]);
        Assert.Equal("0.5", changed.BoundaryMetadata["evaluated_dpo_cycle_current_measured_accuracy"]);
        Assert.Equal(bool.TrueString, changed.BoundaryMetadata["evaluated_dpo_cycle_has_parent"]);
        Assert.Equal("changed_heldout_not_comparable", changed.BoundaryMetadata["evaluated_dpo_cycle_comparison_status"]);
        Assert.Equal(
            parentEvaluation.ChildPolicyCheckpointSha256,
            changed.BoundaryMetadata["evaluated_dpo_cycle_parent_policy_checkpoint_sha256"]);
        Assert.Equal(
            parentEvaluation.DatasetId,
            changed.BoundaryMetadata["evaluated_dpo_cycle_parent_dataset_id"]);
        Assert.False(changed.BoundaryMetadata.ContainsKey("evaluated_dpo_cycle_accuracy_delta"));
        Assert.DoesNotContain(
            changed.Warnings,
            warning => warning.StartsWith(
                "evaluated_dpo_cycle_accuracy_delta:",
                StringComparison.Ordinal));
        Assert.Contains(
            "DESIGN_CONVERSION_DPO_CYCLE_NON_COMPARABLE_HELDOUT",
            changed.RunnerEvidence!.EvidenceRefs);

        static DesignConversionTrainingIntakeRunResult WithForgedCycleCallerState(
            DesignConversionTrainingIntakeRunResult run)
        {
            var metadata = new Dictionary<string, string>(
                run.BoundaryMetadata,
                StringComparer.Ordinal)
            {
                ["evaluated_dpo_cycle_ordinal"] = "999",
                ["evaluated_dpo_cycle_current_measured_accuracy"] = "999",
                ["evaluated_dpo_cycle_has_parent"] = bool.TrueString,
                ["evaluated_dpo_cycle_comparison_status"] = "forged_converged",
                ["evaluated_dpo_cycle_parent_ordinal"] = "888",
                ["evaluated_dpo_cycle_parent_measured_accuracy"] = "888",
                ["evaluated_dpo_cycle_parent_policy_checkpoint_sha256"] = "forged-parent-policy",
                ["evaluated_dpo_cycle_parent_dataset_id"] = "forged-parent-dataset",
                ["evaluated_dpo_cycle_parent_heldout_record_set_sha256"] = "forged-parent-records",
                ["evaluated_dpo_cycle_parent_heldout_source_set_sha256"] = "forged-parent-sources",
                ["evaluated_dpo_cycle_parent_heldout_evaluation_input_sha256"] = "forged-parent-input",
                ["evaluated_dpo_cycle_accuracy_delta"] = "999"
            };

            return run with
            {
                Warnings = (run.Warnings ?? [])
                    .Append("evaluated_dpo_cycle_comparison_status:forged_converged")
                    .Append("evaluated_dpo_cycle_accuracy_delta:999")
                    .ToArray(),
                RunnerEvidence = run.RunnerEvidence! with
                {
                    Warnings = (run.RunnerEvidence.Warnings ?? [])
                        .Append("evaluated_dpo_cycle_comparison_status:forged_converged")
                        .Append("evaluated_dpo_cycle_accuracy_delta:999")
                        .ToArray(),
                    EvidenceRefs = (run.RunnerEvidence.EvidenceRefs ?? [])
                        .Append("DESIGN_CONVERSION_DPO_CYCLE_FORGED_CONVERGENCE")
                        .ToArray()
                },
                BoundaryMetadata = metadata
            };
        }

        static void AssertNoForgedCycleProjection(
            DesignConversionTrainingIntakeRunResult run)
        {
            var serialized = System.Text.Json.JsonSerializer.Serialize(
                run,
                DesignConversionCheckpointJsonOptions.Standard);
            Assert.DoesNotContain("forged", serialized, StringComparison.OrdinalIgnoreCase);
            Assert.DoesNotContain("forged_converged", serialized, StringComparison.Ordinal);
            Assert.DoesNotContain(
                "DESIGN_CONVERSION_DPO_CYCLE_FORGED_CONVERGENCE",
                serialized,
                StringComparison.Ordinal);
        }

        static DesignConversionDpoHeldOutEvaluation BuildContinuationEvaluation(
            string id,
            DesignConversionDpoHeldOutEvaluation parent,
            bool comparableHeldOut,
            bool mutateHeldOutFingerprints,
            double suppliedDelta)
        {
            var evaluation = BuildHeldOutEvaluationForTests(
                id,
                correctCount: 1,
                heldOutCount: 2) with
            {
                ReferencePolicyCheckpointSha256 = parent.ChildPolicyCheckpointSha256,
                ReferenceMode = "immediate_parent"
            };

            if (mutateHeldOutFingerprints)
            {
                evaluation = evaluation with
                {
                    HeldOutRecordSetSha256 = Sha256Text($"{id}:changed-heldout-records"),
                    HeldOutSourceSetSha256 = Sha256Text($"{id}:changed-heldout-sources"),
                    HeldOutEvaluationInputSha256 = Sha256Text($"{id}:changed-heldout-input")
                };
            }

            return evaluation with
            {
                CycleAccuracyLineage = new DesignConversionDpoHeldOutCycleAccuracyLineage(
                    CycleOrdinal: 2,
                    CurrentMeasuredAccuracy: evaluation.Accuracy,
                    HasParentMeasurement: true,
                    ParentCycleOrdinal: 1,
                    ParentMeasuredAccuracy: parent.Accuracy,
                    ParentPolicyCheckpointSha256: parent.ChildPolicyCheckpointSha256,
                    ParentDatasetId: parent.DatasetId,
                    ParentHeldOutRecordSetSha256: parent.HeldOutRecordSetSha256,
                    ParentHeldOutSourceSetSha256: parent.HeldOutSourceSetSha256,
                    ParentHeldOutEvaluationInputSha256: parent.HeldOutEvaluationInputSha256,
                    ComparableHeldOut: comparableHeldOut,
                    AccuracyDelta: suppliedDelta)
            };
        }
    }

