    public async Task EvaluatedPromotion_AuthoritativeBlockerPreventsPublisherAndUploaderInvocation(
        string blocker)
    {
        var root = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString("N"));
        var fixture = await BuildPromotionReadyIntakeFixtureAsync(root, BuildSafeBlockerFixtureId(blocker));
        var uploader = new CountingLocalOnlyPromotionUploader();
        var terminalReturnObserved = 0;
        var db = new JsonlDesignConversionLocalArtifactDb(
            root,
            createTrainingIntakeJournalWaitTaskObserverForTesting: null,
            createTrainingIntakeJournalGateAcquiredCallbackForTesting: null,
            promotionUploader: uploader,
            dpoPolicyBaseProvider: new DesignConversionDpoPolicyBaseTestProvider(),
            runTrainingIntakeLocalPromotionCompletedRunnerResultTransformerForTesting: runner =>
                runner with
                {
                    PipelineResult = runner.PipelineResult with
                    {
                        LifecycleEvidence = runner.PipelineResult.LifecycleEvidence with
                        {
                            FailureReasons = runner.PipelineResult.LifecycleEvidence.FailureReasons
                                .Append(blocker)
                                .ToArray()
                        }
                    }
                },
            promotionBeforeTerminalReturnObserverForTesting: _ =>
                Interlocked.Increment(ref terminalReturnObserved),
            legalTeacherAdmissionAuthority: CreateEvaluatedLegalTeacherCapability());

        var promoted = await DesignConversionTrainingIntakeRouteAdmissionContext.RunAsync(
            BuildLocalPromotionAdmission(
                "authoritative-blocker-" + BuildSafeBlockerFixtureId(blocker)),
            () => db.RunTrainingIntakeAndPromoteLocalAsync(
                fixture.Intake.IntakeId,
                Path.Combine(root, "output"),
                fixture.Options));

        Assert.True(promoted.IsSuccess, promoted.ErrorMessage);
        Assert.Equal(0, uploader.Count);
        Assert.Equal(0, terminalReturnObserved);
        Assert.Null(promoted.Value!.Publication);
        Assert.Empty(promoted.Value.PromotedCheckpointPath);
        Assert.False(promoted.Value.TrainingRun.ModelUploadReady);
        Assert.False(promoted.Value.LocalPromotionReady);
        Assert.Contains(blocker, promoted.Value.BlockReasons);
        Assert.Equal("False", promoted.Value.TrainingRun.BoundaryMetadata["model_upload_ready"]);
        Assert.Equal("True", promoted.Value.TrainingRun.BoundaryMetadata["model_upload_not_ready"]);
        Assert.Equal(DesignConversionMeasurementGateStatus.Failed,
            promoted.Value.TrainingRun.MeasurementGateStatus);
    }

    [Theory]
    [InlineData("stale-evaluation-only", true)]
    [InlineData("train-count", false)]
    [InlineData("unknown-false-aggregate", false)]
    public async Task EvaluatedPromotion_ReclassifiesDatasetAggregateReasons(
        string datasetCase,
        bool expectsUpload)
    {
        var root = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString("N"));
        var fixture = await BuildValidatedEvaluatedPublisherFixtureAsync(
            root,
            $"dataset-{datasetCase}");
        var uploader = new CountingLocalOnlyPromotionUploader();
        var current = fixture.CompletedRunnerResult.PipelineResult.DatasetCountGate;
        var replacement = datasetCase switch
        {
            "stale-evaluation-only" => current with
            {
                ActualHeldOutRecords = 0,
                SourceDisjoint = false,
                Passed = false,
                Reasons =
                [
                    "HELD_OUT_RECORD_COUNT_BELOW_TARGET:0<1",
                    "SOURCE_DISJOINT_SPLIT_FAILED"
                ]
            },
            "train-count" => current with
            {
                ActualTrainRecords = 0,
                Passed = false,
                Reasons = ["TRAIN_RECORD_COUNT_BELOW_TARGET:0<1"]
            },
            _ => current with
            {
                Passed = false,
                Reasons = []
            }
        };
        var completedRunnerResult = fixture.CompletedRunnerResult with
        {
            DatasetCountGate = replacement,
            PipelineResult = fixture.CompletedRunnerResult.PipelineResult with
            {
                DatasetCountGate = replacement
            }
        };
        var promoted = await new DesignConversionPromotionPublisher(uploader)
            .PublishEvaluatedDpoAsync(
                fixture.Machine,
                completedRunnerResult,
                $"dataset-{datasetCase}-manifest",
                fixture.ArtifactPublication,
                fixture.PassingGateReport,
                CancellationToken.None);

        Assert.True(promoted.IsSuccess, promoted.ErrorMessage);
        Assert.Equal(expectsUpload ? 1 : 0, uploader.Count);
        Assert.Equal(expectsUpload, promoted.Value!.Decision.AllowsUpload);
        if (datasetCase == "train-count")
            Assert.Contains("TRAIN_RECORD_COUNT_BELOW_TARGET:0<1", promoted.Value.Decision.Reasons);
        else if (datasetCase == "unknown-false-aggregate")
            Assert.Contains(
                "DESIGN_CONVERSION_DPO_DATASET_COUNT_GATE_UNCLASSIFIED",
                promoted.Value.Decision.Reasons);
        else
        {
            Assert.DoesNotContain(
                "HELD_OUT_RECORD_COUNT_BELOW_TARGET:0<1",
                promoted.Value.Decision.Reasons);
            Assert.DoesNotContain(
                "SOURCE_DISJOINT_SPLIT_FAILED",
                promoted.Value.Decision.Reasons);
        }
    }

    [Fact]
    public async Task EvaluatedPromotion_RequiresExplicitSourceEncoderManifestPathAndFourArtifactGate()
    {
        var root = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString("N"));
        try
        {
            var fixture = await BuildValidatedEvaluatedPublisherFixtureAsync(
                root,
                "explicit-source-manifest");
            var artifacts = fixture.ArtifactPublication.ManifestArtifacts;
            var expectedSourcePath = SourceEncoderContractPathForPolicyContractPath(artifacts.PolicyPath);

            Assert.Equal(expectedSourcePath, artifacts.SourceEncoderPath);
            Assert.True(File.Exists(artifacts.SourceEncoderPath!));
            var serialized = JsonSerializer.Serialize(
                artifacts,
                DesignConversionCheckpointJsonOptions.Standard);
            Assert.Contains("\"sourceEncoderPath\"", serialized, StringComparison.Ordinal);
            using (var parsedArtifacts = JsonDocument.Parse(serialized))
            {
                Assert.Equal(
                    artifacts.SourceEncoderPath,
                    parsedArtifacts.RootElement.GetProperty("sourceEncoderPath").GetString());
            }

            var missingExplicitSource = fixture.ArtifactPublication with
            {
                ManifestArtifacts = artifacts with { SourceEncoderPath = null }
            };
            Assert.True(File.Exists(expectedSourcePath));
            Assert.False(DesignConversionDpoPromotionArtifactContractCodec
                .ValidateEvaluatedArtifactPublication(missingExplicitSource));
            var missingLease = DesignConversionDpoPromotionArtifactContractCodec
                .AcquireValidatedEvaluatedArtifactPublication(missingExplicitSource);
            Assert.False(missingLease.IsSuccess);

            var mismatchedSourcePath = Path.Combine(
                fixture.OutputDirectory,
                "explicit-source-manifest-mismatched-source-encoder-contract.json");
            await File.WriteAllBytesAsync(
                mismatchedSourcePath,
                await File.ReadAllBytesAsync(expectedSourcePath));
            var mismatchedExplicitSource = fixture.ArtifactPublication with
            {
                ManifestArtifacts = artifacts with { SourceEncoderPath = mismatchedSourcePath }
            };
            Assert.True(File.Exists(expectedSourcePath));
            Assert.True(File.Exists(mismatchedSourcePath));
            Assert.False(DesignConversionDpoPromotionArtifactContractCodec
                .ValidateEvaluatedArtifactPublication(mismatchedExplicitSource));
            var mismatchedLease = DesignConversionDpoPromotionArtifactContractCodec
                .AcquireValidatedEvaluatedArtifactPublication(mismatchedExplicitSource);
            Assert.False(mismatchedLease.IsSuccess);

            var uploader = new CountingLocalOnlyPromotionUploader();
            var published = await new DesignConversionPromotionPublisher(uploader)
                .PublishEvaluatedDpoAsync(
                    fixture.Machine,
                    fixture.CompletedRunnerResult,
                    "explicit-source-manifest",
                    fixture.ArtifactPublication,
                    fixture.PassingGateReport,
                    CancellationToken.None);

            Assert.True(published.IsSuccess, published.ErrorMessage);
            Assert.True(published.Value!.Decision.AllowsUpload);
            Assert.Equal(1, uploader.Count);
            Assert.NotNull(uploader.LastGateReport);
            var sourcePathRef = $"SOURCE_ENCODER_PATH_REF:{DesignConversionDpoLeakageGuard.HashRef(
                "design-conversion-promotion-source-encoder-path",
                artifacts.SourceEncoderPath!)}";
            Assert.Equal(4, uploader.LastGateReport!.RequiredArtifactPaths.Count);
            Assert.Contains(artifacts.SourceEncoderPath!, uploader.LastGateReport.RequiredArtifactPaths);
            Assert.Contains(artifacts.SourceEncoderPath!, uploader.LastGateReport.PresentArtifactPaths);
            Assert.Contains(sourcePathRef, uploader.LastGateReport.EvidenceRefs);
            Assert.Contains(sourcePathRef, published.Value.Manifest.EvidenceRefs);
            Assert.DoesNotContain(
                artifacts.SourceEncoderPath!,
                string.Join('\n', published.Value.Manifest.EvidenceRefs),
                StringComparison.Ordinal);
        }
        finally
        {
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }

    [Fact]
    public void LegacyTrainingManifestArtifacts_RemainThreeArgumentAndOmitNullSourceEncoder()
    {
        var legacy = new DesignConversionTrainingManifestArtifacts(
            "legacy-checkpoint.json",
            "legacy-tokenizer.json",
            "legacy-policy.json");

        Assert.Null(legacy.SourceEncoderPath);
        Assert.Null(legacy.CanonicalBpeTokenizerPath);
        Assert.Null(legacy.CanonicalBpeTokenizerArtifact);
        var serialized = JsonSerializer.Serialize(
            legacy,
            DesignConversionCheckpointJsonOptions.Standard);
        Assert.DoesNotContain("sourceEncoderPath", serialized, StringComparison.Ordinal);
        Assert.DoesNotContain("canonicalBpeTokenizerPath", serialized, StringComparison.Ordinal);
        Assert.DoesNotContain("canonicalBpeTokenizerArtifact", serialized, StringComparison.Ordinal);

        var deserialized = JsonSerializer.Deserialize<DesignConversionTrainingManifestArtifacts>(
            """
            {
              "checkpointPath": "legacy-checkpoint.json",
              "tokenizerPath": "legacy-tokenizer.json",
              "policyPath": "legacy-policy.json"
            }
            """,
            DesignConversionCheckpointJsonOptions.Standard);
        Assert.NotNull(deserialized);
        Assert.Equal("legacy-checkpoint.json", deserialized!.CheckpointPath);
        Assert.Equal("legacy-tokenizer.json", deserialized.TokenizerPath);
        Assert.Equal("legacy-policy.json", deserialized.PolicyPath);
        Assert.Null(deserialized.SourceEncoderPath);
        Assert.Null(deserialized.CanonicalBpeTokenizerPath);
        Assert.Null(deserialized.CanonicalBpeTokenizerArtifact);

        var artifactPaths = new[]
        {
            legacy.CheckpointPath,
            legacy.TokenizerPath,
            legacy.PolicyPath
        };
        var decision = new DesignConversionPromotionGateEvaluator()
            .Decide(new DesignConversionPromotionGateReport(
                HeldOutScore: 0.99d,
                RequiredHeldOutScore: 0.9d,
                HeldOutSourceDisjoint: true,
                DeterministicShortcutDetected: false,
                HiddenShortcutEvidenceDetected: false,
                FreshLoadPassed: true,
                BudgetTierPolicyPassed: true,
                BudgetTier: "legacy-compatibility",
                DpoQuarantineCount: 0,
                MaxDpoQuarantineCount: 0,
                RequiredArtifactPaths: artifactPaths,
                PresentArtifactPaths: artifactPaths,
                EvidenceRefs: ["LEGACY_THREE_ARTIFACT_COMPATIBILITY"]));

        Assert.True(decision.AllowsUpload);
    }

