    [Theory]
    [InlineData(PausedReceiptMode.AcceptedLocal)]
    [InlineData(PausedReceiptMode.AcceptedRemote)]
    [InlineData(PausedReceiptMode.Rejected)]
    public async Task EvaluatedPromotion_RetainsAllValidatedArtifactsAcrossAsyncUploadAndReceipt(
        PausedReceiptMode receiptMode)
    {
        var root = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString("N"));
        var fixture = await BuildValidatedEvaluatedPublisherFixtureAsync(
            root,
            $"retained-upload-lease-{receiptMode}",
            CreateW085DeterministicPromotionProvider());
        var artifactsForLease = fixture.ArtifactPublication.ManifestArtifacts;
        var sourceEncoderPath = artifactsForLease.SourceEncoderPath;
        Assert.False(string.IsNullOrWhiteSpace(sourceEncoderPath));
        Assert.True(File.Exists(sourceEncoderPath));
        var uploader = new PausedArtifactLeaseUploader(receiptMode);
        var manifestId = $"retained-upload-lease-{receiptMode}-manifest";
        var promotionTask = new DesignConversionPromotionPublisher(uploader)
            .PublishEvaluatedDpoAsync(
                fixture.Machine,
                fixture.CompletedRunnerResult,
                manifestId,
                fixture.ArtifactPublication,
                fixture.PassingGateReport,
                CancellationToken.None);
        await uploader.Entered.Task.WaitAsync(TimeSpan.FromSeconds(30));

        Exception? pausedAssertion = null;
        try
        {
            var artifacts = fixture.ArtifactPublication.ManifestArtifacts;
            var expectedLockedPaths = new[]
            {
                artifacts.CheckpointPath,
                artifacts.TokenizerPath,
                artifacts.PolicyPath,
                sourceEncoderPath!,
                Path.Combine(
                    fixture.OutputDirectory,
                    fixture.ArtifactPublication.Anchors.PolicyCheckpointFileName)
            };
            var expectedLockedFullPaths = expectedLockedPaths
                .Select(Path.GetFullPath)
                .ToArray();
            Assert.Equal(5, expectedLockedPaths.Length);
            Assert.Equal(5, expectedLockedFullPaths.Distinct(StringComparer.OrdinalIgnoreCase).Count());
            Assert.Equal(5, uploader.OriginalBytes.Count);
            Assert.Equal(
                expectedLockedFullPaths.OrderBy(static path => path, StringComparer.OrdinalIgnoreCase),
                uploader.OriginalBytes.Keys
                    .Select(Path.GetFullPath)
                    .OrderBy(static path => path, StringComparer.OrdinalIgnoreCase));
            foreach (var lockedPath in expectedLockedPaths)
            {
                Assert.True(uploader.OriginalBytes.ContainsKey(lockedPath), lockedPath);
                var originalBytes = uploader.OriginalBytes[lockedPath];
                if (OperatingSystem.IsWindows())
                {
                    Assert.True(Record.Exception(() => File.Delete(lockedPath)) is
                        IOException or UnauthorizedAccessException);
                    Assert.True(Record.Exception(() =>
                        File.WriteAllBytes(lockedPath, [0xde, 0xad, 0xbe, 0xef])) is
                        IOException or UnauthorizedAccessException);
                    Assert.True(Record.Exception(() =>
                        File.Move(lockedPath, lockedPath + ".rename-attack")) is
                        IOException or UnauthorizedAccessException);
                }
                else
                {
                    // На Linux открытый файл не блокирует unlink/rename имени в
                    // каталоге. Поэтому этот тест не должен сам разрушать
                    // manifest-пути загрузчика; Linux-защиты от подмены имён
                    // проверяются отдельными identity-bound сценариями тренера.
                    Assert.True(File.Exists(lockedPath), lockedPath);
                }

                Assert.Equal(originalBytes, await File.ReadAllBytesAsync(lockedPath));
            }
            if (OperatingSystem.IsWindows())
            {
                Assert.True(Record.Exception(() =>
                    Directory.Move(
                        fixture.OutputDirectory,
                        fixture.OutputDirectory + ".directory-rename-attack")) is
                    IOException or UnauthorizedAccessException);
            }
            else
            {
                // Каталог на Linux тоже можно переименовать при открытых файлах,
                // поэтому здесь проверяем удержание байтов без разрушительной
                // атаки на имена, которыми потом пользуется загрузчик.
                Assert.True(Directory.Exists(fixture.OutputDirectory));
            }
        }
        catch (Exception exception)
        {
            pausedAssertion = exception;
        }
        finally
        {
            uploader.Release.TrySetResult();
        }
        var promoted = await promotionTask;
        if (pausedAssertion is not null)
            ExceptionDispatchInfo.Capture(pausedAssertion).Throw();

        Assert.True(promoted.IsSuccess, promoted.ErrorMessage);
        Assert.Equal(1, uploader.Count);
        Assert.Equal(
            manifestId,
            uploader.LastManifest!.ManifestId);
        Assert.NotNull(uploader.LastGateReport);
        Assert.Equal(4, uploader.LastGateReport!.RequiredArtifactPaths.Count);
        Assert.Contains(sourceEncoderPath!, uploader.LastGateReport.RequiredArtifactPaths);
        Assert.Equal(
            uploader.LastGateReport.RequiredArtifactPaths
                .OrderBy(static path => path, StringComparer.OrdinalIgnoreCase),
            uploader.LastGateReport.PresentArtifactPaths
                .OrderBy(static path => path, StringComparer.OrdinalIgnoreCase));
        Assert.Equal(
            uploader.OriginalBytes.Keys.OrderBy(static path => path, StringComparer.OrdinalIgnoreCase),
            uploader.ObservedBytes.Keys.OrderBy(static path => path, StringComparer.OrdinalIgnoreCase));
        foreach (var artifact in uploader.OriginalBytes)
            Assert.Equal(artifact.Value, uploader.ObservedBytes[artifact.Key]);
        var published = promoted.Value!;
        var manifest = published.Manifest;
        switch (receiptMode)
        {
            case PausedReceiptMode.AcceptedLocal:
                Assert.Equal(
                    DesignConversionPromotionPublicationKind.LocalOnlyNoRemoteAttempt,
                    published.PublicationKind);
                Assert.Equal(
                    DesignConversionPromotionPublicationStatus.NotUploaded,
                    published.PublicationStatus);
                Assert.Equal("local_receipt_only", manifest.PromotionReceiptKind);
                Assert.False(manifest.ModelServerUploadAttempted);
                Assert.False(manifest.ModelServerPromotionClaimed);
                Assert.NotNull(published.UploadReceipt);
                Assert.False(published.UploadReceipt!.UploadAttempted);
                Assert.False(published.UploadReceipt.ExternalCloudUploadAttempted);
                Assert.False(published.UploadReceipt.UploadSucceeded);
                Assert.False(published.UploadReceipt.VerificationSucceeded);
                break;
            case PausedReceiptMode.AcceptedRemote:
                Assert.Equal(
                    DesignConversionPromotionPublicationKind.VerifiedModelServerUpload,
                    published.PublicationKind);
                Assert.Equal(
                    DesignConversionPromotionPublicationStatus.UploadedVerified,
                    published.PublicationStatus);
                Assert.Equal("model_server_upload_verified", manifest.PromotionReceiptKind);
                Assert.True(manifest.ModelServerUploadAttempted);
                Assert.True(manifest.ModelServerPromotionClaimed);
                Assert.NotNull(published.UploadReceipt);
                Assert.True(published.UploadReceipt!.UploadAttempted);
                Assert.True(published.UploadReceipt.UploadSucceeded);
                Assert.True(published.UploadReceipt.VerificationSucceeded);
                break;
            case PausedReceiptMode.Rejected:
                Assert.Equal(
                    DesignConversionPromotionPublicationKind.Rejected,
                    published.PublicationKind);
                Assert.Equal(
                    DesignConversionPromotionPublicationStatus.Rejected,
                    published.PublicationStatus);
                Assert.Null(published.UploadReceipt);
                Assert.Equal("invalid_local_receipt", manifest.PromotionReceiptKind);
                Assert.Contains(
                    "DESIGN_CONVERSION_PROMOTION_LOCAL_RECEIPT_UPLOAD_FLAGS_MUST_BE_FALSE",
                    published.Decision.Reasons);
                break;
            default:
                throw new InvalidOperationException(receiptMode.ToString());
        }
        var manifestText = System.Text.Json.JsonSerializer.Serialize(
            manifest,
            DesignConversionCheckpointJsonOptions.Standard);
        Assert.DoesNotContain("HELD_OUT_RECORD_COUNT_PASSED:999", manifestText, StringComparison.OrdinalIgnoreCase);
        Assert.DoesNotContain("SOURCE_DISJOINT_PROOF_PASSED", manifestText, StringComparison.OrdinalIgnoreCase);
        Assert.Contains(
