        Assert.Contains("VALIDATED_EVALUATED_PUBLISHER_FIXTURE", manifestText, StringComparison.Ordinal);
        var artifactsForEvidence = fixture.ArtifactPublication.ManifestArtifacts;
        var expectedPathRefs = new[]
        {
            $"CHECKPOINT_PATH_REF:{DesignConversionDpoLeakageGuard.HashRef(
                "design-conversion-promotion-checkpoint-path",
                artifactsForEvidence.CheckpointPath)}",
            $"TOKENIZER_PATH_REF:{DesignConversionDpoLeakageGuard.HashRef(
                "design-conversion-promotion-tokenizer-path",
                artifactsForEvidence.TokenizerPath)}",
            $"POLICY_PATH_REF:{DesignConversionDpoLeakageGuard.HashRef(
                "design-conversion-promotion-policy-path",
                artifactsForEvidence.PolicyPath)}",
            $"SOURCE_ENCODER_PATH_REF:{DesignConversionDpoLeakageGuard.HashRef(
                "design-conversion-promotion-source-encoder-path",
                sourceEncoderPath!)}"
        };
        foreach (var pathRef in expectedPathRefs)
        {
            Assert.Contains(pathRef, uploader.LastGateReport.EvidenceRefs);
            Assert.Contains(pathRef, manifest.EvidenceRefs);
        }

        foreach (var artifact in uploader.OriginalBytes)
        {
            File.WriteAllBytes(artifact.Key, [0xca, 0xfe, 0xba, 0xbe]);
            Assert.Equal([0xca, 0xfe, 0xba, 0xbe], await File.ReadAllBytesAsync(artifact.Key));
            File.WriteAllBytes(artifact.Key, artifact.Value);
            Assert.Equal(artifact.Value, await File.ReadAllBytesAsync(artifact.Key));
        }
    }

    [Fact]
    public async Task EvaluatedPromotion_HardLinkMutationIsEitherUnsupportedOrFailsClosed()
    {
        var root = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString("N"));
        var fixture = await BuildW085DeterministicPromotionReadyIntakeFixtureAsync(root, "retained-hardlink");
        var uploader = new PausedArtifactLeaseUploader(PausedReceiptMode.AcceptedLocal);
        var db = new JsonlDesignConversionLocalArtifactDb(
            root,
            createTrainingIntakeJournalWaitTaskObserverForTesting: null,
            createTrainingIntakeJournalGateAcquiredCallbackForTesting: null,
            promotionUploader: uploader,
            dpoPolicyBaseProvider: CreateW085DeterministicPromotionProvider(),
            legalTeacherAdmissionAuthority: CreateEvaluatedLegalTeacherCapability(),
            localReceiptOnlyPromotionAuthority: uploader.Authority);
        var gate = BuildPassingMeasurementGateRequest("retained-hardlink-gate") with
        {
            Thresholds = new DesignConversionMeasurementGateThresholds(0d, 800, 1.00m, 512)
        };
        var bridgeOptions = new DesignConversionDpoPolicyCheckpointBridgeOptions(DpoStepCount: 2);
        var promotionTask = DesignConversionTrainingIntakeRouteAdmissionContext
            .RunAsync(
                BuildLocalPromotionAdmission("retained-hardlink"),
                () => db.RunTrainingIntakeAndPromoteLocalAsync(
                    fixture.Intake.IntakeId,
                    Path.Combine(root, "output"),
                    Pass157LocalPromotionOptions(
                        "retained-hardlink-run",
                        gate,
                        bridgeOptions)));
        await uploader.Entered.Task.WaitAsync(TimeSpan.FromSeconds(30));

        var links = new List<string>();
        foreach (var artifact in uploader.OriginalBytes)
        {
            var link = artifact.Key + ".hardlink-attack";
            if (CreateHardLinkForPublicationLease(link, artifact.Key, IntPtr.Zero))
            {
                links.Add(link);
                Assert.Equal(artifact.Value, await File.ReadAllBytesAsync(link));
            }
        }
        uploader.Release.TrySetResult();
        var promoted = await promotionTask;
        if (links.Count == 0)
        {
            Assert.True(promoted.IsSuccess, promoted.ErrorMessage);
        }
        else
        {
            Assert.False(promoted.IsSuccess);
            Assert.Equal(
                "DESIGN_CONVERSION_TRAINING_INTAKE_PROMOTE_LOCAL_INDETERMINATE_AFTER_INTENT",
                promoted.ErrorCode);
        }
        foreach (var link in links)
            File.Delete(link);
        foreach (var artifact in uploader.OriginalBytes)
        {
            Assert.Equal(artifact.Value, await File.ReadAllBytesAsync(artifact.Key));
            File.WriteAllBytes(artifact.Key, artifact.Value);
        }
    }

    [Theory]
    [InlineData("decision-rejected")]
    [InlineData("missing-uploader")]
    [InlineData("upload-error")]
    [InlineData("rejected-receipt")]
    [InlineData("accepted-local")]
    [InlineData("accepted-remote")]
    public async Task EvaluatedPromotion_EveryReachableTerminalRevalidatesHardLinkNamespaceMutation(
        string terminalCase)
    {
        var root = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString("N"));
        var fixture = await BuildValidatedEvaluatedPublisherFixtureAsync(
            root,
            $"terminal-{terminalCase}");
        var countingUploader = terminalCase == "decision-rejected"
            ? new CountingLocalOnlyPromotionUploader()
            : null;
        var pausedUploader = terminalCase switch
        {
            "upload-error" => new PausedArtifactLeaseUploader(PausedReceiptMode.UploadError),
            "rejected-receipt" => new PausedArtifactLeaseUploader(PausedReceiptMode.Rejected),
            "accepted-local" => new PausedArtifactLeaseUploader(PausedReceiptMode.AcceptedLocal),
            "accepted-remote" => new PausedArtifactLeaseUploader(PausedReceiptMode.AcceptedRemote),
            _ => null
        };
        IDesignConversionPromotionUploader? uploader = countingUploader;
        uploader ??= pausedUploader;
        var links = new List<string>();
        DesignConversionPromotionPublicationKind? terminalKind = null;
        var terminalCallbackCount = 0;
        var publisher = new DesignConversionPromotionPublisher(uploader)
        {
            BeforeTerminalReturnForTesting = kind =>
            {
                terminalCallbackCount++;
                terminalKind = kind;
                if (!OperatingSystem.IsWindows())
                    return;

                var artifacts = fixture.ArtifactPublication.ManifestArtifacts;
                foreach (var artifact in new[]
                {
                    artifacts.CheckpointPath,
                    artifacts.TokenizerPath,
                    artifacts.PolicyPath,
                    Path.Combine(
                        fixture.OutputDirectory,
                        fixture.ArtifactPublication.Anchors.PolicyCheckpointFileName)
                })
                {
                    var link = artifact + $".terminal-{terminalCase}.hardlink";
                    if (CreateHardLinkForPublicationLease(link, artifact, IntPtr.Zero))
                        links.Add(link);
                }
            }
        };
        var gateReport = terminalCase == "decision-rejected"
            ? fixture.PassingGateReport with { HiddenShortcutEvidenceDetected = true }
            : fixture.PassingGateReport;
        var publicationTask = publisher.PublishEvaluatedDpoAsync(
            fixture.Machine,
            fixture.CompletedRunnerResult,
            $"terminal-{terminalCase}-manifest",
            fixture.ArtifactPublication,
            gateReport,
            CancellationToken.None);
        if (pausedUploader is not null)
        {
            await pausedUploader.Entered.Task.WaitAsync(TimeSpan.FromSeconds(30));
            pausedUploader.Release.TrySetResult();
        }

        var promoted = await publicationTask;

        var expectedKind = terminalCase switch
        {
            "accepted-local" => DesignConversionPromotionPublicationKind.LocalOnlyNoRemoteAttempt,
            "accepted-remote" => DesignConversionPromotionPublicationKind.VerifiedModelServerUpload,
            _ => DesignConversionPromotionPublicationKind.Rejected
        };
        Assert.Equal(1, terminalCallbackCount);
        Assert.Equal(expectedKind, terminalKind);
        Assert.Equal(pausedUploader is null ? 0 : 1, pausedUploader?.Count ?? countingUploader?.Count ?? 0);
        if (links.Count > 0)
        {
            Assert.False(promoted.IsSuccess);
            Assert.Equal(
                DesignConversionDpoPromotionArtifactContractCodec.ContractInvalidErrorCode,
                promoted.ErrorCode);
        }
        else if (terminalCase == "upload-error")
        {
            Assert.False(promoted.IsSuccess);
            Assert.Equal("INJECTED_UPLOAD_FAILED", promoted.ErrorCode);
        }
        else
        {
            Assert.True(promoted.IsSuccess, promoted.ErrorMessage);
            Assert.Equal(expectedKind, promoted.Value!.PublicationKind);
            if (terminalCase is "decision-rejected" or "missing-uploader" or "rejected-receipt")
                Assert.False(promoted.Value.Decision.AllowsUpload);
            if (terminalCase == "decision-rejected")
                Assert.Contains("HIDDEN_SHORTCUT_EVIDENCE_DETECTED", promoted.Value.Decision.Reasons);
            if (terminalCase == "missing-uploader")
                Assert.Contains("DESIGN_CONVERSION_PROMOTION_UPLOADER_REQUIRED", promoted.Value.Decision.Reasons);
        }

        foreach (var link in links)
            File.Delete(link);
    }

    [Fact]
    public void ConsumedPartitionProjection_DeepSnapshotsNestedMutableTrainingGraphs()
    {
        var vector = new[] { 1.0, 2.0, 3.0 };
        var chosenEvidence = new[] { "chosen-before" };
        var metadata = new Dictionary<string, string>(StringComparer.Ordinal)
        {
            ["mutable"] = "before"
        };
        var trainTemplate = WithSourceIdentity(
            BuildTrainingRecord(
                "projection-deep-train",
                DesignConversionDpoUnits.ImproverUnit,
                usefulness: 0.99),
            "projection-deep-source-train");
        var train = trainTemplate with
        {
            InternalVectorPayload = vector,
            Chosen = trainTemplate.Chosen with
            {
                EvidenceRefs = chosenEvidence
            },
            Provenance = trainTemplate.Provenance with
            {
                Metadata = metadata
            }
        };
        var heldOut = WithSourceIdentity(
            BuildTrainingRecord(
                "projection-deep-heldout",
                DesignConversionDpoUnits.CriticUnit,
                usefulness: 0.98),
            "projection-deep-source-heldout");
        var partition = new DesignConversionDpoResolvedPartition(
            "projection-deep",
            [train],
            [heldOut],
            string.Empty,
            string.Empty,
            string.Empty,
            string.Empty,
            string.Empty);

        Assert.True(DesignConversionDpoConsumedPartitionProjectionContract.TryCreate(
            partition,
            maximumTrainRecords: 1,
            out var projection));
        Assert.NotNull(projection);

        vector[0] = 99;
        chosenEvidence[0] = "chosen-after";
        metadata["mutable"] = "after";

        var snapshot = Assert.Single(projection!.TrainRecords);
        Assert.NotSame(train, snapshot);
        Assert.Equal(1.0, snapshot.InternalVectorPayload[0]);
        Assert.Equal("chosen-before", Assert.Single(snapshot.Chosen.EvidenceRefs));
        Assert.Equal("before", snapshot.Provenance.Metadata["mutable"]);
    }

    [Theory]
    [InlineData("unlock")]
    [InlineData("dispose")]
    public async Task DpoTrainer_FatalReservationReleaseHookStillDisposesAndRethrowsExact(
        string failingPhase)
    {
        var inputs = await BuildDirectDpoTrainerInputsAsync(
            $"fatal-reservation-release-{failingPhase}");
        var root = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(root);
        var fatal = new OutOfMemoryException($"fatal-{failingPhase}");
        var observer = new DpoTrainerPublicationObserver
        {
            BeforeReservationUnlockForTesting = failingPhase == "unlock"
                ? () => throw fatal
                : null,
            BeforeReservationStreamDisposeForTesting = failingPhase == "dispose"
                ? () => throw fatal
                : null
        };

        var observed = Assert.Throws<OutOfMemoryException>(() =>
            CreateAdmittedTrainer(
                    inputs.Policy,
                    inputs.Reference,
                    root,
                    1e-5f,
