    [Fact]
    public async Task DpoTrainer_CleanupFatalSupersedesNonFatalPrimaryExactly()
    {
        var inputs = await BuildDirectDpoTrainerInputsAsync(
            "cleanup-fatal-over-nonfatal-primary");
        var root = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(root);
        var primary = new IOException("primary-nonfatal");
        var cleanup = new OutOfMemoryException("cleanup-fatal");
        var observer = new DpoTrainerPublicationObserver
        {
            ArtifactOwnershipProven = proof =>
            {
                if (proof.Kind == DpoTrainerArtifactKind.PolicyStaging)
                    throw primary;
            },
            BeforeReservationUnlockForTesting = () => throw cleanup
        };

        var observed = Assert.Throws<OutOfMemoryException>(() =>
            CreateAdmittedTrainer(
                    inputs.Policy,
                    inputs.Reference,
                    root,
                    1e-5f,
                    observer)
                .StepVector([inputs.Batch], 1));

        Assert.Same(cleanup, observed);
        Assert.NotNull(observed.Data["DPO_CLEANUP_FAILURE"]);
        var retry = CreateAdmittedTrainer(inputs.Policy, inputs.Reference, root);
        if (OperatingSystem.IsWindows())
        {
            var retryMetrics = retry.StepVector([inputs.Batch], 1);
            Assert.Equal(1, retryMetrics.Step);
            Assert.True(File.Exists(Path.Combine(
                root,
                DpoTrainer.BuildPolicyCheckpointFileName(1))));
            Assert.True(File.Exists(Path.Combine(
                root,
                DpoTrainer.BuildMetricsFileName(1))));
        }
        else
        {
            // Текущая Linux-очистка умеет удалить принадлежащий попытке staging
            // через удержанный дескриптор. Поэтому после fatal-ошибки unlock-а
            // повтор должен быть таким же рабочим, как на Windows: иначе тест
            // закрепит уже исправленную старую коллизию временного файла.
            var retryMetrics = retry.StepVector([inputs.Batch], 1);
            Assert.Equal(1, retryMetrics.Step);
            Assert.True(File.Exists(Path.Combine(
                root,
                DpoTrainer.BuildPolicyCheckpointFileName(1))));
            Assert.True(File.Exists(Path.Combine(
                root,
                DpoTrainer.BuildMetricsFileName(1))));
        }
    }

    [Fact]
    public void EvaluatedBridgeLease_CleansOwnedFinalsUnlessCommittedAndPreservesReplacementIdentity()
    {
        static DesignConversionDomain.DesignConversionDpoPolicyRuntimeCheckpointBridgeResult DummyResult()
            => new(
                2,
                1,
                1,
                "policy_step_000001.bin",
                new string('a', 64),
                "runtime.json",
                null!,
                null!,
                null!,
                true,
                [],
                []);

        static ServerOwnedLegalTrainingTeacherAdmissionLease CreateAdmissionLease()
        {
            var record = BuildTrainingRecord(
                $"bridge-lease-{Guid.NewGuid():N}",
                DesignConversionDpoUnits.ImproverUnit,
                usefulness: 0.99);
            var acquired = CreateEvaluatedLegalTeacherCapability()
                .AcquireTrainingLease([record.TeacherProvenance]);
            Assert.True(acquired.IsSuccess, acquired.ErrorMessage);
            return acquired.Value!;
        }

        var root = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(root);
        try
        {
            var policy = Path.Combine(root, "policy_step_000001.bin");
            var runtime = Path.Combine(root, "runtime.json");
            var policyBytes = new byte[] { 1, 2, 3, 4 };
            var runtimeBytes = new byte[] { 5, 6, 7, 8 };
            File.WriteAllBytes(policy, policyBytes);
            File.WriteAllBytes(runtime, runtimeBytes);
            var policySha = Convert.ToHexString(SHA256.HashData(policyBytes)).ToLowerInvariant();
            var runtimeSha = Convert.ToHexString(SHA256.HashData(runtimeBytes)).ToLowerInvariant();

            var uncommittedAdmission = CreateAdmissionLease();
            new DesignConversionDpoEvaluatedBridgeLease(
                DummyResult(), null!, policy, runtime, policySha, runtimeSha,
                expectedPolicyIdentity: null,
                expectedRuntimeIdentity: null,
                ownedAdmissionLease: uncommittedAdmission).Dispose();
            if (OperatingSystem.IsWindows())
            {
                Assert.False(File.Exists(policy));
                Assert.False(File.Exists(runtime));
            }
            else
            {
                // Linux-очистка без удержанных файловых дескрипторов намеренно
                // падает закрыто: совпавший путь, контрольная сумма и снимок
                // номера устройства с индексным номером файла не доказывают
                // владение после закрытия исходных файловых дескрипторов.
                Assert.True(File.Exists(policy));
                Assert.True(File.Exists(runtime));
            }
            Assert.Equal(
                ServerOwnedLegalTrainingTeacherAdmissionAuthority.AdmissionRevokedErrorCode,
                uncommittedAdmission.AcquireMutationPermit().ErrorCode);

            File.WriteAllBytes(policy, policyBytes);
            File.WriteAllBytes(runtime, runtimeBytes);
            var committedAdmission = CreateAdmissionLease();
            using (var committed = new DesignConversionDpoEvaluatedBridgeLease(
                       DummyResult(), null!, policy, runtime, policySha, runtimeSha,
                       expectedPolicyIdentity: null,
                       expectedRuntimeIdentity: null,
                       ownedAdmissionLease: committedAdmission))
            {
                committed.CommitPublishedArtifacts();
                committed.CommitPublishedArtifacts();
            }
            Assert.True(File.Exists(policy));
            Assert.True(File.Exists(runtime));
            Assert.Equal(
                ServerOwnedLegalTrainingTeacherAdmissionAuthority.AdmissionRevokedErrorCode,
                committedAdmission.AcquireMutationPermit().ErrorCode);

            File.Delete(policy);
            File.Delete(runtime);
            File.WriteAllBytes(policy, policyBytes);
            File.WriteAllBytes(runtime, runtimeBytes);
            var replacementLease = new DesignConversionDpoEvaluatedBridgeLease(
                DummyResult(), null!, policy, runtime, policySha, runtimeSha);
            File.Delete(runtime);
            File.WriteAllBytes(runtime, runtimeBytes);
            replacementLease.Dispose();
            if (OperatingSystem.IsWindows())
                Assert.False(File.Exists(policy));
            else
                Assert.True(File.Exists(policy));
            Assert.True(File.Exists(runtime));
        }
        finally
        {
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }

    [Fact]
    public void EvaluatedBridgeLease_LeaseWithoutRetainedStreamsPreservesLinuxReplacement()
    {
        static DesignConversionDomain.DesignConversionDpoPolicyRuntimeCheckpointBridgeResult DummyResult()
            => new(
                2,
                1,
                1,
                "policy_step_000001.bin",
                new string('a', 64),
                "runtime.json",
                null!,
                null!,
                null!,
                true,
                [],
                []);

        var root = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(root);
        try
        {
            var policy = Path.Combine(root, "policy_step_000001.bin");
            var runtime = Path.Combine(root, "runtime.json");
            var policyBytes = new byte[] { 1, 2, 3, 4 };
            var runtimeBytes = new byte[] { 5, 6, 7, 8 };
            File.WriteAllBytes(policy, policyBytes);
            File.WriteAllBytes(runtime, runtimeBytes);
            var policySha = Convert.ToHexString(SHA256.HashData(policyBytes)).ToLowerInvariant();
            var runtimeSha = Convert.ToHexString(SHA256.HashData(runtimeBytes)).ToLowerInvariant();
            var lease = new DesignConversionDpoEvaluatedBridgeLease(
                DummyResult(),
                null!,
                policy,
                runtime,
                policySha,
                runtimeSha);

            File.Delete(runtime);
            File.WriteAllBytes(runtime, runtimeBytes);
            lease.Dispose();

            if (OperatingSystem.IsWindows())
            {
                Assert.False(File.Exists(policy));
                Assert.True(File.Exists(runtime));
                return;
            }

            // Без живых удержанных дескрипторов Linux не удаляет по старому
            // снимку номера устройства и индексного номера файла: новая запись
            // с той же контрольной суммой сохраняется, а исходный файл политики
            // остаётся понятным долгом очистки.
            Assert.True(File.Exists(policy));
            Assert.True(File.Exists(runtime));
        }
        finally
        {
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }

    [Fact]
    public async Task DpoPolicyBridge_ProviderExceptionGraphsMapOnlyOrdinaryNonFatalFailures()
    {
        var records = new[]
        {
            BuildTrainingRecord(
                "provider-exception-improver",
                DesignConversionDpoUnits.ImproverUnit,
                usefulness: 0.99),
            BuildTrainingRecord(
                "provider-exception-critic",
                DesignConversionDpoUnits.CriticUnit,
                usefulness: 0.98)
        };

        async Task<OperationResult<DesignConversionDomain.DesignConversionDpoPolicyRuntimeCheckpointBridgeResult>>
            ExecuteAsync(
                DesignConversionDpoPolicyBaseTestProvider provider,
                string caseName,
                CancellationToken cancellationToken = default)
        {
            var output = Path.Combine(
                Path.GetTempPath(),
                Guid.NewGuid().ToString("N"),
                caseName);
            return await DesignConversionDpoPolicyCheckpointBridge.ExecuteAndConvertAsync(
                CreateEvaluatedLegalTeacherCapability(),
                records,
                output,
                caseName,
                Path.Combine(output, $"{caseName}-promoted-checkpoint.json"),
                provider,
                cancellationToken);
        }

        var fatal = new OutOfMemoryException("fatal-provider-identity");
        var observedFatal = await Assert.ThrowsAsync<OutOfMemoryException>(() =>
            ExecuteAsync(
                new DesignConversionDpoPolicyBaseTestProvider(_ => throw fatal),
                "provider-fatal"));
        Assert.Same(fatal, observedFatal);

        var unrequested = new OperationCanceledException("unrequested-provider-identity");
        var observedUnrequested = await Assert.ThrowsAsync<OperationCanceledException>(() =>
            ExecuteAsync(
                new DesignConversionDpoPolicyBaseTestProvider(_ => throw unrequested),
                "provider-unrequested-cancellation"));
        Assert.Same(unrequested, observedUnrequested);

        var nestedCancellation = new IOException(
            "nested-provider-identity",
            new OperationCanceledException("nested-provider-cancellation"));
        var observedNested = await Assert.ThrowsAsync<IOException>(() =>
            ExecuteAsync(
                new DesignConversionDpoPolicyBaseTestProvider(_ => throw nestedCancellation),
                "provider-nested-cancellation"));
        Assert.Same(nestedCancellation, observedNested);

        const string privateProviderFailure = "private provider failure must not leak";
        var ordinary = await ExecuteAsync(
            new DesignConversionDpoPolicyBaseTestProvider(
                _ => throw new IOException(privateProviderFailure)),
            "provider-ordinary-nonfatal");
        Assert.False(ordinary.IsSuccess);
        Assert.Equal(
            "DESIGN_CONVERSION_DPO_POLICY_BASE_PROVIDER_FAILED",
            ordinary.ErrorCode);
        Assert.Equal(
            "DesignConversion DPO policy base provider failed.",
            ordinary.ErrorMessage);
        Assert.DoesNotContain(
            privateProviderFailure,
            ordinary.ErrorMessage,
            StringComparison.Ordinal);

        using var requestedCts = new CancellationTokenSource();
        var requested = await ExecuteAsync(
            new DesignConversionDpoPolicyBaseTestProvider(_ =>
            {
                requestedCts.Cancel();
                throw new OperationCanceledException(requestedCts.Token);
            }),
            "provider-requested-cancellation",
            requestedCts.Token);
        Assert.False(requested.IsSuccess);
        Assert.Equal("CANCELLED", requested.ErrorCode);
    }

