                "file:///private/output",
                "uri-output"),
            DesignConversionDpoPromotionArtifactContractCodec.ResolvePaths(
                root,
                Path.Combine(root, "safe", "..", "escape"),
                "traversal-output"),
            DesignConversionDpoPromotionArtifactContractCodec.ResolvePaths(
                root,
                Path.Combine(root, "promotion"),
                "../traversal-run"),
            DesignConversionDpoPromotionArtifactContractCodec.ResolvePaths(
                root,
                Path.Combine(root, "promotion"),
                "file:///uri-run")
        };
        Assert.All(invalidPaths, result =>
        {
            Assert.False(result.IsSuccess);
            Assert.Equal(
                DesignConversionDpoPromotionArtifactContractCodec.ContractInvalidErrorCode,
                result.ErrorCode);
        });

        Assert.True(
            OperatingSystem.IsWindows(),
            "This no-follow reparse contract requires the supported Windows handle boundary.");
        var reparse = Path.Combine(root, "reparse-output");
        CreatePromotionContractDirectoryJunction(reparse, outside);

        var reparseResult = DesignConversionDpoPromotionArtifactContractCodec.ResolvePaths(
            root,
            reparse,
            "reparse-run");
        Assert.False(reparseResult.IsSuccess);
        Assert.Equal(
            DesignConversionDpoPromotionArtifactContractCodec.ContractInvalidErrorCode,
            reparseResult.ErrorCode);

        var physicalAncestor = Path.Combine(parent, "physical-ancestor");
        var linkedAncestor = Path.Combine(parent, "linked-ancestor");
        var rootBelowLinkedAncestor = Path.Combine(linkedAncestor, "nested-root");
        Directory.CreateDirectory(Path.Combine(physicalAncestor, "nested-root"));
        CreatePromotionContractDirectoryJunction(linkedAncestor, physicalAncestor);
        var ancestorReparseResult =
            DesignConversionDpoPromotionArtifactContractCodec.ResolvePaths(
                rootBelowLinkedAncestor,
                Path.Combine(rootBelowLinkedAncestor, "promotion"),
                "ancestor-reparse-run");
        Assert.False(ancestorReparseResult.IsSuccess);
        Assert.Equal(
            DesignConversionDpoPromotionArtifactContractCodec.ContractInvalidErrorCode,
            ancestorReparseResult.ErrorCode);
    }

    [Fact]
    public async Task DpoPromotionContractPublication_RejectsInvalidMetadataAndTamperedCheckpoints()
    {
        var root = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString("N"));
        var fixture = await BuildDpoPromotionContractFixtureAsync(root, "invalid-contract");
        var bridge = fixture.Bridge;
        var policyRef = bridge.PolicyCheckpointRef!;
        var descriptor = bridge.SourceEncoderDescriptor!;
        var context = policyRef.TrainingContext;
        var lora = context.Lora!;
        var invalidBridges = new (string Name, DesignConversionDomain.DesignConversionDpoPolicyRuntimeCheckpointBridgeResult Bridge)[]
        {
            ("descriptor", bridge with
            {
                SourceEncoderDescriptor = descriptor with { EncoderName = "unknown-encoder" }
            }),
            ("feature-map", bridge with
            {
                SourceEncoderDescriptor = descriptor with
                {
                    FeatureMapHash = "dcm-source-encoder-feature-map-0000000000000000"
                }
            }),
            ("ref", bridge with { PolicyCheckpointRef = null }),
            ("name", bridge with { PolicyCheckpointPath = "../outside-policy.bin" }),
            ("hash", bridge with { PolicyCheckpointSha256 = new string('0', 64) }),
            ("length", bridge with
            {
                PolicyCheckpointRef = policyRef with
                {
                    PolicyCheckpointByteLength = policyRef.PolicyCheckpointByteLength + 1
                }
            }),
            ("config", bridge with
            {
                PolicyCheckpointRef = policyRef with
                {
                    TrainingContext = context with { VocabSize = 1 }
                }
            }),
            ("lora", bridge with
            {
                PolicyCheckpointRef = policyRef with
                {
                    TrainingContext = context with
                    {
                        Lora = lora with { Alpha = lora.Alpha + 1f }
                    }
                }
            }),
            ("count", bridge with { BridgePreferenceCount = 0 }),
            ("context", bridge with
            {
                PolicyCheckpointRef = policyRef with
                {
                    TrainingContext = context with { SchemaVersion = 1 }
                }
            }),
            ("raw-payload-flag", bridge with
            {
                PolicyCheckpointRef = policyRef with
                {
                    TrainingContext = context with { RawPayloadPersisted = false }
                }
            }),
            ("absolute-path-flag", bridge with
            {
                PolicyCheckpointRef = policyRef with
                {
                    TrainingContext = context with { AbsolutePathPersisted = true }
                }
            }),
            ("rooted-provider", bridge with
            {
                PolicyCheckpointRef = policyRef with
                {
                    TrainingContext = context with { ProviderKind = "C:\\provider" }
                }
            }),
            ("uri-revision", bridge with
            {
                PolicyCheckpointRef = policyRef with
                {
                    TrainingContext = context with { BaseRevision = "file:revision" }
                }
            }),
            ("private-model", bridge with
            {
                PolicyCheckpointRef = policyRef with
                {
                    TrainingContext = context with { BaseModelId = "test-org/private-model" }
                }
            }),
            ("private-provider", bridge with
            {
                PolicyCheckpointRef = policyRef with
                {
                    TrainingContext = context with { ProviderKind = "private-provider" }
                }
            }),
            ("private-revision", bridge with
            {
                PolicyCheckpointRef = policyRef with
                {
                    TrainingContext = context with { BaseRevision = "private-revision" }
                }
            }),
            ("private-config", bridge with
            {
                PolicyCheckpointRef = policyRef with
                {
                    TrainingContext = context with { ConfigKind = "private.config" }
                }
            }),
            ("uri-model", bridge with
            {
                PolicyCheckpointRef = policyRef with
                {
                    TrainingContext = context with { BaseModelId = "https://model.example/id" }
                }
            }),
            ("uri-config", bridge with
            {
                PolicyCheckpointRef = policyRef with
                {
                    TrainingContext = context with { ConfigKind = "file:config" }
                }
            })
        };

        foreach (var invalid in invalidBridges)
        {
            var rejected = await DesignConversionDpoPromotionArtifactContractCodec.PublishAsync(
                fixture.Paths,
                invalid.Bridge,
                CancellationToken.None);
            Assert.False(rejected.IsSuccess, invalid.Name);
            Assert.Equal(
                DesignConversionDpoPromotionArtifactContractCodec.ContractInvalidErrorCode,
                rejected.ErrorCode);
            Assert.Equal(
                DesignConversionDpoPromotionArtifactContractCodec.ContractInvalidSafeMessage,
                rejected.ErrorMessage);
            Assert.False(File.Exists(fixture.Paths.SourceEncoderContractPath));
            Assert.False(File.Exists(fixture.Paths.PolicyCheckpointContractPath));
            Assert.DoesNotContain("private", rejected.ErrorMessage, StringComparison.OrdinalIgnoreCase);
        }

        var policyPath = Path.Combine(
            fixture.Paths.OutputDirectory,
            bridge.PolicyCheckpointPath);
        var policyBytes = await File.ReadAllBytesAsync(policyPath);
        await File.WriteAllBytesAsync(policyPath, [.. policyBytes, 0x7f]);
        var tamperedPolicy = await DesignConversionDpoPromotionArtifactContractCodec.PublishAsync(
            fixture.Paths,
            bridge,
            CancellationToken.None);
        Assert.False(tamperedPolicy.IsSuccess);
        Assert.Equal(
            DesignConversionDpoPromotionArtifactContractCodec.ContractInvalidErrorCode,
            tamperedPolicy.ErrorCode);
        await File.WriteAllBytesAsync(policyPath, policyBytes);

        await File.WriteAllTextAsync(fixture.Paths.RuntimeCheckpointPath, "{malformed-runtime");
        var malformedRuntime = await DesignConversionDpoPromotionArtifactContractCodec.PublishAsync(
            fixture.Paths,
            bridge,
            CancellationToken.None);
        Assert.False(malformedRuntime.IsSuccess);
        Assert.Equal(
            DesignConversionDpoPromotionArtifactContractCodec.ContractInvalidErrorCode,
            malformedRuntime.ErrorCode);
        Assert.False(File.Exists(fixture.Paths.SourceEncoderContractPath));
        Assert.False(File.Exists(fixture.Paths.PolicyCheckpointContractPath));
        AssertNoPromotionContractTemps(fixture.Paths.OutputDirectory);
    }

