    [Theory]
    [InlineData("missing-file")]
    [InlineData("corrupted-content")]
    [InlineData("anchor-hash-mismatch")]
    [InlineData("binding-length-mismatch")]
    public async Task EvaluatedPromotionTokenizerArtifactMutationsFailClosedDuringValidatedAcquisition(
        string mutation)
    {
        var root = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString("N"));
        try
        {
            var fixture = await BuildValidatedEvaluatedPublisherFixtureAsync(
                root,
                $"tokenizer-mut-{mutation}");
            var publication = fixture.ArtifactPublication;
            Assert.True(DesignConversionDpoPromotionArtifactContractCodec
                .ValidateEvaluatedArtifactPublication(publication));
            var accepted = DesignConversionDpoPromotionArtifactContractCodec
                .AcquireValidatedEvaluatedArtifactPublication(publication);
            Assert.True(accepted.IsSuccess, accepted.ErrorMessage);
            Assert.NotNull(accepted.Value);
            accepted.Value!.Dispose();

            var tokenizerPath = publication.ManifestArtifacts.TokenizerPath;
            var tokenizerBytes = await File.ReadAllBytesAsync(tokenizerPath);
            publication = mutation switch
            {
                "missing-file" => DeleteTokenizerArtifact(publication, tokenizerPath),
                "corrupted-content" => await CorruptTokenizerArtifactAsync(
                    publication,
                    tokenizerPath,
                    tokenizerBytes),
                "anchor-hash-mismatch" => WithTokenizerBindingAndAnchors(
                    publication,
                    TokenizerMutationSha256("retained-tokenizer-hash-mismatch"),
                    tokenizerBytes.LongLength),
                "binding-length-mismatch" => WithTokenizerBindingAndAnchors(
                    publication,
                    Convert.ToHexString(SHA256.HashData(tokenizerBytes)).ToLowerInvariant(),
                    tokenizerBytes.LongLength + 1),
                _ => throw new InvalidOperationException(mutation)
            };

            var rejected = DesignConversionDpoPromotionArtifactContractCodec
                .AcquireValidatedEvaluatedArtifactPublication(publication);

            Assert.False(rejected.IsSuccess, mutation);
            Assert.Null(rejected.Value);
            Assert.Equal(
                DesignConversionDpoPromotionArtifactContractCodec.ContractInvalidErrorCode,
                rejected.ErrorCode);
            Assert.False(DesignConversionDpoPromotionArtifactContractCodec
                .ValidateEvaluatedArtifactPublication(publication));
        }
        finally
        {
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }

        static DesignConversionDpoPromotionArtifactPublication DeleteTokenizerArtifact(
            DesignConversionDpoPromotionArtifactPublication publication,
            string tokenizerPath)
        {
            File.Delete(tokenizerPath);
            // Falsification: the legacy alias/no-tokenizer contract treated the
            // manifest tokenizer slot as the source contract path, so removing
            // this distinct tokenizer artifact would not have invalidated the
            // retained artifact set before the dedicated tokenizer binding.
            return publication;
        }
    }

