    [Fact]
    public async Task EvaluatedPromotionCanonicalBpeSidecarPublishesExactArtifactAndBindsContractsManifestAndV3Identity()
    {
        var root = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString("N"));
        try
        {
            var canonical = CreateCanonicalBpeProviderForPublication();
            var fixture = await BuildValidatedEvaluatedPublisherFixtureAsync(
                root,
                "canonical-bpe-sidecar-success",
                canonical.Provider);
            var publication = fixture.ArtifactPublication;
            var binding = publication.SourceEncoderContract.Binding;
            var bpeBinding = Assert.IsType<DesignConversionDpoCanonicalBpeTokenizerArtifactBinding>(
                binding.CanonicalBpeTokenizer);
            var artifacts = publication.ManifestArtifacts;
            var bpePath = Assert.IsType<string>(artifacts.CanonicalBpeTokenizerPath);

            Assert.Equal(1, canonical.Source.InvocationCount);
            Assert.Equal(
                Path.GetFullPath(Path.Combine(fixture.OutputDirectory, bpeBinding.FileName)),
                Path.GetFullPath(bpePath));
            Assert.True(File.Exists(bpePath));
            Assert.Equal(canonical.Snapshot.Bytes, await File.ReadAllBytesAsync(bpePath));
            Assert.Equal(canonical.Snapshot.Descriptor.Sha256, bpeBinding.Sha256);
            Assert.Equal(canonical.Snapshot.Descriptor.ByteLength, bpeBinding.ByteLength);
            Assert.Equal(canonical.Snapshot.Descriptor, bpeBinding.Descriptor);
            Assert.Equal(bpeBinding, publication.PolicyCheckpointContract.Binding.CanonicalBpeTokenizer);
            Assert.Equal(bpeBinding, publication.Anchors.CanonicalBpeTokenizer);
            Assert.Equal(bpeBinding, publication.CanonicalBpeTokenizer);
            Assert.EndsWith(
                DesignConversionDpoPromotionArtifactContractCodec.CanonicalBpeTokenizerArtifactSuffix,
                bpeBinding.FileName,
                StringComparison.Ordinal);

            var expectedV3 = DesignConversionDpoPromotionArtifactContractCodec.BuildArtifactSetId(
                binding.PolicyCheckpointFileName,
                binding.PolicyCheckpointSha256,
                binding.PolicyCheckpointByteLength,
                binding.RuntimeCheckpointFileName,
                binding.RuntimeCheckpointSha256,
                binding.RuntimeCheckpointByteLength,
                binding.TokenizerArtifactFileName,
                binding.TokenizerArtifactSha256,
                binding.TokenizerArtifactByteLength,
                binding.SourceEncoderDescriptor,
                publication.PolicyCheckpointContract.Evaluation,
                bpeBinding);
            var legacyV2 = DesignConversionDpoPromotionArtifactContractCodec.BuildArtifactSetId(
                binding.PolicyCheckpointFileName,
                binding.PolicyCheckpointSha256,
                binding.PolicyCheckpointByteLength,
                binding.RuntimeCheckpointFileName,
                binding.RuntimeCheckpointSha256,
                binding.RuntimeCheckpointByteLength,
                binding.TokenizerArtifactFileName,
                binding.TokenizerArtifactSha256,
                binding.TokenizerArtifactByteLength,
                binding.SourceEncoderDescriptor,
                publication.PolicyCheckpointContract.Evaluation);

            Assert.Equal(expectedV3, binding.ArtifactSetId);
            Assert.NotEqual(legacyV2, binding.ArtifactSetId);
            await AssertManifestDescriptorMatchesFileAsync(
                artifacts.CanonicalBpeTokenizerArtifact,
                DesignConversionDpoPromotionArtifactContractCodec.CanonicalBpeTokenizerArtifactKind,
                bpePath,
                bpeBinding.Sha256,
                bpeBinding.ByteLength,
                binding);
            Assert.Contains(
                "canonicalBpeTokenizer",
                JsonSerializer.Serialize(
                    publication.SourceEncoderContract,
                    DesignConversionCheckpointJsonOptions.Standard),
                StringComparison.Ordinal);
            Assert.True(DesignConversionDpoPromotionArtifactContractCodec
                .ValidateEvaluatedArtifactPublication(publication));
            var lease = DesignConversionDpoPromotionArtifactContractCodec
                .AcquireValidatedEvaluatedArtifactPublication(publication);
            Assert.True(lease.IsSuccess, lease.ErrorMessage);
            lease.Value!.Dispose();
            AssertNoPromotionContractTemps(fixture.OutputDirectory);
        }
        finally
        {
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }

