                id);
            Assert.True(paths.IsSuccess, paths.ErrorMessage);
            var canonical = CreateCanonicalBpeProviderForPublication();
            var evaluated = await DesignConversionDpoPolicyCheckpointBridge
                .ExecuteEvaluatedAndConvertAsync(
                    CreateEvaluatedLegalTeacherCapability(),
                    BuildEvaluatedPartitionForTests(id, heldOutCount: 1),
                    paths.Value!.OutputDirectory,
                    id,
                    paths.Value.RuntimeCheckpointPath,
                    canonical.Provider,
                    new DesignConversionDpoPolicyCheckpointBridgeOptions(1, 1),
                    ct: CancellationToken.None);
            Assert.True(evaluated.IsSuccess, evaluated.ErrorMessage);
            using var lease = evaluated.Value!;
            var foreignBytes = System.Text.Encoding.UTF8.GetBytes(
                "foreign-canonical-bpe-sidecar-owned-by-another-publication");
            await File.WriteAllBytesAsync(
                paths.Value.CanonicalBpeTokenizerPath!,
                foreignBytes);

            var rejected = await DesignConversionDpoPromotionArtifactContractCodec
                .PublishEvaluatedAsync(
                    paths.Value,
                    lease.Result,
                    lease.Evaluation,
                    CancellationToken.None);

            Assert.False(rejected.IsSuccess);
            Assert.Equal(
                DesignConversionDpoPromotionArtifactContractCodec.ArtifactCollisionErrorCode,
                rejected.ErrorCode);
            Assert.Equal(1, canonical.Source.InvocationCount);
            Assert.Equal(
                foreignBytes,
                await File.ReadAllBytesAsync(paths.Value.CanonicalBpeTokenizerPath!));
            Assert.False(File.Exists(paths.Value.TokenizerArtifactPath));
            Assert.False(File.Exists(paths.Value.SourceEncoderContractPath));
            Assert.False(File.Exists(paths.Value.PolicyCheckpointContractPath));
            AssertNoPromotionContractTemps(paths.Value.OutputDirectory);
        }
        finally
        {
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }

    [Theory]
    [InlineData("missing-sidecar")]
    [InlineData("tampered-sidecar")]
    [InlineData("manifest-mismatch")]
    public async Task EvaluatedPromotionCanonicalBpeSidecarMutationsFailClosedDuringValidatedAcquisition(
        string mutation)
    {
        var root = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString("N"));
        try
        {
            var canonical = CreateCanonicalBpeProviderForPublication();
            var fixture = await BuildValidatedEvaluatedPublisherFixtureAsync(
                root,
                $"canonical-bpe-mut-{mutation}",
                canonical.Provider);
            var publication = fixture.ArtifactPublication;
            var bpePath = publication.ManifestArtifacts.CanonicalBpeTokenizerPath!;
            Assert.True(File.Exists(bpePath));
            var accepted = DesignConversionDpoPromotionArtifactContractCodec
                .AcquireValidatedEvaluatedArtifactPublication(publication);
            Assert.True(accepted.IsSuccess, accepted.ErrorMessage);
            accepted.Value!.Dispose();

            publication = mutation switch
            {
                "missing-sidecar" => DeleteCanonicalBpeSidecar(publication, bpePath),
                "tampered-sidecar" => await TamperCanonicalBpeSidecarAsync(publication, bpePath),
                "manifest-mismatch" => publication with
                {
                    ManifestArtifacts = publication.ManifestArtifacts with
                    {
                        CanonicalBpeTokenizerArtifact =
                            publication.ManifestArtifacts.CanonicalBpeTokenizerArtifact! with
                            {
                                Sha256 = TokenizerMutationSha256("canonical-bpe-manifest-mismatch")
                            }
                    }
                },
                _ => throw new InvalidOperationException(mutation)
            };

            var rejected = DesignConversionDpoPromotionArtifactContractCodec
                .AcquireValidatedEvaluatedArtifactPublication(publication);

            Assert.False(rejected.IsSuccess, mutation);
            Assert.Null(rejected.Value);
            Assert.Equal(
                DesignConversionDpoPromotionArtifactContractCodec.ContractInvalidErrorCode,
                rejected.ErrorCode);
            Assert.False(DesignConversionDpoPromotionArtifactContractCodec
                .ValidateEvaluatedArtifactPublication(publication));
        }
        finally
        {
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }

        static DesignConversionDpoPromotionArtifactPublication DeleteCanonicalBpeSidecar(
            DesignConversionDpoPromotionArtifactPublication publication,
            string bpePath)
        {
            File.Delete(bpePath);
            return publication;
        }

        static async Task<DesignConversionDpoPromotionArtifactPublication> TamperCanonicalBpeSidecarAsync(
            DesignConversionDpoPromotionArtifactPublication publication,
            string bpePath)
        {
            var bytes = await File.ReadAllBytesAsync(bpePath);
            bytes[0] ^= 0x7f;
            await File.WriteAllBytesAsync(bpePath, bytes);
            return publication;
        }
    }

