                fixture.Paths.OutputDirectory,
                fixture.Bridge.PolicyCheckpointPath);
            var policyBytes = new byte[
                DesignConversionDpoPromotionArtifactContractCodec.CheckpointHashBufferBytes + 257];
            for (var index = 0; index < policyBytes.Length; index++)
                policyBytes[index] = unchecked((byte)(index * 31 + 17));
            await File.WriteAllBytesAsync(policyPath, policyBytes);
            var policySha256 = await ReadSha256Async(policyPath);
            var policyRef = fixture.Bridge.PolicyCheckpointRef! with
            {
                Sha256 = policySha256,
                PolicyCheckpointByteLength = policyBytes.Length
            };
            var runtimeCheckpoint = fixture.Bridge.RuntimeCheckpoint with
            {
                DpoPolicyCheckpointRef = policyRef
            };
            await File.WriteAllBytesAsync(
                fixture.Paths.RuntimeCheckpointPath,
                System.Text.Json.JsonSerializer.SerializeToUtf8Bytes(
                    runtimeCheckpoint,
                    DesignConversionCheckpointJsonOptions.Standard));
            var bridge = fixture.Bridge with
            {
                PolicyCheckpointSha256 = policySha256,
                PolicyCheckpointRef = policyRef,
                RuntimeCheckpoint = runtimeCheckpoint
            };

            var published = await DesignConversionDpoPromotionArtifactContractCodec.PublishAsync(
                fixture.Paths,
                bridge,
                CancellationToken.None);

            Assert.True(published.IsSuccess, published.ErrorMessage);
            Assert.Equal(
                policyBytes.LongLength,
                published.Value!.SourceEncoderContract.Binding.PolicyCheckpointByteLength);
            Assert.Equal(
                policySha256,
                published.Value.SourceEncoderContract.Binding.PolicyCheckpointSha256);
            Assert.Equal(
                policyBytes.LongLength,
                published.Value.PolicyCheckpointContract.Binding.PolicyCheckpointByteLength);
            Assert.Null(published.Value.PolicyCheckpointContract.Evaluation);
            Assert.DoesNotContain(
                "\"evaluation\"",
                await File.ReadAllTextAsync(fixture.Paths.PolicyCheckpointContractPath),
                StringComparison.OrdinalIgnoreCase);
            AssertNoPromotionContractTemps(fixture.Paths.OutputDirectory);
        }
        finally
        {
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }

