    [Fact]
    public async Task DpoPromotionContractPublication_IsReplaySafeCollisionDenyingAndConcurrent()
    {
        var root = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString("N"));
        var fixture = await BuildDpoPromotionContractFixtureAsync(root, "replay-master");
        var first = await DesignConversionDpoPromotionArtifactContractCodec.PublishAsync(
            fixture.Paths,
            fixture.Bridge,
            CancellationToken.None);
        Assert.True(first.IsSuccess, first.ErrorMessage);
        var sourceBytes = await File.ReadAllBytesAsync(fixture.Paths.SourceEncoderContractPath);
        var policyBytes = await File.ReadAllBytesAsync(fixture.Paths.PolicyCheckpointContractPath);

        var replay = await DesignConversionDpoPromotionArtifactContractCodec.PublishAsync(
            fixture.Paths,
            fixture.Bridge,
            CancellationToken.None);
        Assert.True(replay.IsSuccess, replay.ErrorMessage);
        Assert.Equal(sourceBytes, await File.ReadAllBytesAsync(fixture.Paths.SourceEncoderContractPath));
        Assert.Equal(policyBytes, await File.ReadAllBytesAsync(fixture.Paths.PolicyCheckpointContractPath));

        File.Delete(fixture.Paths.PolicyCheckpointContractPath);
        var partialRecovery = await DesignConversionDpoPromotionArtifactContractCodec.PublishAsync(
            fixture.Paths,
            fixture.Bridge,
            CancellationToken.None);
        Assert.True(partialRecovery.IsSuccess, partialRecovery.ErrorMessage);
        Assert.Equal(sourceBytes, await File.ReadAllBytesAsync(fixture.Paths.SourceEncoderContractPath));
        Assert.Equal(policyBytes, await File.ReadAllBytesAsync(fixture.Paths.PolicyCheckpointContractPath));

        var collision = CloneDpoPromotionContractFixture(fixture, root, "collision");
        var collisionBytes = System.Text.Encoding.UTF8.GetBytes("preexisting-owned-by-someone-else");
        await File.WriteAllBytesAsync(collision.Paths.SourceEncoderContractPath, collisionBytes);
        var collisionResult = await DesignConversionDpoPromotionArtifactContractCodec.PublishAsync(
            collision.Paths,
            collision.Bridge,
            CancellationToken.None);
        Assert.False(collisionResult.IsSuccess);
        Assert.Equal(
            DesignConversionDpoPromotionArtifactContractCodec.ArtifactCollisionErrorCode,
            collisionResult.ErrorCode);
        Assert.Equal(
            collisionBytes,
            await File.ReadAllBytesAsync(collision.Paths.SourceEncoderContractPath));
        Assert.False(File.Exists(collision.Paths.PolicyCheckpointContractPath));
        AssertNoPromotionContractTemps(collision.Paths.OutputDirectory);

        var secondLeafCollision = CloneDpoPromotionContractFixture(
            fixture,
            root,
            "second-leaf-collision");
        var policySentinel = System.Text.Encoding.UTF8.GetBytes(
            "preexisting-policy-owned-by-someone-else");
        await File.WriteAllBytesAsync(
            secondLeafCollision.Paths.PolicyCheckpointContractPath,
            policySentinel);
        var secondLeafCollisionResult =
            await DesignConversionDpoPromotionArtifactContractCodec.PublishAsync(
                secondLeafCollision.Paths,
                secondLeafCollision.Bridge,
                CancellationToken.None);
        Assert.False(secondLeafCollisionResult.IsSuccess);
        Assert.Equal(
            DesignConversionDpoPromotionArtifactContractCodec.ArtifactCollisionErrorCode,
            secondLeafCollisionResult.ErrorCode);
        Assert.False(File.Exists(secondLeafCollision.Paths.SourceEncoderContractPath));
        Assert.Equal(
            policySentinel,
            await File.ReadAllBytesAsync(
                secondLeafCollision.Paths.PolicyCheckpointContractPath));
        AssertNoPromotionContractTemps(secondLeafCollision.Paths.OutputDirectory);

        var concurrent = CloneDpoPromotionContractFixture(fixture, root, "concurrent");
        using var winnerHoldingFinalHandle = new ManualResetEventSlim(false);
        using var loserObservedSharingRetry = new ManualResetEventSlim(false);
        var winner = Task.Run(() =>
            DesignConversionDpoPromotionArtifactContractCodec.PublishAsync(
                concurrent.Paths,
                concurrent.Bridge,
                CancellationToken.None,
                stage =>
                {
                    if (stage == DesignConversionDpoPromotionContractIoStage.AfterSourceEncoderPublish)
                    {
                        winnerHoldingFinalHandle.Set();
                        if (OperatingSystem.IsWindows())
                        {
                            Assert.True(loserObservedSharingRetry.Wait(TimeSpan.FromSeconds(10)));
                        }
                    }
                }));
        Assert.True(winnerHoldingFinalHandle.Wait(TimeSpan.FromSeconds(10)));
        var loser = Task.Run(() =>
            DesignConversionDpoPromotionArtifactContractCodec.PublishAsync(
                concurrent.Paths,
                concurrent.Bridge,
                CancellationToken.None,
                stage =>
                {
                    if (stage == DesignConversionDpoPromotionContractIoStage.ExistingContractSharingRetry)
                        loserObservedSharingRetry.Set();
                }));
        var concurrentResults = await Task.WhenAll(winner, loser);
        // На Windows mandatory sharing доказывается конкретным retry у loser.
        // На Linux flock advisory, а long-lived artifacts специально оставлены
        // reader/replay-compatible; там контракт — оба publisher'а сходятся без
        // WRITE_FAILED и без collision.
        if (OperatingSystem.IsWindows())
            Assert.True(loserObservedSharingRetry.IsSet);
        Assert.All(concurrentResults, result => Assert.True(result.IsSuccess, result.ErrorMessage));
        Assert.True(File.Exists(concurrent.Paths.SourceEncoderContractPath));
        Assert.True(File.Exists(concurrent.Paths.PolicyCheckpointContractPath));
        AssertNoPromotionContractTemps(concurrent.Paths.OutputDirectory);
    }

    [Fact]
    public async Task DpoPromotionContractPublication_MapsCancellationAndNonFatalButLetsNestedAndFatalEscape()
    {
        var root = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString("N"));
        var fixture = await BuildDpoPromotionContractFixtureAsync(root, "exceptions-master");

        var preCancelled = CloneDpoPromotionContractFixture(fixture, root, "pre-cancelled");
        using (var cts = new CancellationTokenSource())
        {
            cts.Cancel();
            var cancelled = await DesignConversionDpoPromotionArtifactContractCodec.PublishAsync(
                preCancelled.Paths,
                preCancelled.Bridge,
                cts.Token);
            Assert.Equal(
                DesignConversionDpoPromotionArtifactContractCodec.CancelledErrorCode,
                cancelled.ErrorCode);
        }

        var midCancelled = CloneDpoPromotionContractFixture(fixture, root, "mid-cancelled");
        using (var cts = new CancellationTokenSource())
        {
            var cancelled = await DesignConversionDpoPromotionArtifactContractCodec.PublishAsync(
                midCancelled.Paths,
                midCancelled.Bridge,
                cts.Token,
                stage =>
                {
                    if (stage == DesignConversionDpoPromotionContractIoStage.AfterSourceEncoderPublish)
                        cts.Cancel();
                });
            Assert.Equal(
                DesignConversionDpoPromotionArtifactContractCodec.CancelledErrorCode,
                cancelled.ErrorCode);
            Assert.False(File.Exists(midCancelled.Paths.SourceEncoderContractPath));
            Assert.False(File.Exists(midCancelled.Paths.PolicyCheckpointContractPath));
            AssertNoPromotionContractTemps(midCancelled.Paths.OutputDirectory);
        }

        var ordinary = CloneDpoPromotionContractFixture(fixture, root, "ordinary-nonfatal");
        var ordinaryFailure = await DesignConversionDpoPromotionArtifactContractCodec.PublishAsync(
            ordinary.Paths,
            ordinary.Bridge,
            CancellationToken.None,
            stage =>
            {
                if (stage == DesignConversionDpoPromotionContractIoStage.AfterSourceEncoderPublish)
                    throw new IOException("private payload must not escape");
            });
        Assert.False(ordinaryFailure.IsSuccess);
        Assert.Equal(
            DesignConversionDpoPromotionArtifactContractCodec.WriteFailedErrorCode,
            ordinaryFailure.ErrorCode);
        Assert.Equal(
            DesignConversionDpoPromotionArtifactContractCodec.WriteFailedSafeMessage,
            ordinaryFailure.ErrorMessage);
        Assert.DoesNotContain("private payload", ordinaryFailure.ErrorMessage, StringComparison.Ordinal);
        Assert.False(File.Exists(ordinary.Paths.SourceEncoderContractPath));
        Assert.False(File.Exists(ordinary.Paths.PolicyCheckpointContractPath));
        AssertNoPromotionContractTemps(ordinary.Paths.OutputDirectory);

        var replacement = CloneDpoPromotionContractFixture(
            fixture,
            root,
            "same-content-contract-replacement");
        byte[]? replacementBytes = null;
        var replacementFailure = await DesignConversionDpoPromotionArtifactContractCodec
            .PublishAsync(
                replacement.Paths,
                replacement.Bridge,
                CancellationToken.None,
                stage =>
                {
                    if (stage != DesignConversionDpoPromotionContractIoStage.BeforePolicyCheckpointWrite)
                        return;
                    replacementBytes = File.ReadAllBytes(
                        replacement.Paths.SourceEncoderContractPath);
                    File.Delete(replacement.Paths.SourceEncoderContractPath);
                    File.WriteAllBytes(
                        replacement.Paths.SourceEncoderContractPath,
                        replacementBytes);
                    throw new IOException("fail after same-content replacement");
                });
        Assert.False(replacementFailure.IsSuccess);
        Assert.Equal(
            DesignConversionDpoPromotionArtifactContractCodec.WriteFailedErrorCode,
            replacementFailure.ErrorCode);
        Assert.NotNull(replacementBytes);
        Assert.Equal(
            replacementBytes,
            await File.ReadAllBytesAsync(replacement.Paths.SourceEncoderContractPath));
        Assert.False(File.Exists(replacement.Paths.PolicyCheckpointContractPath));

        var nestedCancellation = CloneDpoPromotionContractFixture(
            fixture,
            root,
            "nested-cancellation");
        await Assert.ThrowsAsync<IOException>(() =>
            DesignConversionDpoPromotionArtifactContractCodec.PublishAsync(
                nestedCancellation.Paths,
                nestedCancellation.Bridge,
                CancellationToken.None,
                _ => throw new IOException(
                    "nested cancellation",
                    new OperationCanceledException("nested"))));

        var unrequestedCancellation = CloneDpoPromotionContractFixture(
            fixture,
            root,
            "unrequested-cancellation");
        await Assert.ThrowsAsync<OperationCanceledException>(() =>
            DesignConversionDpoPromotionArtifactContractCodec.PublishAsync(
                unrequestedCancellation.Paths,
                unrequestedCancellation.Bridge,
                CancellationToken.None,
                _ => throw new OperationCanceledException("unrequested")));

        var fatal = CloneDpoPromotionContractFixture(fixture, root, "fatal-partial");
        await Assert.ThrowsAsync<OutOfMemoryException>(() =>
            DesignConversionDpoPromotionArtifactContractCodec.PublishAsync(
                fatal.Paths,
                fatal.Bridge,
                CancellationToken.None,
                stage =>
                {
                    if (stage == DesignConversionDpoPromotionContractIoStage.AfterSourceEncoderPublish)
                        throw new OutOfMemoryException("fatal test injection");
                }));
        Assert.True(File.Exists(fatal.Paths.SourceEncoderContractPath));
        Assert.False(File.Exists(fatal.Paths.PolicyCheckpointContractPath));
        AssertNoPromotionContractTemps(fatal.Paths.OutputDirectory);

        var recovered = await DesignConversionDpoPromotionArtifactContractCodec.PublishAsync(
            fatal.Paths,
            fatal.Bridge,
            CancellationToken.None);
        Assert.True(recovered.IsSuccess, recovered.ErrorMessage);
        Assert.True(File.Exists(fatal.Paths.PolicyCheckpointContractPath));
        AssertNoPromotionContractTemps(fatal.Paths.OutputDirectory);
    }

    [Fact]
    public async Task JsonlStorage_RoundTripsExamplesWithDeterministicOrdering()
    {
        var path = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString("N"), "design-dpo.jsonl");
        var storage = new JsonlDesignConversionDpoStorage(path);

        await Save(storage, DesignConversionDpoGeneratorTests.CreateExample("medium", DesignConversionDpoUnits.CriticUnit, usefulness: 0.60));
        await Save(storage, DesignConversionDpoGeneratorTests.CreateExample("high", DesignConversionDpoUnits.CriticUnit, usefulness: 0.95));
        await Save(storage, DesignConversionDpoGeneratorTests.CreateExample("low", DesignConversionDpoUnits.ImproverUnit, usefulness: 0.30));

        var reloaded = new JsonlDesignConversionDpoStorage(path);
        var listed = await reloaded.ListExamplesAsync();
        var queried = await reloaded.QueryExamplesAsync(new DesignConversionDpoStorageQuery(UnitId: "critic"));

        Assert.True(listed.IsSuccess, listed.ErrorMessage);
        Assert.Equal(["high", "low", "medium"], listed.Value!.Select(example => example.ExampleId).ToArray());
        Assert.True(queried.IsSuccess, queried.ErrorMessage);
        Assert.Equal(["high", "medium"], queried.Value!.Select(example => example.ExampleId).ToArray());
    }

