    [Fact]
    public async Task RunTrainingIntake_FinalJournalRevocationPreventsTerminalRowAndSuccessAfterEarlierPairEffects()
    {
        var root = Path.Combine(
            Path.GetTempPath(),
            Guid.NewGuid().ToString("N"),
            "training-intake-final-journal-revocation");
        var pairStore = new RecordingDpoPairStore();
        var revocable = DesignConversionLegalTeacherCapabilityTestFactory.CreateRevocable(
            expectedOllamaModelLayerDigest: LegalTeacherModelLayerDigest);
        var previousBoundaryObserver =
            DesignConversionTrainingPipeline.MutationBoundaryObserverForTesting;

        try
        {
            var setupDb = new JsonlDesignConversionLocalArtifactDb(root);
            var fixture = await CreateOrdinaryApprovedRuntimeTrainingIntakeAsync(
                setupDb,
                "final-journal-revocation");
            var finalJournalBoundaryCount = 0;
            DesignConversionTrainingPipeline.MutationBoundaryObserverForTesting = boundary =>
            {
                if (!string.Equals(boundary, "run_final_journal", StringComparison.Ordinal))
                    return;

                finalJournalBoundaryCount++;
                revocable.BeginRevocationAsync().GetAwaiter().GetResult();
            };
            var db = new JsonlDesignConversionLocalArtifactDb(
                root,
                createTrainingIntakeJournalWaitTaskObserverForTesting: null,
                createTrainingIntakeJournalGateAcquiredCallbackForTesting: null,
                legalTeacherAdmissionAuthority: revocable.Authority,
                trainingIntakeDpoPairStoreForTesting: pairStore);

            var result = await db.RunTrainingIntakeAsync(
                fixture.Intake.IntakeId,
                Pass157LocalPromotionOptions(
                    "final-journal-revocation-run",
                    BuildPassingMeasurementGateRequest(
                        "final-journal-revocation-gate")));

            Assert.False(result.IsSuccess);
            Assert.Equal(
                ServerOwnedLegalTrainingTeacherAdmissionAuthority
                    .AdmissionRevokedErrorCode,
                result.ErrorCode);
            Assert.Equal(1, finalJournalBoundaryCount);
            var persistedPairs = pairStore.GetAll();
            Assert.True(persistedPairs.IsSuccess, persistedPairs.ErrorMessage);
            Assert.Single(persistedPairs.Value!);
            Assert.False(File.Exists(Path.Combine(root, "training-intake-runs.jsonl")));
        }
        finally
        {
            DesignConversionTrainingPipeline.MutationBoundaryObserverForTesting =
                previousBoundaryObserver;
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }

