    private static void AssertOptimizerPayloadCustodyReady(
        IReadOnlyList<DesignConversionDpoTrainingRecord> records)
    {
        Assert.False(DesignConversionDpoCorpusAdmissionRequirementPolicy
                .RequiresAdmission(records),
            "Optimizer-side-content-contract fixtures must remain ordinary runtime-approved records; " +
            "they must not require corpus admission.");
        foreach (var record in records)
        {
            var custody = JsonlDesignConversionLocalArtifactDb
                .ValidateAndMaterializePayloadCustody(record);
            Assert.True(
                custody.IsSuccess,
                $"{record.RecordId}: {custody.ErrorCode}; blocks=" +
                string.Join(",", DesignConversionTrainingMeasurementGatePolicy
                    .GetRecordBlockReasons(record)));
        }
    }

    private static async Task ApproveRuntimeCreatedDpoCandidatesAsync(
        JsonlDesignConversionLocalArtifactDb db,
        string storedRecordId,
        IReadOnlyList<DesignConversionDpoTrainingRecord> candidates,
        string id,
