    {
        for (var index = 0; index < candidates.Count; index++)
        {
            var candidate = candidates[index];
            var approval = await db.ApproveRuntimeCreatedDpoCandidateAsync(
                storedRecordId,
                candidate.RecordId,
                $"reviewer:{id}:{index:00}:{candidate.RecordId}",
                $"{id} candidate approved through runtime authority rewrite",
                DateTimeOffset.UnixEpoch.AddMinutes(approvalStartMinute + index));
