    private static async Task<DesignConversionTrainingIntakeRecord>
        CreateDualTargetTeacherTrainingIntakeAsync(
            JsonlDesignConversionLocalArtifactDb db,
            Tests.DesignConversionDualTargetTeacherAdmissionTests.Fixture aggregate,
            string id,
            bool mismatchAggregateAuthoringIdentity = false,
            bool includeHeldOutRecord = true)
    {
        var pairRecords = aggregate.Records
            .Take(2)
            .Select((record, index) => ToReviewPendingTeacherCandidate(
                record,
                $"{id}-aggregate",
                mismatchAggregateAuthoringIdentity && index == 1
                    ? DesignConversionDpoGenerator.Sha256Ref(
                        $"{id}:mismatched-authoring-output")
                    : null))
            .ToArray();
        Assert.Equal(
            new[]
            {
                DesignConversionDpoUnits.CriticUnit,
                DesignConversionDpoUnits.ImproverUnit
            },
            pairRecords.Select(static record => record.UnitId));
        var heldOut = ToReviewPendingTeacherCandidate(
            aggregate.Records[2],
            $"{id}-heldout");
        var records = includeHeldOutRecord
            ? pairRecords.Append(heldOut).ToArray()
            : pairRecords;
        Assert.False(DesignConversionDpoCorpusAdmissionRequirementPolicy
            .RequiresAdmission(records));
        var stored = await Save(db, BuildArtifactRecord(
            $"storage-record-{id}",
            $"job-{id}",
            $"request-{id}",
            DesignConversionVisualQaBoundaryPolicy.TestProviderOnlyMarker,
            records,
            "<main>dual target teacher local intake</main>",
            ".dual-target-teacher-local-intake{}") with
        {
            SanitizedSourceRefs = new Dictionary<string, string>(
                StringComparer.Ordinal)
            {
                ["source_manifest_ref"] =
                    $"manifest://design-conversion/{id}",
                ["source_kind"] = "figma",
                ["design_tree_payload_ref"] = $"sha256:{id}-design-tree",
                ["original_tree_payload_ref"] =
                    $"sha256:{id}-original-tree",
                ["source_artifact:expected_desktop"] =
                    $"sha256:{id}-expected",
                ["source_artifact:actual_desktop"] =
                    $"sha256:{id}-actual"
            }
        });
        foreach (var record in records)
        {
            var reviewerRef = string.Equals(
                    record.TeacherProvenance?.RequestId,
                    pairRecords[0].TeacherProvenance?.RequestId,
                    StringComparison.Ordinal)
                ? $"reviewer:{id}:aggregate"
                : $"reviewer:{id}:heldout";
            var approval = await db.ApproveRuntimeCreatedDpoCandidateAsync(
                stored.RecordId,
                record.RecordId,
                reviewerRef,
                $"{id} exact dual target teacher fixture approved",
                DateTimeOffset.UnixEpoch.AddMinutes(240));
            Assert.True(approval.IsSuccess, approval.ErrorMessage);
        }

        var handoff = await db.ExportApprovedRuntimeDpoCandidatesAsync(
            new DesignConversionLocalArtifactDbQuery(JobId: $"job-{id}"),
            DateTimeOffset.UnixEpoch.AddMinutes(241));
        Assert.True(handoff.IsSuccess, handoff.ErrorMessage);
        Assert.Equal(
            includeHeldOutRecord ? 3 : 2,
            handoff.Value!.Rows.Count);
        var intake = await db.CreateTrainingIntakeAsync(
            handoff.Value,
            $"requester:{id}",
            $"{id} exact dual target teacher training intake",
            DateTimeOffset.UnixEpoch.AddMinutes(242));
        Assert.True(intake.IsSuccess, intake.ErrorMessage);
        Assert.Equal(
            includeHeldOutRecord ? 3 : 2,
            intake.Value!.AcceptedCandidateCount);
        return intake.Value;
    }

    private static DesignConversionDpoTrainingRecord
        ToReviewPendingTeacherCandidate(
            DesignConversionDpoTrainingRecord record,
            string id,
            string? teacherAuthoringOutputHashOverride = null)
    {
        var prepared = WithRuntimeArtifactProofRefs(
            ToRuntimeApprovedCandidate(record),
            id);
        if (!string.IsNullOrWhiteSpace(teacherAuthoringOutputHashOverride))
        {
            var metadata = new Dictionary<string, string>(
                prepared.Provenance.Metadata,
                StringComparer.Ordinal)
            {
                ["teacher_authoring_output_hash"] =
                    teacherAuthoringOutputHashOverride
            };
            prepared = prepared with
            {
                Provenance = prepared.Provenance with { Metadata = metadata }
            };
        }

        // Custody строим тем же canonical helper, что и зелёные runtime
        // fixtures: он переводит approved metadata обратно в review-pending
        // lifecycle и привязывает секрет к уже подготовленным real html/css.
        return AttachOptimizerPayloadCustody(
            prepared,
            prepared.Chosen,
            prepared.Rejected);
    }

