            new DesignConversionLocalArtifactDbQuery(JobId: $"job-{id}"),
            DateTimeOffset.UnixEpoch.AddMinutes(311));
        Assert.True(handoff.IsSuccess, handoff.ErrorMessage);
        Assert.Equal(2, handoff.Value!.Rows.Count);

        var intake = await api.CreateTrainingIntakeAsync(
            handoff.Value,
            $"requester:{id}",
            $"{id} approved runtime DPO pair-store training intake",
            DateTimeOffset.UnixEpoch.AddMinutes(312));

        var storedTrain = Assert.Single(
            stored.DpoCandidates,
            candidate => string.Equals(candidate.RecordId, train.RecordId, StringComparison.Ordinal));
        var storedHeldOut = Assert.Single(
            stored.DpoCandidates,
            candidate => string.Equals(candidate.RecordId, heldOut.RecordId, StringComparison.Ordinal));

        return new ApprovedTrainingIntakeAttempt(
            intake,
            storedTrain.TrainingRecord,
            storedHeldOut.TrainingRecord);
    }

