    private static void AssertTrainingIntakePairMatchesRecord(
        IReadOnlyList<DpoPair> pairs,
        DesignConversionDpoTrainingRecord record)
    {
        var item = DesignConversionTrainingPipeline.ToCanonicalTrainingItem(record);
        var pair = Assert.Single(pairs, candidate =>
            string.Equals(candidate.Prompt, item.Prompt, StringComparison.Ordinal) &&
            string.Equals(candidate.Chosen, item.ChosenResponse, StringComparison.Ordinal) &&
            string.Equals(candidate.Rejected, item.RejectedResponse, StringComparison.Ordinal));
        var sharedProjection =
            DesignConversionTrainingIntakeDpoPairAuthority.Project(record);
        Assert.True(sharedProjection.IsSuccess, sharedProjection.ErrorMessage);
        Assert.Equal(
            ToComparableDpoPair(sharedProjection.Value!),
            ToComparableDpoPair(pair));
        // Для DesignConversion intake v5 identity является частью контракта:
        // v4 больше не доказывает сохранение sideAuthorship.
        Assert.Equal(
            FileDpoPairStore.ComputeIdentity(
                sharedProjection.Value!,
                schemaVersion: 5),
            FileDpoPairStore.ComputeIdentity(pair, schemaVersion: 5));

        Assert.Equal(DesignConversionMachine.DomainTag, pair.Domain);
        Assert.Equal(record.Provenance.CreatedAtUtc, pair.CapturedAt);
        var projectedContent = DpoPairTrainingContentAuthority.Project([pair]);
        Assert.True(projectedContent.IsSuccess, projectedContent.ErrorMessage);
        Assert.Equal(
            record.TeacherProvenance with
            {
                TrainingContentSha256 = projectedContent.Value!.Rows[0].Sha256
            },
            pair.TeacherProvenance);
        Assert.NotNull(pair.GovernanceDecision);
        Assert.True(pair.GovernanceDecision!.LicenseAccepted);
        Assert.False(pair.GovernanceDecision.IsQuarantined);
        Assert.NotEmpty(pair.GovernanceDecision.EvidenceRefs);
        Assert.All(pair.GovernanceDecision.EvidenceRefs, reference =>
            Assert.Matches("^sha256:[0-9a-f]{64}$", reference));
    }

    private static string ToComparableDpoPair(DpoPair pair)
        => JsonSerializer.Serialize(new
        {
            pair.Prompt,
            pair.Chosen,
            pair.Rejected,
            pair.Domain,
            pair.CapturedAt,
            pair.TeacherProvenance,
            pair.GovernanceDecision,
            pair.ChosenAuthorship,
            pair.RejectedAuthorship
        }, DesignConversionCheckpointJsonOptions.Standard);

    private static (
        DesignConversionDpoTrainingRecord Selected,
        DesignConversionDpoTrainingRecord Excluded)
        ResolvePersistedFixtureRecord(
            DpoPair pair,
            ApprovedTrainingIntakeFixture fixture)
    {
        var records = new[] { fixture.TrainRecord, fixture.HeldOutRecord };
        var selected = Assert.Single(
            records,
            record => MatchesPersistedDpoPair(record, pair));
        var excluded = Assert.Single(
            records,
            record => !string.Equals(
                record.RecordId,
                selected.RecordId,
                StringComparison.Ordinal));
        return (selected, excluded);
    }

    private static bool MatchesPersistedDpoPair(
        DesignConversionDpoTrainingRecord record,
        DpoPair pair)
    {
        if (record.PayloadCustodySecret is not
            DesignConversionDpoPayloadCustodySecret custody)
        {
            return false;
        }

        return string.Equals(custody.Prompt, pair.Prompt, StringComparison.Ordinal) &&
               string.Equals(custody.ChosenResponse, pair.Chosen, StringComparison.Ordinal) &&
               string.Equals(custody.RejectedResponse, pair.Rejected, StringComparison.Ordinal);
    }

    private static string DescribeLocalPromotionReadiness(
        DesignConversionTrainingIntakeLocalPromotionResult result)
        => string.Join(
            "|",
            (result.BlockReasons ?? [])
                .Concat(result.Warnings ?? [])
                .Concat(result.BoundaryMetadata
                    .Where(static pair =>
                        pair.Key.Contains("ready", StringComparison.OrdinalIgnoreCase) ||
                        pair.Key.Contains("promotion", StringComparison.OrdinalIgnoreCase) ||
                        pair.Key.Contains("checkpoint", StringComparison.OrdinalIgnoreCase) ||
                        pair.Key.Contains("weight", StringComparison.OrdinalIgnoreCase) ||
                        pair.Key.Contains("measurement", StringComparison.OrdinalIgnoreCase) ||
                        pair.Key.Contains("continuation", StringComparison.OrdinalIgnoreCase))
                    .Select(static pair => $"{pair.Key}={pair.Value}")));

    private sealed class FailingDpoPairStore : IDpoPairBatchReservationStore
    {
        public const string ErrorCode = "TEST_DPO_PAIR_STORE_FAILED";
        public int AddCallCount { get; private set; }
        public int AddAtomicGroupCallCount { get; private set; }
        public int ReserveBatchCallCount { get; private set; }
        public int ReleaseBatchCallCount { get; private set; }
        public IReadOnlyList<DpoPair> Pairs => [];

        public OperationResult<DpoPairBatchReservation> ReserveBatch(
            string reservationId,
            IReadOnlyList<DpoPair> pairs)
        {
            ReserveBatchCallCount++;
            var batchSha256 = $"sha256:{Sha256Text(string.Join(
                "|",
                pairs.Select(pair => JsonSerializer.Serialize(
                    pair,
                    DesignConversionCheckpointJsonOptions.Standard))))}";
            return OperationResult<DpoPairBatchReservation>.Ok(
                new DpoPairBatchReservation(
                    reservationId,
                    batchSha256,
                    pairs.Count));
        }

        public OperationResult<string> Add(DpoPair pair)
        {
            AddCallCount++;
            return OperationResult<string>.Fail(
                "Injected DPO pair-store failure.",
