    private sealed class RecordingDpoPairStore : IDpoPairBatchReservationStore
    {
        private readonly List<DpoPair> _pairs = [];

        public int AddCallCount { get; private set; }
        public int ReserveBatchCallCount { get; private set; }
        public int ReleaseBatchCallCount { get; private set; }

        public OperationResult<DpoPairBatchReservation> ReserveBatch(
            string reservationId,
            IReadOnlyList<DpoPair> pairs)
        {
            lock (_pairs)
            {
                ReserveBatchCallCount++;
                var batchSha256 = $"sha256:{Sha256Text(string.Join(
                    "|",
                    pairs.Select(pair => JsonSerializer.Serialize(
                        pair,
                        DesignConversionCheckpointJsonOptions.Standard))))}";
                return OperationResult<DpoPairBatchReservation>.Ok(
                    new DpoPairBatchReservation(
                        reservationId,
                        batchSha256,
                        pairs.Count));
            }
        }

        public OperationResult<string> Add(DpoPair pair)
        {
            lock (_pairs)
            {
                AddCallCount++;
                _pairs.Add(pair);
                return OperationResult<string>.Ok($"recording-dpo-pair:{_pairs.Count}");
            }
        }

        public OperationResult<IReadOnlyList<DpoPair>> GetAll()
        {
            lock (_pairs)
            {
                return OperationResult<IReadOnlyList<DpoPair>>.Ok(_pairs.ToArray());
            }
        }

        public OperationResult<bool> ReleaseBatch(
            DpoPairBatchReservation reservation)
        {
            lock (_pairs)
            {
                ReleaseBatchCallCount++;
                return OperationResult<bool>.Ok(true);
            }
        }
    }

    private static async Task<string> AppendAndReadHtmlRefAsync(
        string scope,
        string htmlRef)
    {
        var root = Path.Combine(
            Path.GetTempPath(),
            Guid.NewGuid().ToString("N"),
            "local-artifact-db-" + scope);
        var db = new JsonlDesignConversionLocalArtifactDb(root);
        var record = BuildArtifactRecord(
            "storage-record-" + scope,
            "job-" + scope,
            "request-" + scope,
            DesignConversionVisualQaBoundaryPolicy.TestProviderOnlyMarker,
            [
                BuildTrainingRecord(
                    scope,
                    DesignConversionDpoUnits.ImproverUnit,
                    usefulness: 0.91)
            ],
            "<main>payload ref culture</main>",
            ".payload-ref-culture{}");
        var append = await db.AppendRecordAsync(
            record with
            {
                ConversionResult =
                    record.ConversionResult with
                    {
                        HtmlRef = htmlRef
                    }
            });
        Assert.True(append.IsSuccess, append.ErrorMessage);
        return append.Value!.ConversionResult.HtmlRef;
    }

    private static string SourceEncoderContractPathForPolicyContractPath(string policyContractPath)
    {
        var policyContractFileName = Path.GetFileName(policyContractPath);
        Assert.EndsWith(
            DesignConversionDpoPromotionArtifactContractCodec.PolicyCheckpointContractSuffix,
            policyContractFileName,
            StringComparison.Ordinal);
        var artifactStem = policyContractFileName[
            ..^DesignConversionDpoPromotionArtifactContractCodec.PolicyCheckpointContractSuffix.Length];
        return Path.Combine(
            Path.GetDirectoryName(policyContractPath)!,
            artifactStem + DesignConversionDpoPromotionArtifactContractCodec.SourceEncoderContractSuffix);
    }

    private sealed class CountingLocalOnlyPromotionUploader
        : IDesignConversionBoundedPromotionUploader,
          IDesignConversionPromotionUploaderPreflight
    {
        private int _count;
        private readonly char _fingerprintCharacter;

        public CountingLocalOnlyPromotionUploader(
            char fingerprintCharacter = 'a')
            => _fingerprintCharacter = fingerprintCharacter;

        public int Count => Interlocked.CompareExchange(ref _count, 0, 0);
        public int MaximumSerializedReceiptUtf8Bytes => 64 * 1024;
        public DesignConversionLocalReceiptOnlyPromotionUploadAuthority Authority
        {
            get
            {
                var issued =
                    DesignConversionLocalReceiptOnlyPromotionUploadAuthority
                        .Issue(
                            this,
                            "DESIGN_CONVERSION_TEST_LOCAL_RECEIPT_ONLY_UPLOAD_AUTHORITY");
                if (!issued.IsSuccess)
                    throw new InvalidOperationException(issued.ErrorMessage);
                return issued.Value!;
            }
        }

        public DesignConversionTrainingManifest? LastManifest { get; private set; }
        public DesignConversionPromotionGateReport? LastGateReport { get; private set; }
        public OperationResult<string> PreflightConfigurationFingerprintSha256()
            => OperationResult<string>.Ok(
                "sha256:" + new string(_fingerprintCharacter, 64));

        public Task<OperationResult<DesignConversionPromotionUploadReceipt>> UploadAsync(
            DesignConversionTrainingManifest manifest,
            DesignConversionPromotionGateReport gateReport,
            CancellationToken ct = default)
        {
            Interlocked.Increment(ref _count);
            LastManifest = manifest;
            LastGateReport = gateReport;
            return Task.FromResult(OperationResult<DesignConversionPromotionUploadReceipt>.Ok(
                new DesignConversionPromotionUploadReceipt(
                    UploadId: $"{manifest.ManifestId}:local-only",
                    RemoteRef: DesignConversionPromotedLocalModelLoader.LocalOnlyPromotionRefPrefix +
                               Uri.EscapeDataString(manifest.ManifestId),
                    UploadedAtUtc: DateTimeOffset.UtcNow,
                    EvidenceRefs:
                    [
                        "DESIGN_CONVERSION_TRAINING_INTAKE_LOCAL_ONLY_PROMOTION_UPLOADER_CALLED",
                        "EXTERNAL_CLOUD_UPLOAD_NOT_ATTEMPTED",
                        "DESIGN_CONVERSION_TRAINING_INTAKE_EXTERNAL_CLOUD_UPLOAD_NOT_ATTEMPTED"
                    ])
                {
                    PublicationKind = DesignConversionPromotionPublicationKind.LocalOnlyNoRemoteAttempt,
                    UploadAttempted = false,
                    UploadSucceeded = false,
                    VerificationSucceeded = false,
                    PublicationStatus = DesignConversionPromotionPublicationStatus.NotUploaded
                }));
        }
    }

    private sealed class NativeErrorIOException : IOException
    {
        public NativeErrorIOException(int nativeError)
            : base($"injected native error {nativeError}")
            => HResult = nativeError;
    }

    private sealed class NativeErrorException : Exception
    {
        public NativeErrorException(int nativeError, Exception inner)
            : base($"injected unrelated native-shaped error {nativeError}", inner)
            => HResult = nativeError;
    }

    public enum PausedReceiptMode
    {
        AcceptedLocal,
        AcceptedRemote,
        Rejected,
        UploadError
    }

    private sealed class PausedArtifactLeaseUploader
        : IDesignConversionBoundedPromotionUploader,
          IDesignConversionPromotionUploaderPreflight
    {
        private int _count;
        private readonly PausedReceiptMode _receiptMode;

        public PausedArtifactLeaseUploader(PausedReceiptMode receiptMode)
            => _receiptMode = receiptMode;

        public int Count => Interlocked.CompareExchange(ref _count, 0, 0);
        public int MaximumSerializedReceiptUtf8Bytes => 64 * 1024;
        public DesignConversionLocalReceiptOnlyPromotionUploadAuthority Authority
        {
            get
            {
                var issued =
                    DesignConversionLocalReceiptOnlyPromotionUploadAuthority
                        .Issue(
                            this,
                            "DESIGN_CONVERSION_TEST_PAUSED_LOCAL_RECEIPT_ONLY_UPLOAD_AUTHORITY");
                if (!issued.IsSuccess)
                    throw new InvalidOperationException(issued.ErrorMessage);
                return issued.Value!;
            }
        }

        public TaskCompletionSource Entered { get; } =
            new(TaskCreationOptions.RunContinuationsAsynchronously);
        public TaskCompletionSource Release { get; } =
            new(TaskCreationOptions.RunContinuationsAsynchronously);
        public Dictionary<string, byte[]> OriginalBytes { get; } =
            new(StringComparer.OrdinalIgnoreCase);
        public Dictionary<string, byte[]> ObservedBytes { get; } =
            new(StringComparer.OrdinalIgnoreCase);
        public DesignConversionTrainingManifest? LastManifest { get; private set; }
        public DesignConversionPromotionGateReport? LastGateReport { get; private set; }
        public OperationResult<string> PreflightConfigurationFingerprintSha256()
            => OperationResult<string>.Ok(
                "sha256:" + new string('f', 64));

        public async Task<OperationResult<DesignConversionPromotionUploadReceipt>> UploadAsync(
            DesignConversionTrainingManifest manifest,
            DesignConversionPromotionGateReport gateReport,
            CancellationToken ct = default)
        {
            Interlocked.Increment(ref _count);
            LastManifest = manifest;
            LastGateReport = gateReport;
            var artifacts = manifest.PromotionArtifacts!;
            var outputDirectory = Path.GetDirectoryName(artifacts.CheckpointPath)!;
            Assert.NotNull(artifacts.PolicyCheckpointArtifact);
            Assert.False(string.IsNullOrWhiteSpace(artifacts.SourceEncoderPath));
            Assert.True(File.Exists(artifacts.SourceEncoderPath));
            var paths = new[]
            {
                artifacts.CheckpointPath,
                artifacts.TokenizerPath,
                artifacts.PolicyPath,
                artifacts.SourceEncoderPath!,
                Path.Combine(
                    outputDirectory,
                    artifacts.PolicyCheckpointArtifact!.FileName)
            };
            Assert.Equal(5, paths
                .Select(Path.GetFullPath)
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .Count());
            foreach (var path in paths)
                OriginalBytes[path] = File.ReadAllBytes(path);
            Entered.TrySetResult();
            await Release.Task.WaitAsync(ct);
            foreach (var path in paths)
                ObservedBytes[path] = File.ReadAllBytes(path);

            if (_receiptMode == PausedReceiptMode.UploadError)
            {
                return OperationResult<DesignConversionPromotionUploadReceipt>.Fail(
                    "Injected evaluated promotion upload failure.",
                    "INJECTED_UPLOAD_FAILED");
            }

            var receipt = new DesignConversionPromotionUploadReceipt(
                UploadId: $"{manifest.ManifestId}:retained-lease",
                RemoteRef: _receiptMode == PausedReceiptMode.AcceptedRemote
                    ? "https://model.example.test/design-conversion/retained-lease"
                    : DesignConversionPromotedLocalModelLoader.LocalOnlyPromotionRefPrefix +
                      Uri.EscapeDataString(manifest.ManifestId),
                UploadedAtUtc: DateTimeOffset.UtcNow,
                EvidenceRefs: ["DESIGN_CONVERSION_RETAINED_UPLOAD_LEASE_TEST"])
            {
                PublicationKind = _receiptMode == PausedReceiptMode.AcceptedRemote
                    ? DesignConversionPromotionPublicationKind.VerifiedModelServerUpload
                    : DesignConversionPromotionPublicationKind.LocalOnlyNoRemoteAttempt,
                UploadAttempted = _receiptMode != PausedReceiptMode.AcceptedLocal,
                UploadSucceeded = _receiptMode == PausedReceiptMode.AcceptedRemote,
                VerificationSucceeded = _receiptMode == PausedReceiptMode.AcceptedRemote,
                PublicationStatus = _receiptMode == PausedReceiptMode.AcceptedRemote
                    ? DesignConversionPromotionPublicationStatus.UploadedVerified
                    : DesignConversionPromotionPublicationStatus.NotUploaded,
                ProvenanceRef = _receiptMode == PausedReceiptMode.AcceptedRemote
                    ? "retained-lease-verified-provenance"
                    : string.Empty
            };
            if (_receiptMode == PausedReceiptMode.Rejected)
                receipt = receipt with { UploadAttempted = true };
            return OperationResult<DesignConversionPromotionUploadReceipt>.Ok(receipt);
        }
    }

