    private static async Task<DesignConversionLocalArtifactDbRecord>
        PersistLegacyApprovedCandidateWithoutBlockReasonsAsync(
            string root,
            DesignConversionLocalArtifactDbRecord stored)
    {
        var storedCandidate = Assert.Single(stored.DpoCandidates);
        var legacy = stored with
        {
            DpoCandidates =
            [
                storedCandidate with { BlockReasons = [] }
            ]
        };
        var fingerprintProjector = typeof(JsonlDesignConversionLocalArtifactDb)
            .GetMethod(
                "BuildImmutableAppendFingerprint",
                BindingFlags.Static | BindingFlags.NonPublic,
                binder: null,
                types: [typeof(DesignConversionLocalArtifactDbRecord)],
                modifiers: null);
        Assert.NotNull(fingerprintProjector);
        var fingerprint = Assert.IsType<string>(
            fingerprintProjector!.Invoke(null, [legacy]));
        legacy = legacy with
        {
            Metadata = new Dictionary<string, string>(
                legacy.Metadata,
                StringComparer.Ordinal)
            {
                [JsonlDesignConversionLocalArtifactDb
                    .ImmutableAppendFingerprintMetadataKey] = fingerprint
            }
        };

        var jsonOptions = new JsonSerializerOptions(
            DesignConversionCheckpointJsonOptions.Standard)
        {
            WriteIndented = false
        };
        // Simulate a pre-policy authority row directly. Re-entering through
        // AppendRecordAsync would normalize the candidate and repopulate its
        // block-reason array before query/export could exercise the consumer guard.
        await File.WriteAllTextAsync(
            Path.Combine(root, "conversion-results.jsonl"),
            JsonSerializer.Serialize(legacy, jsonOptions) + Environment.NewLine,
            new UTF8Encoding(
                encoderShouldEmitUTF8Identifier: false,
                throwOnInvalidBytes: true));
        File.Delete(Path.Combine(root, "conversion-results.index.json"));
        return legacy;
    }

