    private static DesignConversionDpoPolicyBaseTestProvider
        CreateW085DeterministicPromotionProvider()
        => new(modelSet =>
        {
            SetW085DeterministicCheckpointState(modelSet.Policy);
            DesignConversionDpoPolicyBaseTestProvider.CopyParameters(
                modelSet.Policy,
                modelSet.Reference);
            DesignConversionDpoPolicyBaseTestProvider.CopyParameters(
                modelSet.Policy,
                modelSet.FreshLoadTarget);

            AssertW085CheckpointModelsBitwiseEqual(
                modelSet.Policy,
                modelSet.Reference);
            AssertW085CheckpointModelsBitwiseEqual(
                modelSet.Policy,
                modelSet.FreshLoadTarget);
            AssertW085NoPreAttachedLoraState(modelSet.Policy);
            AssertW085NoPreAttachedLoraState(modelSet.Reference);
            AssertW085NoPreAttachedLoraState(modelSet.FreshLoadTarget);
            return OperationResult<DesignConversionDpoPolicyBaseModelSet>.Ok(modelSet);
        });

    private static void SetW085DeterministicCheckpointState(LlmModel model)
    {
        var rng = new Random(42);
        var baseParameters = model.BaseParameters.ToArray();
        Assert.Equal(12, baseParameters.Length);
        FillW085Normal(baseParameters[0].Value.Data, rng, std: 0.02f);
        FillW085Ones(baseParameters[1].Value.Data);
        FillW085Kaiming(
            baseParameters[2].Value.Data,
            rng,
            baseParameters[2].Value.Shape.Dimensions[1]);
        FillW085Kaiming(
            baseParameters[3].Value.Data,
            rng,
            baseParameters[3].Value.Shape.Dimensions[1]);
        FillW085Kaiming(
            baseParameters[4].Value.Data,
            rng,
            baseParameters[4].Value.Shape.Dimensions[1]);
        FillW085Kaiming(
            baseParameters[5].Value.Data,
            rng,
            baseParameters[5].Value.Shape.Dimensions[1]);
        FillW085Ones(baseParameters[6].Value.Data);
        FillW085Kaiming(
            baseParameters[7].Value.Data,
            rng,
            baseParameters[7].Value.Shape.Dimensions[1]);
        FillW085Kaiming(
            baseParameters[8].Value.Data,
            rng,
            baseParameters[8].Value.Shape.Dimensions[1]);
        FillW085Kaiming(
            baseParameters[9].Value.Data,
            rng,
            baseParameters[9].Value.Shape.Dimensions[1]);
        FillW085Ones(baseParameters[10].Value.Data);
        FillW085Kaiming(
            baseParameters[11].Value.Data,
            rng,
            baseParameters[11].Value.Shape.Dimensions[1]);

        foreach (var entry in model.GetCheckpointParameterEntries())
        {
            if (entry.Key.EndsWith(".lora_a", StringComparison.Ordinal))
            {
                for (var index = 0; index < entry.Parameter.Value.Data.Length; index++)
                {
                    entry.Parameter.Value.Data[index] =
                        ((index % 7) - 3) * 0.03125f;
                }
            }
            else if (entry.Key.EndsWith(".lora_b", StringComparison.Ordinal))
            {
                Array.Clear(entry.Parameter.Value.Data);
            }
            else
            {
                Assert.Contains(
                    baseParameters,
                    parameter => ReferenceEquals(parameter, entry.Parameter));
            }

            Assert.All(entry.Parameter.Value.Data, value => Assert.True(float.IsFinite(value)));
        }
    }

    private static void FillW085Kaiming(float[] data, Random rng, int fanIn)
    {
        var bound = MathF.Sqrt(6.0f / fanIn);
        for (var index = 0; index < data.Length; index++)
            data[index] = (float)(rng.NextDouble() * 2 * bound - bound);
    }

    private static void FillW085Normal(float[] data, Random rng, float std)
    {
        for (var index = 0; index < data.Length; index += 2)
        {
            var u1 = 1.0 - rng.NextDouble();
            var u2 = 1.0 - rng.NextDouble();
            var radius = Math.Sqrt(-2.0 * Math.Log(u1));
            var theta = 2.0 * Math.PI * u2;
            data[index] = (float)(radius * Math.Cos(theta) * std);
            if (index + 1 < data.Length)
                data[index + 1] = (float)(radius * Math.Sin(theta) * std);
        }
    }

    private static void FillW085Ones(float[] data)
        => Array.Fill(data, 1.0f);

    private static void AssertW085CheckpointModelsBitwiseEqual(
        LlmModel expected,
        LlmModel actual)
    {
        var expectedEntries = expected.GetCheckpointParameterEntries();
        var actualEntries = actual.GetCheckpointParameterEntries();
        Assert.Equal(expectedEntries.Count, actualEntries.Count);
        for (var entryIndex = 0; entryIndex < expectedEntries.Count; entryIndex++)
        {
            var expectedEntry = expectedEntries[entryIndex];
            var actualEntry = actualEntries[entryIndex];
            Assert.Equal(expectedEntry.Key, actualEntry.Key);
            Assert.Equal(
                expectedEntry.Parameter.Value.Shape.Dimensions,
                actualEntry.Parameter.Value.Shape.Dimensions);
            Assert.NotSame(
                expectedEntry.Parameter.Value.Data,
                actualEntry.Parameter.Value.Data);
            Assert.Equal(
                expectedEntry.Parameter.Value.Data
                    .Select(BitConverter.SingleToInt32Bits)
                    .ToArray(),
                actualEntry.Parameter.Value.Data
                    .Select(BitConverter.SingleToInt32Bits)
                    .ToArray());
        }
    }

    private static void AssertW085NoPreAttachedLoraState(LlmModel model)
    {
        var checkpointEntries = model.GetCheckpointParameterEntries();
        Assert.DoesNotContain(
            checkpointEntries,
            entry => entry.Key.EndsWith(".lora_a", StringComparison.Ordinal));
        Assert.DoesNotContain(
            checkpointEntries,
            entry => entry.Key.EndsWith(".lora_b", StringComparison.Ordinal));
    }

    private static void PerturbEvaluatedContinuationModelSetWeightsInLockstep(
        DesignConversionDpoPolicyBaseModelSet modelSet)
    {
        foreach (var model in new[]
                 {
                     modelSet.Policy,
                     modelSet.Reference,
                     modelSet.FreshLoadTarget
                 })
        {
            var entries = model.GetCheckpointParameterEntries();
            Assert.NotEmpty(entries);
            var values = entries[0].Parameter.Value.Data;
            Assert.NotEmpty(values);
            values[0] += 0.03125f;
        }
    }

    private static async Task<(LlmModel Policy, LlmModel Reference, DpoVectorBatch Batch)>
        BuildDirectDpoTrainerInputsAsync(string id)
    {
        var provider = new DesignConversionDpoPolicyBaseTestProvider();
        var provided = await provider.CreateModelSetAsync(CancellationToken.None);
        Assert.True(provided.IsSuccess, provided.ErrorMessage);
        var config = DesignConversionDpoPolicyBaseTestProvider.CreateConfig();
        var row = BuildEvaluatedPartitionForTests(id, heldOutCount: 1).TrainRecords[0];
        var packed = DesignConversionDpoPolicyCheckpointBridge
            .BuildEvaluatedPackedBatchPreviewForTests(
                row,
                config,
                includeTrainingVectorAndWeight: true);
        Assert.True(packed.IsSuccess, packed.ErrorMessage);
        return (
            provided.Value!.Policy,
            provided.Value.Reference,
            packed.Value!.VectorBatch);
    }

