    private sealed class WorkspaceLocalDpoStorageTestRoot : IDisposable
    {
        private static readonly string StorageTestRoot =
            Path.TrimEndingDirectorySeparator(Path.GetFullPath(
                Path.Combine(
                    DiscoverRepoRoot(),
                    "TestResults",
                    "design-conversion-dpo-storage")));

        private WorkspaceLocalDpoStorageTestRoot(string directoryPath)
        {
            DirectoryPath = RequireSafeChild(directoryPath);
            Directory.CreateDirectory(DirectoryPath);
        }

        public string DirectoryPath { get; }

        public static WorkspaceLocalDpoStorageTestRoot Create(string testName)
        {
            if (string.IsNullOrWhiteSpace(testName) ||
                Path.IsPathRooted(testName))
            {
                throw new InvalidOperationException(
                    $"Unsafe DesignConversion DPO storage test root name: {testName}");
            }

            return new WorkspaceLocalDpoStorageTestRoot(
                Path.Combine(
                    StorageTestRoot,
                    $"{testName}-{Guid.NewGuid():N}"));
        }

        public void Dispose()
        {
            var safePath = RequireSafeChild(DirectoryPath);
            if (Directory.Exists(safePath))
                Directory.Delete(safePath, recursive: true);
        }

        private static string RequireSafeChild(string directoryPath)
        {
            var fullPath = Path.TrimEndingDirectorySeparator(
                Path.GetFullPath(directoryPath));
            var requiredPrefix =
                StorageTestRoot + Path.DirectorySeparatorChar;
            if (string.Equals(
                    fullPath,
                    StorageTestRoot,
                    StringComparison.OrdinalIgnoreCase) ||
                !fullPath.StartsWith(
                    requiredPrefix,
                    StringComparison.OrdinalIgnoreCase))
            {
                throw new InvalidOperationException(
                    $"Refusing to clean a path outside {StorageTestRoot}: {fullPath}");
            }

            return fullPath;
        }

        private static string DiscoverRepoRoot()
        {
            var searchedStarts = new[]
            {
                AppContext.BaseDirectory,
                Directory.GetCurrentDirectory()
            };

            foreach (var start in searchedStarts)
            {
                var root = TryDiscoverRepoRoot(start);
                if (root is not null)
                    return root;
            }

            throw new InvalidOperationException(
                "Unable to discover llm_mvp_core repository root from " +
                $"{nameof(AppContext.BaseDirectory)}='{AppContext.BaseDirectory}' " +
                $"or current directory='{Directory.GetCurrentDirectory()}'. " +
                "Expected an ancestor containing both LlmFromScratch.sln and the Tests directory.");
        }

        private static string? TryDiscoverRepoRoot(string startPath)
        {
            if (string.IsNullOrWhiteSpace(startPath))
                return null;

            var fullStartPath = Path.GetFullPath(startPath);
            var directory = Directory.Exists(fullStartPath)
                ? new DirectoryInfo(fullStartPath)
                : Directory.GetParent(fullStartPath);

            while (directory is not null)
            {
                if (File.Exists(Path.Combine(directory.FullName, "LlmFromScratch.sln")) &&
                    Directory.Exists(Path.Combine(directory.FullName, "Tests")))
                {
                    return Path.TrimEndingDirectorySeparator(
                        Path.GetFullPath(directory.FullName));
                }

                directory = directory.Parent;
            }

            return null;
        }
    }

    private static async Task<DesignConversionDpoPromotionArtifactPublication>
        CorruptTokenizerArtifactAsync(
            DesignConversionDpoPromotionArtifactPublication publication,
            string tokenizerPath,
            byte[] tokenizerBytes)
    {
        var tokenizer = JsonSerializer.Deserialize<
            DesignConversionDpoUtf8ByteTokenizerArtifact>(
                tokenizerBytes,
                DesignConversionCheckpointJsonOptions.Standard);
        Assert.NotNull(tokenizer);
        var vocabulary = tokenizer!.Vocabulary.ToArray();
        var token = vocabulary[17];
        vocabulary[17] = token with { TokenId = token.TokenId == 17 ? 18 : 17 };
        var corrupted = tokenizer with { Vocabulary = vocabulary };
        await File.WriteAllBytesAsync(
            tokenizerPath,
            JsonSerializer.SerializeToUtf8Bytes(
                corrupted,
                new JsonSerializerOptions(DesignConversionCheckpointJsonOptions.Standard)
                {
                    WriteIndented = false
                }));
        return publication;
    }

    private static DesignConversionDpoPromotionArtifactPublication
        WithTokenizerBindingAndAnchors(
            DesignConversionDpoPromotionArtifactPublication publication,
            string tokenizerSha256,
            long tokenizerByteLength)
    {
        var original = publication.SourceEncoderContract.Binding;
        var binding = original with
        {
            TokenizerArtifactSha256 = tokenizerSha256,
            TokenizerArtifactByteLength = tokenizerByteLength
        };
        binding = binding with
        {
            ArtifactSetId = DesignConversionDpoPromotionArtifactContractCodec
                .BuildArtifactSetId(
                    binding.PolicyCheckpointFileName,
                    binding.PolicyCheckpointSha256,
                    binding.PolicyCheckpointByteLength,
                    binding.RuntimeCheckpointFileName,
                    binding.RuntimeCheckpointSha256,
                    binding.RuntimeCheckpointByteLength,
                    binding.TokenizerArtifactFileName,
                    binding.TokenizerArtifactSha256,
                    binding.TokenizerArtifactByteLength,
                    binding.SourceEncoderDescriptor,
                    publication.PolicyCheckpointContract.Evaluation)
        };

        return publication with
        {
            SourceEncoderContract = publication.SourceEncoderContract with
            {
                Binding = binding
            },
            PolicyCheckpointContract = publication.PolicyCheckpointContract with
            {
                Binding = binding
            },
            Anchors = publication.Anchors with
            {
                ArtifactSetId = binding.ArtifactSetId,
                TokenizerArtifactSha256 = binding.TokenizerArtifactSha256,
                TokenizerArtifactByteLength = binding.TokenizerArtifactByteLength
            }
        };
    }

    private static async Task<EvaluatedLineagePublication>
        PublishEvaluatedLineageCycleAsync(
            string root,
            string id,
            DesignConversionDpoResolvedPartition partition,
            IDesignConversionDpoPolicyBaseProvider provider,
            DesignConversionDpoPolicyContinuationRequest? continuationRequest = null)
    {
        Directory.CreateDirectory(root);
        var paths = DesignConversionDpoPromotionArtifactContractCodec.ResolvePaths(
            root,
            Path.Combine(root, id),
            id);
        Assert.True(paths.IsSuccess, paths.ErrorMessage);

        OperationResult<DesignConversionDpoEvaluatedBridgeLease> evaluated;
        if (continuationRequest is null)
        {
            evaluated = await DesignConversionDpoPolicyCheckpointBridge
                .ExecuteEvaluatedAndConvertAsync(
                    CreateEvaluatedLegalTeacherCapability(),
                    partition,
                    paths.Value!.OutputDirectory,
                    id,
                    paths.Value.RuntimeCheckpointPath,
                    provider,
                    new DesignConversionDpoPolicyCheckpointBridgeOptions(1, 1),
                    ct: CancellationToken.None);
        }
        else
        {
            evaluated = await DesignConversionDpoPolicyCheckpointBridge
                .ExecuteEvaluatedAndConvertAsync(
                    CreateEvaluatedLegalTeacherCapability(),
                    partition,
                    paths.Value!.OutputDirectory,
                    id,
                    paths.Value.RuntimeCheckpointPath,
                    provider,
                    new DesignConversionDpoPolicyCheckpointBridgeOptions(1, 1),
                    continuationRequest,
                    ct: CancellationToken.None);
        }

        Assert.True(evaluated.IsSuccess, evaluated.ErrorMessage);
        using var lease = evaluated.Value!;
        var publication = await DesignConversionDpoPromotionArtifactContractCodec
            .PublishEvaluatedAsync(
                paths.Value!,
                lease.Result,
                lease.Evaluation,
                CancellationToken.None);
        Assert.True(publication.IsSuccess, publication.ErrorMessage);
        Assert.True(DesignConversionDpoPromotionArtifactContractCodec
            .ValidateEvaluatedArtifactPublication(publication.Value));
        lease.CommitPublishedArtifacts();

        var published = publication.Value!;
        return new EvaluatedLineagePublication(
            published,
            published.PolicyCheckpointContract.Evaluation!,
            Path.Combine(paths.Value.OutputDirectory, lease.Result.PolicyCheckpointPath));
    }

    private static DesignConversionDpoPolicyContinuationRequest
        CreateLineageContinuationRequest(EvaluatedLineagePublication publication)
        => CreateLineageContinuationRequest(
            publication.PolicyCheckpointPath,
            publication.Publication);

    private static DesignConversionDpoPolicyContinuationRequest
        CreateLineageContinuationRequest(
        string policyCheckpointPath,
        DesignConversionDpoPromotionArtifactPublication publication)
        => CreateLineageContinuationRequest(
            new RecordingEvaluatedCheckpointSource(policyCheckpointPath),
            new RecordingEvaluatedCheckpointSource(policyCheckpointPath),
            publication);

    private static DesignConversionDpoPolicyContinuationRequest
        CreateLineageContinuationRequest(
            IDesignConversionDpoPolicyCheckpointSource checkpointSource,
            IDesignConversionDpoPolicyCheckpointSource bridgeProofSource,
            DesignConversionDpoPromotionArtifactPublication publication)
    {
        var runtimeBinding = DesignConversionDpoPromotionArtifactContractCodec
            .BuildRuntimeEncodingBinding(
                publication.SourceEncoderContract,
                publication.TokenizerArtifact);
        Assert.True(runtimeBinding.IsSuccess, runtimeBinding.ErrorMessage);
        var mutationAdmission =
            DesignConversionDpoCheckpointMutationAdmission.CreateTrustedCurrent(
                publication.SourceEncoderContract,
                publication.PolicyCheckpointContract,
                publication.PolicyCheckpointContract.Binding
                    .PolicyCheckpointSha256,
                publication.PolicyCheckpointContract.Binding
                    .PolicyCheckpointByteLength,
                publication.PolicyCheckpointContract.Binding
                    .PolicyCheckpointFileName,
                publication.SourceEncoderContract.Binding
                    .SourceEncoderDescriptor.SourceSignalSetSha256);
        Assert.True(mutationAdmission.IsSuccess, mutationAdmission.ErrorMessage);
        return new DesignConversionDpoPolicyContinuationRequest(
            checkpointSource,
            publication.SourceEncoderContract,
            publication.PolicyCheckpointContract,
            publication.TokenizerArtifact,
            runtimeBinding.Value)
        {
            CheckpointMutationAdmission = mutationAdmission.Value,
            BridgeProofCheckpointSource = bridgeProofSource
        };
    }

    private static void AssertComparableContinuationLineage(
        DesignConversionDpoHeldOutEvaluation evaluation,
        EvaluatedLineagePublication parent,
        int expectedCycleOrdinal)
    {
        var lineage = Assert.IsType<DesignConversionDpoHeldOutCycleAccuracyLineage>(
            evaluation.CycleAccuracyLineage);
        var parentLineage = Assert.IsType<DesignConversionDpoHeldOutCycleAccuracyLineage>(
            parent.Evaluation.CycleAccuracyLineage);

        Assert.Equal(DesignConversionDpoPolicyCheckpointBridge.EvaluatedSchema, evaluation.Schema);
        Assert.Equal(expectedCycleOrdinal, lineage.CycleOrdinal);
        Assert.Equal(evaluation.Accuracy, lineage.CurrentMeasuredAccuracy);
        Assert.True(lineage.HasParentMeasurement);
        Assert.Equal(parentLineage.CycleOrdinal, lineage.ParentCycleOrdinal);
        Assert.Equal(parent.Evaluation.Accuracy, lineage.ParentMeasuredAccuracy);
        Assert.Equal(
            evaluation.ReferencePolicyCheckpointSha256,
            lineage.ParentPolicyCheckpointSha256);
        Assert.Equal(
            parent.Publication.PolicyCheckpointContract.Binding.PolicyCheckpointSha256,
            lineage.ParentPolicyCheckpointSha256);
        Assert.Equal(parent.Evaluation.DatasetId, lineage.ParentDatasetId);
        Assert.Equal(
            parent.Evaluation.HeldOutRecordSetSha256,
            lineage.ParentHeldOutRecordSetSha256);
        Assert.Equal(
            parent.Evaluation.HeldOutSourceSetSha256,
            lineage.ParentHeldOutSourceSetSha256);
        Assert.Equal(
            parent.Evaluation.HeldOutEvaluationInputSha256,
            lineage.ParentHeldOutEvaluationInputSha256);
        Assert.True(lineage.ComparableHeldOut);
        Assert.Equal(evaluation.Accuracy - parent.Evaluation.Accuracy, lineage.AccuracyDelta);
    }

    private static DesignConversionDpoPromotionArtifactPublication
        WithEvaluationAndRecomputedBinding(
            DesignConversionDpoPromotionArtifactPublication publication,
            DesignConversionDpoHeldOutEvaluation evaluation)
    {
        var original = publication.SourceEncoderContract.Binding;
        var binding = original with
        {
            ArtifactSetId = DesignConversionDpoPromotionArtifactContractCodec
                .BuildArtifactSetId(
                    original.PolicyCheckpointFileName,
                    original.PolicyCheckpointSha256,
                    original.PolicyCheckpointByteLength,
                    original.RuntimeCheckpointFileName,
                    original.RuntimeCheckpointSha256,
                    original.RuntimeCheckpointByteLength,
                    original.TokenizerArtifactFileName,
                    original.TokenizerArtifactSha256,
                    original.TokenizerArtifactByteLength,
                    original.SourceEncoderDescriptor,
                    evaluation)
        };

        return publication with
        {
            SourceEncoderContract = publication.SourceEncoderContract with
            {
                Binding = binding
            },
            PolicyCheckpointContract = publication.PolicyCheckpointContract with
            {
                Binding = binding,
                Evaluation = evaluation
            },
            Anchors = publication.Anchors with
            {
                ArtifactSetId = binding.ArtifactSetId
            }
        };
    }

    private static string TokenizerMutationSha256(string value)
        => Convert.ToHexString(SHA256.HashData(
                System.Text.Encoding.UTF8.GetBytes(value)))
            .ToLowerInvariant();

    private static async Task<ValidatedEvaluatedPublisherFixture>
        BuildValidatedEvaluatedPublisherFixtureAsync(
            string root,
            string id,
            IDesignConversionDpoPolicyBaseProvider? provider = null)
    {
        Directory.CreateDirectory(root);
        var partition = BuildEvaluatedPartitionForTests(id, heldOutCount: 1);
        var outputDirectory = Path.Combine(root, $"{id}-evaluated-publication");
        var paths = DesignConversionDpoPromotionArtifactContractCodec.ResolvePaths(
            root,
            outputDirectory,
            id);
        Assert.True(paths.IsSuccess, paths.ErrorMessage);
        var evaluated = await DesignConversionDpoPolicyCheckpointBridge
            .ExecuteEvaluatedAndConvertAsync(
                CreateEvaluatedLegalTeacherCapability(),
                partition,
                paths.Value!.OutputDirectory,
                id,
                paths.Value.RuntimeCheckpointPath,
                provider ?? new DesignConversionDpoPolicyBaseTestProvider(),
                new DesignConversionDpoPolicyCheckpointBridgeOptions(1, 1),
                ct: CancellationToken.None);
        Assert.True(evaluated.IsSuccess, evaluated.ErrorMessage);
        using var bridgeLease = evaluated.Value!;
        var artifactPublication = await DesignConversionDpoPromotionArtifactContractCodec
            .PublishEvaluatedAsync(
                paths.Value,
                bridgeLease.Result,
                bridgeLease.Evaluation,
                CancellationToken.None);
        Assert.True(artifactPublication.IsSuccess, artifactPublication.ErrorMessage);
        Assert.True(DesignConversionDpoPromotionArtifactContractCodec
            .ValidateEvaluatedArtifactPublication(artifactPublication.Value));
        Assert.NotNull(artifactPublication.Value!.PolicyCheckpointContract.Evaluation);
        bridgeLease.CommitPublishedArtifacts();

        var runnerOptions = Pass157LocalPromotionOptions(
            $"{id}-publisher-runner",
            BuildPassingMeasurementGateRequest($"{id}-publisher-gate") with
            {
                Thresholds = new DesignConversionMeasurementGateThresholds(0d, 800, 1.00m, 512)
            });
        var runner = await DesignConversionLegalTeacherCapabilityTestFactory.RunStrictRunnerAsync(
            new DesignConversionTrainingRunner(),
            new DesignConversionMachine(),
            partition.TrainRecords.Concat(partition.HeldOutRecords).ToArray(),
            runnerOptions,
            CancellationToken.None);
        Assert.True(runner.IsSuccess, runner.ErrorMessage);
        Assert.True(runner.Value!.PipelineResult.DatasetCountGate.Passed);
        Assert.True(runner.Value.PipelineResult.LifecycleEvidence.CheckpointContainsRealTrainedWeights);
        Assert.DoesNotContain(
            runner.Value.PipelineResult.LifecycleEvidence.FailureReasons,
            reason => !DesignConversionCallerEvidenceClassifier.IsPureEvaluationProjection(reason) &&
                      !DesignConversionCallerEvidenceClassifier.IsCallerMeasurementAdvisory(reason));

        var artifacts = artifactPublication.Value!.ManifestArtifacts;
        var artifactPaths = new[]
        {
            artifacts.CheckpointPath,
            artifacts.TokenizerPath,
            artifacts.PolicyPath
        };
        var gateReport = new DesignConversionPromotionGateReport(
            HeldOutScore: bridgeLease.Evaluation.Accuracy,
            RequiredHeldOutScore: 0d,
            HeldOutSourceDisjoint: true,
            DeterministicShortcutDetected: false,
            HiddenShortcutEvidenceDetected: false,
            FreshLoadPassed: true,
            BudgetTierPolicyPassed: true,
            BudgetTier: "validated-evaluated-publisher-test",
            DpoQuarantineCount: 0,
            MaxDpoQuarantineCount: 0,
            RequiredArtifactPaths: artifactPaths,
            PresentArtifactPaths: artifactPaths,
            EvidenceRefs: ["VALIDATED_EVALUATED_PUBLISHER_FIXTURE"]);
        return new ValidatedEvaluatedPublisherFixture(
            bridgeLease.Result.RuntimeMachine,
            runner.Value,
            artifactPublication.Value,
            bridgeLease.Evaluation,
            gateReport,
            paths.Value.OutputDirectory);
    }

    private static async Task<(DesignConversionPromotionPublicationResult Publication, string CheckpointPath)>
        BuildValidatedEvaluatedLocalLoaderPublicationAsync(
            string root,
            string id)
    {
        var fixture = await BuildValidatedEvaluatedPublisherFixtureAsync(
            root,
            $"{id}-loader");
        var artifacts = fixture.ArtifactPublication.ManifestArtifacts;
        var loaded = await DesignConversionMachine.LoadCheckpointAsync(
            artifacts.CheckpointPath,
            CancellationToken.None);
        Assert.True(loaded.IsSuccess, loaded.ErrorMessage);
        var checkpoint = loaded.Value!.Checkpoint;
        var manifestId = $"{id}-validated-evaluated-loader-manifest";
        var evaluatedEvidence = new[]
        {
            "DESIGN_CONVERSION_PROMOTION_GATE_FROM_VALIDATED_EVALUATED_DPO_CONTRACT",
            "DESIGN_CONVERSION_TRAINING_INTAKE_LOCAL_ONLY_PROMOTION_UPLOADER_CALLED",
            "EXTERNAL_CLOUD_UPLOAD_NOT_ATTEMPTED"
        };
        var manifest = new DesignConversionTrainingManifest(
            ManifestId: manifestId,
            MachineId: checkpoint.MachineId,
            DomainTag: checkpoint.DomainTag,
            Version: checkpoint.Version,
            CheckpointRef: Path.GetFileName(artifacts.CheckpointPath),
            ManifestRef: $"manifest://design-conversion-machine/{manifestId}",
            CreatedAtUtc: DateTimeOffset.UtcNow,
            AcceptedRecordCount:
                fixture.ArtifactPublication.PolicyCheckpointContract.SourceRecordCount,
            QuarantinedRecordCount: 0,
            UnitIds: [],
            Batches: [],
            EvidenceRefs: evaluatedEvidence,
            ModelServerUploadAttempted: false,
            ModelServerPromotionClaimed: false,
            DeterministicLogicClaimedAsLearning: false)
        {
            PromotionArtifacts = artifacts,
            PromotionUploadRef =
                DesignConversionPromotedLocalModelLoader
                    .LocalOnlyPromotionRefPrefix + Uri.EscapeDataString(manifestId),
            PromotionUploadedAtUtc = DateTimeOffset.UtcNow,
            LocalPromotionReceiptWritten = true,
            PromotionReceiptKind = "local_receipt_only"
        };
        var decision = new DesignConversionPromotionDecision(
            DesignConversionPromotionDecisionKind.Promote,
            ["ALL_PROMOTION_GATES_PASSED"],
            evaluatedEvidence);
        var receipt = new DesignConversionPromotionUploadReceipt(
            UploadId: $"{manifestId}:local-only",
            RemoteRef: manifest.PromotionUploadRef!,
            UploadedAtUtc: manifest.PromotionUploadedAtUtc!.Value,
            EvidenceRefs: evaluatedEvidence)
        {
            PublicationKind =
                DesignConversionPromotionPublicationKind.LocalOnlyNoRemoteAttempt,
            UploadAttempted = false,
            UploadSucceeded = false,
            VerificationSucceeded = false,
            PublicationStatus =
                DesignConversionPromotionPublicationStatus.NotUploaded
        };
        return (
            new DesignConversionPromotionPublicationResult(
                decision,
                manifest,
                receipt),
            artifacts.CheckpointPath);
    }

    private static void AssertBuiltInLocalOnlyPublication(
        DesignConversionTrainingIntakeLocalPromotionResult result)
    {
        Assert.NotNull(result.Publication);
        var publication = result.Publication;
        Assert.Equal(
            DesignConversionPromotionPublicationKind.LocalOnlyNoRemoteAttempt,
            publication.PublicationKind);
        Assert.Equal(
            DesignConversionPromotionPublicationStatus.NotUploaded,
            publication.PublicationStatus);
        Assert.False(publication.Manifest.ModelServerUploadAttempted);
        Assert.False(publication.Manifest.ModelServerPromotionClaimed);
        Assert.True(publication.Manifest.LocalPromotionReceiptWritten);
        Assert.Equal(
            "local_receipt_only",
            publication.Manifest.PromotionReceiptKind);
        Assert.StartsWith(
            DesignConversionPromotedLocalModelLoader.LocalOnlyPromotionRefPrefix,
            publication.Manifest.PromotionUploadRef,
            StringComparison.Ordinal);
        Assert.NotNull(publication.UploadReceipt);
        var receipt = publication.UploadReceipt;
        Assert.Equal(
            DesignConversionPromotionPublicationKind.LocalOnlyNoRemoteAttempt,
            receipt.PublicationKind);
        Assert.False(receipt.UploadAttempted);
        Assert.False(receipt.UploadSucceeded);
        Assert.False(receipt.VerificationSucceeded);
        Assert.Equal(
            DesignConversionPromotionPublicationStatus.NotUploaded,
            receipt.PublicationStatus);
        Assert.Equal(
            publication.Manifest.PromotionUploadRef,
            receipt.RemoteRef);
    }

    private static async Task<(DesignConversionPromotionPublicationResult Publication, string CheckpointPath)>
        BuildManualEvaluatedLocalLoaderPublicationAsync(
            string root,
            string id)
    {
        Directory.CreateDirectory(root);
        var paths = DesignConversionDpoPromotionArtifactContractCodec.ResolvePaths(
            root,
            Path.Combine(root, $"{id}-manual-evaluated-loader"),
            id);
        Assert.True(paths.IsSuccess, paths.ErrorMessage);
        Directory.CreateDirectory(paths.Value!.OutputDirectory);

        var partition = BuildEvaluatedPartitionForTests(id, heldOutCount: 1);
        var provider = new DesignConversionDpoPolicyBaseTestProvider();
        var provided = await provider.CreateModelSetAsync(CancellationToken.None);
        Assert.True(provided.IsSuccess, provided.ErrorMessage);
        var modelSet = provided.Value!;
        var config = modelSet.Policy.Config;

        var descriptor = DesignConversionDpoSourceEncoderContractBuilder
            .BuildEvaluatedDescriptor(partition.TrainRecords, config);
        Assert.True(descriptor.IsSuccess, descriptor.ErrorMessage);

        var policyAdapters =
            DesignConversionDpoPolicyBaseMetadata.AttachCanonicalLoraTopology(modelSet.Policy);
        _ = DesignConversionDpoPolicyBaseMetadata.AttachCanonicalLoraTopology(modelSet.Reference);
        _ = DesignConversionDpoPolicyBaseMetadata.AttachCanonicalLoraTopology(modelSet.FreshLoadTarget);
        DesignConversionDpoPolicyBaseTestProvider.CopyParameters(modelSet.Policy, modelSet.Reference);
        DesignConversionDpoPolicyBaseTestProvider.CopyParameters(modelSet.Policy, modelSet.FreshLoadTarget);

        var initialWeightSha256 =
            DesignConversionDpoPolicyBaseMetadata.ComputeInitialWeightSha256(modelSet.Reference);
        var loraContext = DesignConversionDpoPolicyBaseMetadata.CreateCanonicalLoraContext(
            config,
            policyAdapters.Count);
        var configSha256 = DesignConversionDpoPolicyBaseMetadata.ComputeConfigSha256(config);
        Assert.NotEqual(initialWeightSha256, modelSet.Identity.BaseCheckpointSha256);

        var packed = DesignConversionDpoPolicyCheckpointBridge
            .BuildEvaluatedPackedBatchPreviewForTests(
                partition.TrainRecords[0],
                config,
                includeTrainingVectorAndWeight: true);
        Assert.True(packed.IsSuccess, packed.ErrorMessage);
        var trainer = CreateAdmittedTrainer(modelSet.Policy, modelSet.Reference, paths.Value.OutputDirectory);
        _ = trainer.StepVector([packed.Value!.VectorBatch], step: 1);
        var policyCheckpointFileName = DpoTrainer.BuildPolicyCheckpointFileName(1);
        var policyCheckpointPath = Path.Combine(paths.Value.OutputDirectory, policyCheckpointFileName);
        Assert.True(File.Exists(policyCheckpointPath));
        var policyCheckpointBytes = await File.ReadAllBytesAsync(policyCheckpointPath);
        var policyCheckpointSha256 = Sha256(policyCheckpointBytes);
        Assert.True(policyCheckpointBytes.Length > 0);
        modelSet.FreshLoadTarget.LoadCheckpoint(policyCheckpointPath);

        var policyEvidenceRefs = BuildManualEvaluatedPolicyEvidenceRefs(
            modelSet.Identity,
            configSha256,
            initialWeightSha256,
            loraContext,
            policyCheckpointFileName,
            policyCheckpointSha256,
            sourceRecordCount: partition.TrainRecords.Count + partition.HeldOutRecords.Count,
            bridgePreferenceCount: partition.TrainRecords.Count,
            dpoStepCount: 1);
        var trainingContext = new DesignConversionDpoPolicyCheckpointTrainingContext(
            ConfigKind: modelSet.Identity.ConfigurationKind,
            VocabSize: config.VocabSize,
            ContextLength: config.ContextLen,
            HiddenDim: config.HiddenDim,
            NumLayers: config.NumLayers,
            NumHeads: config.NumHeads,
            NumKvHeads: config.NumKvHeads,
            FfnHiddenDim: config.FfnHiddenDim,
            RawPayloadPersisted: true,
            AbsolutePathPersisted: false,
            SchemaVersion: 3,
            RopeTheta: config.RopeTheta,
            RmsNormEps: config.RmsNormEps,
            ProviderKind: modelSet.Identity.ProviderKind,
            BaseModelId: modelSet.Identity.BaseModelId,
            BaseRevision: modelSet.Identity.BaseRevision,
            BaseCheckpointSha256: modelSet.Identity.BaseCheckpointSha256,
            ConfigSha256: configSha256,
            InitialWeightSha256: initialWeightSha256,
            Lora: loraContext) with
        {
            LegalTeacherAdmissionCommitment =
                DesignConversionDpoLegalTeacherAdmissionCommitmentTestFactory.Create(
                    policyEvidenceRefs)
        };
        var policyRef = new DesignConversionDpoPolicyCheckpointRef(
            ArtifactKind: DesignConversionDpoTrainerRouteBGate.PolicyCheckpointArtifactKind,
            PolicyCheckpointFileName: policyCheckpointFileName,
            Sha256: policyCheckpointSha256,
            SourceSystem: "11.DPO:DpoTrainer",
            SourceMechanism: "11.DPO:DpoTrainer.StepVector:fresh_loaded",
            RuntimeBridgeKind: DesignConversionMachine.DpoPolicyDirectInferenceRuntimeBridgeKind,
            FreshLoadVerified: true,
            ConvertedToRuntimeWeights: true,
            SourceRecordCount: partition.TrainRecords.Count + partition.HeldOutRecords.Count,
            BridgePreferenceCount: partition.TrainRecords.Count,
            DpoStepCount: 1,
            TrainingContext: trainingContext,
            EvidenceRefs: policyEvidenceRefs,
            PolicyCheckpointByteLength: policyCheckpointBytes.Length);

        var runtimeMachine = new DesignConversionMachine();
        var runtimeBatch = new LearningBatch<DesignConversionDomain.DesignConversionDomain>(
                BatchId: $"manual-evaluated-loader:{id}",
                DomainTag: DesignConversionMachine.DomainTag,
                TrainingItems: partition.TrainRecords
                    .Select(row => DesignConversionDpoPolicyCheckpointBridge
                        .BuildPolicyRuntimeBridgeItemPreviewForTests(
                            row,
                            policyCheckpointFileName,
                            policyCheckpointSha256))
                    .ToArray(),
                SourceIds: partition.TrainRecords
                    .SelectMany(DesignConversionDpoPolicyCheckpointBridge
                        .BuildSourceSignalSourceIdsPreviewForTests)
                    .Append("11.DPO/DpoTrainer")
                    .Append($"dpo_policy_sha256:{policyCheckpointSha256}")
                    .Append($"dpo_policy_file:{policyCheckpointFileName}")
                    .Distinct(StringComparer.Ordinal)
                    .ToArray());
        var runtimeTrain = await DesignConversionLegalTeacherCapabilityTestFactory
            .TrainMachineStrictAsync(
            runtimeMachine,
            runtimeBatch,
            CancellationToken.None);
        Assert.True(runtimeTrain.IsSuccess, runtimeTrain.ErrorMessage);
        var checkpoint = runtimeMachine.ExportCheckpoint();
        Assert.True(checkpoint.IsSuccess, checkpoint.ErrorMessage);
        Assert.True(DesignConversionMachine.CheckpointHasRealLearnedWeights(checkpoint.Value));

        var evaluation = new DesignConversionDpoHeldOutEvaluation(
            Schema: DesignConversionDpoPolicyCheckpointBridge.EvaluatedSchema,
            PackingId: DesignConversionDpoPolicyCheckpointBridge.EvaluatedPackingId,
            VocabSize: config.VocabSize,
            ContextLength: config.ContextLen,
            DpoStepCount: 1,
            MaxBridgePreferenceCount: partition.TrainRecords.Count,
            ChildPolicyCheckpointSha256: policyCheckpointSha256,
            ReferencePolicyCheckpointSha256: modelSet.Identity.BaseCheckpointSha256,
            ReferenceMode: "provider_fresh_step_zero",
            DatasetId: partition.DatasetId,
            PartitionSnapshotSha256: partition.PartitionSnapshotSha256,
            TrainRecordSetSha256: partition.TrainRecordSetSha256,
            HeldOutRecordSetSha256: partition.HeldOutRecordSetSha256,
            TrainSourceSetSha256: partition.TrainSourceSetSha256,
            HeldOutSourceSetSha256: partition.HeldOutSourceSetSha256,
            SelectedTrainInputSha256: Sha256Text($"{id}:selected-train-input"),
            HeldOutEvaluationInputSha256: Sha256Text($"{id}:heldout-evaluation-input"),
            TrainRecordCount: partition.TrainRecords.Count,
            HeldOutRecordCount: partition.HeldOutRecords.Count,
            EvaluatedHeldOutRecordCount: partition.HeldOutRecords.Count,
            CorrectCount: partition.HeldOutRecords.Count,
            Accuracy: 1d,
            MeanRelativeMargin: 1d,
            MeanChildMargin: 2d,
            MeanReferenceMargin: 1d,
            FreshLoadVerified: true,
            ReferenceFrozen: true,
            SourceDisjoint: true,
            HeldOutNotTrained: true);
        evaluation = evaluation with
        {
            G3Metrics = new DesignConversionG3AcceptanceMetrics(
                HeldOutCount: partition.HeldOutRecords.Count,
                BaselineWinCount: partition.HeldOutRecords.Count,
                BaselineWinRate: 1d,
                AbsoluteChildPreferenceCorrectCount:
                    partition.HeldOutRecords.Count,
                AbsoluteChildPreferenceAccuracy: 1d)
            {
                MeasurementNoiseScorerIdentity =
                    DesignConversionDpoPolicyCheckpointBridge
                        .EvaluatedMeasurementNoiseScorerIdentity,
                MeasurementNoiseEvaluationSetId = partition.DatasetId
            },
            CycleAccuracyLineage = BuildColdCycleAccuracyLineage(evaluation)
        };
        var heldOutAccuracyEvidence =
            BuildManualEvaluatedRuntimeAccuracyEvidence(evaluation);
        var runtimeCheckpoint = checkpoint.Value! with
        {
            AccuracyAfterLastBatch = evaluation.Accuracy,
            DpoPolicyCheckpointRef = policyRef with
            {
                EvaluatedHeldOutAcceptanceAuthority = evaluation
            },
            EvidenceRefs = checkpoint.Value.EvidenceRefs
                .Concat(policyEvidenceRefs)
                .Concat(heldOutAccuracyEvidence)
                .Distinct(StringComparer.Ordinal)
                .Order(StringComparer.Ordinal)
                .ToArray()
        };
        var runtimeBytes = JsonSerializer.SerializeToUtf8Bytes(
            runtimeCheckpoint,
            DesignConversionCheckpointJsonOptions.Standard);
        await File.WriteAllBytesAsync(paths.Value.RuntimeCheckpointPath, runtimeBytes);
        var runtimeSha256 = Sha256(runtimeBytes);

        var tokenizer = DesignConversionDpoPromotionArtifactContractCodec
            .BuildCanonicalTokenizerArtifact(descriptor.Value);
        Assert.True(tokenizer.IsSuccess, tokenizer.ErrorMessage);
        var tokenizerBytes = SerializeCompact(tokenizer.Value!);
        var tokenizerSha256 = Sha256(tokenizerBytes);
        var binding = new DesignConversionDpoPromotionArtifactBinding(
            ArtifactSetId: DesignConversionDpoPromotionArtifactContractCodec.BuildArtifactSetId(
                policyCheckpointFileName,
                policyCheckpointSha256,
                policyCheckpointBytes.LongLength,
                paths.Value.RuntimeCheckpointFileName,
                runtimeSha256,
                runtimeBytes.LongLength,
                paths.Value.TokenizerArtifactFileName,
                tokenizerSha256,
                tokenizerBytes.LongLength,
                descriptor.Value!,
                evaluation),
            PolicyCheckpointFileName: policyCheckpointFileName,
            PolicyCheckpointSha256: policyCheckpointSha256,
            PolicyCheckpointByteLength: policyCheckpointBytes.LongLength,
            RuntimeCheckpointFileName: paths.Value.RuntimeCheckpointFileName,
            RuntimeCheckpointSha256: runtimeSha256,
            RuntimeCheckpointByteLength: runtimeBytes.LongLength,
            TokenizerArtifactFileName: paths.Value.TokenizerArtifactFileName,
            TokenizerArtifactSha256: tokenizerSha256,
            TokenizerArtifactByteLength: tokenizerBytes.LongLength,
            SourceEncoderDescriptor: descriptor.Value!);
        var sourceContract = new DesignConversionDpoSourceEncoderContract(
            DesignConversionDpoPromotionArtifactContractCodec.SourceEncoderContractSchema,
            "design_conversion_dpo_source_encoder_contract",
            binding);
        var policyContract = new DesignConversionDpoPolicyCheckpointContract(
            DesignConversionDpoPromotionArtifactContractCodec.PolicyCheckpointContractSchema,
            "design_conversion_dpo_policy_checkpoint_contract",
            binding,
            policyRef.SourceSystem,
            policyRef.SourceMechanism,
            policyRef.RuntimeBridgeKind,
            policyRef.FreshLoadVerified,
            policyRef.ConvertedToRuntimeWeights,
            policyRef.SourceRecordCount,
            policyRef.BridgePreferenceCount,
            policyRef.DpoStepCount,
            policyRef.TrainingContext,
            RawPayloadPersisted: false,
            AbsolutePathPersisted: false)
        {
            Evaluation = evaluation
        };
        Assert.True(DesignConversionDpoPromotionArtifactContractCodec
            .ValidateEvaluatedContractPair(sourceContract, policyContract));
        var sourceContractBytes = SerializeCompact(sourceContract);
        var policyContractBytes = SerializeCompact(policyContract);
        await File.WriteAllBytesAsync(paths.Value.TokenizerArtifactPath, tokenizerBytes);
        await File.WriteAllBytesAsync(paths.Value.SourceEncoderContractPath, sourceContractBytes);
        await File.WriteAllBytesAsync(paths.Value.PolicyCheckpointContractPath, policyContractBytes);

        DesignConversionTrainingManifestArtifactDescriptor Descriptor(
            string artifactKind,
            string path,
            string sha256,
            long byteLength)
            => new(
                artifactKind,
                Path.GetFullPath(path),
                Path.GetFileName(path),
                sha256,
                byteLength,
                binding.ArtifactSetId,
                runtimeSha256);

        var artifacts = new DesignConversionTrainingManifestArtifacts(
            CheckpointPath: paths.Value.RuntimeCheckpointPath,
            TokenizerPath: paths.Value.TokenizerArtifactPath,
            PolicyPath: paths.Value.PolicyCheckpointContractPath)
        {
            SourceEncoderPath = paths.Value.SourceEncoderContractPath,
            RuntimeCheckpointArtifact = Descriptor(
                "design_conversion_dpo_runtime_checkpoint",
                paths.Value.RuntimeCheckpointPath,
                runtimeSha256,
                runtimeBytes.LongLength),
            TokenizerArtifact = Descriptor(
                "design_conversion_dpo_utf8_byte_tokenizer_artifact",
                paths.Value.TokenizerArtifactPath,
                tokenizerSha256,
                tokenizerBytes.LongLength),
            SourceEncoderContractArtifact = Descriptor(
                "design_conversion_dpo_source_encoder_contract",
                paths.Value.SourceEncoderContractPath,
                Sha256(sourceContractBytes),
                sourceContractBytes.LongLength),
            PolicyCheckpointContractArtifact = Descriptor(
                "design_conversion_dpo_policy_checkpoint_contract",
                paths.Value.PolicyCheckpointContractPath,
                Sha256(policyContractBytes),
                policyContractBytes.LongLength),
            PolicyCheckpointArtifact = Descriptor(
                DesignConversionDpoTrainerRouteBGate
                    .PolicyCheckpointArtifactKind,
                policyCheckpointPath,
                policyCheckpointSha256,
                policyCheckpointBytes.LongLength)
        };
        var manifestId = $"{id}-manual-evaluated-loader-manifest";
        var manifest = new DesignConversionTrainingManifest(
            ManifestId: manifestId,
            MachineId: runtimeCheckpoint.MachineId,
            DomainTag: runtimeCheckpoint.DomainTag,
            Version: runtimeCheckpoint.Version,
            CheckpointRef: paths.Value.RuntimeCheckpointFileName,
            ManifestRef: $"manifest://design-conversion-machine/{manifestId}",
            CreatedAtUtc: DateTimeOffset.UtcNow,
            AcceptedRecordCount: partition.TrainRecords.Count + partition.HeldOutRecords.Count,
            QuarantinedRecordCount: 0,
            UnitIds: partition.TrainRecords.Concat(partition.HeldOutRecords)
                .Select(row => row.UnitId)
                .Distinct(StringComparer.Ordinal)
                .Order(StringComparer.Ordinal)
                .ToArray(),
            Batches:
            [
                new DesignConversionTrainingManifestBatch(
                    BatchId: $"manual-evaluated-loader:{id}",
                    UnitId: "mixed-design-conversion-units",
                    RecordCount: partition.TrainRecords.Count + partition.HeldOutRecords.Count,
                    RecordIds: partition.TrainRecords.Concat(partition.HeldOutRecords)
                        .Select(row => row.RecordId)
                        .ToArray(),
                    SourceIds: partition.TrainRecords.Concat(partition.HeldOutRecords)
                        .SelectMany(DesignConversionDpoPolicyCheckpointBridge
                            .BuildSourceSignalSourceIdsPreviewForTests)
                        .Distinct(StringComparer.Ordinal)
                        .ToArray())
            ],
            EvidenceRefs: policyEvidenceRefs
                .Concat(heldOutAccuracyEvidence)
                .Concat([
                    "DESIGN_CONVERSION_PROMOTION_GATE_FROM_VALIDATED_EVALUATED_DPO_CONTRACT",
                    "DESIGN_CONVERSION_TRAINING_INTAKE_LOCAL_ONLY_PROMOTION_UPLOADER_CALLED",
                    "EXTERNAL_CLOUD_UPLOAD_NOT_ATTEMPTED"
                ])
                .Distinct(StringComparer.Ordinal)
                .Order(StringComparer.Ordinal)
                .ToArray(),
            ModelServerUploadAttempted: false,
            ModelServerPromotionClaimed: false,
            DeterministicLogicClaimedAsLearning: false)
        {
            PromotionArtifacts = artifacts,
            PromotionUploadRef = DesignConversionPromotedLocalModelLoader.LocalOnlyPromotionRefPrefix +
                                 Uri.EscapeDataString(manifestId),
            PromotionUploadedAtUtc = DateTimeOffset.UtcNow,
            LocalPromotionReceiptWritten = true,
            PromotionReceiptKind = "local_receipt_only"
        };
        var decision = new DesignConversionPromotionDecision(
            DesignConversionPromotionDecisionKind.Promote,
            ["ALL_PROMOTION_GATES_PASSED"],
            manifest.EvidenceRefs);
        var receipt = new DesignConversionPromotionUploadReceipt(
            UploadId: $"{manifestId}:local-only",
            RemoteRef: manifest.PromotionUploadRef!,
            UploadedAtUtc: manifest.PromotionUploadedAtUtc!.Value,
            EvidenceRefs:
            [
                "DESIGN_CONVERSION_TRAINING_INTAKE_LOCAL_ONLY_PROMOTION_UPLOADER_CALLED",
                "EXTERNAL_CLOUD_UPLOAD_NOT_ATTEMPTED"
            ])
        {
            PublicationKind = DesignConversionPromotionPublicationKind.LocalOnlyNoRemoteAttempt,
            UploadAttempted = false,
            UploadSucceeded = false,
            VerificationSucceeded = false,
            PublicationStatus = DesignConversionPromotionPublicationStatus.NotUploaded
        };
        var publication = new DesignConversionPromotionPublicationResult(
            decision,
            manifest,
            receipt);
        return (publication, paths.Value.RuntimeCheckpointPath);
    }

