    private static byte[] SerializeCompact<T>(T value)
        => JsonSerializer.SerializeToUtf8Bytes(
            value,
            new JsonSerializerOptions(DesignConversionCheckpointJsonOptions.Standard)
            {
                WriteIndented = false
            });

    private static Task WriteLocalPromotionOperationRecordsAsync(
        string path,
        IEnumerable<JsonlDesignConversionLocalArtifactDb
            .LocalPromotionOperationJournalRecord> records)
    {
        // Рабочий журнал операций намеренно обрамляет каждую запись CRLF.
        // Тесты, которые вручную пересобирают журнал, обязаны повторять этот
        // формат, иначе Linux-запуск проверяет не старый валидный журнал, а
        // файл, который настоящий читатель справедливо считает повреждённым.
        var lines = records.Select(record =>
            Encoding.UTF8.GetString(SerializeCompact(record)));
        return File.WriteAllTextAsync(path, string.Concat(
            lines.Select(line => line + "\r\n")));
    }

    private static string Sha256(byte[] bytes)
        => Convert.ToHexString(SHA256.HashData(bytes)).ToLowerInvariant();

    private static string Sha256Text(string value)
        => Sha256(System.Text.Encoding.UTF8.GetBytes(value));

    private static string BuildExpectedPromoteLocalIdempotencyPayloadHashForTests(
        DesignConversionTrainingIntakeRecord intake,
        DesignConversionTrainingPipelineOptions options,
        string promotionOutputDirectory,
        string thresholdPolicyVersion)
    {
        return BuildExpectedPromoteLocalIdempotencyPayloadHashForTests(
            intake,
            options,
            promotionOutputDirectory,
            thresholdPolicyVersion,
            "BuiltInLocalReceiptOnly",
            BuildBuiltInLocalReceiptOnlyPromotionAuthorityFingerprintForTests());
    }

    private static string BuildExpectedPromoteLocalIdempotencyPayloadHashForTests(
        DesignConversionTrainingIntakeRecord intake,
        DesignConversionTrainingPipelineOptions options,
        string promotionOutputDirectory,
        string thresholdPolicyVersion,
        string uploaderAuthorityMode,
        string uploaderAuthorityFingerprintSha256)
        => BuildExpectedPromoteLocalIdempotencyPayloadHashTraceForTests(
            intake,
            options,
            promotionOutputDirectory,
            thresholdPolicyVersion,
            uploaderAuthorityMode,
            uploaderAuthorityFingerprintSha256,
            normalizeOptions: true).Sha256Ref;

    private static PromoteLocalIdempotencyPayloadHashTrace
        BuildExpectedPromoteLocalIdempotencyPayloadHashTraceForTests(
        DesignConversionTrainingIntakeRecord intake,
        DesignConversionTrainingPipelineOptions options,
        string promotionOutputDirectory,
        string thresholdPolicyVersion,
        string uploaderAuthorityMode,
        string uploaderAuthorityFingerprintSha256,
        bool normalizeOptions)
    {
        var effectiveOptions = normalizeOptions
            ? SnapshotPromoteLocalOptionsForExpectedHashForTests(options)
            : options;
        var serializedOptions = JsonSerializer.Serialize(
            effectiveOptions,
            PromoteLocalIdempotencyPayloadJsonOptionsForTests());
        var components = new[]
        {
            JsonlDesignConversionLocalArtifactDb.TrainingIntakeLocalPromotionSchemaVersion,
            thresholdPolicyVersion,
            uploaderAuthorityMode,
            uploaderAuthorityFingerprintSha256,
            intake.IntakeId,
            string.IsNullOrWhiteSpace(effectiveOptions.RunId)
                ? $"training-run-{intake.IntakeId}"
                : effectiveOptions.RunId,
            serializedOptions,
            Path.GetFullPath(promotionOutputDirectory)
        };
        var finalInput = string.Join("|", components);
        return new PromoteLocalIdempotencyPayloadHashTrace(
            effectiveOptions,
            components,
            serializedOptions,
            serializedOptions.Length,
            Encoding.UTF8.GetByteCount(serializedOptions),
            finalInput,
            finalInput.Length,
            Encoding.UTF8.GetByteCount(finalInput),
            $"sha256:{Sha256Text(finalInput)}");
    }

    private static DesignConversionTrainingPipelineOptions
        SnapshotPromoteLocalOptionsForExpectedHashForTests(
        DesignConversionTrainingPipelineOptions options)
    {
        var snapshot = DesignConversionTrainingPipeline.SnapshotOptions(options);
        Assert.True(snapshot.IsSuccess, snapshot.ErrorMessage);
        return snapshot.Value!;
    }

    private static JsonSerializerOptions
        PromoteLocalIdempotencyPayloadJsonOptionsForTests()
        => new(DesignConversionCheckpointJsonOptions.Standard)
        {
            WriteIndented = false
        };

    private static string
        BuildBuiltInLocalReceiptOnlyPromotionAuthorityFingerprintForTests()
    {
        var builtInUploaderPreflightFingerprint =
            $"sha256:{Sha256Text("design-conversion-local-only-promotion-uploader-v1")}";
        return $"sha256:{Sha256Text(string.Join("|",
        [
            "design-conversion-local-promotion-uploader-authority-fingerprint-v1",
            "BuiltInLocalReceiptOnly",
            "design-conversion-local-only-promotion-uploader",
            (64 * 1024).ToString(CultureInfo.InvariantCulture),
            builtInUploaderPreflightFingerprint,
            JsonlDesignConversionLocalArtifactDb
                .MaxTrainingIntakeLocalPromotionOperationJournalRowByteLength
                .ToString(CultureInfo.InvariantCulture)
        ]))}";
    }

    private static async Task
        WritePromoteLocalIdempotencyHashDiagnosticIfRequestedAsync(
        string testName,
        DesignConversionTrainingIntakeRecord intake,
        DesignConversionTrainingPipelineOptions options,
        string promotionOutputDirectory,
        string thresholdPolicyVersion,
        string uploaderAuthorityMode,
        string uploaderAuthorityFingerprintSha256,
        string actualProductionHash)
    {
        var diagnosticsPath = Environment.GetEnvironmentVariable(
            "XIIGEN_PROMOTE_LOCAL_HASH_DIAGNOSTICS_PATH");
        if (string.IsNullOrWhiteSpace(diagnosticsPath))
            return;

        var legacyExpected =
            BuildExpectedPromoteLocalIdempotencyPayloadHashTraceForTests(
                intake,
                options,
                promotionOutputDirectory,
                thresholdPolicyVersion,
                uploaderAuthorityMode,
                uploaderAuthorityFingerprintSha256,
                normalizeOptions: false);
        var effectiveExpected =
            BuildExpectedPromoteLocalIdempotencyPayloadHashTraceForTests(
                intake,
                options,
                promotionOutputDirectory,
                thresholdPolicyVersion,
                uploaderAuthorityMode,
                uploaderAuthorityFingerprintSha256,
                normalizeOptions: true);
        var firstDifferingComponent =
            FirstDifferingPromotionHashComponentForTests(
                legacyExpected.Components,
                effectiveExpected.Components);
        var firstDifferingByte =
            FirstDifferingUtf8BytePositionForTests(
                legacyExpected.FinalInput,
                effectiveExpected.FinalInput);
        var lines = new List<string>
        {
            $"test={testName}",
            "fixture=synthetic W085 deterministic promotion-ready intake",
            $"original_options_shape={DescribePromotionHashOptionsShapeForTests(options)}",
            $"effective_options_shape={DescribePromotionHashOptionsShapeForTests(effectiveExpected.Options)}",
            $"legacy_expected_digest={legacyExpected.Sha256Ref}",
            $"actual_production_digest={actualProductionHash}",
            $"effective_expected_digest={effectiveExpected.Sha256Ref}",
            $"legacy_expected_recomputed_matches={legacyExpected.Sha256Ref == $"sha256:{Sha256Text(legacyExpected.FinalInput)}"}",
            $"effective_expected_recomputed_matches={effectiveExpected.Sha256Ref == $"sha256:{Sha256Text(effectiveExpected.FinalInput)}"}",
            $"effective_expected_matches_actual_production={effectiveExpected.Sha256Ref == actualProductionHash}",
            $"legacy_serialized_options_text_length={legacyExpected.SerializedOptionsTextLength}",
            $"legacy_serialized_options_utf8_byte_length={legacyExpected.SerializedOptionsUtf8ByteLength}",
            $"effective_serialized_options_text_length={effectiveExpected.SerializedOptionsTextLength}",
            $"effective_serialized_options_utf8_byte_length={effectiveExpected.SerializedOptionsUtf8ByteLength}",
            $"legacy_final_input_text_length={legacyExpected.FinalInputTextLength}",
            $"legacy_final_input_utf8_byte_length={legacyExpected.FinalInputUtf8ByteLength}",
            $"effective_final_input_text_length={effectiveExpected.FinalInputTextLength}",
            $"effective_final_input_utf8_byte_length={effectiveExpected.FinalInputUtf8ByteLength}",
            $"first_differing_component={(firstDifferingComponent is null ? "none" : $"{firstDifferingComponent.Value}: {PromoteLocalIdempotencyPayloadHashComponentNameForTests(firstDifferingComponent.Value)}")}",
            $"first_differing_utf8_byte_position={(firstDifferingByte is null ? "none" : firstDifferingByte.Value.ToString(CultureInfo.InvariantCulture))}",
            "candidate_divergences:",
            $"  authority fingerprint component: {(legacyExpected.Components[2] == effectiveExpected.Components[2] && legacyExpected.Components[3] == effectiveExpected.Components[3] ? "ruled out for this invocation" : "demonstrated cause")}",
            $"  run id component: {(legacyExpected.Components[5] == effectiveExpected.Components[5] ? "ruled out for this invocation" : "demonstrated cause")}",
            $"  serializer settings/options serialization: {(legacyExpected.Components[6] == effectiveExpected.Components[6] ? "ruled out for this invocation" : "demonstrated cause")} (settings are Standard+WriteIndented=false on both sides; serialized options text differs after SnapshotOptions normalization)"
        };
        AddPromotionHashTraceLinesForTests(lines, "legacy_expected_test_side", legacyExpected);
        AddPromotionHashTraceLinesForTests(lines, "actual_production_effective_side", effectiveExpected);
        lines.Add(string.Empty);

        var directory = Path.GetDirectoryName(diagnosticsPath);
        if (!string.IsNullOrWhiteSpace(directory))
            Directory.CreateDirectory(directory);
        await File.AppendAllTextAsync(
            diagnosticsPath,
            string.Join(Environment.NewLine, lines) + Environment.NewLine);
    }

    private static void AddPromotionHashTraceLinesForTests(
        IList<string> lines,
        string label,
        PromoteLocalIdempotencyPayloadHashTrace trace)
    {
        lines.Add($"{label}:");
        for (var index = 0; index < trace.Components.Length; index++)
        {
            lines.Add(
                $"  component_{index + 1}_{PromoteLocalIdempotencyPayloadHashComponentNameForTests(index)}={trace.Components[index]}");
        }
    }

    private static int? FirstDifferingPromotionHashComponentForTests(
        IReadOnlyList<string> expected,
        IReadOnlyList<string> actual)
    {
        var count = Math.Min(expected.Count, actual.Count);
        for (var index = 0; index < count; index++)
        {
            if (!string.Equals(expected[index], actual[index], StringComparison.Ordinal))
                return index;
        }

        return expected.Count == actual.Count ? null : count;
    }

    private static int? FirstDifferingUtf8BytePositionForTests(
        string expected,
        string actual)
    {
        var expectedBytes = Encoding.UTF8.GetBytes(expected);
        var actualBytes = Encoding.UTF8.GetBytes(actual);
        var length = Math.Min(expectedBytes.Length, actualBytes.Length);
        for (var index = 0; index < length; index++)
        {
            if (expectedBytes[index] != actualBytes[index])
                return index;
        }

        return expectedBytes.Length == actualBytes.Length ? null : length;
    }

    private static string PromoteLocalIdempotencyPayloadHashComponentNameForTests(
        int zeroBasedIndex)
        => zeroBasedIndex switch
        {
            0 => "schema_version",
            1 => "threshold_policy_version",
            2 => "uploader_authority_mode",
            3 => "uploader_authority_fingerprint_sha256",
            4 => "training_intake_id",
            5 => "run_id",
            6 => "serialized_options",
            7 => "promotion_output_directory",
            _ => "unknown"
        };

    private static string DescribePromotionHashOptionsShapeForTests(
        DesignConversionTrainingPipelineOptions options)
        => string.Join(
            ";",
            [
                $"RunId={options.RunId}",
                $"BatchSize={options.BatchSize.ToString(CultureInfo.InvariantCulture)}",
                $"CallMachineLifecycleHook={options.CallMachineLifecycleHook}",
                $"RequireDatasetCountGate={options.RequireDatasetCountGate}",
                $"DatasetOptions={(options.DatasetOptions is null ? "null" : "present")}",
                $"MeasurementGateRequest={(options.MeasurementGateRequest is null ? "null" : "present")}",
                $"DpoPolicyBridgeOptions={(options.DpoPolicyBridgeOptions is null ? "null" : "present")}",
                $"RepositoryOwnedDpoTransactionContext={DescribeRepositoryOwnedDpoContextForTests(options.RepositoryOwnedDpoTransactionContext)}",
                $"RepositoryOwnedModelCheckpointContext={DescribeRepositoryOwnedModelCheckpointContextForTests(options.RepositoryOwnedModelCheckpointContext)}"
            ]);

    private static string DescribeRepositoryOwnedDpoContextForTests(
        DesignConversionRepositoryOwnedDpoTransactionContext? context)
        => context is null
            ? "null"
            : $"Enabled={context.Enabled};Address={(context.Address is null ? "null" : "present")};RequestIdentity={(context.RequestIdentity is null ? "null" : "present")}";

    private static string DescribeRepositoryOwnedModelCheckpointContextForTests(
        DesignConversionRepositoryOwnedModelCheckpointContext? context)
        => context is null
            ? "null"
            : $"Enabled={context.Enabled};Request={(context.Request is null ? "null" : "present")}";

    private sealed record PromoteLocalIdempotencyPayloadHashTrace(
        DesignConversionTrainingPipelineOptions Options,
        string[] Components,
        string SerializedOptions,
        int SerializedOptionsTextLength,
        int SerializedOptionsUtf8ByteLength,
        string FinalInput,
        int FinalInputTextLength,
        int FinalInputUtf8ByteLength,
        string Sha256Ref);

    private static async Task<PromotionReadyIntakeFixture>
        BuildW085DeterministicPromotionReadyIntakeFixtureAsync(
            string root,
            string id)
    {
        var db = new JsonlDesignConversionLocalArtifactDb(root);
        var api = new DesignConversionDpoUsefulnessApi(db);
        var train = WithRuntimeArtifactProofRefs(
            ToRuntimeApprovedCandidate(
                WithSourceIdentity(
                    BuildTrainingRecord(
                        $"{id}-train",
                        DesignConversionDpoUnits.ImproverUnit,
                        usefulness: 0.97),
                    $"{id}-source-train")),
            $"{id}-train");
        train = AttachW085OptimizerPayloadCustody(
            train,
            rejectedHtml: "<main class=\"candidate-r\">R</main>",
            rejectedCss: ".candidate-r{display:block;}");
        var heldOut = WithRuntimeArtifactProofRefs(
            ToRuntimeApprovedCandidate(
                WithSourceIdentity(
                    BuildTrainingRecord(
                        $"{id}-heldout",
                        DesignConversionDpoUnits.ImproverUnit,
                        usefulness: 0.96),
                    $"{id}-source-heldout")),
            $"{id}-heldout");
        heldOut = AttachW085OptimizerPayloadCustody(
            heldOut,
            rejectedHtml: "<main class=\"candidate-s\">S</main>",
            rejectedCss: ".candidate-s{display:block;}");

        Assert.Equal(DesignConversionDpoUnits.ImproverUnit, train.UnitId);
        Assert.Equal(DesignConversionDpoUnits.ImproverUnit, heldOut.UnitId);
        Assert.NotEqual(train.RecordId, heldOut.RecordId);
        Assert.NotEqual(
            Sha256(SerializeCompact(train)),
            Sha256(SerializeCompact(heldOut)));
        Assert.NotEqual(
            DesignConversionDpoDatasetBuilder.ComputeRecordIdentityHash(train),
            DesignConversionDpoDatasetBuilder.ComputeRecordIdentityHash(heldOut));
        Assert.NotEqual(
            DesignConversionDpoDatasetBuilder.ComputeSourceIdentityHash(train),
            DesignConversionDpoDatasetBuilder.ComputeSourceIdentityHash(heldOut));
        Assert.NotNull(train.TeacherProvenance);
        Assert.NotNull(heldOut.TeacherProvenance);
        Assert.NotEqual(
            train.TeacherProvenance!.RequestId,
            heldOut.TeacherProvenance!.RequestId);
        Assert.NotEqual(
            Assert.Single(train.Chosen.QaResults).ResultId,
            Assert.Single(heldOut.Chosen.QaResults).ResultId);
        Assert.NotEqual(
            Assert.Single(train.Rejected.QaResults).ResultId,
            Assert.Single(heldOut.Rejected.QaResults).ResultId);
        Assert.NotEqual(
            train.Provenance.Metadata[
                DesignConversionDpoGenerator.PayloadCustodyBindingSha256MetadataKey],
            heldOut.Provenance.Metadata[
                DesignConversionDpoGenerator.PayloadCustodyBindingSha256MetadataKey]);
        Assert.False(DesignConversionDpoCorpusAdmissionRequirementPolicy
            .RequiresAdmission([train, heldOut]));

        var materializedTrain = JsonlDesignConversionLocalArtifactDb
            .ValidateAndMaterializePayloadCustody(train);
        var materializedHeldOut = JsonlDesignConversionLocalArtifactDb
            .ValidateAndMaterializePayloadCustody(heldOut);
        Assert.True(materializedTrain.IsSuccess, materializedTrain.ErrorMessage);
        Assert.True(materializedHeldOut.IsSuccess, materializedHeldOut.ErrorMessage);
        var config = DesignConversionDpoPolicyBaseTestProvider.CreateConfig();
        var trainPacked = DesignConversionDpoPolicyCheckpointBridge
            .BuildEvaluatedPackedBatchPreviewForTests(materializedTrain.Value!, config);
        var heldOutPacked = DesignConversionDpoPolicyCheckpointBridge
            .BuildEvaluatedPackedBatchPreviewForTests(materializedHeldOut.Value!, config);
        Assert.True(trainPacked.IsSuccess, trainPacked.ErrorMessage);
        Assert.True(heldOutPacked.IsSuccess, heldOutPacked.ErrorMessage);
        Assert.Equal(trainPacked.Value!.Chosen, heldOutPacked.Value!.Chosen);
        Assert.NotEqual(trainPacked.Value.Rejected, heldOutPacked.Value.Rejected);
        var trainDivergence = FirstW085ResponseDivergence(
            trainPacked.Value.Chosen,
            trainPacked.Value.Rejected);
        var heldOutDivergence = FirstW085ResponseDivergence(
            heldOutPacked.Value.Chosen,
            heldOutPacked.Value.Rejected);
        Assert.Equal('c', trainPacked.Value.Chosen[trainDivergence]);
        Assert.Equal('r', trainPacked.Value.Rejected[trainDivergence]);
        Assert.Equal('c', heldOutPacked.Value.Chosen[heldOutDivergence]);
        Assert.Equal('s', heldOutPacked.Value.Rejected[heldOutDivergence]);
        Assert.False(trainPacked.Value.VectorBatch.Batch.RejectedIds.Data.SequenceEqual(
            heldOutPacked.Value.VectorBatch.Batch.RejectedIds.Data));
        Assert.NotEqual(
            trainPacked.Value.InputSha256,
            heldOutPacked.Value.InputSha256);

        var stored = await Save(db, BuildArtifactRecord(
            $"{id}-storage-record",
            $"{id}-job",
            $"{id}-request",
            DesignConversionVisualQaBoundaryPolicy.TestProviderOnlyMarker,
            [train, heldOut],
            "<main>private W085 deterministic fixture payload</main>",
            ".private-w085-deterministic-fixture{color:red;}") with
        {
            SanitizedSourceRefs = new Dictionary<string, string>(StringComparer.Ordinal)
            {
                ["source_manifest_ref"] = $"manifest://design-conversion/{id}",
                ["source_kind"] = "figma",
                ["design_tree_payload_ref"] = $"sha256:{id}-design-tree",
                ["original_tree_payload_ref"] = $"sha256:{id}-original-tree",
                ["source_artifact:expected_desktop"] = $"sha256:{id}-expected",
                ["source_artifact:actual_desktop"] = $"sha256:{id}-actual"
            }
        });
        foreach (var candidate in new[] { train, heldOut })
        {
            var approval = await db.ApproveRuntimeCreatedDpoCandidateAsync(
                stored.RecordId,
                candidate.RecordId,
                $"reviewer:{id}:{candidate.RecordId}",
                $"{id} W085 candidate approved through runtime authority rewrite",
                DateTimeOffset.UnixEpoch.AddMinutes(240));
            Assert.True(approval.IsSuccess, approval.ErrorMessage);
        }

        var handoff = await api.ExportApprovedRuntimeDpoCandidatesAsync(
            new DesignConversionLocalArtifactDbQuery(JobId: $"{id}-job"),
            DateTimeOffset.UnixEpoch.AddMinutes(240));
        Assert.True(handoff.IsSuccess, handoff.ErrorMessage);
        Assert.Equal(2, handoff.Value!.Rows.Count);
        var intake = await api.CreateTrainingIntakeAsync(
            handoff.Value,
            $"requester:{id}",
            $"{id} W085 deterministic evaluated promotion fixture",
            DateTimeOffset.UnixEpoch.AddMinutes(241));
        Assert.True(intake.IsSuccess, intake.ErrorMessage);
        return new PromotionReadyIntakeFixture(
            intake.Value!,
            Pass157LocalPromotionOptions(
                $"{id}-run",
                BuildPassingMeasurementGateRequest($"{id}-gate"),
                new DesignConversionDpoPolicyCheckpointBridgeOptions(
                    MaxBridgePreferenceCount: 1,
                    DpoStepCount: 5)
                {
                    DpoConvergenceThreshold = 0f
                }));

    }

    private static int FirstW085ResponseDivergence(string chosen, string rejected)
    {
        var length = Math.Min(chosen.Length, rejected.Length);
        for (var index = 0; index < length; index++)
        {
            if (chosen[index] != rejected[index])
                return index;
        }

        Assert.Fail("W085 controlled preference responses did not diverge.");
        return -1;
    }

