    private static DesignConversionDpoTrainingRecord
        BuildOrdinaryExternalTeacherApprovedRuntimeRecord(
            string id,
            string unitId,
            double usefulness,
            string teacherRequestId,
            string modelId,
            string modelVersion,
            string? payloadId = null,
            bool independentPreferenceProvenForBridge = false)
    {
        var teacherProvenance = CreateQwenOllamaTeacherProvenance(
            teacherRequestId,
            modelId,
            modelVersion);

        // Паспорт учителя описывает его происхождение, но не авторов двух
        // вариантов. Предпочтительный вариант создан открытой моделью,
        // отвергаемый — локальной; эти сведения задаём до привязки к
        // содержимому пары.
        var authoredRecord = WithExternalTeacherAuthorship(
            WithSourceIdentity(
                BuildTrainingRecord(id, unitId, usefulness) with
                {
                    SourceStructurePayload =
                        BuildRuntimeSourceStructureFixturePayload(id)
                },
                $"{id}-source"),
            teacherProvenance);
        if (independentPreferenceProvenForBridge)
        {
            authoredRecord = MarkOrdinaryExternalTeacherPreferenceProvenForBridge(
                authoredRecord,
                id);
        }

        return AttachInlineOptimizerPayloadCustody(
            WithRuntimeArtifactProofRefs(
                ToRuntimeApprovedCandidate(authoredRecord),
                $"{id}-proof"),
            payloadId ?? id);
    }

    private static DesignConversionDpoTrainingRecord
        MarkOrdinaryExternalTeacherPreferenceProvenForBridge(
            DesignConversionDpoTrainingRecord record,
            string id)
    {
        Assert.Null(record.PayloadCustodySecret);
        var metadata = new Dictionary<string, string>(
            record.Provenance.Metadata,
            StringComparer.Ordinal)
        {
            // Обычный local-promotion bridge принимает строку внешнего учителя
            // только после независимого доказательства предпочтения. Ставим его
            // до payload-custody binding: эти metadata являются immutable
            // governance, в отличие от поздней approval-записи reviewer'а.
            // Не ставим marker dual-target corpus: этот тест проверяет
            // single-pair bridge, а не admission-путь с atomic external
            // consumption.
            ["independent_preference_proven"] = bool.TrueString,
            ["independent_preference_receipt_sha256"] =
                DesignConversionDpoGenerator.Sha256Ref(
                    $"{id}:independent-preference-receipt"),
            ["independent_preference_attempt_number"] = "1",
            ["raw_independent_scorer_request_persisted"] = bool.FalseString,
            ["raw_independent_scorer_output_persisted"] = bool.FalseString
        };
        metadata.Remove("chosen_rejected_pair_not_proven");
        metadata.Remove("independent_preference_not_proven");
        metadata.Remove("teacher_candidate_only_boundary");

        return record with
        {
            Provenance = record.Provenance with { Metadata = metadata }
        };
    }

    private static string BuildRuntimeSourceStructureFixturePayload(string id)
        => JsonSerializer.Serialize(
            new
            {
                schema = "design-conversion-runtime-source-structure-v1",
                tree = new[] { "frame", "candidate" },
                generated_binding =
                    $"artifact://design-conversion/{id}/generated",
                incumbent_binding =
                    $"artifact://design-conversion/{id}/incumbent",
                redacted = true
            },
            DesignConversionCheckpointJsonOptions.Standard);

    private static DesignConversionDpoTrainingRecord AttachOptimizerPayloadCustody(
        DesignConversionDpoTrainingRecord record,
        DesignConversionImprovementOutput chosen,
        DesignConversionImprovementOutput rejected)
    {
        var custodyMetadata = new Dictionary<string, string>(
            record.Provenance.Metadata,
            StringComparer.Ordinal)
        {
            ["runtime_teacher_authored_candidate"] = bool.TrueString,
            ["approval_status"] = "pending",
            ["review_status"] = JsonlDesignConversionLocalArtifactDb
                .RuntimeCandidateReviewPendingStatus,
            ["approved_for_training"] = bool.FalseString,
            ["review_required"] = bool.TrueString,
            ["approval_required"] = bool.TrueString
        };
        custodyMetadata.Remove("approved_by_ref");
        custodyMetadata.Remove("approval_reason");
        custodyMetadata.Remove("approved_at_utc");
        var custodyRecord = record with
        {
            Provenance = record.Provenance with { Metadata = custodyMetadata }
        };
        var materialized = custodyRecord with
        {
            Chosen = chosen,
            Rejected = rejected,
            PayloadCustodySecret = null
        };
        var item = DesignConversionTrainingPipeline.ToCanonicalTrainingItem(
            materialized);
        var promptSha256 = DesignConversionDpoGenerator.Sha256Ref(item.Prompt);
        var chosenSha256 = DesignConversionDpoGenerator.Sha256Ref(
            item.ChosenResponse);
        var rejectedSha256 = DesignConversionDpoGenerator.Sha256Ref(
            item.RejectedResponse);
        var governanceSha256 = DesignConversionDpoGenerator
            .BuildPayloadCustodyGovernanceSha256(custodyRecord);
        var bindingSha256 = DesignConversionDpoGenerator.BuildPayloadCustodyBinding(
            custodyRecord,
            promptSha256,
            chosenSha256,
            rejectedSha256,
            governanceSha256);
        var metadata = new Dictionary<string, string>(
            custodyRecord.Provenance.Metadata,
            StringComparer.Ordinal)
        {
            [DesignConversionDpoGenerator.PayloadCustodyRequiredMetadataKey] =
                bool.TrueString,
            [DesignConversionDpoGenerator.PayloadCustodyVersionMetadataKey] =
                DesignConversionDpoGenerator.PayloadCustodyVersion,
            [DesignConversionDpoGenerator.PayloadCustodyPromptSha256MetadataKey] =
                promptSha256,
            [DesignConversionDpoGenerator.PayloadCustodyChosenSha256MetadataKey] =
                chosenSha256,
            [DesignConversionDpoGenerator.PayloadCustodyRejectedSha256MetadataKey] =
                rejectedSha256,
            [DesignConversionDpoGenerator.PayloadCustodyGovernanceSha256MetadataKey] =
                governanceSha256,
            [DesignConversionDpoGenerator.PayloadCustodyBindingSha256MetadataKey] =
                bindingSha256,
            ["payload_custody_raw_in_public_record"] = bool.FalseString
        };
        return custodyRecord with
        {
            Provenance = custodyRecord.Provenance with { Metadata = metadata },
            PayloadCustodySecret = new DesignConversionDpoPayloadCustodySecret(
                DesignConversionDpoGenerator.PayloadCustodyVersion,
                item.Prompt,
                item.ChosenResponse,
                item.RejectedResponse,
                promptSha256,
                chosenSha256,
                rejectedSha256,
                governanceSha256,
                bindingSha256)
        };
    }

