    private static string BuildSafeBlockerFixtureId(string blocker)
    {
        var token = Convert
            .ToHexString(SHA256.HashData(System.Text.Encoding.UTF8.GetBytes(blocker)))
            .ToLowerInvariant();
        return $"blocker-{token[..16]}";
    }

    private static void CreatePromotionContractDirectoryJunction(
        string linkPath,
        string targetPath)
    {
        Assert.True(OperatingSystem.IsWindows());
        using var process = System.Diagnostics.Process.Start(
            new System.Diagnostics.ProcessStartInfo
            {
                FileName = "cmd.exe",
                ArgumentList =
                {
                    "/d",
                    "/c",
                    "mklink",
                    "/J",
                    linkPath,
                    targetPath
                },
                CreateNoWindow = true,
                UseShellExecute = false,
                RedirectStandardOutput = true,
                RedirectStandardError = true
            });
        Assert.NotNull(process);
        var standardOutput = process!.StandardOutput.ReadToEnd();
        var standardError = process.StandardError.ReadToEnd();
        Assert.True(process.WaitForExit(10_000));
        Assert.True(
            process.ExitCode == 0 && Directory.Exists(linkPath),
            $"Junction capability precondition failed: {standardOutput} {standardError}");
    }

    private static async Task<DpoPromotionContractFixture>
        BuildDpoPromotionContractFixtureAsync(
            string root,
            string runId)
    {
        Directory.CreateDirectory(root);
        var paths = DesignConversionDpoPromotionArtifactContractCodec.ResolvePaths(
            root,
            Path.Combine(root, runId),
            runId);
        Assert.True(paths.IsSuccess, paths.ErrorMessage);

        var bridge = await DesignConversionDpoPolicyCheckpointBridge.ExecuteAndConvertAsync(
            CreateEvaluatedLegalTeacherCapability(),
            [
                BuildTrainingRecord(
                    $"{runId}-improver",
                    DesignConversionDpoUnits.ImproverUnit,
                    usefulness: 0.99),
                BuildTrainingRecord(
                    $"{runId}-critic",
                    DesignConversionDpoUnits.CriticUnit,
                    usefulness: 0.98)
            ],
            paths.Value!.OutputDirectory,
            runId,
            paths.Value.RuntimeCheckpointPath,
            new DesignConversionDpoPolicyBaseTestProvider(),
            new DesignConversionDpoPolicyCheckpointBridgeOptions(
                MaxBridgePreferenceCount: 2,
                DpoStepCount: 1),
            CancellationToken.None);
        Assert.True(bridge.IsSuccess, bridge.ErrorMessage);
        Assert.NotNull(bridge.Value!.PolicyCheckpointRef);
        Assert.NotNull(bridge.Value.SourceEncoderDescriptor);
        return new DpoPromotionContractFixture(paths.Value, bridge.Value);
    }

    private static DpoPromotionContractFixture CloneDpoPromotionContractFixture(
        DpoPromotionContractFixture source,
        string root,
        string runId)
    {
        var paths = DesignConversionDpoPromotionArtifactContractCodec.ResolvePaths(
            root,
            Path.Combine(root, runId),
            runId);
        Assert.True(paths.IsSuccess, paths.ErrorMessage);
        Directory.CreateDirectory(paths.Value!.OutputDirectory);
        File.Copy(
            Path.Combine(
                source.Paths.OutputDirectory,
                source.Bridge.PolicyCheckpointPath),
            Path.Combine(
                paths.Value.OutputDirectory,
                source.Bridge.PolicyCheckpointPath));
        File.Copy(source.Paths.RuntimeCheckpointPath, paths.Value.RuntimeCheckpointPath);

        return new DpoPromotionContractFixture(
            paths.Value,
            source.Bridge with
            {
                RuntimeCheckpointPath = paths.Value.RuntimeCheckpointFileName,
                RuntimeExport = source.Bridge.RuntimeExport with
                {
                    CheckpointRef = paths.Value.RuntimeCheckpointFileName
                }
            });
    }

    private static void AssertNoPromotionContractTemps(string outputDirectory)
        => Assert.Empty(Directory.EnumerateFiles(
