    private static async Task<string> ReadSha256Async(string path)
    {
        var bytes = await File.ReadAllBytesAsync(path);
        return Convert.ToHexString(SHA256.HashData(bytes)).ToLowerInvariant();
    }

    private static async Task AssertManifestDescriptorMatchesFileAsync(
        DesignConversionTrainingManifestArtifactDescriptor? descriptor,
        string artifactKind,
        string path,
        string expectedSha256,
        long expectedByteLength,
        DesignConversionDpoPromotionArtifactBinding binding)
    {
        var value = Assert.IsType<DesignConversionTrainingManifestArtifactDescriptor>(
            descriptor);
        var canonicalPath = Path.GetFullPath(path);
        var bytes = await File.ReadAllBytesAsync(canonicalPath);
        var actualSha256 = Convert.ToHexString(SHA256.HashData(bytes))
            .ToLowerInvariant();

        Assert.Equal(artifactKind, value.ArtifactKind);
        Assert.Equal(canonicalPath, value.CanonicalPath);
        Assert.Equal(Path.GetFileName(canonicalPath), value.FileName);
        Assert.False(value.FileName.EndsWith(".tmp", StringComparison.OrdinalIgnoreCase));
        Assert.Equal(expectedSha256, value.Sha256);
        Assert.Equal(expectedByteLength, value.ByteLength);
        Assert.Equal(binding.ArtifactSetId, value.ArtifactSetId);
        Assert.Equal(binding.RuntimeCheckpointSha256, value.RuntimeCheckpointSha256);
        Assert.Equal(bytes.LongLength, value.ByteLength);
        Assert.Equal(actualSha256, value.Sha256);
    }

    private static string BuildNonCanonicalSameFileAlias(string canonicalPath)
    {
        var directory = Path.GetDirectoryName(canonicalPath)!;
        var alias = Path.Combine(directory, ".", Path.GetFileName(canonicalPath));
        var comparison = OperatingSystem.IsWindows()
            ? StringComparison.OrdinalIgnoreCase
            : StringComparison.Ordinal;
        Assert.False(string.Equals(alias, canonicalPath, comparison));
        Assert.True(string.Equals(
            Path.GetFullPath(alias),
            Path.GetFullPath(canonicalPath),
            comparison));
        return alias;
    }

