    private static CanonicalBpeTokenizerSnapshotFixture
        CreateCanonicalBpeTokenizerSnapshotFixture(
            TransformerModel.Config.ModelConfig config)
    {
        var tokenizer = new Tokenizer.BpeTokenizer();
        tokenizer.Train(
            string.Concat(Enumerable.Repeat(
                "aaaaabbbbbccccc alpha beta gamma ",
                32)),
            vocabSize: 258);
        Assert.Equal(258, tokenizer.VocabSize);

        using var stream = new MemoryStream();
        tokenizer.Save(stream);
        var bytes = stream.ToArray();
        var descriptor = DesignConversionDpoPromotionArtifactContractCodec
            .BuildCanonicalBpeTokenizerArtifactDescriptor(bytes, config);
        Assert.True(descriptor.IsSuccess, descriptor.ErrorMessage);
        return new CanonicalBpeTokenizerSnapshotFixture(bytes, descriptor.Value!);
    }

    private static (
        IDesignConversionDpoPolicyBaseProvider Provider,
        InMemoryCanonicalBpeTokenizerSnapshotSource Source,
        CanonicalBpeTokenizerSnapshotFixture Snapshot) CreateCanonicalBpeProviderForPublication()
    {
        var config = DesignConversionDpoPolicyBaseTestProvider.CreateConfig();
        var snapshot = CreateCanonicalBpeTokenizerSnapshotFixture(config);
        var source = new InMemoryCanonicalBpeTokenizerSnapshotSource(snapshot.Bytes);
        var reference = new DesignConversionDpoCanonicalBpeTokenizerSnapshotReference(
            snapshot.Descriptor,
            config,
            source);
        var provider = new DesignConversionDpoPolicyBaseTestProvider(
            modelSet => OperationResult<DesignConversionDpoPolicyBaseModelSet>.Ok(
                modelSet with
                {
                    CanonicalBpeTokenizerSnapshot = reference
                }));
        return (provider, source, snapshot);
    }

