    private static DesignConversionDpoResolvedPartition BuildEvaluatedPartitionForTests(
        string id,
        int heldOutCount)
    {
        var train = WithSourceIdentity(
            BuildTrainingRecord(
                $"{id}-train",
                DesignConversionDpoUnits.ImproverUnit,
                usefulness: 0.99),
            $"{id}-source-train");
        var heldOut = Enumerable.Range(0, heldOutCount)
            .Select(index => WithSourceIdentity(
                BuildTrainingRecord(
                    $"{id}-heldout-{index}",
                    index % 2 == 0
                        ? DesignConversionDpoUnits.CriticUnit
                        : DesignConversionDpoUnits.ImproverUnit,
                    usefulness: 0.98 - index * 0.01),
                $"{id}-source-heldout-{index}"))
            .ToArray();
        var provisional = new DesignConversionDpoResolvedPartition(
            id,
            [train],
            heldOut,
            string.Empty,
            string.Empty,
            string.Empty,
            string.Empty,
            string.Empty);
        Assert.True(DesignConversionDpoConsumedPartitionProjectionContract.TryCreate(
            provisional,
            provisional.TrainRecords.Count,
            out var full));
        Assert.NotNull(full);
        return provisional with
        {
            TrainRecordSetSha256 = full!.TrainRecordSetSha256,
            HeldOutRecordSetSha256 = full.HeldOutRecordSetSha256,
            TrainSourceSetSha256 = full.TrainSourceSetSha256,
            HeldOutSourceSetSha256 = full.HeldOutSourceSetSha256,
            PartitionSnapshotSha256 = full.PartitionSnapshotSha256
        };
    }

    private static async Task<DesignConversionDpoTrainingRecord>
        BuildRuntimeTeacherAuthoredTrainingRecordAsync(
            string id,
            string teacherRequestId,
            string modelId,
            string manifestDigest,
            string modelLayerDigest)
    {
        var incumbent = DesignConversionDpoGeneratorTests.CreateRuntimeEvaluation(
            canPersistTrainingCandidate: false,
            jobId: $"{id}-incumbent-job",
            requestId: $"{id}-incumbent-request",
            outputId: $"{id}-incumbent-output",
            candidateId: $"{id}-incumbent-candidate",
            verdictId: $"{id}-incumbent-verdict",
            score: 0.46,
            passed: false,
            htmlSuffix: $"{id}-incumbent");
        using var client = new StorageTeacherAuthoringClient(
            teacherRequestId,
            modelId,
            manifestDigest,
            modelLayerDigest);
        using var runtime = new DesignConversionDpoTeacherAttestationRuntime(
            client,
            modelId,
            manifestDigest,
            modelLayerDigest);
        var reservation = DesignConversionDpoTeacherCallReservation.Create(1, 0);
        Assert.True(reservation.IsSuccess, reservation.ErrorMessage);
        var authored = await runtime.AuthorCandidateAsync(
            BuildStorageTeacherAuthoringUpdateRequest(incumbent),
            reservation.Value!);
        Assert.True(authored.IsSuccess, authored.ErrorMessage);

        var generated = DesignConversionDpoGeneratorTests.CreateRuntimeEvaluation(
            canPersistTrainingCandidate: true,
            jobId: $"{id}-generated-job",
            requestId: authored.Value!.Candidate.RequestId,
            outputId: $"{id}-generated-output",
            candidateId: authored.Value.Candidate.CandidateId,
            verdictId: $"{id}-generated-verdict",
            score: 0.88,
            passed: true,
            htmlSuffix: $"{id}-generated");
        var submitted = generated.SubmittedRequest with
        {
            RequestId = authored.Value.Candidate.RequestId,
            Html = authored.Value.Candidate.Html,
            Css = authored.Value.Candidate.Css,
            Provenance = new Dictionary<string, string>(StringComparer.Ordinal)
            {
                ["source_manifest_ref"] = $"manifest://runtime-teacher-authored/{id}"
            }
        };
        generated = generated with
        {
            SubmittedRequest = submitted,
            RuntimeFlowResult = generated.RuntimeFlowResult with
            {
                Request = submitted,
                Candidate = authored.Value.Candidate,
                Output = generated.RuntimeFlowResult.Output with
                {
                    CandidateId = authored.Value.Candidate.CandidateId
                }
            }
        };
        var pair = new DesignConversionTeacherAuthoredEvaluationPair(
            authored.Value.AuthoringEvidence!.AttemptNumber,
            generated,
            incumbent,
            authored.Value.AuthoringEvidence,
            authored.Value.Candidate.CandidateId);
        var artifactRootBinding = DesignConversionDpoGenerator.Sha256Ref(
            "storage-independent-preference-root|" + id);
        var observedAtUtc = DateTimeOffset.UtcNow;
        var receipt = BuildStorageIndependentPreferenceReceipt(
            pair,
            artifactRootBinding,
            observedAtUtc);
        var build = new DesignConversionDpoGenerator()
            .BuildRuntimeTeacherAuthoredTrainingCandidates(
                [pair],
                [receipt],
                artifactRootBinding,
                observedAtUtc);
        Assert.True(build.IsSuccess, build.ErrorMessage);
        Assert.Equal(
            new[]
            {
                DesignConversionDpoUnits.CriticUnit,
                DesignConversionDpoUnits.ImproverUnit
            },
            build.Value!.AcceptedRecords.Select(static record => record.UnitId));
        var record = build.Value.AcceptedRecords[1];
        Assert.Equal(DesignConversionDpoUnits.ImproverUnit, record.UnitId);
        Assert.NotNull(record.PayloadCustodySecret);
        Assert.Equal(teacherRequestId, record.TeacherProvenance!.RequestId);
        return record;
    }

