    private static DesignConversionDpoHeldOutCycleAccuracyLineage
        BuildColdCycleAccuracyLineage(
            DesignConversionDpoHeldOutEvaluation evaluation)
        => new(
            CycleOrdinal: 1,
            CurrentMeasuredAccuracy: evaluation.Accuracy,
            HasParentMeasurement: false,
            ParentCycleOrdinal: null,
            ParentMeasuredAccuracy: null,
            ParentPolicyCheckpointSha256: null,
            ParentDatasetId: null,
            ParentHeldOutRecordSetSha256: null,
            ParentHeldOutSourceSetSha256: null,
            ParentHeldOutEvaluationInputSha256: null,
            ComparableHeldOut: false,
            AccuracyDelta: null);

    private static DesignConversionDpoHeldOutEvaluation BuildHeldOutEvaluationForTests(
        string id,
        int correctCount,
        int heldOutCount)
    {
        string HashValue(string value)
            => Convert.ToHexString(SHA256.HashData(
                    System.Text.Encoding.UTF8.GetBytes(value)))
                .ToLowerInvariant();
        var accuracy = (double)correctCount / heldOutCount;
        var evaluation = new DesignConversionDpoHeldOutEvaluation(
            DesignConversionDpoPolicyCheckpointBridge.EvaluatedSchema,
            DesignConversionDpoPolicyCheckpointBridge.EvaluatedPackingId,
            VocabSize: 256,
            ContextLength: 8,
            DpoStepCount: 1,
            MaxBridgePreferenceCount: 1,
            ChildPolicyCheckpointSha256: HashValue($"{id}:child"),
            ReferencePolicyCheckpointSha256: HashValue($"{id}:reference"),
            ReferenceMode: "provider_fresh_step_zero",
            DatasetId: id,
            PartitionSnapshotSha256: HashValue($"{id}:partition"),
            TrainRecordSetSha256: HashValue($"{id}:train-records"),
            HeldOutRecordSetSha256: HashValue($"{id}:heldout-records"),
            TrainSourceSetSha256: HashValue($"{id}:train-sources"),
            HeldOutSourceSetSha256: HashValue($"{id}:heldout-sources"),
            SelectedTrainInputSha256: HashValue($"{id}:train-input"),
            HeldOutEvaluationInputSha256: HashValue($"{id}:heldout-input"),
            TrainRecordCount: 1,
            HeldOutRecordCount: heldOutCount,
            EvaluatedHeldOutRecordCount: heldOutCount,
            CorrectCount: correctCount,
            Accuracy: accuracy,
            MeanRelativeMargin: correctCount > 0 ? 1d : -1d,
            MeanChildMargin: correctCount > 0 ? 2d : 0d,
            MeanReferenceMargin: 1d,
            FreshLoadVerified: true,
            ReferenceFrozen: true,
            SourceDisjoint: true,
            HeldOutNotTrained: true);
        return evaluation with
        {
            G3Metrics = new DesignConversionG3AcceptanceMetrics(
                HeldOutCount: heldOutCount,
                BaselineWinCount: correctCount,
                BaselineWinRate: accuracy,
                AbsoluteChildPreferenceCorrectCount: correctCount,
                AbsoluteChildPreferenceAccuracy: accuracy)
            {
                MeasurementNoiseScorerIdentity =
                    DesignConversionDpoPolicyCheckpointBridge
                        .EvaluatedMeasurementNoiseScorerIdentity,
                MeasurementNoiseEvaluationSetId = id
            },
            CycleAccuracyLineage = BuildColdCycleAccuracyLineage(evaluation)
        };
    }

    private static async Task AssertPromotedDpoPolicyCheckpointUsesProviderAsync(
        string promotedCheckpointPath,
        DesignConversionPromotedLocalModelLoadResult promotedLoad,
        DesignConversionTrainingIntakeLocalPromotionResult promotion,
        DesignConversionDpoPolicyBaseTestProvider provider,
        int expectedDpoStepCount = DesignConversionDpoPolicyCheckpointBridgeOptions.DefaultDpoStepCount)
    {
        Assert.True(provider.InvocationCount > 0);
        Assert.NotNull(provider.LastModelSet);

        var providerModelSet = provider.LastModelSet!;
        Assert.NotNull(promotedLoad.Checkpoint.DpoPolicyCheckpointRef);
        var typedRef = promotedLoad.Checkpoint.DpoPolicyCheckpointRef!;

        var expectedConfig = DesignConversionDpoPolicyBaseTestProvider.CreateConfig();
        var expectedConfigSha256 = DesignConversionDpoPolicyBaseMetadata.ComputeConfigSha256(expectedConfig);
        var expectedInitialWeightSha256 =
            DesignConversionDpoPolicyBaseMetadata.ComputeInitialWeightSha256(providerModelSet.Reference);
        Assert.False(string.IsNullOrWhiteSpace(expectedInitialWeightSha256));

        Assert.Equal("11.DPO:DpoTrainer", typedRef.SourceSystem);
        Assert.Equal("11.DPO:DpoTrainer.StepVector:fresh_loaded", typedRef.SourceMechanism);
        Assert.Equal(DesignConversionMachine.DpoPolicyDirectInferenceRuntimeBridgeKind, typedRef.RuntimeBridgeKind);
        Assert.True(typedRef.FreshLoadVerified);
        Assert.True(typedRef.ConvertedToRuntimeWeights);
        Assert.Equal(expectedDpoStepCount, typedRef.DpoStepCount);
        Assert.Equal(DpoTrainer.BuildPolicyCheckpointFileName(expectedDpoStepCount), typedRef.PolicyCheckpointFileName);
        Assert.Equal(4, typedRef.TrainingContext.SchemaVersion);
        Assert.True(DesignConversionDpoLegalTeacherAdmissionCommitmentCodec.Validate(
            typedRef.TrainingContext.LegalTeacherAdmissionCommitment));
        Assert.True(DesignConversionDpoLegalTeacherAdmissionCommitmentCodec.MatchesCheckpointEvidence(
            typedRef.TrainingContext.LegalTeacherAdmissionCommitment,
            typedRef.EvidenceRefs));
        Assert.Equal(providerModelSet.Identity.ProviderKind, typedRef.TrainingContext.ProviderKind);
        Assert.Equal(providerModelSet.Identity.ConfigurationKind, typedRef.TrainingContext.ConfigKind);
        Assert.Equal(providerModelSet.Identity.BaseModelId, typedRef.TrainingContext.BaseModelId);
        Assert.Equal(providerModelSet.Identity.BaseRevision, typedRef.TrainingContext.BaseRevision);
        Assert.Equal(providerModelSet.Identity.BaseCheckpointSha256, typedRef.TrainingContext.BaseCheckpointSha256);
        Assert.Equal(expectedConfigSha256, typedRef.TrainingContext.ConfigSha256);
        Assert.Equal(expectedInitialWeightSha256, typedRef.TrainingContext.InitialWeightSha256);
        Assert.Equal(
            expectedInitialWeightSha256,
            DesignConversionDpoPolicyBaseMetadata.ComputeInitialWeightSha256(providerModelSet.Reference));
        var postPromotionPolicyWeightSha256 =
            DesignConversionDpoPolicyBaseMetadata.ComputeInitialWeightSha256(providerModelSet.Policy);
        if (!string.Equals(postPromotionPolicyWeightSha256, expectedInitialWeightSha256, StringComparison.Ordinal))
            Assert.NotEqual(postPromotionPolicyWeightSha256, typedRef.TrainingContext.InitialWeightSha256);
        Assert.Equal(expectedConfig.VocabSize, typedRef.TrainingContext.VocabSize);
        Assert.Equal(expectedConfig.ContextLen, typedRef.TrainingContext.ContextLength);
        Assert.Equal(expectedConfig.HiddenDim, typedRef.TrainingContext.HiddenDim);
        Assert.Equal(expectedConfig.NumLayers, typedRef.TrainingContext.NumLayers);
        Assert.Equal(expectedConfig.NumHeads, typedRef.TrainingContext.NumHeads);
        Assert.Equal(expectedConfig.NumKvHeads, typedRef.TrainingContext.NumKvHeads);
        Assert.Equal(expectedConfig.FfnHiddenDim, typedRef.TrainingContext.FfnHiddenDim);
        Assert.Equal(expectedConfig.RopeTheta, typedRef.TrainingContext.RopeTheta);
        Assert.Equal(expectedConfig.RmsNormEps, typedRef.TrainingContext.RmsNormEps);
        Assert.DoesNotContain("CreateTinyPolicyConfig", typedRef.TrainingContext.ConfigKind, StringComparison.Ordinal);
        Assert.True(typedRef.TrainingContext.RawPayloadPersisted);
        Assert.False(typedRef.TrainingContext.AbsolutePathPersisted);
        Assert.False(Path.IsPathRooted(typedRef.PolicyCheckpointFileName));
        Assert.Equal(Path.GetFileName(typedRef.PolicyCheckpointFileName), typedRef.PolicyCheckpointFileName);

        var checkpointDirectory = Path.GetDirectoryName(promotedCheckpointPath);
        Assert.False(string.IsNullOrWhiteSpace(checkpointDirectory));
        var policyCheckpointPath = Path.Combine(checkpointDirectory!, typedRef.PolicyCheckpointFileName);
        Assert.True(File.Exists(policyCheckpointPath));
        var payloadBytes = await File.ReadAllBytesAsync(policyCheckpointPath);
        Assert.True(payloadBytes.Length > 0);
        Assert.Equal(payloadBytes.Length, typedRef.PolicyCheckpointByteLength);
        Assert.Equal(typedRef.Sha256, Convert.ToHexString(SHA256.HashData(payloadBytes)).ToLowerInvariant());
        var artifacts = Assert.IsType<DesignConversionTrainingManifestArtifacts>(
            promotion.Publication!.Manifest.PromotionArtifacts);
        var tokenizerArtifactPath = artifacts.TokenizerPath;
        var policyContractFileName = Path.GetFileName(artifacts.PolicyPath);
        Assert.EndsWith(
            DesignConversionDpoPromotionArtifactContractCodec.PolicyCheckpointContractSuffix,
            policyContractFileName,
            StringComparison.Ordinal);
        var artifactStem = policyContractFileName[
            ..^DesignConversionDpoPromotionArtifactContractCodec.PolicyCheckpointContractSuffix.Length];
        var sourceEncoderContractPath = Path.Combine(
            Path.GetDirectoryName(artifacts.PolicyPath)!,
            artifactStem + DesignConversionDpoPromotionArtifactContractCodec.SourceEncoderContractSuffix);
        Assert.Equal(promotedCheckpointPath, artifacts.CheckpointPath);
        Assert.Equal(
            DesignConversionDpoPromotionArtifactContractCodec.TokenizerArtifactSuffix,
            Path.GetFileName(tokenizerArtifactPath)[^DesignConversionDpoPromotionArtifactContractCodec.TokenizerArtifactSuffix.Length..]);
        Assert.Equal(
            DesignConversionDpoPromotionArtifactContractCodec.SourceEncoderContractSuffix,
            Path.GetFileName(sourceEncoderContractPath)[^DesignConversionDpoPromotionArtifactContractCodec.SourceEncoderContractSuffix.Length..]);
        Assert.False(string.Equals(
            tokenizerArtifactPath,
            sourceEncoderContractPath,
            StringComparison.OrdinalIgnoreCase));
        Assert.True(File.Exists(tokenizerArtifactPath));
        Assert.True(File.Exists(sourceEncoderContractPath));
        Assert.True(File.Exists(artifacts.PolicyPath));

        var tokenizerArtifactBytes = await File.ReadAllBytesAsync(tokenizerArtifactPath);
        var sourceContractBytes = await File.ReadAllBytesAsync(sourceEncoderContractPath);
        var policyContractBytes = await File.ReadAllBytesAsync(artifacts.PolicyPath);
        var tokenizerArtifact = System.Text.Json.JsonSerializer.Deserialize<
            DesignConversionDpoUtf8ByteTokenizerArtifact>(
                tokenizerArtifactBytes,
                DesignConversionCheckpointJsonOptions.Standard);
        var sourceContract = System.Text.Json.JsonSerializer.Deserialize<
            DesignConversionDpoSourceEncoderContract>(
                sourceContractBytes,
                DesignConversionCheckpointJsonOptions.Standard);
        var policyContract = System.Text.Json.JsonSerializer.Deserialize<
            DesignConversionDpoPolicyCheckpointContract>(
                policyContractBytes,
                DesignConversionCheckpointJsonOptions.Standard);
        Assert.NotNull(tokenizerArtifact);
        Assert.NotNull(sourceContract);
        Assert.NotNull(policyContract);
        Assert.True(DesignConversionDpoPromotionArtifactContractCodec.ValidateContractPair(
            sourceContract,
            policyContract));
        var evaluation = Assert.IsType<DesignConversionDpoHeldOutEvaluation>(
            policyContract!.Evaluation);
        Assert.Equal(
            DesignConversionDpoPolicyCheckpointBridge.EvaluatedSchema,
            evaluation.Schema);
        Assert.Equal(
            DesignConversionDpoPolicyCheckpointBridge.EvaluatedPackingId,
            evaluation.PackingId);
        Assert.True(evaluation.FreshLoadVerified);
        Assert.True(evaluation.ReferenceFrozen);
        Assert.True(evaluation.SourceDisjoint);
        Assert.True(evaluation.HeldOutNotTrained);
        Assert.Equal(evaluation.HeldOutRecordCount, evaluation.EvaluatedHeldOutRecordCount);
        var policyNode = JsonNode.Parse(policyContractBytes)!.AsObject();
        var evaluationProperty = Assert.Single(
            policyNode,
            property => string.Equals(
                property.Key,
                "evaluation",
                StringComparison.OrdinalIgnoreCase));
        var evaluationNode = Assert.IsType<JsonObject>(evaluationProperty.Value);
        foreach (var propertyName in evaluationNode.Select(property => property.Key).ToArray())
        {
            var tamperedNode = policyNode.DeepClone().AsObject();
            var tamperedEvaluation = Assert.IsType<JsonObject>(
                tamperedNode[evaluationProperty.Key]);
            tamperedEvaluation[propertyName] = "tampered-evaluation-field";
            DesignConversionDpoPolicyCheckpointContract? tamperedContract = null;
            try
            {
                tamperedContract = tamperedNode.Deserialize<
                    DesignConversionDpoPolicyCheckpointContract>(
                        DesignConversionCheckpointJsonOptions.Standard);
            }
            catch (System.Text.Json.JsonException)
            {
            }
            Assert.True(
                tamperedContract is null ||
                !DesignConversionDpoPromotionArtifactContractCodec.ValidateContractPair(
                    sourceContract,
                    tamperedContract),
                $"Evaluation field '{propertyName}' must be contract-bound.");
        }
        Assert.False(DesignConversionDpoPromotionArtifactContractCodec.ValidateContractPair(
            sourceContract,
            policyContract with { Evaluation = null }));
        Assert.Equal(sourceContract!.Binding.ArtifactSetId, policyContract!.Binding.ArtifactSetId);
        Assert.Equal(typedRef.PolicyCheckpointFileName, sourceContract.Binding.PolicyCheckpointFileName);
        Assert.Equal(typedRef.Sha256, sourceContract.Binding.PolicyCheckpointSha256);
        Assert.Equal(typedRef.PolicyCheckpointByteLength, sourceContract.Binding.PolicyCheckpointByteLength);
        Assert.Equal(Path.GetFileName(promotedCheckpointPath), sourceContract.Binding.RuntimeCheckpointFileName);
        Assert.Equal(await ReadSha256Async(promotedCheckpointPath), sourceContract.Binding.RuntimeCheckpointSha256);
        Assert.Equal(new FileInfo(promotedCheckpointPath).Length, sourceContract.Binding.RuntimeCheckpointByteLength);
        Assert.Equal(Path.GetFileName(tokenizerArtifactPath), sourceContract.Binding.TokenizerArtifactFileName);
        Assert.Equal(tokenizerArtifactBytes.LongLength, sourceContract.Binding.TokenizerArtifactByteLength);
        Assert.Equal(
            Convert.ToHexString(SHA256.HashData(tokenizerArtifactBytes)).ToLowerInvariant(),
            sourceContract.Binding.TokenizerArtifactSha256);
        Assert.Equal(typedRef.SourceRecordCount, policyContract.SourceRecordCount);
        Assert.Equal(typedRef.BridgePreferenceCount, policyContract.BridgePreferenceCount);
        Assert.Equal(typedRef.DpoStepCount, policyContract.DpoStepCount);
        Assert.Equal(typedRef.SourceSystem, policyContract.SourceSystem);
        Assert.Equal(typedRef.SourceMechanism, policyContract.SourceMechanism);
        Assert.Equal(typedRef.RuntimeBridgeKind, policyContract.RuntimeBridgeKind);
        Assert.True(policyContract.FreshLoadVerified);
        Assert.True(policyContract.ConvertedToRuntimeWeights);
        Assert.False(policyContract.RawPayloadPersisted);
        Assert.False(policyContract.AbsolutePathPersisted);
        Assert.Equal(
            typedRef.TrainingContext.RawPayloadPersisted,
            policyContract.TrainingContext.RawPayloadPersisted);
        Assert.Equal(
            typedRef.TrainingContext.AbsolutePathPersisted,
            policyContract.TrainingContext.AbsolutePathPersisted);
        Assert.Equal(typedRef.TrainingContext.ConfigKind, policyContract.TrainingContext.ConfigKind);
        Assert.Equal(typedRef.TrainingContext.VocabSize, policyContract.TrainingContext.VocabSize);
        Assert.Equal(typedRef.TrainingContext.ContextLength, policyContract.TrainingContext.ContextLength);

        var descriptor = sourceContract.Binding.SourceEncoderDescriptor;
        Assert.Equal("DesignConversionDefaultSourceEncoder", descriptor.EncoderName);
        Assert.Equal("dcm-source-encoder-v1", descriptor.EncoderSchema);
        Assert.Equal("utf-8", descriptor.PolicyTextEncoding);
        Assert.Equal(
            DesignConversionDpoSourceEncoderContractBuilder.EvaluatedDescriptorSchema,
            descriptor.ContractSchema);
        Assert.Equal("utf8_byte_identity_lossless_0_255", descriptor.PolicyTokenMapping);
        Assert.Equal("pair_aware_shared_response_window_first_or_prefix_length_divergence", descriptor.PolicyContextTruncation);
        Assert.Equal("fixed_context_prompt_and_padding_mask_zero_response_mask_one", descriptor.PolicyTrainingPadding);
        Assert.Equal(0, descriptor.TokenIdMinimum);
        Assert.Equal(255, descriptor.TokenIdMaximum);
        Assert.Equal(typedRef.TrainingContext.ContextLength, descriptor.ContextLength);
        Assert.True(descriptor.TokenizerArtifactPresent);
        Assert.False(descriptor.RawPayloadPersisted);
        Assert.False(descriptor.AbsolutePathPersisted);
        Assert.True(DesignConversionDpoPromotionArtifactContractCodec.ValidateTokenizerArtifact(
            tokenizerArtifact,
            descriptor));
        Assert.Equal(
            DesignConversionDpoPromotionArtifactContractCodec.TokenizerArtifactSchema,
            tokenizerArtifact!.Schema);
        Assert.Equal(256, tokenizerArtifact.Vocabulary.Count);
        for (var byteValue = 0; byteValue < tokenizerArtifact.Vocabulary.Count; byteValue++)
        {
            var token = tokenizerArtifact.Vocabulary[byteValue];
            Assert.Equal(byteValue, token.ByteValue);
            Assert.Equal(byteValue, token.TokenId);
            Assert.Equal(byteValue.ToString("x2", System.Globalization.CultureInfo.InvariantCulture), token.ByteHex);
        }

        var compactJson = new System.Text.Json.JsonSerializerOptions(
            DesignConversionCheckpointJsonOptions.Standard)
        {
            WriteIndented = false
        };
        Assert.Equal(
            System.Text.Json.JsonSerializer.SerializeToUtf8Bytes(typedRef.TrainingContext, compactJson),
            System.Text.Json.JsonSerializer.SerializeToUtf8Bytes(policyContract.TrainingContext, compactJson));
        Assert.Equal(
            tokenizerArtifactBytes,
            System.Text.Json.JsonSerializer.SerializeToUtf8Bytes(tokenizerArtifact, compactJson));
        Assert.Equal(
            sourceContractBytes,
            System.Text.Json.JsonSerializer.SerializeToUtf8Bytes(sourceContract, compactJson));
        Assert.Equal(
            policyContractBytes,
            System.Text.Json.JsonSerializer.SerializeToUtf8Bytes(policyContract, compactJson));
        Assert.False(tokenizerArtifactBytes.AsSpan().StartsWith(System.Text.Encoding.UTF8.GetPreamble()));
        Assert.False(sourceContractBytes.AsSpan().StartsWith(System.Text.Encoding.UTF8.GetPreamble()));
        Assert.False(policyContractBytes.AsSpan().StartsWith(System.Text.Encoding.UTF8.GetPreamble()));
        var contractText = System.Text.Encoding.UTF8.GetString(tokenizerArtifactBytes) +
                           System.Text.Encoding.UTF8.GetString(sourceContractBytes) +
                           System.Text.Encoding.UTF8.GetString(policyContractBytes);
        Assert.DoesNotContain(checkpointDirectory!, contractText, StringComparison.OrdinalIgnoreCase);
        Assert.DoesNotContain("externalCloudUpload", contractText, StringComparison.OrdinalIgnoreCase);
        AssertDoesNotContainRawPrivatePayload(contractText);
        Assert.Equal($"dpo_policy_checkpoint_sha256:{typedRef.Sha256}", promotedLoad.Model.DpoPolicyCheckpointSha256Ref);
        Assert.Equal($"dpo_policy_checkpoint_file:{typedRef.PolicyCheckpointFileName}", promotedLoad.Model.DpoPolicyCheckpointFileRef);
        Assert.Equal(promotedLoad.Model.DpoPolicyCheckpointSha256Ref, promotion.PromotedLocalModel!.DpoPolicyCheckpointSha256Ref);
        Assert.Equal(promotedLoad.Model.DpoPolicyCheckpointFileRef, promotion.PromotedLocalModel.DpoPolicyCheckpointFileRef);

        Assert.Contains(DesignConversionMachine.DpoTrainerPolicyCheckpointFreshLoadedEvidence, typedRef.EvidenceRefs);
        Assert.Contains(DesignConversionMachine.DpoTrainerPolicyCheckpointConvertedEvidence, typedRef.EvidenceRefs);
        Assert.Contains(DesignConversionMachine.DpoPolicyDirectInferenceConfiguredEvidence, typedRef.EvidenceRefs);
        Assert.Contains("DESIGN_CONVERSION_DPO_POLICY_CHECKPOINT_REF_TYPED", typedRef.EvidenceRefs);
        Assert.Contains("DESIGN_CONVERSION_DPO_POLICY_CHECKPOINT_REF_PAYLOAD_FILE_SIBLING", typedRef.EvidenceRefs);
        Assert.Contains("DESIGN_CONVERSION_DPO_POLICY_BASE_PROVIDER_INJECTED", typedRef.EvidenceRefs);
        Assert.Contains("DESIGN_CONVERSION_DPO_POLICY_BASE_IDENTITY_VALIDATED", typedRef.EvidenceRefs);
        Assert.Contains($"dpo_policy_step_count:{expectedDpoStepCount}", typedRef.EvidenceRefs);
        Assert.Contains($"dpo_policy_base_provider_kind:{providerModelSet.Identity.ProviderKind}", typedRef.EvidenceRefs);
        Assert.Contains($"dpo_policy_base_configuration_kind:{providerModelSet.Identity.ConfigurationKind}", typedRef.EvidenceRefs);
        Assert.Contains($"dpo_policy_base_model_id:{providerModelSet.Identity.BaseModelId}", typedRef.EvidenceRefs);
        Assert.Contains($"dpo_policy_base_revision:{providerModelSet.Identity.BaseRevision}", typedRef.EvidenceRefs);
        Assert.Contains($"dpo_policy_base_checkpoint_sha256:{providerModelSet.Identity.BaseCheckpointSha256}", typedRef.EvidenceRefs);
        Assert.Contains($"dpo_policy_config_sha256:{expectedConfigSha256}", typedRef.EvidenceRefs);
        Assert.Contains($"dpo_policy_initial_weight_sha256:{expectedInitialWeightSha256}", typedRef.EvidenceRefs);
        Assert.DoesNotContain("DESIGN_CONVERSION_DPO_POLICY_CHECKPOINT_REF_RAW_PAYLOAD_EMBEDDED", typedRef.EvidenceRefs);
    }

    private static async Task<KeyValuePair<string, string>[]> ReadFileSha256SnapshotAsync(string root)
    {
        if (!Directory.Exists(root))
            return [];

        var snapshot = new List<KeyValuePair<string, string>>();
        foreach (var path in Directory.EnumerateFiles(root, "*", SearchOption.AllDirectories)
                     .OrderBy(path => path, StringComparer.Ordinal))
        {
            var relativePath = Path.GetRelativePath(root, path)
                .Replace(Path.DirectorySeparatorChar, '/')
                .Replace(Path.AltDirectorySeparatorChar, '/');
            snapshot.Add(new KeyValuePair<string, string>(relativePath, await ReadSha256Async(path)));
        }

        return snapshot
            .OrderBy(pair => pair.Key, StringComparer.Ordinal)
            .ToArray();
    }

