    private static Pass157PromotedModelServerFixture
        CreatePass157PromotedLocalWithRuntimeArtifactDb(
        string root,
        string id,
        DesignConversionPromotedLocalModelLoadResult promotedLoad,
        IDesignConversionRenderProvider renderProvider,
        IDesignConversionComparisonProvider comparisonProvider,
        IDesignConversionVisualJudge? visualJudge = null,
        Func<DateTimeOffset>? utcNow = null,
        DesignConversionDpoUsefulnessApi? trainingReadbackApi = null,
        IDesignConversionLocalArtifactDb? runtimeArtifactDb = null)
    {
        var service = DesignConversionPromotedLocalModelLoader.CreateInternalService(
            promotedLoad,
            renderProvider,
            comparisonProvider,
            visualJudge);
        var evaluator = new DesignConversionInternalServiceThinClientJobEvaluator(service);
        var artifactDb = new RecordingRuntimeArtifactDb(
            runtimeArtifactDb ??
            new JsonlDesignConversionLocalArtifactDb(Path.Combine(root, $"{id}-runtime-artifact-db")));
        var teacherAssociation = DesignConversionDpoTeacherTestAssociation
            .Associate(
                artifactDb,
                supportTeacherAuthoring: true,
                supportIndependentPreferenceEvidence: true);

        // Keep the same fresh-load authority as CreateFromTrainingIntakeLocalPromotionAsync while adding
        // the test-local artifact DB required for runtime-created DPO candidate persistence.
        var apiType = typeof(DesignConversionModelServerApi);
        var proofType = apiType.GetNestedType("PromotedLocalModelVerificationProof", BindingFlags.NonPublic);
        Assert.NotNull(proofType);
        var proofFactory = proofType!.GetMethod(
            "FromFreshPromotionLoad",
            BindingFlags.Public | BindingFlags.Static);
        Assert.NotNull(proofFactory);
        var proof = proofFactory!.Invoke(null, [promotedLoad.Model]);
        Assert.NotNull(proof);
        var constructor = apiType
            .GetConstructors(BindingFlags.Instance | BindingFlags.NonPublic)
            .Single(ctor =>
            {
                var parameters = ctor.GetParameters();
                return parameters.Length == 14 &&
                       parameters[0].ParameterType == typeof(IDesignConversionThinClientJobEvaluator) &&
                       parameters[2].ParameterType == typeof(IDesignConversionLocalArtifactDb);
            });

        try
        {
            var api = (DesignConversionModelServerApi)constructor.Invoke(
                [
                    evaluator,
                    utcNow,
                    artifactDb,
                    trainingReadbackApi,
                    promotedLoad.Model,
                    null,
                    null,
                    null,
                    new JsonlDesignConversionVisualCostLedger(
                        Path.Combine(root, $"{id}-visual-cost-ledger")),
                    new JsonlDesignConversionVisualCostBudgetStore(
                        Path.Combine(root, $"{id}-visual-cost-budget-store")),
                    null,
                    proof,
                    null,
                    null
                ]);
            return new Pass157PromotedModelServerFixture(api, teacherAssociation, artifactDb);
        }
        catch
        {
            teacherAssociation.Dispose();
            throw;
        }
    }

