    private static DesignConversionModelServerApiRequest CreatePass157RetryRequest(
        string requestId,
        string? tenantId = null)
    {
        var request = CreatePass157Request(requestId);
        var metadata = new Dictionary<string, string>(
            request.Metadata ?? new Dictionary<string, string>(),
            StringComparer.Ordinal);
        var tier = request.Budget!.Tier;
        if (!string.IsNullOrWhiteSpace(tenantId))
        {
            tier = "pro";
            metadata["tenant_id"] = tenantId;
            metadata[DesignConversionModelServerApi.ServerAssignedDesignTierMetadataKey] =
                tier;
            metadata[DesignConversionModelServerApi.ServerAssignedMonthlyVisualCostLimitUsdMetadataKey] =
                "125.75";
            metadata[DesignConversionModelServerApi.DesignTierAuthorityMetadataKey] =
                DesignConversionModelServerApi.PlatformTenantConfigurationAuthority;
            metadata[DesignConversionModelServerApi.MonthlyVisualCostLimitAuthorityMetadataKey] =
                DesignConversionModelServerApi.PlatformTenantConfigurationAuthority;
            metadata[DesignConversionModelServerApi.UserIdentityAuthorityMetadataKey] =
                DesignConversionModelServerApi.VerifiedInboundPrincipalAuthority;
        }

        return request with
        {
            Budget = request.Budget! with
            {
                UserId = "platform-user-pass157-route",
                Tier = tier,
                BudgetUsd = 1.00m
            },
            Metadata = metadata
        };
    }

    private static DesignConversionModelServerRouteAdmissionContext
        CreatePass157RouteAdmissionContext(string tenantId)
    {
        var tenant = DesignConversionModelActivationRegistry
            .TryBuildTenantIdentity(tenantId);
        Assert.True(tenant.IsSuccess, tenant.ErrorMessage);
        var tenantIdentity = tenant.Value!;
        var scope = string.Concat(
            DesignConversionModelServerRouteAdmission.RouteScopeDefault,
            "\n",
            tenantIdentity.TenantIdRef);
        return new DesignConversionModelServerRouteAdmissionContext(
            TenantBound: true,
            TenantId: tenantIdentity.TenantId,
            TenantIdRef: tenantIdentity.TenantIdRef,
            Scope: scope,
            ScopeRef: BuildPass157ScopedSha256Ref(
                "design-conversion-route-admission-scope",
                scope));
    }

    private static string BuildPass157ScopedSha256Ref(
        string scope,
        string value)
        => $"sha256:{scope}:{Convert.ToHexString(
            SHA256.HashData(Encoding.UTF8.GetBytes(value ?? string.Empty)))
            .ToLowerInvariant()}";

