    private sealed class Pass157RecordingComparisonProvider(params VisualVerdict[] verdicts)
        : IDesignConversionComparisonProvider
    {
        private readonly VisualVerdict[] _verdicts = verdicts.Length == 0
            ? [CreatePass157Verdict("pass157-recording-default-verdict", 0.93, passed: true)]
            : verdicts;
        private int _verdictIndex;

        public Task<OperationResult<DesignConversionQaComparisonArtifact>> CompareAsync(
            DesignConversionQaComparisonRequest request,
            CancellationToken cancellationToken = default)
        {
            var verdictIndex = Interlocked.Increment(ref _verdictIndex) - 1;
            var verdict = _verdicts[Math.Min(verdictIndex, _verdicts.Length - 1)];
            return Task.FromResult(OperationResult<DesignConversionQaComparisonArtifact>.Ok(new DesignConversionQaComparisonArtifact(
                ArtifactId: $"{request.ComparisonRequestId}:artifact",
                ComparisonRequestId: request.ComparisonRequestId,
                Expected: request.Expected,
                Actual: request.Actual,
                Verdict: verdict,
                DiffImageUri: $"artifact://pass157/diff/{request.ComparisonRequestId}.png",
                DiffImageSha256: $"sha256:{request.ComparisonRequestId}:diff",
                Metrics: new Dictionary<string, double> { ["visual_distance"] = 1.0 - verdict.Score },
                EvidenceRefs: ["pass157-comparison-provider"])));
        }
    }

    private sealed class Pass157RecordingVisualJudge(params double[] scores)
        : IDesignConversionVisualJudge
    {
        private readonly double[] _scores = scores.Length == 0
            ? [0.93]
            : scores;
        private int _scoreIndex;

        public Task<OperationResult<DesignConversionVisualJudgeResult>> JudgeAsync(
            DesignConversionVisualJudgeRequest request,
            CancellationToken cancellationToken = default)
        {
            var scoreIndex = Interlocked.Increment(ref _scoreIndex) - 1;
            var score = _scores[Math.Min(scoreIndex, _scores.Length - 1)];
            var passed = score >= 0.90;
            var verdict = new VisualVerdict(
                VerdictId: $"{request.JudgeRequestId}:pass157-recording-verdict",
                Score: score,
                Defects: passed
                    ? []
                    :
                    [
                        new VisualDefect(
                            DefectId: $"{request.JudgeRequestId}:pass157-recording-defect",
                            Category: "quality",
                            Severity: "minor",
                            Description: "Pass157 recording visual judge scripted quality signal.",
                            X: 0,
                            Y: 0,
                            Width: 1,
                            Height: 1,
                            EvidenceImageIds: [request.ExpectedScreenshot.ImageId, request.RenderedImage.ImageId])
                    ],
                EvidenceRefs: [$"pass157-recording-visual-judge:{request.JudgeRequestId}"],
                Passed: passed);

            var metadata = new Dictionary<string, string>
            {
                [DesignConversionVisualQaBoundaryPolicy.TestProviderOnlyMarker] = bool.TrueString,
                ["external_ai_visual_judge_executed"] = bool.FalseString
            };

            return Task.FromResult(OperationResult<DesignConversionVisualJudgeResult>.Ok(new DesignConversionVisualJudgeResult(
                JudgeResultId: $"{request.JudgeRequestId}:pass157-recording-result",
                JudgeRequestId: request.JudgeRequestId,
                Status: "PASS157_RECORDING_VISUAL_JUDGE_VERDICT_RECEIVED",
                IsBlocked: false,
                Verdict: verdict,
                Provider: new DesignConversionVisualJudgeProviderMetadata(
                    ProviderName: "pass157-recording-local-judge",
                    EndpointHost: "none",
                    ModelId: "pass157-recording-local-v1",
                    ExternalCallExecuted: false,
                    Metadata: metadata),
                EstimatedCostUsd: 0m,
                TokenMetadata: new Dictionary<string, double>(),
                EvidenceRefs: verdict.EvidenceRefs,
                Metadata: metadata)));
        }
    }

