    private sealed class CheckpointPropertyStream(
        string? throwingProperty,
        bool canWrite = true) : Stream
    {
        public override bool CanRead => false;

        public override bool CanSeek => throwingProperty == "CanSeek"
            ? throw new NotSupportedException("injected CanSeek failure")
            : true;

        public override bool CanWrite => throwingProperty == "CanWrite"
            ? throw new IOException("injected CanWrite failure")
            : canWrite;

        public override long Length => throwingProperty == "Length"
            ? throw new NotSupportedException("injected Length failure")
            : 0;

        public override long Position
        {
            get => throwingProperty == "Position"
                ? throw new IOException("injected Position failure")
                : 0;
            set => throw new NotSupportedException();
        }

        public override void Flush()
            => throw new NotSupportedException();

        public override int Read(byte[] buffer, int offset, int count)
            => throw new NotSupportedException();

        public override long Seek(long offset, SeekOrigin origin)
            => throw new NotSupportedException();

        public override void SetLength(long value)
            => throw new NotSupportedException();

        public override void Write(byte[] buffer, int offset, int count)
            => throw new NotSupportedException();
    }

    private sealed class ContinuationOwnedValueProbe(Exception? disposeException)
        : IDisposable
    {
        private int _disposeCount;

        public int DisposeCount => Volatile.Read(ref _disposeCount);

        public void Dispose()
        {
            Interlocked.Increment(ref _disposeCount);
            if (disposeException is not null)
                throw disposeException;
        }
    }

    private sealed class RecordingEvaluatedContinuationProvider
        : IDesignConversionDpoPolicyContinuationProvider
    {
        private readonly DesignConversionDpoPolicyBaseTestProvider _inner = new();
        private readonly Func<
            DesignConversionDpoPolicyBaseModelSet,
            OperationResult<DesignConversionDpoPolicyBaseModelSet>>?
            _continuedModelSetTransform;

        public RecordingEvaluatedContinuationProvider(
            Func<
                DesignConversionDpoPolicyBaseModelSet,
                OperationResult<DesignConversionDpoPolicyBaseModelSet>>?
                continuedModelSetTransform = null)
        {
            _continuedModelSetTransform = continuedModelSetTransform;
        }

        public int FreshInvocationCount { get; private set; }
        public int ContinuationInvocationCount { get; private set; }
        public DesignConversionDpoPolicyContinuationRequest? LastContinuationRequest
        {
            get;
            private set;
        }

        public OperationResult<DesignConversionDpoPolicyBasePreparationDescriptor>
            DescribePreparation()
            => _inner.DescribePreparation();

        public Task<OperationResult<DesignConversionDpoPolicyBaseModelSet>>
            CreateModelSetAsync(CancellationToken cancellationToken)
        {
            FreshInvocationCount++;
            return _inner.CreateModelSetAsync(cancellationToken);
        }

        public Task<OperationResult<DesignConversionDpoPolicyBaseModelSet>>
            CreateModelSetAsync(
                DesignConversionDpoPolicyBasePreparationDescriptor preparation,
                CancellationToken cancellationToken)
        {
            FreshInvocationCount++;
            return _inner.CreateModelSetAsync(preparation, cancellationToken);
        }

        public async Task<OperationResult<DesignConversionDpoPolicyBaseModelSet>>
            CreateContinuedModelSetAsync(
                DesignConversionDpoPolicyContinuationRequest continuationRequest,
                CancellationToken cancellationToken)
        {
            ContinuationInvocationCount++;
            LastContinuationRequest = continuationRequest;
            var result = await _inner.CreateContinuedModelSetAsync(
                continuationRequest,
                cancellationToken);
            return TransformContinuationResult(result);
        }

        public async Task<OperationResult<DesignConversionDpoPolicyBaseModelSet>>
            CreateContinuedModelSetAsync(
                DesignConversionDpoPolicyBasePreparationDescriptor preparation,
                DesignConversionDpoPolicyContinuationRequest continuationRequest,
                CancellationToken cancellationToken)
        {
            ContinuationInvocationCount++;
            LastContinuationRequest = continuationRequest;
            var result = await _inner.CreateContinuedModelSetAsync(
                preparation,
                continuationRequest,
                cancellationToken);
            return TransformContinuationResult(result);
        }

        // Отдельный счётчик сверочных обращений: прежние счётчики не трогаем.
        public int VerificationInvocationCount { get; private set; }

        // Сверочный набор передаём внутреннему тестовому поставщику без
        // преобразования: он расходный и в обучение не идёт, поэтому
        // преобразование продолженного набора к нему не применяется.
        public Task<OperationResult<DesignConversionDpoPolicyBaseModelSet>>
            CreateContinuationVerificationModelSetAsync(
                ModelConfig config,
                DesignConversionDpoPolicyRandomContext randomContext,
                CancellationToken cancellationToken)
        {
            VerificationInvocationCount++;
            return _inner.CreateContinuationVerificationModelSetAsync(
                config,
                randomContext,
                cancellationToken);
        }

        private OperationResult<DesignConversionDpoPolicyBaseModelSet>
            TransformContinuationResult(
                OperationResult<DesignConversionDpoPolicyBaseModelSet> result)
        {
            if (_continuedModelSetTransform is null ||
                !result.IsSuccess ||
                result.Value is null)
            {
                return result;
            }

            return _continuedModelSetTransform(result.Value);
        }
    }

    private sealed class RecordingCanonicalBpeTokenizerSnapshotSource
        : IDesignConversionDpoCanonicalBpeTokenizerSnapshotSource
    {
        private int _invocationCount;

        public int InvocationCount
            => Interlocked.CompareExchange(ref _invocationCount, 0, 0);

        public Task<OperationResult<Stream>> OpenCanonicalBpeTokenizerSnapshotAsync(
            CancellationToken cancellationToken)
        {
            Interlocked.Increment(ref _invocationCount);
            return Task.FromResult(OperationResult<Stream>.Fail(
                "Test canonical BPE tokenizer source must not be opened by bridge transport.",
                "TEST_CANONICAL_BPE_TOKENIZER_SOURCE_OPENED"));
        }
    }

    private sealed class InMemoryCanonicalBpeTokenizerSnapshotSource(byte[] bytes)
        : IDesignConversionDpoCanonicalBpeTokenizerSnapshotSource
    {
        private int _invocationCount;

        public int InvocationCount
            => Interlocked.CompareExchange(ref _invocationCount, 0, 0);

        public Task<OperationResult<Stream>> OpenCanonicalBpeTokenizerSnapshotAsync(
            CancellationToken cancellationToken)
        {
            Interlocked.Increment(ref _invocationCount);
            if (cancellationToken.IsCancellationRequested)
            {
                return Task.FromResult(OperationResult<Stream>.Fail(
                    "Test canonical BPE tokenizer snapshot cancelled.",
                    "CANCELLED"));
            }

            return Task.FromResult(OperationResult<Stream>.Ok(
                new MemoryStream(bytes.ToArray(), writable: false)));
        }
    }

    private sealed class RecordingEvaluatedCheckpointSource(string path)
        : IDesignConversionDpoPolicyCheckpointSource
    {
        public int OpenCount { get; private set; }

        public Task<OperationResult<Stream>> OpenCheckpointSnapshotAsync(
            CancellationToken cancellationToken)
        {
            OpenCount++;
            if (cancellationToken.IsCancellationRequested)
            {
                return Task.FromResult(OperationResult<Stream>.Fail(
                    "Evaluated continuation checkpoint source cancelled.",
                    "CANCELLED"));
            }

            return Task.FromResult(OperationResult<Stream>.Ok(
                new FileStream(
                    path,
                    FileMode.Open,
                    FileAccess.Read,
                    FileShare.Read)));
        }
    }

    private static TypedCompositeBridgeAuthorityFixture
        CreateTypedCompositeBridgeAuthority(
            ServerOwnedLegalTrainingTeacherAdmissionAuthority authority,
            DesignConversionDpoPolicyCheckpointBridge
                .PreparedEvaluatedCompositeExecution prepared,
            string id)
    {
        var bridgeInput = prepared.FinalOptimizer.Inputs[0];
        var pipelineInput = new LearningTrainingItem(
            $"{id}:pipeline:0",
            bridgeInput.Prompt,
            bridgeInput.Chosen,
            bridgeInput.Rejected);
        var pipeline = DesignConversionDpoTrainingContentAuthority
            .ProjectFinalOptimizerInputs(
                [pipelineInput],
                [TrainingTeacherProvenance.Deterministic(
                    bridgeInput.Provenance!.RequestId)],
                static input => input.Prompt,
                static input => input.ChosenResponse,
                static input => input.RejectedResponse,
                static _ => Array.Empty<float>(),
                static _ => null,
                static input =>
                    $"typed-composite-bridge-test|item={input.ItemId}");
        Assert.True(pipeline.IsSuccess, pipeline.ErrorMessage);
        var pair = DpoPairTrainingContentAuthority.Bind(
            new DpoPair(
                pipelineInput.Prompt,
                pipelineInput.ChosenResponse,
                pipelineInput.RejectedResponse,
                DesignConversionMachine.DomainTag,
                DateTimeOffset.UnixEpoch)
            {
                TeacherProvenance = pipeline.Value!.Provenance[0],
                GovernanceDecision = new TrainingDataGovernanceDecision(
                    licenseAccepted: true,
                    isQuarantined: false,
                    ["sha256:" + new string('d', 64)])
            });
        Assert.True(pair.IsSuccess, pair.ErrorMessage);
        var commitment = DesignConversionDpoTrainingContentAuthority
            .ProjectCompositeOptimizerInputs(
                pipeline.Value,
                [pair.Value!],
                prepared.FinalOptimizer);
        Assert.True(commitment.IsSuccess, commitment.ErrorMessage);
        var lease = authority.AcquireTrainingLease(
            commitment.Value!.FinalOptimizer.Content,
            commitment.Value.FinalOptimizer.Provenance);
        Assert.True(lease.IsSuccess, lease.ErrorMessage);
        var binding = DesignConversionPipelineTrainingBinding.MintComposite(
            commitment.Value,
            pipeline.Value,
            prepared.FinalOptimizer,
            lease.Value);
        Assert.True(binding.IsSuccess, binding.ErrorMessage);
        return new TypedCompositeBridgeAuthorityFixture(
            commitment.Value,
            binding.Value!,
            lease.Value!);
    }

    private sealed record TypedCompositeBridgeAuthorityFixture(
        DesignConversionDpoTrainingContentAuthority
            .CompositeOptimizerCommitment Commitment,
        DesignConversionPipelineTrainingBinding Binding,
        ServerOwnedLegalTrainingTeacherAdmissionLease ParentLease);

    private static DpoTrainer CreateAdmittedTrainer(
        LlmModel policy,
        LlmModel reference,
        string checkpointDir,
        float learningRate = 1e-5f,
        DpoTrainerPublicationObserver? publicationObserver = null)
    {
        return new DpoTrainer(
            policy,
            reference,
            checkpointDir,
            DpoMutationAdmissionCapability.Issue(
                new TestDpoMutationAdmissionLease()),
            learningRate,
            publicationObserver);
    }

    private sealed class TestDpoMutationAdmissionLease
        : IDpoMutationAdmissionIssuer
    {
        IDisposable IDpoMutationAdmissionIssuer
            .AcquireDpoTrainerMutationPermit()
            => new CancellationTokenSource();

        public void Dispose()
        {
        }
    }

    private sealed record CanonicalBpeTokenizerSnapshotFixture(
        byte[] Bytes,
        DesignConversionDpoCanonicalBpeTokenizerArtifactDescriptor Descriptor);
}

file sealed class EvaluatedBridgeThrowOnAccessTrainingRecordList :
    IReadOnlyList<DesignConversionDpoTrainingRecord>
{
    public int AccessCount { get; private set; }

    public int Count => Fail<int>();

    public DesignConversionDpoTrainingRecord this[int index] =>
        Fail<DesignConversionDpoTrainingRecord>();

    public IEnumerator<DesignConversionDpoTrainingRecord> GetEnumerator()
        => Fail<IEnumerator<DesignConversionDpoTrainingRecord>>();

    System.Collections.IEnumerator System.Collections.IEnumerable.GetEnumerator()
        => GetEnumerator();

    private T Fail<T>()
    {
