        throw new InvalidOperationException(
            "Evaluated partition records must not be observed before legal authority admission.");
    }
}

file sealed class DesignConversionDpoPromotionReparseFactAttribute : FactAttribute
{
    public DesignConversionDpoPromotionReparseFactAttribute()
        => Skip = OperatingSystem.IsWindows()
            ? null
            : "REPARSE_TEST_PLATFORM_LIMITATION: GAP-7 handle-bound promotion is Windows-specific.";
}

// Этот локальный атрибут делает платформенную границу честной в отчёте:
// Windows запускает тело теста, а другая система показывает явный пропуск с причиной.
file sealed class DesignConversionDpoWindowsFileShareFactAttribute : FactAttribute
{
    // Причина написана обычным русским языком, чтобы читатель сразу понял,
    // почему строка теста не является ни успехом, ни дефектом Linux-запуска.
    private const string WindowsOpenFileSkipReason =
        "Тест требует Windows: он проверяет запрет чтения, записи или замены открытого файла. " +
        "В Linux эти ограничения действуют иначе.";

    // Конструктор задаёт статус до запуска тела теста, поэтому Linux не получает ложный зелёный результат.
    public DesignConversionDpoWindowsFileShareFactAttribute()
    {
        // В Windows проверка исполняется; в остальных системах отчёт сохраняет строку с понятной причиной пропуска.
        Skip = OperatingSystem.IsWindows()
            ? null
            : WindowsOpenFileSkipReason;
    }
}

