        => Skip = DesignConversionDpoRuntimeLeafReparseTestSupport.GetCapabilitySkipReason();
}

file sealed class DesignConversionDpoRuntimeLeafReparseTheoryAttribute : TheoryAttribute
{
    public DesignConversionDpoRuntimeLeafReparseTheoryAttribute()
        => Skip = DesignConversionDpoRuntimeLeafReparseTestSupport.GetCapabilitySkipReason();
}

file static class DesignConversionDpoRuntimeLeafReparseTestSupport
{
    private const int HResultPrivilegeNotHeld = unchecked((int)0x80070522);

    public static string? GetCapabilitySkipReason()
    {
        var root = Path.Combine(
            Path.GetTempPath(),
            $"design-conversion-runtime-leaf-capability-{Guid.NewGuid():N}");
        var targetPath = Path.Combine(root, "target.json");
        var linkPath = Path.Combine(root, "link.json");
        try
        {
            Directory.CreateDirectory(root);
            File.WriteAllBytes(targetPath, [1]);
            try
            {
                File.CreateSymbolicLink(linkPath, targetPath);
                return null;
            }
            catch (Exception exception)
                when (exception is IOException or UnauthorizedAccessException
                    && exception.HResult == HResultPrivilegeNotHeld)
            {
                return "REPARSE_TEST_PLATFORM_LIMITATION: " +
                    $"{exception.GetType().FullName}, HResult=0x{exception.HResult:X8}: " +
                    exception.Message;
            }
        }
        finally
        {
            if (File.Exists(linkPath)) File.Delete(linkPath);
            if (Directory.Exists(root)) Directory.Delete(root, recursive: true);
        }
    }
}


