    [Fact]
    public async Task EvaluatedBridge_WrongContinuationRoleFailsBeforeChildPublicationWithoutMutation()
    {
        var root = Path.Combine(
            Path.GetTempPath(),
            $"cycle-lineage-wrong-role-{Guid.NewGuid():N}");
        var partition = BuildEvaluatedPartitionForTests(
            "cycle-lineage-wrong-role",
            heldOutCount: 1);
        SeededModelStateSnapshot[] snapshots = [];
        var provider = new DesignConversionDpoPolicyBaseTestProvider(modelSet =>
        {
            var transformed = modelSet with
            {
                Policy = modelSet.Reference,
                Reference = modelSet.Policy
            };
            snapshots =
            [
                SnapshotSeededModelState(transformed.Policy),
                SnapshotSeededModelState(transformed.Reference),
                SnapshotSeededModelState(transformed.FreshLoadTarget)
            ];
            return OperationResult<DesignConversionDpoPolicyBaseModelSet>.Ok(
                transformed);
        });

        try
        {
            var parent = await PublishEvaluatedLineageCycleAsync(
                root,
                "cycle-lineage-wrong-role-parent",
                partition,
                new DesignConversionDpoPolicyBaseTestProvider());
            var continuation = CreateLineageContinuationRequest(parent);
            var checkpointSource = Assert.IsType<RecordingEvaluatedCheckpointSource>(
                continuation.CheckpointSource);
            var proofSource = Assert.IsType<RecordingEvaluatedCheckpointSource>(
                continuation.BridgeProofCheckpointSource);
            var paths = DesignConversionDpoPromotionArtifactContractCodec.ResolvePaths(
                root,
                Path.Combine(root, "cycle-lineage-wrong-role-child"),
                "cycle-lineage-wrong-role-child");
            Assert.True(paths.IsSuccess, paths.ErrorMessage);

            var failed = await DesignConversionDpoPolicyCheckpointBridge
                .ExecuteEvaluatedAndConvertAsync(
                    CreateEvaluatedLegalTeacherCapability(),
                    partition,
                    paths.Value!.OutputDirectory,
                    "cycle-lineage-wrong-role-child",
                    paths.Value.RuntimeCheckpointPath,
                    provider,
                    new DesignConversionDpoPolicyCheckpointBridgeOptions(1, 1),
                    continuation,
                    ct: CancellationToken.None);

            Assert.False(failed.IsSuccess);
            Assert.Equal(
                "DESIGN_CONVERSION_DPO_POLICY_LORA_APPLICATION_FAILED",
                failed.ErrorCode);
            Assert.Equal(0, provider.InvocationCount);
            Assert.Equal(1, provider.ContinuationInvocationCount);
            Assert.Equal(1, proofSource.OpenCount);
            Assert.Equal(1, checkpointSource.OpenCount);
            Assert.False(Directory.Exists(paths.Value.OutputDirectory));
            Assert.False(File.Exists(paths.Value.RuntimeCheckpointPath));
            Assert.Equal(3, snapshots.Length);
            foreach (var snapshot in snapshots)
                AssertSeededModelStateUnchanged(snapshot);
        }
        finally
        {
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }


