    [Theory]
    [InlineData("fork-relinked")]
    [InlineData("duplicate-phase")]
    [InlineData("out-of-order-phase")]
    [InlineData("output-reservation-ref-out-of-root")]
    public async Task LocalArtifactDb_CoherentlyRehashedOperationStructureForgeryFailsClosed(
        string mutation)
    {
        var caseId = mutation switch
        {
            "fork-relinked" => "fork",
            "duplicate-phase" => "duplicate",
            "out-of-order-phase" => "order",
            "output-reservation-ref-out-of-root" => "out-root",
            _ => throw new ArgumentOutOfRangeException(nameof(mutation), mutation, null)
        };
        var root = DesignConversionPostEvaluationEligibilityTestFixture
            .CreateHandleBoundTempRoot($"operation-structure-forgery-{caseId}");
        var siblingRoot = root + "-sibling";
        try
        {
            var fixture = await BuildW085DeterministicPromotionReadyIntakeFixtureAsync(
                root,
                $"operation-structure-forgery-{caseId}");
            var admission = BuildLocalPromotionAdmission(
                $"operation-structure-forgery-{caseId}");
            var provider = CreateW085DeterministicPromotionProvider();
            var uploader = new CountingLocalOnlyPromotionUploader();
            var runnerCount = 0;
            var promoted = await RunLocalPromotionWithAdmissionAsync(
                new JsonlDesignConversionLocalArtifactDb(
                    root,
                    createTrainingIntakeJournalWaitTaskObserverForTesting: null,
                    createTrainingIntakeJournalGateAcquiredCallbackForTesting: null,
                    promotionUploader: uploader,
                    runTrainingIntakeLocalPromotionRunnerBeforeInvokeObserverForTesting:
                        () => Interlocked.Increment(ref runnerCount),
                    dpoPolicyBaseProvider: provider,
                    legalTeacherAdmissionAuthority:
                        CreateEvaluatedLegalTeacherCapability(),
                    localReceiptOnlyPromotionAuthority:
                        uploader.Authority),
                fixture,
                Path.Combine(root, "output"),
                admission);
            Assert.True(promoted.IsSuccess, promoted.ErrorMessage);
            var before = (runnerCount, provider.InvocationCount, uploader.Count);
            var journalPath = Path.Combine(
                root,
                JsonlDesignConversionLocalArtifactDb
                    .TrainingIntakeLocalPromotionOperationFileName);
            var records = (await ReadLocalPromotionOperationRecordsAsync(
                    journalPath))
                .ToList();
            Assert.Equal(4, records.Count);
            Assert.Equal(
                [0, 1, 2, 3],
                records.Select(record => (int)record.Phase).ToArray());
            if (string.Equals(mutation, "fork-relinked", StringComparison.Ordinal))
            {
                records[^1] = records[^1] with
                {
                    PreviousRecordSha256 = records[1].RecordSha256,
                    RecordSha256 = string.Empty
                };
                records[^1] = records[^1] with
                {
                    RecordSha256 = JsonlDesignConversionLocalArtifactDb
                        .BuildLocalPromotionOperationRecordSha256(records[^1])
                };
            }
            else if (string.Equals(
                         mutation,
                         "duplicate-phase",
                         StringComparison.Ordinal))
            {
                records.Insert(3, records[2] with
                {
                    PreviousRecordSha256 = string.Empty,
                    RecordSha256 = string.Empty
                });
                records = RelinkLocalPromotionOperationRecords(records).ToList();
            }
            else if (string.Equals(
                         mutation,
                         "out-of-order-phase",
                         StringComparison.Ordinal))
            {
                (records[1], records[2]) = (records[2], records[1]);
                records = RelinkLocalPromotionOperationRecords(records).ToList();
            }
            else
            {
                Directory.CreateDirectory(siblingRoot);
                var originalRef = records[0].OutputNamespaceReservationRef;
                var siblingRef = Path.Combine(
                    siblingRoot,
                    Path.GetFileName(originalRef));
                await File.WriteAllBytesAsync(
                    siblingRef,
                    await File.ReadAllBytesAsync(originalRef));
                for (var index = 0; index < records.Count; index++)
                {
                    records[index] = records[index] with
                    {
                        OutputNamespaceReservationRef = siblingRef
                    };
                }
                var preparedIndex = records.FindIndex(record =>
                    record.Phase == JsonlDesignConversionLocalArtifactDb
                        .LocalPromotionOperationPhase.Prepared);
                var prepared = records[preparedIndex];
                var metadata = new Dictionary<string, string>(
                    prepared.FinalResult!.BoundaryMetadata,
                    StringComparer.Ordinal)
                {
                    ["local_promotion_output_namespace_reservation_ref"] =
                        siblingRef
                };
                var finalResult = prepared.FinalResult with
                {
                    BoundaryMetadata = metadata
                };
                var finalSha = JsonlDesignConversionLocalArtifactDb
                    .BuildLocalPromotionFinalResultSha256(finalResult);
                metadata["local_promotion_committed_snapshot_sha256"] = finalSha;
                finalResult = finalResult with { BoundaryMetadata = metadata };
                records[preparedIndex] = prepared with
                {
                    OutputNamespaceReservationRef = siblingRef,
                    FinalResult = finalResult,
                    FinalResultSha256 = finalSha
                };
                var committedIndex = records.FindIndex(record =>
                    record.Phase == JsonlDesignConversionLocalArtifactDb
                        .LocalPromotionOperationPhase.Committed);
                records[committedIndex] = records[committedIndex] with
                {
                    OutputNamespaceReservationRef = siblingRef,
                    FinalResultSha256 = finalSha
                };
                records = RelinkLocalPromotionOperationRecords(records).ToList();
            }
            await WriteLocalPromotionOperationRecordsAsync(
                journalPath,
                records);

            var retry = await RunLocalPromotionWithAdmissionAsync(
                new JsonlDesignConversionLocalArtifactDb(
                    root,
                    createTrainingIntakeJournalWaitTaskObserverForTesting: null,
                    createTrainingIntakeJournalGateAcquiredCallbackForTesting: null,
                    promotionUploader: uploader,
                    runTrainingIntakeLocalPromotionRunnerBeforeInvokeObserverForTesting:
                        () => Interlocked.Increment(ref runnerCount),
                    dpoPolicyBaseProvider: provider,
                    legalTeacherAdmissionAuthority:
                        CreateEvaluatedLegalTeacherCapability(),
                    localReceiptOnlyPromotionAuthority: uploader.Authority),
                fixture,
                Path.Combine(root, "output"),
                admission);
            Assert.False(retry.IsSuccess);
            Assert.Equal(
                "DESIGN_CONVERSION_TRAINING_INTAKE_PROMOTE_LOCAL_OPERATION_STATE_INVALID",
                retry.ErrorCode);
            Assert.Equal(before, (
                runnerCount,
                provider.InvocationCount,
                uploader.Count));
        }
        finally
        {
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
            if (Directory.Exists(siblingRoot))
                Directory.Delete(siblingRoot, recursive: true);
        }
    }


