            var pairStore = new FileDpoPairStore(pairRoot);
            var provider = new DesignConversionDpoPolicyBaseTestProvider();
            var uploader = new CountingLocalOnlyPromotionUploader();
            var runnerCount = 0;
            var activationCount = 0;
            var db = new JsonlDesignConversionLocalArtifactDb(
                root,
                createTrainingIntakeJournalWaitTaskObserverForTesting: null,
                createTrainingIntakeJournalGateAcquiredCallbackForTesting: null,
                promotionUploader: uploader,
                runTrainingIntakeLocalPromotionRunnerBeforeInvokeObserverForTesting:
                    () => Interlocked.Increment(ref runnerCount),
                runTrainingIntakeLocalPromotionActivationInvokedObserverForTesting:
                    () => Interlocked.Increment(ref activationCount),
                dpoPolicyBaseProvider: provider,
                legalTeacherAdmissionAuthority: CreateEvaluatedLegalTeacherCapability(),
                trainingIntakeDpoPairStoreForTesting: pairStore,
                localReceiptOnlyPromotionAuthority: uploader.Authority);
            var promoted = await RunLocalPromotionWithAdmissionAsync(
                db,
                fixture,
                output,
                admission);
            Assert.True(promoted.IsSuccess, promoted.ErrorMessage);
            var countsBeforeTamper = (
                Runner: runnerCount,
                Provider: provider.InvocationCount,
                Uploader: uploader.Count,
                Activation: activationCount);
            var pairStoreSnapshotBeforeTamper =
                await ReadFileSha256SnapshotAsync(pairRoot);

            if (string.Equals(tamperTarget, "artifact", StringComparison.Ordinal))
            {
                await File.AppendAllTextAsync(
                    promoted.Value!.PromotedCheckpointPath,
                    "\nTAMPERED_COMMITTED_PROMOTION_ARTIFACT");
            }
            else if (string.Equals(
                         tamperTarget,
                         "operation-journal",
                         StringComparison.Ordinal))
            {
                var journal = await File.ReadAllTextAsync(operationPath);
                Assert.Contains(fixture.Options.RunId, journal, StringComparison.Ordinal);
                await File.WriteAllTextAsync(
                    operationPath,
                    journal.Replace(
                        fixture.Options.RunId,
                        fixture.Options.RunId + "-tampered",
                        StringComparison.Ordinal));
            }
            else if (string.Equals(
                         tamperTarget,
                         "operation-journal-frame",
                         StringComparison.Ordinal))
            {
                var bytes = await File.ReadAllBytesAsync(operationPath);
                Assert.True(bytes.Length > Environment.NewLine.Length);
                await File.WriteAllBytesAsync(
                    operationPath,
                    bytes[..^Environment.NewLine.Length]);
            }
            else if (string.Equals(
                         tamperTarget,
                         "operation-journal-truncated-json",
                         StringComparison.Ordinal))
            {
                var lines = await File.ReadAllLinesAsync(operationPath);
                Assert.NotEmpty(lines);
                Assert.True(lines[^1].Length > 16);
                lines[^1] = lines[^1][..^16];
                await File.WriteAllTextAsync(
                    operationPath,
                    string.Join(Environment.NewLine, lines) +
                    Environment.NewLine);
            }
            else
            {
                var marker = promoted.Value!.BoundaryMetadata[
                    "local_promotion_output_namespace_reservation_ref"];
                if (string.Equals(
                        tamperTarget,
                        "reservation-marker-missing",
                        StringComparison.Ordinal))
                {
                    File.Delete(marker);
                }
                else
                {
                    if (string.Equals(
                            tamperTarget,
                            "reservation-marker-extra-property",
                            StringComparison.Ordinal))
                    {
                        var node = JsonNode.Parse(
                            await File.ReadAllTextAsync(marker))!.AsObject();
                        node["ignoredExtraProperty"] = true;
                        await File.WriteAllTextAsync(
                            marker,
                            node.ToJsonString());
                    }
                    else
                    {
                        await File.WriteAllTextAsync(
                            marker,
                            "{\"forged\":true}");
                    }
                }
            }

            var retry = await RunLocalPromotionWithAdmissionAsync(
                new JsonlDesignConversionLocalArtifactDb(
                    root,
                    createTrainingIntakeJournalWaitTaskObserverForTesting: null,
                    createTrainingIntakeJournalGateAcquiredCallbackForTesting: null,
                    promotionUploader: uploader,
                    runTrainingIntakeLocalPromotionRunnerBeforeInvokeObserverForTesting:
                        () => Interlocked.Increment(ref runnerCount),
                    runTrainingIntakeLocalPromotionActivationInvokedObserverForTesting:
                        () => Interlocked.Increment(ref activationCount),
                    dpoPolicyBaseProvider: provider,
                    legalTeacherAdmissionAuthority: CreateEvaluatedLegalTeacherCapability(),
                    trainingIntakeDpoPairStoreForTesting:
                        new FileDpoPairStore(pairRoot),
                    localReceiptOnlyPromotionAuthority: uploader.Authority),
                fixture,
                output,
                admission);

            Assert.False(retry.IsSuccess);
            Assert.Equal(
                "DESIGN_CONVERSION_TRAINING_INTAKE_PROMOTE_LOCAL_OPERATION_STATE_INVALID",
                retry.ErrorCode);
            Assert.Equal(countsBeforeTamper.Runner, runnerCount);
            Assert.Equal(countsBeforeTamper.Provider, provider.InvocationCount);
            Assert.Equal(countsBeforeTamper.Uploader, uploader.Count);
            Assert.Equal(countsBeforeTamper.Activation, activationCount);
            Assert.Equal(
                pairStoreSnapshotBeforeTamper,
                await ReadFileSha256SnapshotAsync(pairRoot));
        }
        finally
        {
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }


