    [Theory]
    [InlineData("omitted-artifact")]
    [InlineData("out-of-root-artifact")]
    public async Task LocalArtifactDb_MissingCommittedOutputStillRejectsRehashedPreparedDescriptorForgery(
        string mutation)
    {
        var root = Path.Combine(
            Path.GetTempPath(),
            Guid.NewGuid().ToString("N"),
            $"missing-committed-output-rehashed-forgery-{mutation}");
        var output = Path.Combine(root, "promotion-output");
        var siblingRoot = root + "-sibling";
        try
        {
            var fixture = await BuildPromotionReadyIntakeFixtureAsync(
                root,
                $"missing-committed-output-rehashed-forgery-{mutation}");
            var admission = BuildLocalPromotionAdmission(
                $"missing-committed-output-rehashed-forgery-{mutation}");
            var pairRoot = Path.Combine(
                root,
                JsonlDesignConversionLocalArtifactDb
                    .TrainingIntakeDpoPairStoreDirectoryName);
            var provider = new DesignConversionDpoPolicyBaseTestProvider();
            var uploader = new CountingLocalOnlyPromotionUploader();
            var runnerCount = 0;
            var activationCount = 0;
            var promoted = await RunLocalPromotionWithAdmissionAsync(
                new JsonlDesignConversionLocalArtifactDb(
                    root,
                    createTrainingIntakeJournalWaitTaskObserverForTesting: null,
                    createTrainingIntakeJournalGateAcquiredCallbackForTesting: null,
                    promotionUploader: uploader,
                    runTrainingIntakeLocalPromotionRunnerBeforeInvokeObserverForTesting:
                        () => Interlocked.Increment(ref runnerCount),
                    runTrainingIntakeLocalPromotionActivationInvokedObserverForTesting:
                        () => Interlocked.Increment(ref activationCount),
                    dpoPolicyBaseProvider: provider,
                    legalTeacherAdmissionAuthority:
                        CreateEvaluatedLegalTeacherCapability(),
                    trainingIntakeDpoPairStoreForTesting:
                        new FileDpoPairStore(pairRoot),
                    localReceiptOnlyPromotionAuthority: uploader.Authority),
                fixture,
                output,
                admission);
            Assert.True(promoted.IsSuccess, promoted.ErrorMessage);
            var countsBeforeForgery = (
                Runner: runnerCount,
                Provider: provider.InvocationCount,
                Uploader: uploader.Count,
                Activation: activationCount);
            var pairStoreSnapshotBeforeForgery =
                await ReadFileSha256SnapshotAsync(pairRoot);
            var journalPath = Path.Combine(
                root,
                JsonlDesignConversionLocalArtifactDb
                    .TrainingIntakeLocalPromotionOperationFileName);
            var records = (await ReadLocalPromotionOperationRecordsAsync(
                    journalPath))
                .ToArray();
            var preparedIndex = Array.FindIndex(
                records,
                record => record.Phase ==
                    JsonlDesignConversionLocalArtifactDb
                        .LocalPromotionOperationPhase.Prepared);
            Assert.True(preparedIndex >= 0);
            var prepared = records[preparedIndex];
            Assert.NotEmpty(prepared.ArtifactDescriptors);
            var descriptors = prepared.ArtifactDescriptors.ToArray();
            if (string.Equals(
                    mutation,
                    "omitted-artifact",
                    StringComparison.Ordinal))
            {
                descriptors = descriptors.Skip(1).ToArray();
            }
            else
            {
                Directory.CreateDirectory(siblingRoot);
                descriptors[0] = descriptors[0] with
                {
                    CanonicalPath = Path.Combine(
                        siblingRoot,
                        Path.GetFileName(descriptors[0].CanonicalPath))
                };
            }
            records[preparedIndex] = prepared with
            {
                ArtifactDescriptors = descriptors
            };
            records = RelinkLocalPromotionOperationRecords(records).ToArray();
            await WriteLocalPromotionOperationRecordsAsync(
                journalPath,
                records);
            Directory.Delete(output, recursive: true);

            var replay = await RunLocalPromotionWithAdmissionAsync(
                new JsonlDesignConversionLocalArtifactDb(
                    root,
                    createTrainingIntakeJournalWaitTaskObserverForTesting: null,
                    createTrainingIntakeJournalGateAcquiredCallbackForTesting: null,
                    promotionUploader: uploader,
                    runTrainingIntakeLocalPromotionRunnerBeforeInvokeObserverForTesting:
                        () => Interlocked.Increment(ref runnerCount),
                    runTrainingIntakeLocalPromotionActivationInvokedObserverForTesting:
                        () => Interlocked.Increment(ref activationCount),
                    dpoPolicyBaseProvider: provider,
                    legalTeacherAdmissionAuthority:
                        CreateEvaluatedLegalTeacherCapability(),
                    trainingIntakeDpoPairStoreForTesting:
                        new FileDpoPairStore(pairRoot),
                    localReceiptOnlyPromotionAuthority: uploader.Authority),
                fixture,
                output,
                admission);

            Assert.False(replay.IsSuccess);
            Assert.Equal(
                "DESIGN_CONVERSION_TRAINING_INTAKE_PROMOTE_LOCAL_OPERATION_STATE_INVALID",
                replay.ErrorCode);
            Assert.Equal(countsBeforeForgery, (
                runnerCount,
                provider.InvocationCount,
                uploader.Count,
                activationCount));
            Assert.Equal(
                pairStoreSnapshotBeforeForgery,
                await ReadFileSha256SnapshotAsync(pairRoot));
            Assert.False(Directory.Exists(output));
        }
        finally
        {
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
            if (Directory.Exists(siblingRoot))
                Directory.Delete(siblingRoot, recursive: true);
        }
    }

    [Fact]
    public void HandleBoundDirectory_WindowsAcceptsLegalMultibyteLeafAcrossCreateEnumerateAndRead()
    {
        if (!OperatingSystem.IsWindows())
            return;

        var root = Path.Combine(
            Path.GetTempPath(),
            Guid.NewGuid().ToString("N"),
            "windows-handle-bound-multibyte");
        var leafName = new string('\u754c', 86);
        const string lockLeaf = "mutation.lock";
        var expectedBytes = Encoding.UTF8.GetBytes("допустимое имя Windows");
        try
        {
            Assert.Equal(258, Encoding.UTF8.GetByteCount(leafName));
            using var directory =
                DesignConversionHandleBoundDirectory.AcquireOrCreate(
                    root,
                    beforeIo: null);
            DesignConversionFileIdentity createdIdentity;
            using (var created = directory.CreateNew(
                       leafName,
                       FileShare.None,
                       writeThrough: true))
            {
                created.Write(expectedBytes);
                created.Flush(flushToDisk: true);
                createdIdentity = directory.GetIdentity(created, leafName);
            }

            using var mutationLease = directory.OpenOrCreate(
                lockLeaf,
                FileShare.None,
                writeThrough: true);
            var entries = directory.EnumerateEntries(
                maximumEntryCount: 8,
                heldLeafName: lockLeaf,
                heldStream: mutationLease);
            Assert.Contains(entries, entry =>
                string.Equals(entry.Name, leafName, StringComparison.Ordinal) &&
                entry.Identity == createdIdentity &&
                entry.Length == expectedBytes.Length);

            using var read = directory.TryOpenExistingReadOnly(leafName);
            Assert.NotNull(read);
            var observedBytes = new byte[expectedBytes.Length];
            read!.ReadExactly(observedBytes);
            Assert.Equal(expectedBytes, observedBytes);
        }
        finally
        {
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }

    [Fact]
    public void HandleBoundDirectory_LinuxRejectsLeafBeyondUtf8NameLimit()
    {
        if (!OperatingSystem.IsLinux())
            return;

        var root = Path.Combine(
            Path.GetTempPath(),
            Guid.NewGuid().ToString("N"),
            "linux-handle-bound-multibyte-limit");
        var leafName = new string('\u754c', 86);
        try
        {
            Assert.Equal(258, Encoding.UTF8.GetByteCount(leafName));
            using var directory =
                DesignConversionHandleBoundDirectory.AcquireOrCreate(
                    root,
                    beforeIo: null);

            // Linux отклоняет слишком длинное имя до системного вызова: это
            // ошибка входного имени, а не признак повреждения сохранённого
            // состояния хранилища.
            var failure = Assert.Throws<ArgumentException>(
                () => directory.CreateNew(
                    leafName,
                    FileShare.None,
                    writeThrough: true));

            Assert.Contains("255-byte UTF-8", failure.Message, StringComparison.Ordinal);
            Assert.Empty(Directory.EnumerateFileSystemEntries(root));
        }
        finally
        {
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }

    [Fact]
    public void HandleBoundDirectory_LinuxCreateReadListLockAndDeleteStayRootRelative()
    {
        if (!OperatingSystem.IsLinux())
            return;

        var root = Path.Combine(
            Path.GetTempPath(),
            Guid.NewGuid().ToString("N"),
            "linux-handle-bound-positive");
        const string stateLeaf = "state.json";
        const string lockLeaf = "mutation.lock";
        var stateBytes = Encoding.UTF8.GetBytes("{\"linux\":true}");
        try
        {
            using var directory =
                DesignConversionHandleBoundDirectory.AcquireOrCreate(
                    root,
                    beforeIo: null);
            DesignConversionFileIdentity stateIdentity;
            using (var state = directory.CreateNew(
                       stateLeaf,
                       FileShare.None,
                       writeThrough: true))
            {
                state.Write(stateBytes);
                state.Flush(flushToDisk: true);
                stateIdentity = directory.GetIdentity(state, stateLeaf);
                Assert.Equal(1u, directory.GetLinkCount(state, stateLeaf));
            }

            using (var read = directory.TryOpenExistingReadOnly(stateLeaf))
            {
                Assert.NotNull(read);
                var observed = new byte[stateBytes.Length];
                read!.ReadExactly(observed);
                Assert.Equal(stateBytes, observed);
            }

            using var mutationLease = directory.OpenOrCreate(
                lockLeaf,
                FileShare.None,
                writeThrough: true);
            using var contender =
                DesignConversionHandleBoundDirectory.AcquireExisting(
                    root,
                    beforeIo: null);
            Assert.Throws<DesignConversionHandleBoundSharingViolationException>(
                () => contender.OpenOrCreate(
                    lockLeaf,
                    FileShare.None,
                    writeThrough: true));

            var entries = directory.EnumerateEntries(
                maximumEntryCount: 8,
                heldLeafName: lockLeaf,
                heldStream: mutationLease);
            Assert.Contains(entries, entry =>
                string.Equals(entry.Name, stateLeaf, StringComparison.Ordinal) &&
                entry.Identity == stateIdentity &&
                entry.Length == stateBytes.Length);

            Assert.Equal(
                DesignConversionHandleBoundDeleteDisposition.DurableDelete,
                directory.DeleteIfRegular(stateLeaf, stateIdentity));
            Assert.False(directory.ContainsNameNoFollow(
                maximumEntryCount: 8,
                stateLeaf));
        }
        finally
        {
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }

    [Fact]
    public void HandleBoundDirectory_LinuxPinnedRootSurvivesPathSwap()
    {
        if (!OperatingSystem.IsLinux())
            return;

        var parent = Path.Combine(
            Path.GetTempPath(),
            Guid.NewGuid().ToString("N"));
        var root = Path.Combine(parent, "root");
        var displacedRoot = Path.Combine(parent, "root-original");
        const string leaf = "state.json";
        var originalBytes = Encoding.UTF8.GetBytes("original-root");
        var swappedBytes = Encoding.UTF8.GetBytes("swapped-root");
        try
        {
            Directory.CreateDirectory(root);
            File.WriteAllBytes(Path.Combine(root, leaf), originalBytes);
            using var directory =
                DesignConversionHandleBoundDirectory.AcquireExisting(
                    root,
                    beforeIo: null);

            Directory.Move(root, displacedRoot);
            Directory.CreateDirectory(root);
            File.WriteAllBytes(Path.Combine(root, leaf), swappedBytes);

            using var stream = directory.TryOpenExistingReadOnly(leaf);
            Assert.NotNull(stream);
            var observed = new byte[originalBytes.Length];
            stream!.ReadExactly(observed);
            Assert.Equal(originalBytes, observed);
            Assert.Equal(swappedBytes, File.ReadAllBytes(Path.Combine(root, leaf)));
        }
        finally
        {
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
            if (Directory.Exists(displacedRoot))
                Directory.Delete(displacedRoot, recursive: true);
            if (Directory.Exists(parent))
                Directory.Delete(parent, recursive: true);
        }
    }

