    [Fact]
    public async Task HandleBoundDirectory_LinuxAtomicPublicationCreatesDestinationFromTemp()
    {
        if (!OperatingSystem.IsLinux())
            return;

        var root = Path.Combine(
            Path.GetTempPath(),
            Guid.NewGuid().ToString("N"),
            "linux-handle-bound-publish",
            "post-evaluation-finalization");
        const string stateRef =
            "dcm-post-evaluation-state-ffa23b98456cf81526c589324e38ee7583e7edbfc7c2155c0a18b92d3e897b82";
        var destinationLeaf = stateRef + ".json";
        var tempLeaf = $"{destinationLeaf}.{Guid.NewGuid():N}.write.tmp";
        const string lockLeaf =
            JsonDesignConversionPostEvaluationStateStore.MutationLockFileName;
        var bytes = Encoding.UTF8.GetBytes("{\"published\":true}");
        try
        {
            using var directory =
                DesignConversionHandleBoundDirectory.AcquireOrCreate(
                    root,
                    beforeIo: null);
            using var mutationLease = directory.OpenOrCreate(
                lockLeaf,
                FileShare.None,
                writeThrough: true);
            using var temp = directory.CreateNew(
                tempLeaf,
                FileShare.None,
                writeThrough: true);
            await temp.WriteAsync(bytes);
            await temp.FlushAsync();
            temp.Flush(flushToDisk: true);

            var entriesBeforePublication = directory.EnumerateEntries(
                maximumEntryCount: 4,
                heldLeafName: lockLeaf,
                heldStream: mutationLease,
                secondHeldLeafName: tempLeaf,
                secondHeldStream: temp);
            var tempEntry = Assert.Single(entriesBeforePublication, entry =>
                string.Equals(entry.Name, tempLeaf, StringComparison.Ordinal));
            Assert.Equal(bytes.Length, tempEntry.Length);

            directory.AtomicReplaceAndFlush(
                temp,
                tempLeaf,
                destinationLeaf,
                maximumRollbackBytes: 1024);

            temp.Dispose();
            Assert.False(File.Exists(Path.Combine(root, tempLeaf)));
            Assert.Equal(bytes, File.ReadAllBytes(Path.Combine(root, destinationLeaf)));
        }
        finally
        {
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }

    [Fact]
    public void HandleBoundDirectory_LinuxAtomicPublicationDoesNotOverwriteExternalDestination()
    {
        if (!OperatingSystem.IsLinux())
            return;

        var root = Path.Combine(
            Path.GetTempPath(),
            Guid.NewGuid().ToString("N"),
            "linux-handle-bound-no-overwrite");
        const string tempLeaf = "state.tmp";
        const string destinationLeaf = "state.json";
        var ours = Encoding.UTF8.GetBytes("{\"ours\":true}");
        var foreign = Encoding.UTF8.GetBytes("{\"foreign\":true}");
        try
        {
            Directory.CreateDirectory(root);
            using var directory =
                DesignConversionHandleBoundDirectory.AcquireExisting(
                    root,
                    beforeIo: null);
            using var temp = directory.CreateNew(
                tempLeaf,
                FileShare.None,
                writeThrough: true);
            temp.Write(ours);
            temp.Flush(flushToDisk: true);
            File.WriteAllBytes(Path.Combine(root, destinationLeaf), foreign);

            Assert.Throws<DesignConversionHandleBoundTrustException>(
                () => directory.AtomicReplaceAndFlush(
                    temp,
                    tempLeaf,
                    destinationLeaf,
                    maximumRollbackBytes: 1024,
                    DesignConversionHandleBoundDestinationExpectation.Absent));

            Assert.Equal(foreign, File.ReadAllBytes(Path.Combine(root, destinationLeaf)));
            Assert.True(File.Exists(Path.Combine(root, tempLeaf)));
        }
        finally
        {
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }

    [Fact]
    public void HandleBoundDirectory_LinuxPublicationRacePreservesOldStateBackupAndForeignDestination()
    {
        if (!OperatingSystem.IsLinux())
