            Guid.NewGuid().ToString("N"),
            "linux-handle-bound-race-preserves-backup");
        const string tempLeaf = "state.tmp";
        const string destinationLeaf = "state.json";
        var activePath = Path.Combine(root, destinationLeaf);
        var backupPath = activePath +
            DesignConversionHandleBoundDirectory.PublicationBackupSuffix;
        var stagedForeignPath = Path.Combine(root, "foreign-stage.json");
        var oldBytes = Encoding.UTF8.GetBytes("{\"old\":true}");
        var newBytes = Encoding.UTF8.GetBytes("{\"new\":true}");
        var foreignBytes = Encoding.UTF8.GetBytes("{\"foreign\":true}");
        var injectedForeign = false;
        try
        {
            Directory.CreateDirectory(root);
            File.WriteAllBytes(activePath, oldBytes);

            DesignConversionFileIdentity oldIdentity;
            using (var identityDirectory =
                   DesignConversionHandleBoundDirectory.AcquireExisting(
                       root,
                       beforeIo: null))
            using (var oldStream = identityDirectory.TryOpenExisting(
                       destinationLeaf,
                       FileShare.Read,
                       writeThrough: false))
            {
                Assert.NotNull(oldStream);
                oldIdentity = identityDirectory.GetIdentity(
                    oldStream!,
                    destinationLeaf);
            }
            var expectedOldHash = "sha256:" + Convert.ToHexString(
                    System.Security.Cryptography.SHA256.HashData(oldBytes))
                .ToLowerInvariant();

            using var directory =
                DesignConversionHandleBoundDirectory.AcquireExisting(
                    root,
                    (stage, _) =>
                    {
                        if (stage != DesignConversionHandleBoundIoStage.BeforeAtomicRename ||
                            injectedForeign)
                        {
                            return;
                        }

                        injectedForeign = true;
                        // На Linux advisory lock не останавливает чужой rename.
                        // Поэтому тест доказывает обнаружение гонки и сохранение
                        // старого trusted-файла в backup, а не невозможную блокировку.
                        Assert.False(File.Exists(activePath));
                        Assert.Equal(oldBytes, File.ReadAllBytes(backupPath));
                        File.WriteAllBytes(stagedForeignPath, foreignBytes);
                        File.Move(stagedForeignPath, activePath);
                    });
            using var temp = directory.CreateNew(
                tempLeaf,
                FileShare.None,
                writeThrough: true);
            temp.Write(newBytes);
            temp.Flush(flushToDisk: true);

            var failure = Assert.Throws<DesignConversionHandleBoundTrustException>(
                () => directory.AtomicReplaceAndFlush(
                    temp,
                    tempLeaf,
                    destinationLeaf,
                    maximumRollbackBytes: 1024,
                    DesignConversionHandleBoundDestinationExpectation.Exact(
                        oldIdentity,
                        oldBytes.Length,
                        expectedOldHash)));

            Assert.True(injectedForeign);
            Assert.Contains("preserved in backup", failure.Message);
            Assert.Equal(foreignBytes, File.ReadAllBytes(activePath));
            Assert.Equal(oldBytes, File.ReadAllBytes(backupPath));
            Assert.False(File.Exists(Path.Combine(root, tempLeaf)));
            Assert.False(File.Exists(stagedForeignPath));
        }
        finally
        {
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }

    [Fact]
    public void HandleBoundDirectory_LinuxEnumerationCanRepeatFromStart()
    {
        if (!OperatingSystem.IsLinux())
            return;

        var root = Path.Combine(
            Path.GetTempPath(),
            Guid.NewGuid().ToString("N"),
            "linux-handle-bound-repeat-enumeration");
