            File.WriteAllText(Path.Combine(root, "b.json"), "b");
            using var directory =
                DesignConversionHandleBoundDirectory.AcquireExisting(
                    root,
                    beforeIo: null);
            using var mutationLease = directory.OpenOrCreate(
                lockLeaf,
                FileShare.None,
