        {
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }

    [Fact]
    public async Task PostEvaluationStateStore_LinuxWriterRaceKeepsBackupAndForeignDestination()
    {
        if (!OperatingSystem.IsLinux())
            return;

        var root = Path.Combine(
            Path.GetTempPath(),
            Guid.NewGuid().ToString("N"),
            "linux-post-evaluation-writer-race");
        var state = BuildNoReservationPostEvaluationState("linux-writer-race");
        var stateLeaf = state.StateRef + ".json";
        var activePath = Path.Combine(root, stateLeaf);
        var backupPath = activePath +
            DesignConversionHandleBoundDirectory.PublicationBackupSuffix;
        var stagedForeignPath = Path.Combine(root, "foreign-stage.json");
        var foreignBytes = Encoding.UTF8.GetBytes("{\"foreign\":true}");
        var armRace = false;
        var injectedForeign = false;
        var options = DesignConversionPostEvaluationStateStoreOptions.Default with
        {
            BeforeHandleIoForTesting = (stage, _) =>
            {
                if (!armRace ||
                    injectedForeign ||
                    stage != DesignConversionHandleBoundIoStage.BeforeAtomicRename)
                {
                    return;
                }

                injectedForeign = true;
                // Writer-level proof: the Linux backend has already moved the
                // verified old state into backup before any uncooperative
                // process gets a chance to occupy the destination name.
                Assert.False(File.Exists(activePath));
                Assert.True(File.Exists(backupPath));
                File.WriteAllBytes(stagedForeignPath, foreignBytes);
                File.Move(stagedForeignPath, activePath);
            }
        };
        var store = new JsonDesignConversionPostEvaluationStateStore(
            root,
            options);
        try
        {
            var first = await store.WriteAsync(state, CancellationToken.None);
            Assert.True(first.IsSuccess, first.ErrorMessage);
            var oldBytes = await File.ReadAllBytesAsync(activePath);

            armRace = true;
            var second = await store.WriteAsync(
                state with
                {
                    UpdatedAtUtc = state.UpdatedAtUtc.AddSeconds(1),
                    Version = first.Value!.Version
                },
                CancellationToken.None);

            Assert.False(second.IsSuccess);
            Assert.Equal(
                JsonDesignConversionPostEvaluationStateStore.TrustBoundaryErrorCode,
                second.ErrorCode);
            Assert.Contains("preserved in backup", second.ErrorMessage);
            Assert.True(injectedForeign);
            Assert.Equal(foreignBytes, await File.ReadAllBytesAsync(activePath));
            Assert.Equal(oldBytes, await File.ReadAllBytesAsync(backupPath));
            Assert.Empty(Directory.EnumerateFiles(root, "*.write.tmp"));
            Assert.False(File.Exists(stagedForeignPath));
        }
        finally
        {
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }

    [Fact]
    public async Task PostEvaluationStateStore_LinuxOrphanBackupRequiresManualReconciliation()
    {
        if (!OperatingSystem.IsLinux())
            return;

        var root = Path.Combine(
            Path.GetTempPath(),
            Guid.NewGuid().ToString("N"),
            "linux-post-evaluation-backup-recovery");
        var state = BuildNoReservationPostEvaluationState("linux-backup-recovery");
        var stateLeaf = state.StateRef + ".json";
        var activePath = Path.Combine(root, stateLeaf);
        var backupLeaf = stateLeaf +
            DesignConversionHandleBoundDirectory.PublicationBackupSuffix;
        var backupPath = Path.Combine(root, backupLeaf);
        var initialStore = new JsonDesignConversionPostEvaluationStateStore(root);
        try
        {
            var written = await initialStore.WriteAsync(state, CancellationToken.None);
            Assert.True(written.IsSuccess, written.ErrorMessage);
            var oldBytes = await File.ReadAllBytesAsync(activePath);
            File.Move(activePath, backupPath);
            // Удерживаем настоящий файл открытым: после отказа проверяем не
            // только имя, но и то, что тот же inode и те же байты сохранились.
            using var directory =
                DesignConversionHandleBoundDirectory.AcquireExisting(
                    root,
                    beforeIo: null);
            using var heldBackup = directory.TryOpenExistingReadOnly(backupLeaf);
            Assert.NotNull(heldBackup);
            var backupIdentity = directory.GetIdentity(heldBackup!, backupLeaf);

            // Новый экземпляр изображает перезапуск: у него нет удержанного
            // дескриптора или другого свидетеля исходной транзакции.
            var restartedStore = new JsonDesignConversionPostEvaluationStateStore(root);
            var rejected = await restartedStore.ListAsync(CancellationToken.None);

            Assert.False(rejected.IsSuccess);
            Assert.Equal(
                JsonDesignConversionPostEvaluationStateStore.TrustBoundaryErrorCode,
                rejected.ErrorCode);
            Assert.Contains(
                "manual reconciliation",
                rejected.ErrorMessage,
                StringComparison.OrdinalIgnoreCase);
            Assert.False(File.Exists(activePath));
            Assert.True(File.Exists(backupPath));
            Assert.Equal(backupIdentity, directory.GetIdentity(heldBackup!, backupLeaf));
            heldBackup!.Position = 0;
            var bytesThroughHeldHandle = new byte[oldBytes.Length];
            heldBackup.ReadExactly(bytesThroughHeldHandle);
            Assert.Equal(oldBytes, bytesThroughHeldHandle);
            Assert.Equal(oldBytes, await File.ReadAllBytesAsync(backupPath));
        }
        finally
        {
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }

    private static DesignConversionPostEvaluationState
        BuildNoReservationPostEvaluationState(string idempotencySource)
    {
        var stateRef = JsonDesignConversionPostEvaluationStateStore.BuildStateRef(
            idempotencySource);
        return new DesignConversionPostEvaluationState(
            stateRef,
            stateRef,
            JsonDesignConversionPostEvaluationStateStore.NoReservationUserRef,
            JsonDesignConversionPostEvaluationStateStore.NoReservationPeriodStartUtc,
            JsonDesignConversionPostEvaluationStateStore.NoReservationPeriodEndExclusiveUtc,
            0m,
            JsonDesignConversionPostEvaluationStateStore.AccountingSettled,
            JsonDesignConversionPostEvaluationStateStore.DesiredNone,
            false,
            false,
            false,
            JsonDesignConversionPostEvaluationStateStore.PersistenceProvisional,
            string.Empty,
            string.Empty,
            string.Empty,
            string.Empty,
            string.Empty,
            DateTimeOffset.UnixEpoch,
            1L);
    }


    [Theory]
    [InlineData("absent", false)]
    [InlineData("file", true)]
    [InlineData("directory", true)]
    [InlineData("case", true)]
    public void HandleBoundDirectory_ContainsNameNoFollowClassifiesNamespaceEntries(
        string fixture,
        bool expected)
    {
        if (!OperatingSystem.IsWindows())
            return;
        var root = Path.Combine(
            Path.GetTempPath(),
            Guid.NewGuid().ToString("N"),
            "contains-name-no-follow-classification");
        const string queryLeaf = "promotion-output";
        var storedLeaf = string.Equals(fixture, "case", StringComparison.Ordinal)
            ? "PROMOTION-OUTPUT"
            : queryLeaf;
        try
        {
            Directory.CreateDirectory(root);
            if (string.Equals(fixture, "file", StringComparison.Ordinal) ||
                string.Equals(fixture, "case", StringComparison.Ordinal))
            {
                File.WriteAllText(Path.Combine(root, storedLeaf), "retained");
            }
            else if (string.Equals(fixture, "directory", StringComparison.Ordinal))
            {
                Directory.CreateDirectory(Path.Combine(root, storedLeaf));
            }

            using var directory =
                DesignConversionHandleBoundDirectory.AcquireExisting(
                    root,
