        const string leaf = "promotion-output";
        var link = Path.Combine(root, leaf);
        var junctionCreated = false;
        try
        {
            Directory.CreateDirectory(root);
            Directory.CreateDirectory(target);
            CreatePromotionContractDirectoryJunction(link, target);
            junctionCreated = true;
            Directory.Delete(target, recursive: true);

            Assert.True(
                (File.GetAttributes(link) & FileAttributes.ReparsePoint) != 0);
            using var directory =
                DesignConversionHandleBoundDirectory.AcquireExisting(
                    root,
                    beforeIo: null);

            Assert.True(directory.ContainsNameNoFollow(
                maximumEntryCount: 8,
