    [Theory]
    [InlineData("appears")]
    [InlineData("disappears")]
    [InlineData("file-to-directory")]
    public void HandleBoundDirectory_ContainsNameNoFollowObservesBothSidesOfNamespaceTransition(
        string transition)
    {
        if (!OperatingSystem.IsWindows())
            return;
        var root = Path.Combine(
            Path.GetTempPath(),
            Guid.NewGuid().ToString("N"),
            "contains-name-no-follow-transition");
        const string leaf = "promotion-output";
        var path = Path.Combine(root, leaf);
        var betweenScanCount = 0;
        try
        {
            Directory.CreateDirectory(root);
            if (!string.Equals(transition, "appears", StringComparison.Ordinal))
                File.WriteAllText(path, "first-scan");
            using var directory =
                DesignConversionHandleBoundDirectory.AcquireExisting(
                    root,
                    (stage, observedPath) =>
                    {
                        if (stage != DesignConversionHandleBoundIoStage
                                .BetweenNamespacePresenceScans)
                        {
                            return;
                        }

                        Assert.Equal(path, observedPath);
                        Assert.Equal(1, Interlocked.Increment(ref betweenScanCount));
                        if (string.Equals(transition, "appears", StringComparison.Ordinal))
                        {
                            File.WriteAllText(path, "second-scan");
                        }
                        else if (string.Equals(
                                     transition,
                                     "disappears",
                                     StringComparison.Ordinal))
                        {
                            File.Delete(path);
                        }
                        else
                        {
                            File.Delete(path);
                            Directory.CreateDirectory(path);
                        }
                    });

            Assert.True(directory.ContainsNameNoFollow(
                maximumEntryCount: 8,
                leaf));
            Assert.Equal(1, betweenScanCount);
        }
        finally
        {
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }

