    [Fact]
    public async Task LocalArtifactDb_GenuinelyAbsentCommittedOutputReplaysWithoutRecreation()
    {
        if (!OperatingSystem.IsWindows())
            return;
        var root = Path.Combine(
            Path.GetTempPath(),
            Guid.NewGuid().ToString("N"),
            "genuinely-absent-committed-output");
        var output = Path.Combine(root, "promotion-output");
        try
        {
            var caseId = "genuinely-absent-committed-output";
            var fixture = await BuildPromotionReadyIntakeFixtureAsync(root, caseId);
            var admission = BuildLocalPromotionAdmission(caseId);
            var pairRoot = Path.Combine(
                root,
                JsonlDesignConversionLocalArtifactDb
                    .TrainingIntakeDpoPairStoreDirectoryName);
            var provider = new DesignConversionDpoPolicyBaseTestProvider();
            var uploader = new CountingLocalOnlyPromotionUploader();
            var runnerCount = 0;
            var activationCount = 0;

            JsonlDesignConversionLocalArtifactDb CreateDb()
                => new(
                    root,
                    createTrainingIntakeJournalWaitTaskObserverForTesting: null,
                    createTrainingIntakeJournalGateAcquiredCallbackForTesting: null,
                    promotionUploader: uploader,
                    runTrainingIntakeLocalPromotionRunnerBeforeInvokeObserverForTesting:
                        () => Interlocked.Increment(ref runnerCount),
                    runTrainingIntakeLocalPromotionActivationInvokedObserverForTesting:
                        () => Interlocked.Increment(ref activationCount),
                    dpoPolicyBaseProvider: provider,
                    legalTeacherAdmissionAuthority:
                        CreateEvaluatedLegalTeacherCapability(),
                    trainingIntakeDpoPairStoreForTesting:
                        new FileDpoPairStore(pairRoot),
                    localReceiptOnlyPromotionAuthority: uploader.Authority);

            var promoted = await RunLocalPromotionWithAdmissionAsync(
                CreateDb(),
                fixture,
                output,
                admission);
            Assert.True(promoted.IsSuccess, promoted.ErrorMessage);
            var countsBeforeDeletion = (
                Runner: runnerCount,
                Provider: provider.InvocationCount,
                Uploader: uploader.Count,
                Activation: activationCount);
            var pairStoreSnapshotBeforeDeletion =
                await ReadFileSha256SnapshotAsync(pairRoot);
            Directory.Delete(output, recursive: true);

            var replay = await RunLocalPromotionWithAdmissionAsync(
                CreateDb(),
                fixture,
                output,
                admission);

            Assert.True(replay.IsSuccess, replay.ErrorMessage);
            Assert.Equal(
                promoted.Value!.LocalPromotionReady,
                replay.Value!.LocalPromotionReady);
            Assert.Equal(
                bool.TrueString,
                replay.Value.BoundaryMetadata[
                    "training_intake_idempotency_replay_hit"]);
            Assert.Equal(
                promoted.Value.PromotedCheckpointPath,
                replay.Value.PromotedCheckpointPath);
            Assert.Equal(
                promoted.Value.PromotedLocalModel?.ModelId,
                replay.Value.PromotedLocalModel?.ModelId);
            Assert.Equal(
                promoted.Value.PromotedLocalModel?.CheckpointSha256,
                replay.Value.PromotedLocalModel?.CheckpointSha256);
            Assert.Equal(countsBeforeDeletion, (
                runnerCount,
                provider.InvocationCount,
                uploader.Count,
                activationCount));
            Assert.Equal(
                pairStoreSnapshotBeforeDeletion,
                await ReadFileSha256SnapshotAsync(pairRoot));
            Assert.False(Directory.Exists(output));
            Assert.False(File.Exists(output));
        }
        finally
        {
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }

    [DesignConversionDpoPromotionReparseFact]
    public async Task LocalArtifactDb_DanglingCommittedOutputJunctionFailsClosedInsteadOfProjectingAbsentReplay()
    {
        Assert.True(
            OperatingSystem.IsWindows(),
            "This committed-projection namespace test requires Windows junction support.");
        var parent = Path.Combine(
            Path.GetTempPath(),
            Guid.NewGuid().ToString("N"));
        var root = Path.Combine(parent, "db-root");
        var output = Path.Combine(root, "promotion-output");
        var junctionTarget = Path.Combine(parent, "junction-target");
