            var activationCount = 0;

            JsonlDesignConversionLocalArtifactDb CreateDb()
                => new(
                    root,
                    createTrainingIntakeJournalWaitTaskObserverForTesting: null,
                    createTrainingIntakeJournalGateAcquiredCallbackForTesting: null,
                    promotionUploader: uploader,
                    runTrainingIntakeLocalPromotionRunnerBeforeInvokeObserverForTesting:
                        () => Interlocked.Increment(ref runnerCount),
                    runTrainingIntakeLocalPromotionActivationInvokedObserverForTesting:
                        () => Interlocked.Increment(ref activationCount),
                    dpoPolicyBaseProvider: provider,
                    legalTeacherAdmissionAuthority:
                        CreateEvaluatedLegalTeacherCapability(),
                    trainingIntakeDpoPairStoreForTesting:
                        new FileDpoPairStore(pairRoot),
                    localReceiptOnlyPromotionAuthority: uploader.Authority);

            var promoted = await RunLocalPromotionWithAdmissionAsync(
                CreateDb(),
                fixture,
                output,
                admission);
            Assert.True(promoted.IsSuccess, promoted.ErrorMessage);
            var countsBeforeTamper = (
                Runner: runnerCount,
                Provider: provider.InvocationCount,
                Uploader: uploader.Count,
                Activation: activationCount);
            var pairStoreSnapshotBeforeTamper =
