                        operationMaximum,
                    localPromotionMaximumSealedSegmentCount: 8,
                    localReceiptOnlyPromotionAuthority: uploader.Authority);

            var db = CreateDb();
            var admissionA = BuildLocalPromotionAdmission("forced-rotation-a");
            var admissionB = BuildLocalPromotionAdmission("forced-rotation-b");
            var admissionC = BuildLocalPromotionAdmission("forced-rotation-c");
            var outputA = Path.Combine(root, "output-a");
            var outputB = Path.Combine(root, "output-b");
            var outputC = Path.Combine(root, "output-c");
            var first = await RunLocalPromotionWithAdmissionAsync(
                db,
                fixtureA,
                outputA,
                admissionA);
            var second = await RunLocalPromotionWithAdmissionAsync(
                db,
                fixtureB,
                outputB,
                admissionB);
            Assert.True(first.IsSuccess, first.ErrorMessage);
            Assert.True(second.IsSuccess, second.ErrorMessage);
            Assert.True(File.Exists(Path.Combine(
                root,
                "training-intake-local-promotion-journals.g0000000000.seal.json")));
            var uploaderCountAfterSecond = uploader.Count;
            var providerCountAfterSecond = ProviderInvocationCount();

            var replay = await RunLocalPromotionWithAdmissionAsync(
                db,
                fixtureA,
                outputA,
                admissionA);
            Assert.True(replay.IsSuccess, replay.ErrorMessage);
            Assert.Equal(uploaderCountAfterSecond, uploader.Count);
            Assert.Equal(providerCountAfterSecond, ProviderInvocationCount());

            var projectionFailureCount = 0;
            var failedThird = await RunLocalPromotionWithAdmissionAsync(
                CreateDb(_ =>
                {
                    Interlocked.Increment(ref projectionFailureCount);
                    throw new IOException("injected projection append failure");
                }),
                fixtureC,
                outputC,
                admissionC);
            Assert.False(failedThird.IsSuccess);
            Assert.Equal(1, projectionFailureCount);
            var uploaderCountAfterThird = uploader.Count;
            var providerCountAfterThird = ProviderInvocationCount();

            var recoveryDb = CreateDb();
            var repaired = await recoveryDb
                .ListTrainingIntakeLocalPromotionRecordsAsync();
            Assert.True(repaired.IsSuccess, repaired.ErrorMessage);
            Assert.Equal(3, repaired.Value!.Count);
            Assert.Equal(uploaderCountAfterThird, uploader.Count);
            Assert.Equal(providerCountAfterThird, ProviderInvocationCount());

            var third = Assert.Single(repaired.Value, record => string.Equals(
                record.BoundaryMetadata["training_intake_tenant_id_ref"],
                admissionC["training_intake_tenant_id_ref"],
                StringComparison.Ordinal));
            var expectedRestoredActiveRef = third.BoundaryMetadata[
                "local_promotion_prior_active_local_model_ref"];
            var secondRepaired = repaired.Value[repaired.Value.Count - 2];
            Assert.Equal(
                secondRepaired.BoundaryMetadata["local_promotion_active_local_model_ref"],
                expectedRestoredActiveRef);
            var activeRefBeforeRollback = third.BoundaryMetadata[
                "local_promotion_active_local_model_ref"];
            var projectionSnapshotBeforeBlockedRollback =
                LocalPromotionProjectionSnapshot(
                    await ReadFileSha256SnapshotAsync(root));
            var blockedRollback = await DesignConversionTrainingIntakeRouteAdmissionContext
                .RunAsync(
                    BuildLocalPromotionAdmission("forced-rotation-rollback"),
                    () => recoveryDb.RollbackTrainingIntakeLocalPromotionAsync(
                        third.Publication!.Manifest.PromotionUploadRef!,
                        "reviewer:forced-rotation",
                        "forced-rotation end-to-end rollback",
                        DateTimeOffset.Parse(
                            "2026-08-10T15:00:00Z",
                            CultureInfo.InvariantCulture)));
            Assert.False(blockedRollback.IsSuccess);
            Assert.Equal(
                "DESIGN_CONVERSION_TRAINING_INTAKE_LOCAL_PROMOTIONS_QUOTA_EXCEEDED",
                blockedRollback.ErrorCode);
            Assert.Equal(uploaderCountAfterThird, uploader.Count);
            Assert.Equal(providerCountAfterThird, ProviderInvocationCount());
            var afterBlockedRollback = await recoveryDb
                .ListTrainingIntakeLocalPromotionRecordsAsync();
            Assert.True(afterBlockedRollback.IsSuccess, afterBlockedRollback.ErrorMessage);
            Assert.Equal(3, afterBlockedRollback.Value!.Count);
            Assert.Equal(
                projectionSnapshotBeforeBlockedRollback,
                LocalPromotionProjectionSnapshot(await ReadFileSha256SnapshotAsync(root)));
            Assert.Equal(
                activeRefBeforeRollback,
                afterBlockedRollback.Value.Last().BoundaryMetadata[
                    "local_promotion_active_local_model_ref"]);
            Assert.DoesNotContain(
                afterBlockedRollback.Value,
                record => string.Equals(
                    record.BoundaryMetadata["local_promotion_record_kind"],
                    "rollback",
                    StringComparison.Ordinal));

            var rollbackDb = CreateDb(
                projectionMaximumOverride: checked(2L * projectionMaximum));
            var rollback = await DesignConversionTrainingIntakeRouteAdmissionContext
                .RunAsync(
                    BuildLocalPromotionAdmission("forced-rotation-rollback"),
                    () => rollbackDb.RollbackTrainingIntakeLocalPromotionAsync(
                        third.Publication!.Manifest.PromotionUploadRef!,
                        "reviewer:forced-rotation",
                        "forced-rotation end-to-end rollback",
                        DateTimeOffset.Parse(
                            "2026-08-10T15:00:00Z",
                            CultureInfo.InvariantCulture)));
            Assert.True(rollback.IsSuccess, rollback.ErrorMessage);
            Assert.True(rollback.Value!.RollbackApplied);
            Assert.True(rollback.Value.PriorStateRestored);
            Assert.Equal(activeRefBeforeRollback, rollback.Value.RolledBackLocalModelRef);
            Assert.Equal(expectedRestoredActiveRef, rollback.Value.RestoredActiveLocalModelRef);
            var afterRollback = await rollbackDb
                .ListTrainingIntakeLocalPromotionRecordsAsync();
            Assert.True(afterRollback.IsSuccess, afterRollback.ErrorMessage);
            Assert.Equal(4, afterRollback.Value!.Count);
            var rollbackTail = afterRollback.Value.Last();
            Assert.Equal(
                "rollback",
                rollbackTail.BoundaryMetadata["local_promotion_record_kind"]);
            Assert.Equal(
                expectedRestoredActiveRef,
                rollbackTail.BoundaryMetadata[
                    "local_promotion_active_local_model_ref"]);
            Assert.Single(
                afterRollback.Value,
                record => string.Equals(
                    record.BoundaryMetadata["local_promotion_record_kind"],
                    "rollback",
                    StringComparison.Ordinal));
            Assert.Equal(uploaderCountAfterThird, uploader.Count);
            Assert.Equal(providerCountAfterThird, ProviderInvocationCount());
        }
        finally
        {
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }

        static KeyValuePair<string, string>[] LocalPromotionProjectionSnapshot(
            IEnumerable<KeyValuePair<string, string>> snapshot)
            => snapshot
                .Where(pair => pair.Key.StartsWith(
                    "training-intake-local-promotions",
                    StringComparison.Ordinal))
                .OrderBy(pair => pair.Key, StringComparer.Ordinal)
                .ToArray();
    }


