                await ReadLocalPromotionProjectionRecordsAsync(projectionPath));
            var legacyMetadata = new Dictionary<string, string>(
                legacy.BoundaryMetadata,
                StringComparer.Ordinal);
            foreach (var key in new[]
            {
                "local_promotion_operation_id",
                "local_promotion_pair_reservation_id",
                "local_promotion_pair_reservation_sha256",
                "local_promotion_output_namespace_reservation_ref",
