                "training_intake_promote_local_no_retrain_claimed",
                "training_intake_promote_local_retry_may_repeat_training",
                "training_intake_idempotency_side_effect_boundary"
            })
            {
                legacyMetadata.Remove(key);
            }
            await File.WriteAllTextAsync(
                projectionPath,
                System.Text.Encoding.UTF8.GetString(SerializeCompact(
                    legacy with { BoundaryMetadata = legacyMetadata })) +
                    Environment.NewLine);
            File.Delete(Path.Combine(
                root,
                JsonlDesignConversionLocalArtifactDb
                    .TrainingIntakeLocalPromotionOperationFileName));
            foreach (var path in Directory.EnumerateFiles(
                         root,
                         "training-intake-local-promotion-operations*.jsonl"))
            {
                File.Delete(path);
            }
            foreach (var path in Directory.EnumerateFiles(
                         root,
                         "training-intake-local-promotions.g*.jsonl"))
            {
                File.Delete(path);
            }
            foreach (var path in Directory.EnumerateFiles(
                         root,
                         "training-intake-local-promotion-journals.g*.seal.json"))
            {
                File.Delete(path);
            }
            var runnerCount = 0;
            var provider = new DesignConversionDpoPolicyBaseTestProvider();
            var uploader = new CountingLocalOnlyPromotionUploader();

            var replay = await RunLocalPromotionWithAdmissionAsync(
                new JsonlDesignConversionLocalArtifactDb(
                    root,
                    createTrainingIntakeJournalWaitTaskObserverForTesting: null,
                    createTrainingIntakeJournalGateAcquiredCallbackForTesting: null,
                    promotionUploader: uploader,
                    runTrainingIntakeLocalPromotionRunnerBeforeInvokeObserverForTesting:
                        () => Interlocked.Increment(ref runnerCount),
                    dpoPolicyBaseProvider: provider,
                    legalTeacherAdmissionAuthority:
                        CreateEvaluatedLegalTeacherCapability(),
                    localReceiptOnlyPromotionAuthority:
                        uploader.Authority),
                fixture,
                output,
                admission);

            Assert.True(replay.IsSuccess, replay.ErrorMessage);
            Assert.Equal(
                bool.TrueString,
                replay.Value!.BoundaryMetadata[
                    "training_intake_idempotency_replay_hit"]);
            Assert.False(replay.Value.BoundaryMetadata.ContainsKey(
                "local_promotion_operation_id"));
            Assert.False(replay.Value.BoundaryMetadata.ContainsKey(
                "training_intake_promote_local_no_retrain_claimed"));
            Assert.Equal(0, runnerCount);
            Assert.Equal(0, provider.InvocationCount);
            Assert.Equal(0, uploader.Count);
        }
        finally
        {
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }


