            Assert.True(provider.InvocationCount > 0);
            Assert.Equal(1, uploader.Count);
            var before = (runnerCount, provider.InvocationCount, uploader.Count);

            var replay = await RunLocalPromotionWithAdmissionAsync(
                new JsonlDesignConversionLocalArtifactDb(
                    root,
                    createTrainingIntakeJournalWaitTaskObserverForTesting: null,
                    createTrainingIntakeJournalGateAcquiredCallbackForTesting: null,
                    promotionUploader: uploader,
                    runTrainingIntakeLocalPromotionRunnerBeforeInvokeObserverForTesting:
                        () => Interlocked.Increment(ref runnerCount),
                    dpoPolicyBaseProvider: provider,
                    legalTeacherAdmissionAuthority:
                        CreateEvaluatedLegalTeacherCapability(),
                    localReceiptOnlyPromotionAuthority: authority),
                fixture,
                output,
                admission);

            Assert.True(replay.IsSuccess, replay.ErrorMessage);
            Assert.False(replay.Value!.LocalPromotionReady);
            Assert.Equal(
                bool.TrueString,
                replay.Value.BoundaryMetadata[
                    "training_intake_idempotency_replay_hit"]);
            Assert.Equal(
                bool.FalseString,
                replay.Value.BoundaryMetadata[
                    "training_intake_idempotency_created_new_side_effect"]);
            Assert.Equal(
                before,
                (runnerCount, provider.InvocationCount, uploader.Count));
        }
        finally
        {
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }


    [Fact]
    public async Task LocalArtifactDb_PostCommitProjectionFailureRepairsWithoutRetraining()
    {
        var root = Path.Combine(
            Path.GetTempPath(),
            Guid.NewGuid().ToString("N"),
            "promotion-append-residue");
        Directory.CreateDirectory(root);
        try
        {
            var intake = await BuildPromotionReadyIntakeFixtureAsync(
                root,
                "append-residue");
            var output = Path.Combine(root, "promotion-output");
            var admission = new Dictionary<string, string>(StringComparer.Ordinal)
            {
                ["training_intake_tenant_id_ref"] = "tenant:append-residue",
                ["training_intake_idempotency_key_ref"] = "idempotency:append-residue"
            };
            var firstProvider = new DesignConversionDpoPolicyBaseTestProvider();
            var appendInjectionCount = 0;
            var injectedDb = new JsonlDesignConversionLocalArtifactDb(
                root,
                createTrainingIntakeJournalWaitTaskObserverForTesting: null,
                createTrainingIntakeJournalGateAcquiredCallbackForTesting: null,
                dpoPolicyBaseProvider: firstProvider,
                runTrainingIntakeLocalPromotionBeforeIdempotencyAppendCallbackForTesting:
                    _ =>
                    {
                        Interlocked.Increment(ref appendInjectionCount);
                        throw new IOException("injected append failure");
                    },
                legalTeacherAdmissionAuthority: CreateEvaluatedLegalTeacherCapability());

            var failed = await DesignConversionTrainingIntakeRouteAdmissionContext.RunAsync(
                admission,
                () => new DesignConversionDpoUsefulnessApi(injectedDb)
                    .RunTrainingIntakeAndPromoteLocalAsync(
                        intake.Intake.IntakeId,
                        output,
                        intake.Options));
            Assert.False(failed.IsSuccess);
            Assert.Equal(
                JsonlDesignConversionLocalArtifactDb.LocalArtifactDbWriteFailedErrorCode,
                failed.ErrorCode);
            Assert.Equal(1, appendInjectionCount);
            Assert.True(firstProvider.InvocationCount > 0);
            Assert.False(File.Exists(Path.Combine(
                root,
                "training-intake-local-promotions.jsonl")));
            Assert.Equal(
                [0, 1, 2, 3],
                await ReadLocalPromotionOperationPhaseNumbersAsync(Path.Combine(
                    root,
                    JsonlDesignConversionLocalArtifactDb
                        .TrainingIntakeLocalPromotionOperationFileName)));
            var operationRecords = await ReadLocalPromotionOperationRecordsAsync(
                Path.Combine(
                    root,
                    JsonlDesignConversionLocalArtifactDb
                        .TrainingIntakeLocalPromotionOperationFileName));
            for (var index = 0; index < operationRecords.Length; index++)
            {
                operationRecords[index] = operationRecords[index] with
                {
                    JournalGeneration = 0,
                    JournalOrdinal = index,
                    JournalIsActive = true
                };
            }
            var committedRecord = operationRecords[^1];
            var preparedRecord = operationRecords[^2];
            var backdatedRollbackMetadata = new Dictionary<string, string>(
                preparedRecord.FinalResult!.BoundaryMetadata,
                StringComparer.Ordinal)
            {
                ["local_promotion_record_kind"] = "rollback",
                ["local_promotion_rollback_requested_at_utc"] =
                    DateTimeOffset.UnixEpoch.ToString("O", CultureInfo.InvariantCulture),
                ["training_intake_rollback_local_recorded_at_utc"] =
                    committedRecord.RecordedAtUtc.AddMinutes(1)
                        .ToString("O", CultureInfo.InvariantCulture)
            };
            backdatedRollbackMetadata.Remove("local_promotion_operation_id");
            var backdatedLaterRollback = preparedRecord.FinalResult with
            {
                BoundaryMetadata = backdatedRollbackMetadata
            };
            var projectionEntryType = typeof(JsonlDesignConversionLocalArtifactDb)
                .GetNestedType(
                    "LocalPromotionProjectionJournalEntry",
                    BindingFlags.NonPublic)!;
            var backdatedEntry = Activator.CreateInstance(
                projectionEntryType,
                BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic,
                binder: null,
                args: [backdatedLaterRollback, 0, 0L, true],
                culture: null)!;
            var backdatedEntries = Array.CreateInstance(projectionEntryType, 1);
            backdatedEntries.SetValue(backdatedEntry, 0);
            var repairFence = typeof(JsonlDesignConversionLocalArtifactDb)
                .GetMethod(
                    "IsUniqueSafeLocalPromotionProjectionRepairTail",
                    BindingFlags.Static | BindingFlags.NonPublic)!;
            Assert.False((bool)repairFence.Invoke(
                obj: null,
                parameters: [preparedRecord, operationRecords, backdatedEntries])!);

            var physicallyLaterEntry = Activator.CreateInstance(
                projectionEntryType,
                BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic,
                binder: null,
                args:
                [
                    backdatedLaterRollback with
                    {
                        BoundaryMetadata = new Dictionary<string, string>(
                            backdatedRollbackMetadata,
                            StringComparer.Ordinal)
                        {
                            ["training_intake_rollback_local_recorded_at_utc"] =
                                committedRecord.RecordedAtUtc.AddMinutes(-1)
                                    .ToString("O", CultureInfo.InvariantCulture)
                        }
                    },
                    0,
                    0L,
                    true
                ],
                culture: null)!;
            var physicallyLaterEntries = Array.CreateInstance(
                projectionEntryType,
                1);
            physicallyLaterEntries.SetValue(physicallyLaterEntry, 0);
            Assert.False((bool)repairFence.Invoke(
                obj: null,
                parameters: [preparedRecord, operationRecords, physicallyLaterEntries])!);
            var legacyOperationRecords = operationRecords.ToArray();
            legacyOperationRecords[^1] = committedRecord with
            {
                ProjectionLogicalPrefixCount = 0L,
                ProjectionLogicalPrefixSha256 = null
            };
            Assert.False((bool)repairFence.Invoke(
                obj: null,
                parameters:
                [
                    preparedRecord,
                    legacyOperationRecords,
                    physicallyLaterEntries
                ])!);
            var sourceContractPath = Assert.Single(
                Directory.EnumerateFiles(
                    output,
                    "*" + DesignConversionDpoPromotionArtifactContractCodec.SourceEncoderContractSuffix,
                    SearchOption.AllDirectories));
            var policyContractPath = Assert.Single(
                Directory.EnumerateFiles(
                    output,
                    "*" + DesignConversionDpoPromotionArtifactContractCodec.PolicyCheckpointContractSuffix,
                    SearchOption.AllDirectories));
            var sourceContractResidue = await File.ReadAllBytesAsync(sourceContractPath);
            var policyContractResidue = await File.ReadAllBytesAsync(policyContractPath);

            var retryProvider = new DesignConversionDpoPolicyBaseTestProvider();
            var retry = await DesignConversionTrainingIntakeRouteAdmissionContext.RunAsync(
                admission,
                () => new DesignConversionDpoUsefulnessApi(
                        new JsonlDesignConversionLocalArtifactDb(
                            root,
                            dpoPolicyBaseProvider: retryProvider,
                            legalTeacherAdmissionAuthority:
                                CreateEvaluatedLegalTeacherCapability()))
                    .RunTrainingIntakeAndPromoteLocalAsync(
                        intake.Intake.IntakeId,
                        output,
                        intake.Options));

            Assert.True(retry.IsSuccess, retry.ErrorMessage);
            Assert.Equal(0, retryProvider.InvocationCount);
            Assert.Equal(sourceContractResidue, await File.ReadAllBytesAsync(sourceContractPath));
            Assert.Equal(policyContractResidue, await File.ReadAllBytesAsync(policyContractPath));
            Assert.Equal(
                "promote_local_fenced_operation_journal_then_legacy_projection",
                retry.Value!.BoundaryMetadata["training_intake_idempotency_side_effect_boundary"]);
            Assert.Equal(
                bool.FalseString,
                retry.Value.BoundaryMetadata["training_intake_promote_local_artifact_append_atomic"]);
            Assert.Equal(
                bool.TrueString,
                retry.Value.BoundaryMetadata["training_intake_promote_local_recoverable_residue_possible"]);
            Assert.Equal(
                bool.FalseString,
                retry.Value.BoundaryMetadata["training_intake_promote_local_retry_may_repeat_training"]);
            Assert.Equal(
                bool.TrueString,
                retry.Value.BoundaryMetadata["training_intake_promote_local_no_retrain_claimed"]);
            Assert.Single(await ReadLocalPromotionProjectionRecordsAsync(Path.Combine(
                root,
                JsonlDesignConversionLocalArtifactDb.TrainingIntakeLocalPromotionFileName)));
        }
        finally
        {
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }


