    [Fact]
    public async Task LocalArtifactDb_ComposedProductionHttpFailureCodeAfterIntentIsIndeterminateAndNeverRetrains_WithoutDirectHttpIntegrationClaim()
    {
        var root = DesignConversionPostEvaluationEligibilityTestFixture
            .CreateHandleBoundTempRoot("promotion-http-post-send-ambiguity");
        var output = Path.Combine(root, "output");
        try
        {
            var httpArtifactRoot = Path.Combine(root, "http-transport-artifacts");
            Directory.CreateDirectory(httpArtifactRoot);
            var httpCheckpointPath = Path.Combine(httpArtifactRoot, "checkpoint.bin");
            var httpTokenizerPath = Path.Combine(httpArtifactRoot, "tokenizer.json");
            var httpPolicyPath = Path.Combine(httpArtifactRoot, "policy.json");
            await File.WriteAllTextAsync(
                httpCheckpointPath,
                "post-send checkpoint transport payload");
            await File.WriteAllTextAsync(
                httpTokenizerPath,
                "{\"kind\":\"post-send-tokenizer\"}");
            await File.WriteAllTextAsync(
                httpPolicyPath,
                "{\"kind\":\"post-send-policy\"}");
            var transportManifest = new DesignConversionTrainingManifest(
                ManifestId: "promotion-http-post-send-manifest",
                MachineId: "promotion-http-post-send-machine",
                DomainTag: "design-conversion",
                Version: "v1",
                CheckpointRef: "promotion-http-post-send-checkpoint",
                ManifestRef:
                    "manifest://design-conversion/promotion-http-post-send",
                CreatedAtUtc: DateTimeOffset.UnixEpoch.AddMinutes(250),
                AcceptedRecordCount: 2,
                QuarantinedRecordCount: 0,
                UnitIds: [DesignConversionDpoUnits.ImproverUnit],
                Batches:
                [
                    new DesignConversionTrainingManifestBatch(
                        BatchId: "promotion-http-post-send-batch",
                        UnitId: DesignConversionDpoUnits.ImproverUnit,
                        RecordCount: 2,
                        RecordIds: ["post-send-train", "post-send-heldout"],
                        SourceIds: ["post-send-source"])
                ],
                EvidenceRefs: ["HTTP_POST_SEND_TRANSPORT_PROBE"],
                ModelServerUploadAttempted: false,
                ModelServerPromotionClaimed: false,
                DeterministicLogicClaimedAsLearning: false)
            {
                PromotionArtifacts = new DesignConversionTrainingManifestArtifacts(
                    httpCheckpointPath,
                    httpTokenizerPath,
                    httpPolicyPath)
            };
            var transportGateReport = new DesignConversionPromotionGateReport(
                HeldOutScore: 0.95,
                RequiredHeldOutScore: 0.90,
                HeldOutSourceDisjoint: true,
                DeterministicShortcutDetected: false,
                HiddenShortcutEvidenceDetected: false,
                FreshLoadPassed: true,
                BudgetTierPolicyPassed: true,
                BudgetTier: "bounded-http-post-send-transport-probe",
                DpoQuarantineCount: 0,
                MaxDpoQuarantineCount: 0,
                RequiredArtifactPaths:
                    [httpCheckpointPath, httpTokenizerPath, httpPolicyPath],
                PresentArtifactPaths:
                    [httpCheckpointPath, httpTokenizerPath, httpPolicyPath],
                EvidenceRefs: ["HTTP_POST_SEND_TRANSPORT_GATE_PASSED"]);
            var handler = new AmbiguousPostSendPromotionHttpHandler();
            using var client = new HttpClient(handler, disposeHandler: false);
            var transportUploader =
                new DesignConversionModelServerPromotionHttpUploader(
                    client,
                    new DesignConversionModelServerPromotionHttpUploaderOptions(
                        new Uri(
                            "https://promotion.example/v1/design-conversion/promotions"),
                        "tenant-http-post-send-ambiguity",
                        "bounded-bearer-http-post-send-ambiguity",
                        root)
                    {
                        Timeout = TimeSpan.FromSeconds(5),
                        MaxArtifactBytes = 32 * 1024 * 1024,
                        MaxTotalArtifactBytes = 64 * 1024 * 1024,
                        MaxResponseBodyBytes = 64 * 1024,
                        MaxArtifactCount =
                            DesignConversionModelServerPromotionHttpUploaderOptions
                                .HardMaxArtifactCount
                    });

            var transportFailure = await transportUploader.UploadAsync(
                transportManifest,
                transportGateReport);
            Assert.False(transportFailure.IsSuccess);
            Assert.Equal(
                "DESIGN_CONVERSION_PROMOTION_UPLOAD_HTTP_REQUEST_FAILED",
                transportFailure.ErrorCode);
            Assert.Equal(1, handler.SendCount);
            Assert.True(handler.RequestBodyRead);

            // The local operation has no server-owned remote-upload authority.
            // Bind the exact production transport error to a no-remote-effect
            // uploader so the durable Intent state machine can be proven without
            // minting remote authority or misusing local-receipt-only authority
            // for an HTTP-capable uploader.
            var fixture = await BuildW085DeterministicPromotionReadyIntakeFixtureAsync(
                root,
                "promotion-http-post-send");
            var admission = BuildLocalPromotionAdmission(
                "promotion-http-post-send");
