                transportFailure.ErrorCode!);
            var provider = CreateW085DeterministicPromotionProvider();
            var runnerCount = 0;
            var beforeActivationCount = 0;
            var activationCount = 0;
            Action activationObserver =
                () => Interlocked.Increment(ref activationCount);
            var first = await RunLocalPromotionWithAdmissionAsync(
                new JsonlDesignConversionLocalArtifactDb(
                    root,
                    createTrainingIntakeJournalWaitTaskObserverForTesting: null,
                    createTrainingIntakeJournalGateAcquiredCallbackForTesting: null,
                    promotionUploader: uploader,
                    runTrainingIntakeLocalPromotionRunnerBeforeInvokeObserverForTesting:
                        () => Interlocked.Increment(ref runnerCount),
                    runTrainingIntakeLocalPromotionBeforeActivationObserverForTesting:
                        () => Interlocked.Increment(ref beforeActivationCount),
                    runTrainingIntakeLocalPromotionActivationInvokedObserverForTesting:
                        activationObserver,
                    dpoPolicyBaseProvider: provider,
                    legalTeacherAdmissionAuthority:
                        CreateEvaluatedLegalTeacherCapability(),
                    localReceiptOnlyPromotionAuthority: uploader.Authority),
                fixture,
                output,
                admission);
            Assert.False(first.IsSuccess);
            Assert.Equal(
                "DESIGN_CONVERSION_TRAINING_INTAKE_PROMOTE_LOCAL_INDETERMINATE_AFTER_INTENT",
                first.ErrorCode);
            Assert.Equal(1, runnerCount);
            Assert.Equal(1, uploader.Count);
            Assert.Equal(0, Volatile.Read(ref beforeActivationCount));
            Assert.Equal(0, Volatile.Read(ref activationCount));
            var operationPath = Path.Combine(
                root,
                JsonlDesignConversionLocalArtifactDb
                    .TrainingIntakeLocalPromotionOperationFileName);
            Assert.Equal(
                [0, 1],
                await ReadLocalPromotionOperationPhaseNumbersAsync(operationPath));
            var operationJournalBytes = await File.ReadAllBytesAsync(operationPath);
            Assert.NotEmpty(operationJournalBytes);
            var operationJournalSha256 = Sha256(operationJournalBytes);
            Assert.False(File.Exists(Path.Combine(
                root,
                JsonlDesignConversionLocalArtifactDb
                    .TrainingIntakeLocalPromotionFileName)));
            var artifactSnapshot = await ReadFileSha256SnapshotAsync(output);
            Assert.NotEmpty(artifactSnapshot);
            var providerCount = provider.InvocationCount;

            var retry = await RunLocalPromotionWithAdmissionAsync(
                new JsonlDesignConversionLocalArtifactDb(
                    root,
                    createTrainingIntakeJournalWaitTaskObserverForTesting: null,
                    createTrainingIntakeJournalGateAcquiredCallbackForTesting: null,
                    promotionUploader: uploader,
                    runTrainingIntakeLocalPromotionBeforeActivationObserverForTesting:
                        () => Interlocked.Increment(ref beforeActivationCount),
                    runTrainingIntakeLocalPromotionActivationInvokedObserverForTesting:
                        activationObserver,
                    dpoPolicyBaseProvider: provider,
                    legalTeacherAdmissionAuthority:
                        CreateEvaluatedLegalTeacherCapability(),
                    localReceiptOnlyPromotionAuthority: uploader.Authority),
                fixture,
                output,
                admission);
            Assert.False(retry.IsSuccess);
            Assert.Equal(first.ErrorCode, retry.ErrorCode);
            Assert.Equal(1, runnerCount);
            Assert.Equal(providerCount, provider.InvocationCount);
            Assert.Equal(1, uploader.Count);
            Assert.Equal(1, handler.SendCount);
            Assert.Equal(0, Volatile.Read(ref beforeActivationCount));
            Assert.Equal(0, Volatile.Read(ref activationCount));
            var retryOperationJournalBytes = await File.ReadAllBytesAsync(operationPath);
            Assert.Equal(operationJournalBytes, retryOperationJournalBytes);
            Assert.Equal(operationJournalSha256, Sha256(retryOperationJournalBytes));
            Assert.Equal(
                [0, 1],
                await ReadLocalPromotionOperationPhaseNumbersAsync(operationPath));
            Assert.Equal(
                artifactSnapshot,
                await ReadFileSha256SnapshotAsync(output));
            Assert.False(File.Exists(Path.Combine(
                root,
                JsonlDesignConversionLocalArtifactDb
                    .TrainingIntakeLocalPromotionFileName)));
        }
        finally
        {
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }

    [DesignConversionDpoPromotionReparseFact]
    public async Task LocalArtifactDb_ConfiguredProductionHttpUploaderWithoutServerOwnedRemoteAuthorityNeverSendsAndPreparedCrashRestartIsStableWithoutRetraining()
    {
        var root = Path.Combine(
            Path.GetTempPath(),
            Guid.NewGuid().ToString("N"),
            "promotion-production-http-restart");
        var output = Path.Combine(root, "promotion-output");
        try
        {
            var fixture = await BuildW085DeterministicPromotionReadyIntakeFixtureAsync(
                root,
                "promotion-production-http-restart");
            var admission = BuildLocalPromotionAdmission(
                "promotion-production-http-restart");
            var handler = new CoherentPromotionHttpHandler();
            using var firstClient = new HttpClient(handler, disposeHandler: false);
            var provider = CreateW085DeterministicPromotionProvider();
            var runnerCount = 0;
            var activationCount = 0;
            var preparedCrashCount = 0;
            var firstUploader = new DesignConversionModelServerPromotionHttpUploader(
                firstClient,
                new DesignConversionModelServerPromotionHttpUploaderOptions(
                    new Uri("https://promotion.example/v1/design-conversion/promotions"),
                    "tenant-production-http-restart",
                    "bounded-bearer-production-http-restart",
                    root)
                {
                    Timeout = TimeSpan.FromSeconds(5),
                    MaxArtifactBytes = 32 * 1024 * 1024,
                    MaxTotalArtifactBytes = 64 * 1024 * 1024,
                    MaxResponseBodyBytes = 64 * 1024,
                    MaxArtifactCount =
                        DesignConversionModelServerPromotionHttpUploaderOptions
                            .HardMaxArtifactCount
                });
            var firstConfigurationFingerprint = firstUploader
                .PreflightConfigurationFingerprintSha256();
            Assert.True(
                firstConfigurationFingerprint.IsSuccess,
                firstConfigurationFingerprint.ErrorMessage);
            var firstAuthorityFingerprint =
                BuildConfiguredHttpUploaderAuthorityFingerprint(
                    firstUploader,
                    firstConfigurationFingerprint.Value!);
            await Assert.ThrowsAsync<SimulatedPromotionProcessDeathException>(
                () => RunLocalPromotionWithAdmissionAsync(
                    new JsonlDesignConversionLocalArtifactDb(
                    root,
                    createTrainingIntakeJournalWaitTaskObserverForTesting: null,
                    createTrainingIntakeJournalGateAcquiredCallbackForTesting: null,
                    promotionUploader: firstUploader,
                    runTrainingIntakeLocalPromotionRunnerBeforeInvokeObserverForTesting:
                        () => Interlocked.Increment(ref runnerCount),
                    runTrainingIntakeLocalPromotionActivationInvokedObserverForTesting:
                        () => Interlocked.Increment(ref activationCount),
                    dpoPolicyBaseProvider: provider,
                    legalTeacherAdmissionAuthority:
                        CreateEvaluatedLegalTeacherCapability(),
                    runTrainingIntakeLocalPromotionOperationPhaseObserverForTesting:
                        phase =>
                        {
                            if (phase != JsonlDesignConversionLocalArtifactDb
                                    .LocalPromotionOperationPhase.Prepared)
                            {
                                return;
                            }
                            Interlocked.Increment(ref preparedCrashCount);
                            throw new SimulatedPromotionProcessDeathException(
                                "injected production HTTP Prepared crash");
                        }),
                    fixture,
                    output,
                    admission));

            Assert.Equal(1, preparedCrashCount);
            Assert.Equal(1, runnerCount);
            Assert.Equal(1, provider.InvocationCount);
            Assert.Equal(0, activationCount);
            Assert.Equal(0, handler.SendCount);
            Assert.False(handler.RequestBodyRead);
            Assert.Empty(handler.IdempotencyKeys);
            Assert.Null(handler.MetadataIdempotencyKey);

            var operationPath = Path.Combine(
                root,
                JsonlDesignConversionLocalArtifactDb
                    .TrainingIntakeLocalPromotionOperationFileName);
            var records = await ReadLocalPromotionOperationRecordsAsync(
                operationPath);
            Assert.Equal([0, 1, 2], records.Select(record => (int)record.Phase));
            Assert.Single(records.Select(record => record.OperationId)
                .Distinct(StringComparer.Ordinal));
            Assert.All(records, record =>
            {
                Assert.Equal(
                    admission["training_intake_tenant_id_ref"],
                    record.TenantIdRef);
                Assert.Equal(
                    admission["training_intake_idempotency_key_ref"],
                    record.IdempotencyKeyRef);
            });
            var reservationRef = Assert.Single(records
                .Select(record => record.OutputNamespaceReservationRef)
                .Distinct(StringComparer.Ordinal));
            var preparedRecord = records.Single(record =>
                record.Phase == JsonlDesignConversionLocalArtifactDb
                    .LocalPromotionOperationPhase.Prepared);
            Assert.Equal(
                "ConfiguredUploaderUntrusted",
                preparedRecord.UploaderAuthorityMode);
            Assert.Equal(
                firstAuthorityFingerprint,
                preparedRecord.UploaderConfigurationFingerprintSha256);
            Assert.Equal(
                preparedRecord.UploaderConfigurationFingerprintSha256,
                preparedRecord.FinalResult!.BoundaryMetadata[
                    "local_promotion_uploader_configuration_fingerprint_sha256"]);
            Assert.Equal(reservationRef, preparedRecord.FinalResult!
                .BoundaryMetadata[
                    "local_promotion_output_namespace_reservation_ref"]);
            Assert.Equal(
                Path.Combine(
                    root,
                    ".training-intake-local-promotion-output-reservations"),
                Path.GetDirectoryName(reservationRef));
            Assert.True(File.Exists(reservationRef));
            var preparedResult = preparedRecord.FinalResult!;
            Assert.False(preparedResult.LocalPromotionReady);
            Assert.False(preparedResult.ExternalCloudUploadAttempted);
            Assert.Null(preparedResult.PromotedLocalModel);
            var rejectedPublication = Assert.IsType<
                DesignConversionPromotionPublicationResult>(
                preparedResult.Publication);
            Assert.Equal(
                DesignConversionPromotionDecisionKind.Reject,
                rejectedPublication.Decision.Kind);
            Assert.False(rejectedPublication.Decision.AllowsUpload);
            Assert.Contains(
                "BUDGET_TIER_POLICY_FAILED",
                rejectedPublication.Decision.Reasons);
            Assert.Contains(
                "DESIGN_CONVERSION_SERVER_OWNED_PROMOTION_BUDGET_AUTHORITY_NOT_CONFIGURED",
                rejectedPublication.Decision.EvidenceRefs);
            Assert.Contains(
                "DESIGN_CONVERSION_SERVER_OWNED_PROMOTION_INTEGRITY_AUTHORITY_NOT_CONFIGURED",
                rejectedPublication.Decision.EvidenceRefs);
            Assert.Contains(
                "DESIGN_CONVERSION_CONFIGURED_PROMOTION_UPLOADER_UNTRUSTED_BY_DEFAULT",
                rejectedPublication.Decision.EvidenceRefs);
            Assert.Equal(
                DesignConversionPromotionPublicationKind.Rejected,
                rejectedPublication.PublicationKind);
            Assert.Equal(
                DesignConversionPromotionPublicationStatus.Rejected,
                rejectedPublication.PublicationStatus);
            Assert.Null(rejectedPublication.UploadReceipt);
            Assert.False(rejectedPublication.Manifest.ModelServerUploadAttempted);
            Assert.False(rejectedPublication.Manifest.ModelServerPromotionClaimed);
            Assert.False(rejectedPublication.Manifest.LocalPromotionReceiptWritten);
            Assert.Null(rejectedPublication.Manifest.PromotionUploadRef);
            Assert.Null(rejectedPublication.Manifest.PromotionUploadedAtUtc);
            using (var marker = JsonDocument.Parse(
                       await File.ReadAllBytesAsync(reservationRef)))
            {
                var prepared = records.Single(record =>
                    record.Phase == JsonlDesignConversionLocalArtifactDb
                        .LocalPromotionOperationPhase.Prepared);
                Assert.Equal(
                    prepared.OperationId,
                    marker.RootElement.GetProperty("operationId").GetString());
                Assert.Equal(
                    prepared.CanonicalPromotionOutputDirectory,
                    marker.RootElement.GetProperty(
                        "canonicalOutputDirectory").GetString());
                Assert.Equal(
                    prepared.OutputNamespaceReservationSha256,
                    marker.RootElement.GetProperty("reservationSha256").GetString());
            }
            var operationBytesBeforeRestart =
                await File.ReadAllBytesAsync(operationPath);
            var artifactSnapshot = await ReadFileSha256SnapshotAsync(output);
            Assert.NotEmpty(artifactSnapshot);
            var projectionPath = Path.Combine(
                root,
                JsonlDesignConversionLocalArtifactDb
                    .TrainingIntakeLocalPromotionFileName);
            Assert.False(File.Exists(projectionPath));

            using var retryClient = new HttpClient(handler, disposeHandler: false);
            var retryUploader = new DesignConversionModelServerPromotionHttpUploader(
                retryClient,
                new DesignConversionModelServerPromotionHttpUploaderOptions(
                    new Uri("https://promotion.example/v1/design-conversion/promotions"),
                    "tenant-production-http-restart",
                    "bounded-bearer-production-http-restart",
                    root)
                {
                    Timeout = TimeSpan.FromSeconds(5),
                    MaxArtifactBytes = 32 * 1024 * 1024,
                    MaxTotalArtifactBytes = 64 * 1024 * 1024,
                    MaxResponseBodyBytes = 64 * 1024,
                    MaxArtifactCount =
                        DesignConversionModelServerPromotionHttpUploaderOptions
                            .HardMaxArtifactCount
                });
            var retryConfigurationFingerprint = retryUploader
                .PreflightConfigurationFingerprintSha256();
            Assert.True(
                retryConfigurationFingerprint.IsSuccess,
                retryConfigurationFingerprint.ErrorMessage);
            Assert.Equal(
                firstConfigurationFingerprint.Value,
                retryConfigurationFingerprint.Value);
            var retryAuthorityFingerprint =
                BuildConfiguredHttpUploaderAuthorityFingerprint(
                    retryUploader,
                    retryConfigurationFingerprint.Value!);
            Assert.Equal(firstAuthorityFingerprint, retryAuthorityFingerprint);
            using var changedClient = new HttpClient(
                handler,
                disposeHandler: false);
            var changedConfigurationUploader =
                new DesignConversionModelServerPromotionHttpUploader(
                    changedClient,
                    new DesignConversionModelServerPromotionHttpUploaderOptions(
                        new Uri("https://changed-promotion.example/v2/design-conversion/promotions"),
                        "tenant-production-http-restart",
                        "different-bearer-production-http-restart",
                        root)
                    {
                        Timeout = TimeSpan.FromSeconds(5),
                        MaxArtifactBytes = 32 * 1024 * 1024,
                        MaxTotalArtifactBytes = 64 * 1024 * 1024,
                        MaxResponseBodyBytes = 64 * 1024,
                        MaxArtifactCount =
                            DesignConversionModelServerPromotionHttpUploaderOptions
                                .HardMaxArtifactCount
                    });
            var changedFingerprint = changedConfigurationUploader
                .PreflightConfigurationFingerprintSha256();
            Assert.True(changedFingerprint.IsSuccess, changedFingerprint.ErrorMessage);
            Assert.NotEqual(
                firstConfigurationFingerprint.Value,
                changedFingerprint.Value);
            var changedAuthorityFingerprint =
                BuildConfiguredHttpUploaderAuthorityFingerprint(
                    changedConfigurationUploader,
                    changedFingerprint.Value!);
            Assert.NotEqual(firstAuthorityFingerprint, changedAuthorityFingerprint);
            var changedConfigurationResult =
                await RunLocalPromotionWithAdmissionAsync(
                    new JsonlDesignConversionLocalArtifactDb(
                        root,
                        createTrainingIntakeJournalWaitTaskObserverForTesting: null,
                        createTrainingIntakeJournalGateAcquiredCallbackForTesting: null,
                        promotionUploader: changedConfigurationUploader,
                        runTrainingIntakeLocalPromotionRunnerBeforeInvokeObserverForTesting:
                            () => Interlocked.Increment(ref runnerCount),
                        runTrainingIntakeLocalPromotionActivationInvokedObserverForTesting:
                            () => Interlocked.Increment(ref activationCount),
                        dpoPolicyBaseProvider: provider,
                        legalTeacherAdmissionAuthority:
                            CreateEvaluatedLegalTeacherCapability()),
                    fixture,
                    output,
                    admission);
            Assert.False(changedConfigurationResult.IsSuccess);
            Assert.Equal(
                "DESIGN_CONVERSION_TRAINING_INTAKE_PROMOTE_LOCAL_OPERATION_STATE_INVALID",
                changedConfigurationResult.ErrorCode);
            Assert.Equal(1, runnerCount);
            Assert.Equal(1, provider.InvocationCount);
            Assert.Equal(0, activationCount);
            Assert.Equal(0, handler.SendCount);
            Assert.False(handler.RequestBodyRead);
            Assert.Equal(
                operationBytesBeforeRestart,
                await File.ReadAllBytesAsync(operationPath));
            Assert.Equal(
                artifactSnapshot,
                await ReadFileSha256SnapshotAsync(output));
            Assert.False(File.Exists(projectionPath));
            var retry = await RunLocalPromotionWithAdmissionAsync(
                new JsonlDesignConversionLocalArtifactDb(
                    root,
                    createTrainingIntakeJournalWaitTaskObserverForTesting: null,
                    createTrainingIntakeJournalGateAcquiredCallbackForTesting: null,
                    promotionUploader: retryUploader,
                    runTrainingIntakeLocalPromotionRunnerBeforeInvokeObserverForTesting:
                        () => Interlocked.Increment(ref runnerCount),
                    runTrainingIntakeLocalPromotionActivationInvokedObserverForTesting:
                        () => Interlocked.Increment(ref activationCount),
                    dpoPolicyBaseProvider: provider,
                    legalTeacherAdmissionAuthority:
                        CreateEvaluatedLegalTeacherCapability()),
                fixture,
                output,
                admission);

            Assert.True(retry.IsSuccess, retry.ErrorMessage);
            Assert.Equal(
                bool.TrueString,
                retry.Value!.BoundaryMetadata[
                    "training_intake_idempotency_replay_hit"]);
            Assert.False(retry.Value.LocalPromotionReady);
            Assert.False(retry.Value.ExternalCloudUploadAttempted);
            Assert.Null(retry.Value.PromotedLocalModel);
            Assert.Equal(reservationRef, retry.Value.BoundaryMetadata[
                "local_promotion_output_namespace_reservation_ref"]);
            Assert.Equal(1, runnerCount);
            Assert.Equal(1, provider.InvocationCount);
            Assert.Equal(0, activationCount);
            Assert.Equal(0, handler.SendCount);
            Assert.False(handler.RequestBodyRead);
            Assert.Empty(handler.IdempotencyKeys);
            Assert.Null(handler.MetadataIdempotencyKey);
            var operationBytesAfterRestart =
                await File.ReadAllBytesAsync(operationPath);
            Assert.True(
                operationBytesAfterRestart.Length >
                operationBytesBeforeRestart.Length);
            Assert.True(operationBytesAfterRestart
                .AsSpan(0, operationBytesBeforeRestart.Length)
                .SequenceEqual(operationBytesBeforeRestart));
            Assert.Equal(
                [0, 1, 2, 3],
                await ReadLocalPromotionOperationPhaseNumbersAsync(
                    operationPath));
            Assert.Equal(
                artifactSnapshot,
                await ReadFileSha256SnapshotAsync(output));
            var projection = Assert.Single(
                await ReadLocalPromotionProjectionRecordsAsync(projectionPath));
            Assert.False(projection.LocalPromotionReady);
            Assert.False(projection.ExternalCloudUploadAttempted);
            Assert.Null(projection.PromotedLocalModel);
            var replayPublication = Assert.IsType<
                DesignConversionPromotionPublicationResult>(
                retry.Value.Publication);
            Assert.False(replayPublication.Decision.AllowsUpload);
            Assert.Contains(
                "BUDGET_TIER_POLICY_FAILED",
                replayPublication.Decision.Reasons);
            Assert.Null(replayPublication.UploadReceipt);
            Assert.False(replayPublication.Manifest.ModelServerUploadAttempted);
            Assert.False(replayPublication.Manifest.ModelServerPromotionClaimed);
            Assert.False(replayPublication.Manifest.LocalPromotionReceiptWritten);
        }
        finally
        {
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }

        static string BuildConfiguredHttpUploaderAuthorityFingerprint(
            DesignConversionModelServerPromotionHttpUploader uploader,
            string preflightFingerprintSha256)
            => "sha256:" + Sha256Text(string.Join("|",
            [
                "design-conversion-local-promotion-uploader-authority-fingerprint-v1",
                "ConfiguredUploaderUntrusted",
                uploader.GetType().FullName!,
                uploader.MaximumSerializedReceiptUtf8Bytes.ToString(
                    CultureInfo.InvariantCulture),
                preflightFingerprintSha256,
                JsonlDesignConversionLocalArtifactDb
                    .MaxTrainingIntakeLocalPromotionOperationJournalRowByteLength
                    .ToString(CultureInfo.InvariantCulture)
            ]));
    }


    [Theory]
    [InlineData("Prepare")]
    [InlineData("Intent")]
    [InlineData("Prepared")]
    [InlineData("Committed")]
    public async Task LocalArtifactDb_PromotionOperationJournal_CrashRestartHonorsPhaseAndNeverRepeatsPreparedSideEffects(
        string crashPhase)
    {
        var root = Path.Combine(
            Path.GetTempPath(),
            Guid.NewGuid().ToString("N"),
            $"promotion-operation-crash-{crashPhase.ToLowerInvariant()}");
        var output = Path.Combine(root, "promotion-output");
        var operationPath = Path.Combine(
            root,
            JsonlDesignConversionLocalArtifactDb.TrainingIntakeLocalPromotionOperationFileName);
        var projectionPath = Path.Combine(
            root,
            JsonlDesignConversionLocalArtifactDb.TrainingIntakeLocalPromotionFileName);
        try
        {
            var fixture = await BuildW085DeterministicPromotionReadyIntakeFixtureAsync(
                root,
                $"operation-crash-{crashPhase.ToLowerInvariant()}");
            var admission = BuildLocalPromotionAdmission(
                $"operation-crash-{crashPhase.ToLowerInvariant()}");
            var pairStore = new RecordingDpoPairStore();
            var provider = CreateW085DeterministicPromotionProvider();
            var uploader = new CountingLocalOnlyPromotionUploader();
            var runnerCount = 0;
            var activationCount = 0;
            var injectedCount = 0;
            var injectedDb = new JsonlDesignConversionLocalArtifactDb(
                root,
                createTrainingIntakeJournalWaitTaskObserverForTesting: null,
                createTrainingIntakeJournalGateAcquiredCallbackForTesting: null,
                promotionUploader: uploader,
                runTrainingIntakeLocalPromotionRunnerBeforeInvokeObserverForTesting:
                    () => Interlocked.Increment(ref runnerCount),
                runTrainingIntakeLocalPromotionActivationInvokedObserverForTesting:
                    () => Interlocked.Increment(ref activationCount),
                dpoPolicyBaseProvider: provider,
                legalTeacherAdmissionAuthority: CreateEvaluatedLegalTeacherCapability(),
                trainingIntakeDpoPairStoreForTesting: pairStore,
                runTrainingIntakeLocalPromotionOperationPhaseObserverForTesting: phase =>
                {
                    if (!string.Equals(phase.ToString(), crashPhase, StringComparison.Ordinal))
                        return;
                    Interlocked.Increment(ref injectedCount);
                    if (crashPhase is "Prepared" or "Committed")
                    {
                        throw new SimulatedPromotionProcessDeathException(
                            $"injected durable {crashPhase} process death");
                    }
                    throw new IOException($"injected durable {crashPhase} crash");
                },
                localReceiptOnlyPromotionAuthority: uploader.Authority);

            OperationResult<DesignConversionTrainingIntakeLocalPromotionResult>?
                failed = null;
            if (crashPhase is "Prepared" or "Committed")
            {
                await Assert.ThrowsAsync<
                    SimulatedPromotionProcessDeathException>(() =>
                    RunLocalPromotionWithAdmissionAsync(
                        injectedDb,
                        fixture,
                        output,
                        admission));
            }
            else
            {
                failed = await RunLocalPromotionWithAdmissionAsync(
                    injectedDb,
                    fixture,
                    output,
                    admission);
            }

            if (string.Equals(crashPhase, "Prepare", StringComparison.Ordinal))
            {
                Assert.False(failed!.IsSuccess);
                Assert.Equal(
                    JsonlDesignConversionLocalArtifactDb.LocalArtifactDbWriteFailedErrorCode,
                    failed.ErrorCode);
            }
            else if (string.Equals(crashPhase, "Intent", StringComparison.Ordinal))
            {
                Assert.False(failed!.IsSuccess);
                Assert.Equal(
                    "DESIGN_CONVERSION_TRAINING_INTAKE_PROMOTE_LOCAL_INDETERMINATE_AFTER_INTENT",
                    failed.ErrorCode);
            }
            else
            {
                Assert.Null(failed);
            }
            Assert.Equal(1, injectedCount);
            var phaseNumbersBeforeRestart = await ReadLocalPromotionOperationPhaseNumbersAsync(
                operationPath);
            Assert.Equal(
                crashPhase switch
                {
                    "Prepare" => new[] { 0 },
                    "Intent" => new[] { 0, 1 },
                    "Prepared" => new[] { 0, 1, 2 },
                    "Committed" => new[] { 0, 1, 2, 3 },
                    _ => throw new InvalidOperationException(
                        $"Unexpected crash phase: {crashPhase}")
                },
                phaseNumbersBeforeRestart);
            var operationJournalBytesBeforeRestart =
                await File.ReadAllBytesAsync(operationPath);
            var artifactsBeforeRestart = await ReadFileSha256SnapshotAsync(output);
            var beforeRestartRunnerCount = runnerCount;
            var beforeRestartProviderCount = provider.InvocationCount;
            var beforeRestartUploaderCount = uploader.Count;
            var beforeRestartActivationCount = activationCount;
            var beforeRestartPairAddCount = pairStore.AddCallCount;
            var stoppedBeforeTraining = crashPhase is "Prepare" or "Intent";
            Assert.Equal(stoppedBeforeTraining ? 0 : 1, beforeRestartRunnerCount);
            Assert.Equal(stoppedBeforeTraining ? 0 : 1, beforeRestartUploaderCount);
            Assert.Equal(stoppedBeforeTraining ? 0 : 1, beforeRestartActivationCount);
            Assert.Equal(stoppedBeforeTraining ? 0 : 1, beforeRestartPairAddCount);
            Assert.Equal(stoppedBeforeTraining ? 0 : 1, beforeRestartProviderCount);
            var pairsBeforeRestart = pairStore.GetAll();
            Assert.True(pairsBeforeRestart.IsSuccess, pairsBeforeRestart.ErrorMessage);
            Assert.Equal(stoppedBeforeTraining ? 0 : 1, pairsBeforeRestart.Value!.Count);
            Assert.False(File.Exists(projectionPath));

            var retryDb = new JsonlDesignConversionLocalArtifactDb(
                root,
                createTrainingIntakeJournalWaitTaskObserverForTesting: null,
                createTrainingIntakeJournalGateAcquiredCallbackForTesting: null,
                promotionUploader: uploader,
                runTrainingIntakeLocalPromotionRunnerBeforeInvokeObserverForTesting:
                    () => Interlocked.Increment(ref runnerCount),
                runTrainingIntakeLocalPromotionActivationInvokedObserverForTesting:
                    () => Interlocked.Increment(ref activationCount),
                dpoPolicyBaseProvider: provider,
                legalTeacherAdmissionAuthority: CreateEvaluatedLegalTeacherCapability(),
                trainingIntakeDpoPairStoreForTesting: pairStore,
                localReceiptOnlyPromotionAuthority: uploader.Authority);

            var retry = await RunLocalPromotionWithAdmissionAsync(
                retryDb,
                fixture,
                output,
                admission);

            if (string.Equals(crashPhase, "Intent", StringComparison.Ordinal))
            {
                Assert.False(retry.IsSuccess);
                Assert.Equal(
                    "DESIGN_CONVERSION_TRAINING_INTAKE_PROMOTE_LOCAL_INDETERMINATE_AFTER_INTENT",
                    retry.ErrorCode);
                Assert.Equal(beforeRestartRunnerCount, runnerCount);
                Assert.Equal(beforeRestartProviderCount, provider.InvocationCount);
                Assert.Equal(beforeRestartUploaderCount, uploader.Count);
                Assert.Equal(beforeRestartActivationCount, activationCount);
                Assert.Equal(beforeRestartPairAddCount, pairStore.AddCallCount);
                Assert.Equal(phaseNumbersBeforeRestart, await ReadLocalPromotionOperationPhaseNumbersAsync(
                    operationPath));
                Assert.Equal(
                    operationJournalBytesBeforeRestart,
                    await File.ReadAllBytesAsync(operationPath));
                Assert.Equal(
                    artifactsBeforeRestart,
                    await ReadFileSha256SnapshotAsync(output));
                Assert.False(File.Exists(projectionPath));
                return;
            }

            Assert.True(retry.IsSuccess, retry.ErrorMessage);
            Assert.True(retry.Value!.LocalPromotionReady);
            Assert.Equal(1, runnerCount);
            Assert.Equal(1, provider.InvocationCount);
            Assert.Equal(1, uploader.Count);
            Assert.Equal(1, activationCount);
            Assert.Equal(1, pairStore.AddCallCount);
            var retainedPairs = pairStore.GetAll();
            Assert.True(retainedPairs.IsSuccess, retainedPairs.ErrorMessage);
            Assert.Single(retainedPairs.Value!);
            if (crashPhase is "Prepared" or "Committed")
            {
                Assert.Equal(beforeRestartRunnerCount, runnerCount);
                Assert.Equal(beforeRestartProviderCount, provider.InvocationCount);
                Assert.Equal(beforeRestartUploaderCount, uploader.Count);
                Assert.Equal(beforeRestartActivationCount, activationCount);
                Assert.Equal(beforeRestartPairAddCount, pairStore.AddCallCount);
                Assert.Equal(
                    artifactsBeforeRestart,
                    await ReadFileSha256SnapshotAsync(output));
            }
            var operationJournalBytesAfterRestart =
                await File.ReadAllBytesAsync(operationPath);
            Assert.Equal(
                [0, 1, 2, 3],
                await ReadLocalPromotionOperationPhaseNumbersAsync(operationPath));
            if (string.Equals(crashPhase, "Prepared", StringComparison.Ordinal))
            {
                Assert.True(
                    operationJournalBytesAfterRestart.Length >
                    operationJournalBytesBeforeRestart.Length);
                Assert.True(operationJournalBytesAfterRestart
                    .AsSpan(0, operationJournalBytesBeforeRestart.Length)
                    .SequenceEqual(operationJournalBytesBeforeRestart));
            }
            else if (string.Equals(crashPhase, "Committed", StringComparison.Ordinal))
            {
                Assert.Equal(
                    operationJournalBytesBeforeRestart,
                    operationJournalBytesAfterRestart);
            }
            var projection = Assert.Single(
                await ReadLocalPromotionProjectionRecordsAsync(projectionPath));
            Assert.False(string.IsNullOrWhiteSpace(
                projection.BoundaryMetadata["local_promotion_operation_id"]));
            Assert.Equal(
                projection.BoundaryMetadata["local_promotion_committed_snapshot_sha256"],
                retry.Value.BoundaryMetadata["local_promotion_committed_snapshot_sha256"]);
            Assert.Equal(
                bool.FalseString,
                retry.Value.BoundaryMetadata[
                    "training_intake_promote_local_retry_may_repeat_training"]);
            Assert.Equal(
                bool.TrueString,
                retry.Value.BoundaryMetadata[
                    "training_intake_promote_local_no_retrain_claimed"]);
        }
        finally
        {
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }


