    [Theory]
    [InlineData("cross-binding")]
    [InlineData("omitted-artifact")]
    [InlineData("out-of-root-artifact")]
    [InlineData("coherent-sibling-directory")]
    public async Task LocalArtifactDb_RehashedPreparedAuthorityForgeryFailsClosed(
        string mutation)
    {
        var root = Path.Combine(
            Path.GetTempPath(),
            Guid.NewGuid().ToString("N"),
            $"promotion-rehashed-forgery-{mutation}");
        var siblingRoot = root + "-sibling";
        try
        {
            var fixture = await BuildPromotionReadyIntakeFixtureAsync(
                root,
                $"promotion-rehashed-forgery-{mutation}");
            var admission = BuildLocalPromotionAdmission(
                $"promotion-rehashed-forgery-{mutation}");
            var pairRoot = Path.Combine(
                root,
                JsonlDesignConversionLocalArtifactDb
                    .TrainingIntakeDpoPairStoreDirectoryName);
            var pairStore = new FileDpoPairStore(pairRoot);
            var provider = new DesignConversionDpoPolicyBaseTestProvider();
            var uploader = new CountingLocalOnlyPromotionUploader();
            var runnerCount = 0;
            var promoted = await RunLocalPromotionWithAdmissionAsync(
                new JsonlDesignConversionLocalArtifactDb(
                    root,
                    createTrainingIntakeJournalWaitTaskObserverForTesting: null,
                    createTrainingIntakeJournalGateAcquiredCallbackForTesting: null,
                    promotionUploader: uploader,
                    runTrainingIntakeLocalPromotionRunnerBeforeInvokeObserverForTesting:
                        () => Interlocked.Increment(ref runnerCount),
                    dpoPolicyBaseProvider: provider,
                    legalTeacherAdmissionAuthority:
                        CreateEvaluatedLegalTeacherCapability(),
                    trainingIntakeDpoPairStoreForTesting: pairStore),
                fixture,
                Path.Combine(root, "output"),
                admission);
            Assert.True(promoted.IsSuccess, promoted.ErrorMessage);
            var counts = (
                runnerCount,
                provider.InvocationCount,
                uploader.Count);
            var pairStoreSnapshotBeforeForgery =
                await ReadFileSha256SnapshotAsync(pairRoot);
            var journalPath = Path.Combine(
                root,
                JsonlDesignConversionLocalArtifactDb
                    .TrainingIntakeLocalPromotionOperationFileName);
            var records = (await File.ReadAllLinesAsync(journalPath))
                .Select(line => JsonSerializer.Deserialize<
                    JsonlDesignConversionLocalArtifactDb
                        .LocalPromotionOperationJournalRecord>(
                    line,
                    DesignConversionCheckpointJsonOptions.Standard)!)
                .ToArray();
            var preparedIndex = Array.FindIndex(
                records,
                record => record.Phase ==
                    JsonlDesignConversionLocalArtifactDb
                        .LocalPromotionOperationPhase.Prepared);
            Assert.True(preparedIndex >= 0);
            var prepared = records[preparedIndex];
            if (string.Equals(
                    mutation,
                    "coherent-sibling-directory",
                    StringComparison.Ordinal))
            {
                Assert.NotEmpty(prepared.ArtifactDescriptors);
                var forgedDirectory = Path.Combine(
                    root,
                    "forged-artifact-sibling");
                Directory.CreateDirectory(forgedDirectory);
                var rewrittenPaths = new Dictionary<string, string>(
                    OperatingSystem.IsWindows()
                        ? StringComparer.OrdinalIgnoreCase
                        : StringComparer.Ordinal);
                var descriptors = prepared.ArtifactDescriptors
                    .Select(descriptor =>
                    {
                        var forgedPath = Path.Combine(
                            forgedDirectory,
                            Path.GetFileName(descriptor.CanonicalPath));
                        File.Copy(
                            descriptor.CanonicalPath,
                            forgedPath,
                            overwrite: false);
                        rewrittenPaths[Path.GetFullPath(descriptor.CanonicalPath)] =
                            Path.GetFullPath(forgedPath);
                        return descriptor with { CanonicalPath = forgedPath };
                    })
                    .ToArray();
                string Rewrite(string path)
                    => rewrittenPaths[Path.GetFullPath(path)];
                DesignConversionTrainingManifestArtifactDescriptor RewriteDescriptor(
                    DesignConversionTrainingManifestArtifactDescriptor descriptor)
                    => descriptor with
                    {
                        CanonicalPath = Rewrite(descriptor.CanonicalPath)
                    };

                var finalResult = prepared.FinalResult!;
                var publication = finalResult.Publication!;
                var manifestArtifacts = publication.Manifest.PromotionArtifacts!;
                manifestArtifacts = manifestArtifacts with
                {
                    CheckpointPath = Rewrite(manifestArtifacts.CheckpointPath),
                    TokenizerPath = Rewrite(manifestArtifacts.TokenizerPath),
                    CanonicalBpeTokenizerPath =
                        manifestArtifacts.CanonicalBpeTokenizerPath is null
                            ? null
                            : Rewrite(manifestArtifacts.CanonicalBpeTokenizerPath),
                    SourceEncoderPath = Rewrite(manifestArtifacts.SourceEncoderPath!),
                    PolicyPath = Rewrite(manifestArtifacts.PolicyPath),
                    RuntimeCheckpointArtifact = RewriteDescriptor(
                        manifestArtifacts.RuntimeCheckpointArtifact!),
                    TokenizerArtifact = RewriteDescriptor(
                        manifestArtifacts.TokenizerArtifact!),
                    CanonicalBpeTokenizerArtifact =
                        manifestArtifacts.CanonicalBpeTokenizerArtifact is null
                            ? null
                            : RewriteDescriptor(
                                manifestArtifacts.CanonicalBpeTokenizerArtifact),
                    SourceEncoderContractArtifact = RewriteDescriptor(
                        manifestArtifacts.SourceEncoderContractArtifact!),
                    PolicyCheckpointContractArtifact = RewriteDescriptor(
                        manifestArtifacts.PolicyCheckpointContractArtifact!),
                    PolicyCheckpointArtifact = RewriteDescriptor(
                        manifestArtifacts.PolicyCheckpointArtifact!)
                };
                var manifest = publication.Manifest with
                {
                    PromotionArtifacts = manifestArtifacts
                };
                finalResult = finalResult with
                {
                    PromotionOutputDirectory = forgedDirectory,
                    PromotedCheckpointPath = Rewrite(
                        finalResult.PromotedCheckpointPath),
                    Publication = publication with { Manifest = manifest },
                    PromotedLocalModel = finalResult.PromotedLocalModel is null
                        ? null
                        : finalResult.PromotedLocalModel with
                        {
                            CheckpointPath = Rewrite(
                                finalResult.PromotedLocalModel.CheckpointPath)
                        }
                };
                var finalMetadata = new Dictionary<string, string>(
                    finalResult.BoundaryMetadata,
                    StringComparer.Ordinal);
                finalResult = finalResult with
                {
                    BoundaryMetadata = finalMetadata
                };
                var finalSha = JsonlDesignConversionLocalArtifactDb
                    .BuildLocalPromotionFinalResultSha256(finalResult);
                finalMetadata["local_promotion_committed_snapshot_sha256"] =
                    finalSha;
                finalResult = finalResult with
                {
                    BoundaryMetadata = finalMetadata
                };
                records[preparedIndex] = prepared with
                {
                    ArtifactDescriptors = descriptors,
                    FinalResult = finalResult,
                    FinalResultSha256 = finalSha
                };
                records[^1] = records[^1] with
                {
                    FinalResultSha256 = finalSha
                };
            }
            else if (string.Equals(mutation, "cross-binding", StringComparison.Ordinal))
            {
                var finalMetadata = new Dictionary<string, string>(
                    prepared.FinalResult!.BoundaryMetadata,
                    StringComparer.Ordinal)
                {
                    ["training_intake_tenant_id_ref"] = "tenant:forged"
                };
                var finalResult = prepared.FinalResult with
                {
                    BoundaryMetadata = finalMetadata
                };
                var finalSha = JsonlDesignConversionLocalArtifactDb
                    .BuildLocalPromotionFinalResultSha256(finalResult);
                finalMetadata["local_promotion_committed_snapshot_sha256"] =
                    finalSha;
                finalResult = finalResult with
                {
                    BoundaryMetadata = finalMetadata
                };
                records[preparedIndex] = prepared with
                {
                    FinalResult = finalResult,
                    FinalResultSha256 = finalSha
                };
                records[^1] = records[^1] with
                {
                    FinalResultSha256 = finalSha
                };
            }
            else
            {
                Assert.NotEmpty(prepared.ArtifactDescriptors);
                var descriptors = prepared.ArtifactDescriptors.ToArray();
                if (string.Equals(
                        mutation,
                        "out-of-root-artifact",
                        StringComparison.Ordinal))
                {
                    Directory.CreateDirectory(siblingRoot);
                    var original = descriptors[0];
                    var matchingBytes = await File.ReadAllBytesAsync(
                        original.CanonicalPath);
                    var siblingPath = Path.Combine(
                        siblingRoot,
                        Path.GetFileName(original.CanonicalPath));
                    await File.WriteAllBytesAsync(siblingPath, matchingBytes);
                    Assert.Equal(original.ByteLength, matchingBytes.LongLength);
                    Assert.Equal(
                        original.Sha256,
                        "sha256:" + Convert.ToHexString(
                                SHA256.HashData(matchingBytes))
                            .ToLowerInvariant());
                    descriptors[0] = original with
                    {
                        CanonicalPath = siblingPath
                    };
                }
                records[preparedIndex] = prepared with
                {
                    ArtifactDescriptors = string.Equals(
                        mutation,
                        "omitted-artifact",
                        StringComparison.Ordinal)
                        ? descriptors.Skip(1).ToArray()
                        : descriptors
                };
            }
            var previous = string.Empty;
            for (var index = 0; index < records.Length; index++)
            {
                records[index] = records[index] with
                {
                    PreviousRecordSha256 = previous,
                    RecordSha256 = string.Empty
                };
                records[index] = records[index] with
                {
                    RecordSha256 = JsonlDesignConversionLocalArtifactDb
                        .BuildLocalPromotionOperationRecordSha256(records[index])
                };
                previous = records[index].RecordSha256;
            }
            await WriteLocalPromotionOperationRecordsAsync(
                journalPath,
                records);

            var retry = await RunLocalPromotionWithAdmissionAsync(
                new JsonlDesignConversionLocalArtifactDb(
                    root,
                    createTrainingIntakeJournalWaitTaskObserverForTesting: null,
                    createTrainingIntakeJournalGateAcquiredCallbackForTesting: null,
                    dpoPolicyBaseProvider: provider,
                    legalTeacherAdmissionAuthority:
                        CreateEvaluatedLegalTeacherCapability(),
                    promotionUploader: uploader,
                    trainingIntakeDpoPairStoreForTesting:
                        new FileDpoPairStore(pairRoot)),
                fixture,
                Path.Combine(root, "output"),
                admission);
            Assert.False(retry.IsSuccess);
            Assert.Equal(
                "DESIGN_CONVERSION_TRAINING_INTAKE_PROMOTE_LOCAL_OPERATION_STATE_INVALID",
                retry.ErrorCode);
            Assert.Equal(counts, (
                runnerCount,
                provider.InvocationCount,
                uploader.Count));
            Assert.Equal(
                pairStoreSnapshotBeforeForgery,
                await ReadFileSha256SnapshotAsync(pairRoot));
        }
        finally
        {
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
            if (Directory.Exists(siblingRoot))
                Directory.Delete(siblingRoot, recursive: true);
        }
    }


    [Fact]
    public async Task LocalArtifactDb_RepositoryUploaderPreparedRestartBindsStableDestinationIdentities()
    {
        var root = DesignConversionPostEvaluationEligibilityTestFixture
            .CreateHandleBoundTempRoot(
                "promotion-repository-uploader-identity-restart");
        var output = Path.Combine(root, "output");
        const string serverBaseUrl = "https://models.example/promotion-repository";
        var repositoryIdentity = "sha256:" + new string('a', 64);
        var locatorIdentity = "sha256:" + new string('b', 64);
        var sharedLocatorRegistry = new SharedStateTestRemoteUnitRegistry(
            locatorIdentity);
        try
        {
            var fixture = await BuildPromotionReadyIntakeFixtureAsync(
                root,
                "promotion-repository-uploader-identity-restart");
            var admission = BuildLocalPromotionAdmission(
                "promotion-repository-uploader-identity-restart");
            var provider = new DesignConversionDpoPolicyBaseTestProvider();
            var runnerCount = 0;
            var firstUploader = new
                DesignConversionModelRepositoryPromotionUploader(
                    new LocalModelRepository(repositoryIdentity),
                    new SharedStateTestRemoteUnitLocator(sharedLocatorRegistry),
                    serverBaseUrl);
            var firstConfigurationFingerprint = firstUploader
                .PreflightConfigurationFingerprintSha256();
            Assert.True(
                firstConfigurationFingerprint.IsSuccess,
                firstConfigurationFingerprint.ErrorMessage);
            var firstAuthorityFingerprint =
                BuildConfiguredUploaderAuthorityFingerprint(
                    firstUploader,
                    firstConfigurationFingerprint.Value!);
            await Assert.ThrowsAsync<SimulatedPromotionProcessDeathException>(
                () => RunLocalPromotionWithAdmissionAsync(
                    new JsonlDesignConversionLocalArtifactDb(
                        root,
                        createTrainingIntakeJournalWaitTaskObserverForTesting: null,
                        createTrainingIntakeJournalGateAcquiredCallbackForTesting: null,
                        promotionUploader: firstUploader,
                        runTrainingIntakeLocalPromotionRunnerBeforeInvokeObserverForTesting:
                            () => Interlocked.Increment(ref runnerCount),
                        dpoPolicyBaseProvider: provider,
                        legalTeacherAdmissionAuthority:
                            CreateEvaluatedLegalTeacherCapability(),
                        runTrainingIntakeLocalPromotionOperationPhaseObserverForTesting:
                            phase =>
                            {
                                if (phase == JsonlDesignConversionLocalArtifactDb
                                        .LocalPromotionOperationPhase.Prepared)
                                {
                                    throw new SimulatedPromotionProcessDeathException(
                                        "injected repository Prepared process death");
                                }
                            }),
                    fixture,
                    output,
                    admission));
            Assert.Equal(1, runnerCount);
            var providerCount = provider.InvocationCount;
            var operationPath = Path.Combine(
                root,
                JsonlDesignConversionLocalArtifactDb
                    .TrainingIntakeLocalPromotionOperationFileName);
            var preparedRecords = await ReadLocalPromotionOperationRecordsAsync(
                operationPath);
            Assert.Equal(
                [0, 1, 2],
                preparedRecords.Select(record => (int)record.Phase));
            var preparedRecord = preparedRecords.Single(record =>
                record.Phase == JsonlDesignConversionLocalArtifactDb
                    .LocalPromotionOperationPhase.Prepared);
            Assert.Equal(
                "ConfiguredUploaderUntrusted",
                preparedRecord.UploaderAuthorityMode);
            Assert.Equal(
                firstAuthorityFingerprint,
                preparedRecord.UploaderConfigurationFingerprintSha256);
            Assert.Equal(
                firstAuthorityFingerprint,
                preparedRecord.FinalResult!.BoundaryMetadata[
                    "local_promotion_uploader_configuration_fingerprint_sha256"]);
            Assert.False(preparedRecord.FinalResult.LocalPromotionReady);
            Assert.NotNull(preparedRecord.FinalResult.Publication);
            Assert.False(
                preparedRecord.FinalResult.Publication!.Decision.AllowsUpload);
            Assert.Contains(
                "BUDGET_TIER_POLICY_FAILED",
                preparedRecord.FinalResult.Publication.Decision.Reasons);
            Assert.Empty(sharedLocatorRegistry.Manifests);

            var changedLocatorRegistry = new SharedStateTestRemoteUnitRegistry(
                "sha256:" + new string('d', 64));
            var changedIdentityUploader = new
                DesignConversionModelRepositoryPromotionUploader(
                    new LocalModelRepository(repositoryIdentity),
                    new SharedStateTestRemoteUnitLocator(changedLocatorRegistry),
                    serverBaseUrl);
            var changedConfigurationFingerprint = changedIdentityUploader
                .PreflightConfigurationFingerprintSha256();
            Assert.True(
                changedConfigurationFingerprint.IsSuccess,
                changedConfigurationFingerprint.ErrorMessage);
            Assert.NotEqual(
                firstConfigurationFingerprint.Value,
                changedConfigurationFingerprint.Value);
            var changedAuthorityFingerprint = BuildConfiguredUploaderAuthorityFingerprint(
                changedIdentityUploader,
                changedConfigurationFingerprint.Value!);
            Assert.NotEqual(firstAuthorityFingerprint, changedAuthorityFingerprint);
            var rejected = await RunLocalPromotionWithAdmissionAsync(
                new JsonlDesignConversionLocalArtifactDb(
                    root,
                    CreateEvaluatedLegalTeacherCapability(),
                    dpoPolicyBaseProvider: provider,
                    promotionUploader: changedIdentityUploader),
                fixture,
                output,
                admission);
            Assert.False(rejected.IsSuccess);
            Assert.Equal(
                "DESIGN_CONVERSION_TRAINING_INTAKE_PROMOTE_LOCAL_OPERATION_STATE_INVALID",
                rejected.ErrorCode);
            Assert.Equal(1, runnerCount);
            Assert.Equal(providerCount, provider.InvocationCount);
            Assert.Empty(changedLocatorRegistry.Manifests);
            Assert.Empty(sharedLocatorRegistry.Manifests);
            Assert.Equal(
                [0, 1, 2],
                await ReadLocalPromotionOperationPhaseNumbersAsync(operationPath));

            var sameIdentityFreshUploader = new
                DesignConversionModelRepositoryPromotionUploader(
                    new LocalModelRepository(repositoryIdentity),
                    new SharedStateTestRemoteUnitLocator(sharedLocatorRegistry),
                    serverBaseUrl);
            var sameIdentityConfigurationFingerprint = sameIdentityFreshUploader
                .PreflightConfigurationFingerprintSha256();
            Assert.True(
                sameIdentityConfigurationFingerprint.IsSuccess,
                sameIdentityConfigurationFingerprint.ErrorMessage);
            Assert.Equal(
                firstConfigurationFingerprint.Value,
                sameIdentityConfigurationFingerprint.Value);
            var sameIdentityAuthorityFingerprint =
                BuildConfiguredUploaderAuthorityFingerprint(
                    sameIdentityFreshUploader,
                    sameIdentityConfigurationFingerprint.Value!);
            Assert.Equal(firstAuthorityFingerprint, sameIdentityAuthorityFingerprint);
            var recovered = await RunLocalPromotionWithAdmissionAsync(
                new JsonlDesignConversionLocalArtifactDb(
                    root,
                    CreateEvaluatedLegalTeacherCapability(),
                    dpoPolicyBaseProvider: provider,
                    promotionUploader: sameIdentityFreshUploader),
                fixture,
                output,
                admission);
            Assert.True(recovered.IsSuccess, recovered.ErrorMessage);
            Assert.Equal(1, runnerCount);
            Assert.Equal(providerCount, provider.InvocationCount);
            Assert.False(recovered.Value!.LocalPromotionReady);
            Assert.Equal(
                bool.TrueString,
                recovered.Value.BoundaryMetadata[
                    "training_intake_idempotency_replay_hit"]);
            Assert.Empty(sharedLocatorRegistry.Manifests);

            var canonicalRemoteRegistry = new SharedStateTestRemoteUnitRegistry(
                locatorIdentity);
            var canonicalRemoteLocator =
                new SharedStateTestRemoteUnitLocator(canonicalRemoteRegistry);
            var canonicalRemoteUploader = new
                DesignConversionModelRepositoryPromotionUploader(
                    new LocalModelRepository(repositoryIdentity),
                    canonicalRemoteLocator,
                    serverBaseUrl);
            var canonicalRemoteFixture =
                await BuildValidatedEvaluatedPublisherFixtureAsync(
                    root,
                    "promotion-repository-uploader-remote-registration");
            var canonicalRemotePublication = await new
                    DesignConversionPromotionPublisher(canonicalRemoteUploader)
                .PublishEvaluatedDpoAsync(
                    canonicalRemoteFixture.Machine,
                    canonicalRemoteFixture.CompletedRunnerResult,
                    "promotion-repository-uploader-remote-registration-manifest",
                    canonicalRemoteFixture.ArtifactPublication,
                    canonicalRemoteFixture.PassingGateReport,
                    CancellationToken.None);

            Assert.True(
                canonicalRemotePublication.IsSuccess,
                canonicalRemotePublication.ErrorMessage);
            Assert.Equal(
                DesignConversionPromotionPublicationKind
                    .VerifiedModelServerUpload,
                canonicalRemotePublication.Value!.PublicationKind);
            Assert.Equal(2, canonicalRemoteRegistry.Manifests.Count);
            Assert.True(canonicalRemoteRegistry.Manifests.ContainsKey(
                DesignConversionRuntimeScaffoldCriticUnit.UnitId));
            Assert.True(canonicalRemoteRegistry.Manifests.ContainsKey(
                DesignConversionRuntimeScaffoldImproverUnit.UnitId));
            Assert.Contains(
                "UPLOAD_RECEIPT_EVIDENCE_SHA256:" +
                Sha256Text("REMOTE_LOCATOR_REGISTERED_BOTH_UNITS"),
                canonicalRemotePublication.Value.UploadReceipt!.EvidenceRefs);
            Assert.Contains(
                "UPLOAD_RECEIPT_EVIDENCE_SHA256:" +
                Sha256Text("REMOTE_LOCATOR_LOCATED_BOTH_UNITS"),
                canonicalRemotePublication.Value.UploadReceipt.EvidenceRefs);
            var unknownRemoteUnit = await canonicalRemoteLocator.LocateAsync(
                "design_conversion_unknown_remote_unit");
            Assert.False(unknownRemoteUnit.IsSuccess);
            Assert.Equal("REMOTE_UNIT_NOT_FOUND", unknownRemoteUnit.ErrorCode);
            Assert.Equal(
                [0, 1, 2, 3],
                await ReadLocalPromotionOperationPhaseNumbersAsync(operationPath));
        }
        finally
        {
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }

        static string BuildConfiguredUploaderAuthorityFingerprint(
            DesignConversionModelRepositoryPromotionUploader uploader,
            string preflightFingerprintSha256)
            => "sha256:" + Sha256Text(string.Join("|",
            [
                "design-conversion-local-promotion-uploader-authority-fingerprint-v1",
                "ConfiguredUploaderUntrusted",
                uploader.GetType().FullName!,
                uploader.MaximumSerializedReceiptUtf8Bytes.ToString(
                    CultureInfo.InvariantCulture),
                preflightFingerprintSha256,
                JsonlDesignConversionLocalArtifactDb
                    .MaxTrainingIntakeLocalPromotionOperationJournalRowByteLength
                    .ToString(CultureInfo.InvariantCulture)
            ]));
    }


    [Theory]
    [InlineData("after-pair-reservation")]
    [InlineData("after-output-reservation")]
    public async Task LocalArtifactDb_ReservationWindowProcessDeathRecoversOnceWithoutMarkerOrPairDuplicates(
        string window)
    {
        var root = Path.Combine(
            Path.GetTempPath(),
            Guid.NewGuid().ToString("N"),
            $"promotion-reservation-window-{window}");
        var output = Path.Combine(root, "output");
        try
        {
            var fixture = await BuildW085DeterministicPromotionReadyIntakeFixtureAsync(
                root,
                $"promotion-reservation-window-{window}");
            var admission = BuildLocalPromotionAdmission(
                $"promotion-reservation-window-{window}");
            var uploader = new CountingLocalOnlyPromotionUploader();
            var authority = uploader.Authority;
            var provider = CreateW085DeterministicPromotionProvider();
            var runnerCount = 0;
            var activationCount = 0;
            Action crash = () => throw new
                SimulatedPromotionProcessDeathException(
                    $"injected {window} process death");
            await Assert.ThrowsAsync<SimulatedPromotionProcessDeathException>(
                () => RunLocalPromotionWithAdmissionAsync(
                    new JsonlDesignConversionLocalArtifactDb(
                        root,
                        createTrainingIntakeJournalWaitTaskObserverForTesting: null,
                        createTrainingIntakeJournalGateAcquiredCallbackForTesting: null,
                        promotionUploader: uploader,
                        runTrainingIntakeLocalPromotionRunnerBeforeInvokeObserverForTesting:
                            () => Interlocked.Increment(ref runnerCount),
                        runTrainingIntakeLocalPromotionActivationInvokedObserverForTesting:
                            () => Interlocked.Increment(ref activationCount),
                        dpoPolicyBaseProvider: provider,
                        legalTeacherAdmissionAuthority:
                            CreateEvaluatedLegalTeacherCapability(),
                        runTrainingIntakeLocalPromotionAfterPairReservationObserverForTesting:
                            string.Equals(
                                window,
                                "after-pair-reservation",
                                StringComparison.Ordinal)
                                ? crash
                                : null,
                        runTrainingIntakeLocalPromotionAfterOutputReservationObserverForTesting:
                            string.Equals(
                                window,
                                "after-output-reservation",
                                StringComparison.Ordinal)
                                ? crash
                                : null,
                        localReceiptOnlyPromotionAuthority: authority),
                    fixture,
                    output,
                    admission));
            Assert.Equal(0, runnerCount);
            Assert.Equal(0, provider.InvocationCount);
            Assert.Equal(0, uploader.Count);
            Assert.Equal(0, activationCount);
            Assert.False(File.Exists(Path.Combine(
                root,
                JsonlDesignConversionLocalArtifactDb
                    .TrainingIntakeLocalPromotionOperationFileName)));
            var pairRoot = Path.Combine(
                root,
                JsonlDesignConversionLocalArtifactDb
                    .TrainingIntakeDpoPairStoreDirectoryName);
            var pairReservationPath = Path.Combine(
                pairRoot,
                ".dpo-pair-batch-reservation.json");
            Assert.True(File.Exists(pairReservationPath));
            var pairReservationBytes =
                await File.ReadAllBytesAsync(pairReservationPath);
            using var pairReservationDocument = JsonDocument.Parse(
                pairReservationBytes);
            var pairReservationId = pairReservationDocument.RootElement
                .GetProperty("ReservationId").GetString()!;
            var pairReservationSha256 = pairReservationDocument.RootElement
                .GetProperty("BatchSha256").GetString()!;
            Assert.Equal(
                1,
                pairReservationDocument.RootElement
                    .GetProperty("PairCount").GetInt32());
            Assert.Single(pairReservationDocument.RootElement
                .GetProperty("PairIds").EnumerateArray());
            const string pairReservationSuffix = ":dpo-pair-batch-v1";
            Assert.EndsWith(
                pairReservationSuffix,
                pairReservationId,
                StringComparison.Ordinal);
            var operationId = pairReservationId[..^pairReservationSuffix.Length];
            var outputReservationRoot = Path.Combine(
                root,
                ".training-intake-local-promotion-output-reservations");
            Assert.Equal(
                string.Equals(
                    window,
                    "after-output-reservation",
                    StringComparison.Ordinal),
                Directory.Exists(outputReservationRoot));
            var outputReservationPath = Path.Combine(
                outputReservationRoot,
                $"{Sha256Text(operationId)}.json");
            byte[]? retainedOutputReservationBytes = null;
            if (string.Equals(
                    window,
                    "after-output-reservation",
                    StringComparison.Ordinal))
            {
                Assert.True(File.Exists(outputReservationPath));
                var runId = fixture.Options.RunId!;
                var requestedPaths =
                    DesignConversionDpoPromotionArtifactContractCodec.ResolvePaths(
                        root,
                        output,
                        runId);
                Assert.True(requestedPaths.IsSuccess, requestedPaths.ErrorMessage);
                var canonicalPaths =
                    DesignConversionDpoPromotionArtifactContractCodec.ResolvePaths(
                        root,
                        Path.Combine(
                            requestedPaths.Value!.OutputDirectory,
                            $"dpo-{Sha256Text(runId)[..12]}-dpo-policy-checkpoints"),
                        runId);
                Assert.True(canonicalPaths.IsSuccess, canonicalPaths.ErrorMessage);
                var fingerprint = uploader
                    .PreflightConfigurationFingerprintSha256();
                Assert.True(fingerprint.IsSuccess, fingerprint.ErrorMessage);
                var authorityValidation = authority.Validate(
                    uploader,
                    fingerprint.Value!,
                    uploader.MaximumSerializedReceiptUtf8Bytes);
                Assert.True(
                    authorityValidation.IsSuccess,
                    authorityValidation.ErrorMessage);
                var uploaderAuthorityMode =
                    DesignConversionPromotionUploadAuthorityMode
                        .LocalReceiptOnly
                        .ToString();
                var authorityFingerprint =
                    authorityValidation.Value!.StableAuthorityFingerprintSha256;
                var uploaderEnvelopeSha256 = "sha256:" + Sha256Text(string.Join(
                    "|",
                    [
                        "design-conversion-promotion-uploader-envelope-v1",
                        uploaderAuthorityMode,
                        uploader.GetType().FullName!,
                        authorityFingerprint,
                        uploader.MaximumSerializedReceiptUtf8Bytes.ToString(
                            CultureInfo.InvariantCulture),
                        JsonlDesignConversionLocalArtifactDb
                            .MaxTrainingIntakeLocalPromotionOperationJournalRowByteLength
                            .ToString(CultureInfo.InvariantCulture)
                    ]));
                var reservationSha256 = "sha256:" + Sha256Text(string.Join(
                    "|",
                    [
                        "design-conversion-local-promotion-output-namespace-reservation-v1",
                        operationId,
                        canonicalPaths.Value!.OutputDirectory,
                        pairReservationId,
                        pairReservationSha256,
                        uploaderEnvelopeSha256,
                        uploaderAuthorityMode,
                        authorityFingerprint
                    ]));
                var expectedMarkerBytes = SerializeCompact(
                    new
                    {
                        SchemaVersion =
                            "design-conversion-training-intake-local-promotion-output-reservation-v1",
                        Version = 1,
                        OperationId = operationId,
                        CanonicalOutputDirectory = canonicalPaths.Value.OutputDirectory,
                        PairStoreReservationId = pairReservationId,
                        PairStoreReservationSha256 = pairReservationSha256,
                        UploaderEnvelopeReservationSha256 = uploaderEnvelopeSha256,
                        UploaderAuthorityMode = uploaderAuthorityMode,
                        UploaderConfigurationFingerprintSha256 =
                            authorityFingerprint,
                        ReservationSha256 = reservationSha256
                    });
                Assert.Equal(
                    expectedMarkerBytes,
                    await File.ReadAllBytesAsync(outputReservationPath));
                retainedOutputReservationBytes = expectedMarkerBytes;
            }
            else
            {
                Assert.False(File.Exists(outputReservationPath));
            }

            var recovered = await RunLocalPromotionWithAdmissionAsync(
                new JsonlDesignConversionLocalArtifactDb(
                    root,
                    createTrainingIntakeJournalWaitTaskObserverForTesting: null,
                    createTrainingIntakeJournalGateAcquiredCallbackForTesting: null,
                    promotionUploader: uploader,
                    runTrainingIntakeLocalPromotionRunnerBeforeInvokeObserverForTesting:
                        () => Interlocked.Increment(ref runnerCount),
                    runTrainingIntakeLocalPromotionActivationInvokedObserverForTesting:
                        () => Interlocked.Increment(ref activationCount),
                    dpoPolicyBaseProvider: provider,
                    legalTeacherAdmissionAuthority:
                        CreateEvaluatedLegalTeacherCapability(),
                    localReceiptOnlyPromotionAuthority: authority),
                fixture,
                output,
                admission);
            Assert.True(recovered.IsSuccess, recovered.ErrorMessage);
            Assert.Equal(1, runnerCount);
            Assert.Equal(1, provider.InvocationCount);
            Assert.Equal(1, uploader.Count);
            Assert.Equal(1, activationCount);
            Assert.False(File.Exists(pairReservationPath));
            Assert.Single(Directory.EnumerateFiles(
                pairRoot,
                "*.dpo-pair.json",
                SearchOption.TopDirectoryOnly));
            Assert.Single(Directory.EnumerateFiles(
                outputReservationRoot,
                "*.json",
                SearchOption.TopDirectoryOnly));
            var operationPath = Path.Combine(
                root,
                JsonlDesignConversionLocalArtifactDb
                    .TrainingIntakeLocalPromotionOperationFileName);
            Assert.Equal(
                [0, 1, 2, 3],
                await ReadLocalPromotionOperationPhaseNumbersAsync(operationPath));
            var operationRecords =
                await ReadLocalPromotionOperationRecordsAsync(operationPath);
            Assert.All(operationRecords, record =>
            {
                Assert.Equal(pairReservationId, record.PairStoreReservationId);
                Assert.Equal(
                    pairReservationSha256,
                    record.PairStoreReservationSha256);
                Assert.Equal(outputReservationPath, record.OutputNamespaceReservationRef);
                Assert.Single(record.PairStoreInputSha256s);
            });
            var outputReservationBytes =
                await File.ReadAllBytesAsync(outputReservationPath);
            if (retainedOutputReservationBytes is not null)
            {
                Assert.Equal(
                    retainedOutputReservationBytes,
                    outputReservationBytes);
            }
            using (var outputReservationDocument = JsonDocument.Parse(
                       outputReservationBytes))
            {
                Assert.Equal(
                    pairReservationId,
                    outputReservationDocument.RootElement
                        .GetProperty("pairStoreReservationId").GetString());
                Assert.Equal(
                    pairReservationSha256,
                    outputReservationDocument.RootElement
                        .GetProperty("pairStoreReservationSha256").GetString());
                Assert.Equal(
                    operationRecords[0].OutputNamespaceReservationSha256,
                    outputReservationDocument.RootElement
                        .GetProperty("reservationSha256").GetString());
            }
            var projectionPath = Path.Combine(
                root,
                JsonlDesignConversionLocalArtifactDb
                    .TrainingIntakeLocalPromotionFileName);
            Assert.Single(
                await ReadLocalPromotionProjectionRecordsAsync(projectionPath));
            var physicalSnapshot = await ReadFileSha256SnapshotAsync(root);
            var replay = await RunLocalPromotionWithAdmissionAsync(
                new JsonlDesignConversionLocalArtifactDb(
                    root,
                    createTrainingIntakeJournalWaitTaskObserverForTesting: null,
                    createTrainingIntakeJournalGateAcquiredCallbackForTesting: null,
                    promotionUploader: uploader,
                    runTrainingIntakeLocalPromotionRunnerBeforeInvokeObserverForTesting:
                        () => Interlocked.Increment(ref runnerCount),
                    runTrainingIntakeLocalPromotionActivationInvokedObserverForTesting:
                        () => Interlocked.Increment(ref activationCount),
                    dpoPolicyBaseProvider: provider,
                    legalTeacherAdmissionAuthority:
                        CreateEvaluatedLegalTeacherCapability(),
                    localReceiptOnlyPromotionAuthority: authority),
                fixture,
                output,
                admission);
            Assert.True(replay.IsSuccess, replay.ErrorMessage);
            Assert.Equal(
                bool.TrueString,
                replay.Value!.BoundaryMetadata[
                    "training_intake_idempotency_replay_hit"]);
            Assert.Equal(1, runnerCount);
            Assert.Equal(1, provider.InvocationCount);
            Assert.Equal(1, uploader.Count);
            Assert.Equal(1, activationCount);
            Assert.Equal(
                physicalSnapshot,
                await ReadFileSha256SnapshotAsync(root));
            Assert.Equal(
                [0, 1, 2, 3],
                await ReadLocalPromotionOperationPhaseNumbersAsync(operationPath));
            Assert.Single(
                await ReadLocalPromotionProjectionRecordsAsync(projectionPath));
        }
        finally
        {
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }


