    [Fact]
    public void LocalArtifactDb_W085PromotionFixtureRejectsCustodyHashSubstitution()
    {
        var candidate = WithRuntimeArtifactProofRefs(
            ToRuntimeApprovedCandidate(
                WithSourceIdentity(
                    BuildTrainingRecord(
                        "promotion-custody-hash-substitution",
                        DesignConversionDpoUnits.ImproverUnit,
                        usefulness: 0.97),
                    "promotion-custody-hash-substitution-source")),
            "promotion-custody-hash-substitution");
        candidate = AttachW085OptimizerPayloadCustody(
            candidate,
            rejectedHtml: "<main class=\"candidate-r\">R</main>",
            rejectedCss: ".candidate-r{display:block;}");
        var payload = Assert.IsType<DesignConversionDpoPayloadCustodySecret>(
            candidate.PayloadCustodySecret);
        var tamperedChosenSha256 = "sha256:" + new string('0', 64);
        Assert.NotEqual(payload.ChosenResponseSha256, tamperedChosenSha256);

        var preCustodyMetadata = new Dictionary<string, string>(
            candidate.Provenance.Metadata,
            StringComparer.Ordinal);
        foreach (var key in new[]
                 {
                     DesignConversionDpoGenerator.PayloadCustodyRequiredMetadataKey,
                     DesignConversionDpoGenerator.PayloadCustodyVersionMetadataKey,
                     DesignConversionDpoGenerator.PayloadCustodyPromptSha256MetadataKey,
                     DesignConversionDpoGenerator.PayloadCustodyChosenSha256MetadataKey,
                     DesignConversionDpoGenerator.PayloadCustodyRejectedSha256MetadataKey,
                     DesignConversionDpoGenerator.PayloadCustodyGovernanceSha256MetadataKey,
                     DesignConversionDpoGenerator.PayloadCustodyBindingSha256MetadataKey,
                     "payload_custody_raw_in_public_record"
                 })
        {
            preCustodyMetadata.Remove(key);
        }
        var preCustodyRecord = candidate with
        {
            Provenance = candidate.Provenance with
            {
                Metadata = preCustodyMetadata
            },
            PayloadCustodySecret = null
        };
        var tamperedBinding = DesignConversionDpoGenerator.BuildPayloadCustodyBinding(
            preCustodyRecord,
            payload.PromptSha256,
            tamperedChosenSha256,
            payload.RejectedResponseSha256,
            payload.GovernanceSha256);
        var tamperedMetadata = new Dictionary<string, string>(
            candidate.Provenance.Metadata,
            StringComparer.Ordinal)
        {
            [DesignConversionDpoGenerator.PayloadCustodyChosenSha256MetadataKey] =
                tamperedChosenSha256,
            [DesignConversionDpoGenerator.PayloadCustodyBindingSha256MetadataKey] =
                tamperedBinding
        };
        var tampered = candidate with
        {
            Provenance = candidate.Provenance with { Metadata = tamperedMetadata },
            PayloadCustodySecret = new DesignConversionDpoPayloadCustodySecret(
                payload.Version,
                payload.Prompt,
                payload.ChosenResponse,
                payload.RejectedResponse,
                payload.PromptSha256,
                tamperedChosenSha256,
                payload.RejectedResponseSha256,
                payload.GovernanceSha256,
                tamperedBinding)
        };

        var validation = JsonlDesignConversionLocalArtifactDb
            .ValidateAndMaterializePayloadCustody(tampered);

        Assert.False(validation.IsSuccess);
        Assert.Equal(
            "DESIGN_CONVERSION_DPO_PAYLOAD_CUSTODY_FAILED",
            validation.ErrorCode);
    }


    [Theory]
    [InlineData("CANCELLED")]
    [InlineData("DESIGN_CONVERSION_PROMOTION_UPLOAD_TIMEOUT")]
    public async Task LocalArtifactDb_ReturnedUploaderFailureAfterIntentBecomesIndeterminateAndNeverRetrains(
        string returnedErrorCode)
    {
        var failureCase = string.Equals(
            returnedErrorCode,
            "CANCELLED",
            StringComparison.Ordinal)
                ? "cancelled"
                : "timeout";
        var root = Path.Combine(
            Path.GetTempPath(),
            Guid.NewGuid().ToString("N"),
            $"promotion-returned-failure-{failureCase}");
        var output = Path.Combine(root, "output");
