    [Fact]
    public async Task LocalPromotionJournalSet_LinuxAppendsAndReadsAfterCustodyChecksWithoutNtfsStreamProbe()
    {
        if (!OperatingSystem.IsLinux())
            return;
        var root = Path.Combine(
            Path.GetTempPath(),
            Guid.NewGuid().ToString("N"),
            "local-promotion-linux-no-ntfs-stream-probe");
        const string operationLeaf = "training-intake-local-promotion-operations.jsonl";
        const string projectionLeaf = "training-intake-local-promotions.jsonl";
        var mutationLeaf = projectionLeaf + ".mutation.lock";
        var operationLine =
            "{\"recordSha256\":\"sha256:aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa\"}";
        const string projectionLine = "{\"projection\":true}";
        try
        {
            Directory.CreateDirectory(root);
            await using var mutationLease =
                AcquireLocalPromotionJournalMutationLeaseForTesting(root, mutationLeaf);
            var journal = new DesignConversionLocalPromotionJournalSet(
                root,
                operationLeaf,
                projectionLeaf,
                mutationLeaf,
                operationActiveMaximumBytes: 512,
                projectionActiveMaximumBytes: 512);
            using var binding = journal.BindMutationLease(mutationLease);

            var operationAppend = await journal.AppendLineAsync(
                DesignConversionLocalPromotionJournalKind.Operation,
                operationLine,
                CancellationToken.None);
            var projectionAppend = await journal.AppendLineAsync(
                DesignConversionLocalPromotionJournalKind.Projection,
                projectionLine,
                CancellationToken.None);
            var read = await journal.ReadAsync(CancellationToken.None);

            Assert.True(operationAppend.IsSuccess, operationAppend.ErrorMessage);
            Assert.True(projectionAppend.IsSuccess, projectionAppend.ErrorMessage);
            Assert.True(read.IsSuccess, read.ErrorMessage);
            var operation = Assert.Single(read.Value!.OperationLines);
            var projection = Assert.Single(read.Value.ProjectionLines);
            Assert.Equal(operationLine, operation.Text);
            Assert.Equal(projectionLine, projection.Text);
            Assert.False(File.Exists(Path.Combine(
                root,
                DesignConversionLocalPromotionJournalSet.AppendPendingFileName)));
        }
        finally
        {
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }


    [Fact]
    public async Task LocalPromotionJournalSet_WindowsForeignAlternateStreamFailsClosedWithoutCanonicalByteMutation()
    {
        if (!OperatingSystem.IsWindows())
            return;
        var root = Path.Combine(
            Path.GetTempPath(),
            Guid.NewGuid().ToString("N"),
            "local-promotion-windows-foreign-ads");
        const string operationLeaf = "training-intake-local-promotion-operations.jsonl";
        const string projectionLeaf = "training-intake-local-promotions.jsonl";
        var mutationLeaf = projectionLeaf + ".mutation.lock";
        var activePath = Path.Combine(root, operationLeaf);
        var sourceBytes = System.Text.Encoding.UTF8.GetBytes(
            "{\"recordSha256\":\"sha256:bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb\"}\r\n");
        try
        {
            Directory.CreateDirectory(root);
            await File.WriteAllBytesAsync(activePath, sourceBytes);
            // The foreign stream is separate NTFS metadata. The journal must
            // reject the leaf without rewriting the operator-visible bytes.
            await File.WriteAllTextAsync(
                activePath + ":foreign-stream",
                "foreign stream must make the leaf untrusted",
                System.Text.Encoding.UTF8);
            await using var mutationLease =
                AcquireLocalPromotionJournalMutationLeaseForTesting(root, mutationLeaf);
            var journal = new DesignConversionLocalPromotionJournalSet(
                root,
                operationLeaf,
                projectionLeaf,
                mutationLeaf,
                operationActiveMaximumBytes: 512,
                projectionActiveMaximumBytes: 512);
            using var binding = journal.BindMutationLease(mutationLease);

            var read = await journal.ReadAsync(CancellationToken.None);

            Assert.False(read.IsSuccess);
            Assert.Equal(
                "DESIGN_CONVERSION_TRAINING_INTAKE_PROMOTE_LOCAL_OPERATION_STATE_INVALID",
                read.ErrorCode);
            Assert.Equal(sourceBytes, await File.ReadAllBytesAsync(activePath));
            Assert.False(File.Exists(Path.Combine(
                root,
                DesignConversionLocalPromotionJournalSet.AppendPendingFileName)));
        }
        finally
