    }


    [Theory]
    [InlineData(true)]
    [InlineData(false)]
    public async Task LocalPromotionJournalSet_AppendRejectsDestinationSubstitution(
        bool sourceInitiallyPresent)
    {
        if (!OperatingSystem.IsWindows())
            return;
        var root = Path.Combine(
            Path.GetTempPath(),
            Guid.NewGuid().ToString("N"),
            sourceInitiallyPresent
                ? "local-promotion-append-source-substitution"
                : "local-promotion-append-absent-substitution");
        const string operationLeaf = "training-intake-local-promotion-operations.jsonl";
        const string projectionLeaf = "training-intake-local-promotions.jsonl";
        var mutationLeaf = projectionLeaf + ".mutation.lock";
        var activePath = Path.Combine(root, projectionLeaf);
        var displacedPath = Path.Combine(root, "displaced-original.jsonl");
        var backupPath = activePath +
            DesignConversionHandleBoundDirectory.PublicationBackupSuffix;
        var sourceBytes = System.Text.Encoding.UTF8.GetBytes(
            "{\"source\":true}\r\n");
        var foreignBytes = System.Text.Encoding.UTF8.GetBytes(
            "{\"foreign\":true}\r\n");
        DesignConversionFileIdentity? foreignIdentity = null;
        try
        {
            Directory.CreateDirectory(root);
            if (sourceInitiallyPresent)
                await File.WriteAllBytesAsync(activePath, sourceBytes);
            await using var mutationLease =
                AcquireLocalPromotionJournalMutationLeaseForTesting(root, mutationLeaf);
            var journal = new DesignConversionLocalPromotionJournalSet(
                root,
                operationLeaf,
                projectionLeaf,
                mutationLeaf,
                operationActiveMaximumBytes: 512,
                projectionActiveMaximumBytes: 512,
                appendBeforeDestinationSnapshotObserver: () =>
                {
                    if (sourceInitiallyPresent)
                        File.Move(activePath, displacedPath);
                    File.WriteAllBytes(activePath, foreignBytes);
                    using var observedDirectory =
                        DesignConversionHandleBoundDirectory.AcquireExisting(
                            root,
                            beforeIo: null);
                    using var observedForeign = observedDirectory.TryOpenExisting(
                        projectionLeaf,
                        FileShare.Read | FileShare.Write | FileShare.Delete,
                        writeThrough: false);
                    Assert.NotNull(observedForeign);
                    foreignIdentity = observedDirectory.GetIdentity(
                        observedForeign!,
                        projectionLeaf);
                });
            using var binding = journal.BindMutationLease(mutationLease);

            var appended = await journal.AppendLineAsync(
                DesignConversionLocalPromotionJournalKind.Projection,
                "{\"next\":true}",
                CancellationToken.None);

            Assert.False(appended.IsSuccess);
            Assert.Equal(foreignBytes, await File.ReadAllBytesAsync(activePath));
            Assert.False(File.Exists(backupPath));
            Assert.True(File.Exists(activePath + ".append-publication.tmp"));
            Assert.True(File.Exists(Path.Combine(
                root,
                DesignConversionLocalPromotionJournalSet.AppendPendingFileName)));
            using var verificationDirectory =
                DesignConversionHandleBoundDirectory.AcquireExisting(
                    root,
                    beforeIo: null);
            using var heldForeign = verificationDirectory.TryOpenExisting(
                projectionLeaf,
                FileShare.Read | FileShare.Write | FileShare.Delete,
                writeThrough: false);
            Assert.NotNull(heldForeign);
            Assert.Equal(
                foreignIdentity,
                verificationDirectory.GetIdentity(heldForeign!, projectionLeaf));
            if (sourceInitiallyPresent)
            {
                Assert.Equal(
                    sourceBytes,
                    await File.ReadAllBytesAsync(displacedPath));
            }
        }
        finally
        {
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }


    [Fact]
    public async Task LocalPromotionJournalSet_AppendRejectsInPlaceDestinationRewrite()
    {
        if (!OperatingSystem.IsWindows())
            return;
        var root = Path.Combine(
            Path.GetTempPath(),
            Guid.NewGuid().ToString("N"),
            "local-promotion-append-in-place-rewrite");
        const string operationLeaf = "training-intake-local-promotion-operations.jsonl";
        const string projectionLeaf = "training-intake-local-promotions.jsonl";
        var mutationLeaf = projectionLeaf + ".mutation.lock";
        var activePath = Path.Combine(root, projectionLeaf);
        var backupPath = activePath +
            DesignConversionHandleBoundDirectory.PublicationBackupSuffix;
        var sourceBytes = System.Text.Encoding.UTF8.GetBytes(
            "{\"source\":true}\r\n");
        var rewrittenBytes = System.Text.Encoding.UTF8.GetBytes(
            "{\"source\":nope}\r\n");
        Assert.Equal(sourceBytes.Length, rewrittenBytes.Length);
        try
        {
            Directory.CreateDirectory(root);
            await File.WriteAllBytesAsync(activePath, sourceBytes);
            DesignConversionFileIdentity originalIdentity;
            using (var originalDirectory =
                   DesignConversionHandleBoundDirectory.AcquireExisting(
                       root,
                       beforeIo: null))
            using (var heldOriginal = originalDirectory.TryOpenExisting(
                       projectionLeaf,
                       FileShare.Read | FileShare.Write | FileShare.Delete,
                       writeThrough: false))
            {
                Assert.NotNull(heldOriginal);
                originalIdentity = originalDirectory.GetIdentity(
                    heldOriginal!,
                    projectionLeaf);
            }
            await using var mutationLease =
                AcquireLocalPromotionJournalMutationLeaseForTesting(root, mutationLeaf);
            var journal = new DesignConversionLocalPromotionJournalSet(
                root,
                operationLeaf,
                projectionLeaf,
                mutationLeaf,
                operationActiveMaximumBytes: 512,
                projectionActiveMaximumBytes: 512,
                appendBeforeDestinationSnapshotObserver: () =>
                {
                    using var rewrite = new FileStream(
                        activePath,
                        FileMode.Open,
                        FileAccess.Write,
                        FileShare.Read | FileShare.Write | FileShare.Delete);
                    rewrite.Position = 0L;
                    rewrite.Write(rewrittenBytes);
                    rewrite.SetLength(rewrittenBytes.Length);
                    rewrite.Flush(flushToDisk: true);
                });
            using var binding = journal.BindMutationLease(mutationLease);

            var appended = await journal.AppendLineAsync(
                DesignConversionLocalPromotionJournalKind.Projection,
                "{\"next\":true}",
                CancellationToken.None);

            Assert.False(appended.IsSuccess);
            Assert.Equal(rewrittenBytes, await File.ReadAllBytesAsync(activePath));
            Assert.False(File.Exists(backupPath));
            Assert.True(File.Exists(activePath + ".append-publication.tmp"));
            Assert.True(File.Exists(Path.Combine(
                root,
                DesignConversionLocalPromotionJournalSet.AppendPendingFileName)));
            using var verificationDirectory =
                DesignConversionHandleBoundDirectory.AcquireExisting(
                    root,
                    beforeIo: null);
            using var heldRewritten = verificationDirectory.TryOpenExisting(
                projectionLeaf,
                FileShare.Read | FileShare.Write | FileShare.Delete,
                writeThrough: false);
            Assert.NotNull(heldRewritten);
            Assert.Equal(
                originalIdentity,
                verificationDirectory.GetIdentity(
                    heldRewritten!,
                    projectionLeaf));
        }
        finally
        {
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }


