    [Fact]
    public async Task LocalPromotionJournalSet_InvalidUtf8AndReservedDirectoryCollisionsFailClosed()
    {
        if (!OperatingSystem.IsWindows())
            return;
        var root = Path.Combine(
            Path.GetTempPath(),
            Guid.NewGuid().ToString("N"),
            "local-promotion-journal-invalid-utf8-reserved-directory");
        const string operationLeaf = "training-intake-local-promotion-operations.jsonl";
        const string projectionLeaf = "training-intake-local-promotions.jsonl";
        var mutationLeaf = projectionLeaf + ".mutation.lock";
        try
        {
            Directory.CreateDirectory(root);
            await File.WriteAllBytesAsync(
                Path.Combine(root, projectionLeaf),
                [0xc3, 0x28]);
            await using var mutationLease =
                AcquireLocalPromotionJournalMutationLeaseForTesting(root, mutationLeaf);
            var journal = new DesignConversionLocalPromotionJournalSet(
                root,
                operationLeaf,
                projectionLeaf,
                mutationLeaf,
                operationActiveMaximumBytes: 256,
                projectionActiveMaximumBytes: 256);
            using var binding = journal.BindMutationLease(mutationLease);

            var invalidUtf8 = await journal.ReadAsync(CancellationToken.None);
            Assert.False(invalidUtf8.IsSuccess);
            Assert.Equal(
                JsonlDesignConversionLocalArtifactDb.InvalidUtf8ErrorCode,
                invalidUtf8.ErrorCode);

            await File.WriteAllBytesAsync(Path.Combine(root, projectionLeaf), []);
            Directory.CreateDirectory(Path.Combine(
                root,
                "training-intake-local-promotion-forged.g0000000000.jsonl"));
            var reservedCollision = await journal.ReadAsync(CancellationToken.None);
            Assert.False(reservedCollision.IsSuccess);
            Assert.Equal(
                "DESIGN_CONVERSION_TRAINING_INTAKE_PROMOTE_LOCAL_OPERATION_STATE_INVALID",
                reservedCollision.ErrorCode);

            Directory.Delete(Path.Combine(
                root,
                "training-intake-local-promotion-forged.g0000000000.jsonl"));
            var ordinaryTarget = Path.Combine(root, "ordinary-operation-target.jsonl");
            await File.WriteAllTextAsync(
                ordinaryTarget,
                "{\"recordSha256\":\"sha256:" + new string('c', 64) + "\"}\r\n",
                new System.Text.UTF8Encoding(false));
            try
            {
                File.CreateSymbolicLink(
                    Path.Combine(root, operationLeaf),
                    ordinaryTarget);
                var reparseCollision = await journal.ReadAsync(
                    CancellationToken.None);
                Assert.False(reparseCollision.IsSuccess);
                Assert.Equal(
                    "DESIGN_CONVERSION_TRAINING_INTAKE_PROMOTE_LOCAL_OPERATION_STATE_INVALID",
                    reparseCollision.ErrorCode);
            }
            catch (Exception exception) when (exception is
                IOException or UnauthorizedAccessException or
                PlatformNotSupportedException)
            {
                // Symbolic-link creation can be unavailable without Developer Mode.
            }
        }
        finally
        {
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }


    [Fact]
    public async Task LocalPromotionJournalSet_OperationPressureRotatesPairWithZeroByteProjection()
    {
        // Сценарий переносим: заполнение журнала операций должно перенести
        // пару файлов вместе, даже когда файл проекции пока пустой.
        var root = Path.Combine(
            Path.GetTempPath(),
            Guid.NewGuid().ToString("N"),
            "local-promotion-journal-zero-projection-rotation");
        const string operationLeaf = "training-intake-local-promotion-operations.jsonl";
        const string projectionLeaf = "training-intake-local-promotions.jsonl";
        var mutationLeaf = projectionLeaf + ".mutation.lock";
        var operationLine = "{\"recordSha256\":\"sha256:" + new string('a', 64) + "\"}";
        try
        {
            Directory.CreateDirectory(root);
            Directory.CreateDirectory(Path.Combine(root, "unrelated-artifact-directory"));
            await File.WriteAllTextAsync(
                Path.Combine(root, operationLeaf),
                operationLine + "\r\n",
                new System.Text.UTF8Encoding(false));
            await File.WriteAllBytesAsync(Path.Combine(root, projectionLeaf), []);
            await using var mutationLease =
                AcquireLocalPromotionJournalMutationLeaseForTesting(root, mutationLeaf);
            var journal = new DesignConversionLocalPromotionJournalSet(
                root,
                operationLeaf,
                projectionLeaf,
                mutationLeaf,
                operationActiveMaximumBytes: 256,
                projectionActiveMaximumBytes: 256);
            using var binding = journal.BindMutationLease(mutationLease);

            var rotated = await journal.EnsureCapacityAsync(
                operationReservationBytes: 200,
                projectionReservationBytes: 0,
                quotaErrorCode: "TEST_QUOTA",
                quotaSafeMessage: "test quota",
                CancellationToken.None);
            var read = await journal.ReadAsync(CancellationToken.None);

            Assert.True(rotated.IsSuccess, rotated.ErrorMessage);
            Assert.True(rotated.Value);
            Assert.True(read.IsSuccess, read.ErrorMessage);
            var operation = Assert.Single(read.Value!.OperationLines);
            Assert.Equal(operationLine, operation.Text);
            Assert.Equal(0, operation.Generation);
            Assert.False(operation.IsActive);
            Assert.Empty(read.Value.ProjectionLines);
            Assert.Equal(1, read.Value.ActiveGeneration);
            Assert.False(File.Exists(Path.Combine(root, operationLeaf)));
            Assert.False(File.Exists(Path.Combine(root, projectionLeaf)));
            Assert.True(File.Exists(Path.Combine(
                root,
                "training-intake-local-promotion-operations.g0000000000.jsonl")));
            Assert.Equal(
                0,
                new FileInfo(Path.Combine(
                    root,
                    "training-intake-local-promotions.g0000000000.jsonl")).Length);
        }
        finally
        {
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }


