    [Theory]
    [InlineData("pending-only", false)]
    [InlineData("source-and-target-temp", false)]
    [InlineData("backup-and-target-temp", true)]
    [InlineData("target-and-backup", true)]
    [InlineData("truncated-temp", false)]
    public async Task LocalPromotionJournalSet_RecoversExactAppendPublicationStates(
        string publicationState,
        bool targetWins)
    {
        if (!OperatingSystem.IsWindows())
            return;
        var root = Path.Combine(
            Path.GetTempPath(),
            Guid.NewGuid().ToString("N"),
            $"local-promotion-append-recovery-{publicationState}");
        const string operationLeaf = "training-intake-local-promotion-operations.jsonl";
        const string projectionLeaf = "training-intake-local-promotions.jsonl";
        var mutationLeaf = projectionLeaf + ".mutation.lock";
        var activePath = Path.Combine(root, projectionLeaf);
        var tempPath = activePath + ".append-publication.tmp";
        var backupPath = activePath +
            DesignConversionHandleBoundDirectory.PublicationBackupSuffix;
        var sourceBytes = System.Text.Encoding.UTF8.GetBytes(
            "{\"source\":true}\r\n");
        var appendedBytes = System.Text.Encoding.UTF8.GetBytes(
            "{\"next\":true}\r\n");
        var targetBytes = sourceBytes.Concat(appendedBytes).ToArray();
        try
        {
            Directory.CreateDirectory(root);
            await File.WriteAllBytesAsync(activePath, sourceBytes);
            await using var mutationLease =
                AcquireLocalPromotionJournalMutationLeaseForTesting(root, mutationLeaf);
            var crashing = new DesignConversionLocalPromotionJournalSet(
                root,
                operationLeaf,
                projectionLeaf,
                mutationLeaf,
                operationActiveMaximumBytes: 512,
                projectionActiveMaximumBytes: 512,
                appendObserver: _ =>
                    throw new InvalidOperationException("simulated append crash"));
            using (crashing.BindMutationLease(mutationLease))
            {
                await Assert.ThrowsAsync<InvalidOperationException>(() =>
                    crashing.AppendLineAsync(
                        DesignConversionLocalPromotionJournalKind.Projection,
                        "{\"next\":true}",
                        CancellationToken.None));
            }

            switch (publicationState)
            {
                case "source-and-target-temp":
                    await File.WriteAllBytesAsync(tempPath, targetBytes);
                    break;
                case "backup-and-target-temp":
                    File.Move(activePath, backupPath);
                    await File.WriteAllBytesAsync(tempPath, targetBytes);
                    break;
                case "target-and-backup":
                    File.Move(activePath, backupPath);
                    await File.WriteAllBytesAsync(activePath, targetBytes);
                    break;
                case "truncated-temp":
                    await File.WriteAllBytesAsync(
                        tempPath,
                        System.Text.Encoding.UTF8.GetBytes("hostile-mismatch"));
                    break;
            }

            var recoveredJournal = new DesignConversionLocalPromotionJournalSet(
                root,
                operationLeaf,
                projectionLeaf,
                mutationLeaf,
                operationActiveMaximumBytes: 512,
                projectionActiveMaximumBytes: 512);
            using var binding = recoveredJournal.BindMutationLease(mutationLease);
            var recovered = await recoveredJournal.RecoverAsync(
                CancellationToken.None);

            Assert.True(recovered.IsSuccess, recovered.ErrorMessage);
            Assert.True(recovered.Value);
            Assert.Equal(
                targetWins ? targetBytes : sourceBytes,
                await File.ReadAllBytesAsync(activePath));
            Assert.False(File.Exists(tempPath));
            Assert.False(File.Exists(backupPath));
            Assert.False(File.Exists(Path.Combine(
                root,
                DesignConversionLocalPromotionJournalSet.AppendPendingFileName)));
            if (string.Equals(
                    publicationState,
                    "backup-and-target-temp",
                    StringComparison.Ordinal))
            {
                await using var exclusiveReadback = new FileStream(
                    activePath,
                    FileMode.Open,
                    FileAccess.ReadWrite,
                    FileShare.None);
                Assert.Equal(targetBytes.Length, exclusiveReadback.Length);
            }
        }
        finally
        {
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }


    [Theory]
    [InlineData((int)DesignConversionLocalPromotionJournalRotationStage.PendingPublished)]
    [InlineData((int)DesignConversionLocalPromotionJournalRotationStage.OperationSegmentCopied)]
    [InlineData((int)DesignConversionLocalPromotionJournalRotationStage.ProjectionSegmentCopied)]
    [InlineData((int)DesignConversionLocalPromotionJournalRotationStage.SealPublished)]
    [InlineData((int)DesignConversionLocalPromotionJournalRotationStage.OperationActiveDeleted)]
    [InlineData((int)DesignConversionLocalPromotionJournalRotationStage.ProjectionActiveDeleted)]
    [InlineData((int)DesignConversionLocalPromotionJournalRotationStage.PendingDeleted)]
    public async Task LocalPromotionJournalSet_RecoversPreSealAndPostSealRotationCrashes(
        int crashStageValue)
    {
        if (!OperatingSystem.IsWindows())
            return;
        var crashStage =
            (DesignConversionLocalPromotionJournalRotationStage)crashStageValue;
        var root = Path.Combine(
            Path.GetTempPath(),
            Guid.NewGuid().ToString("N"),
            $"local-promotion-journal-crash-{crashStage}");
        const string operationLeaf = "training-intake-local-promotion-operations.jsonl";
        const string projectionLeaf = "training-intake-local-promotions.jsonl";
        var mutationLeaf = projectionLeaf + ".mutation.lock";
        var operationLine = "{\"recordSha256\":\"sha256:" + new string('b', 64) + "\"}";
        try
        {
            Directory.CreateDirectory(root);
            await File.WriteAllTextAsync(
                Path.Combine(root, operationLeaf),
                operationLine + "\r\n",
                new System.Text.UTF8Encoding(false));
            await File.WriteAllTextAsync(
                Path.Combine(root, projectionLeaf),
                "{\"legacy\":true}\r\n",
                new System.Text.UTF8Encoding(false));
            await using var mutationLease =
                AcquireLocalPromotionJournalMutationLeaseForTesting(
                    root,
                    mutationLeaf);
            var crashing = new DesignConversionLocalPromotionJournalSet(
                root,
                operationLeaf,
                projectionLeaf,
                mutationLeaf,
                operationActiveMaximumBytes: 256,
                projectionActiveMaximumBytes: 256,
                rotationObserver: stage =>
                {
                    if (stage == crashStage)
                        throw new InvalidOperationException("simulated hard crash");
                });
            using (crashing.BindMutationLease(mutationLease))
            {
                await Assert.ThrowsAsync<InvalidOperationException>(() =>
                    crashing.EnsureCapacityAsync(
                        operationReservationBytes: 200,
                        projectionReservationBytes: 0,
                        quotaErrorCode: "TEST_QUOTA",
                        quotaSafeMessage: "test quota",
                        CancellationToken.None));
            }

            var recoveredJournal = new DesignConversionLocalPromotionJournalSet(
                root,
                operationLeaf,
                projectionLeaf,
                mutationLeaf,
                operationActiveMaximumBytes: 256,
                projectionActiveMaximumBytes: 256);
            using var recoveryBinding = recoveredJournal.BindMutationLease(mutationLease);
            var recovered = await recoveredJournal.RecoverAsync(CancellationToken.None);
            var read = await recoveredJournal.ReadAsync(CancellationToken.None);

            Assert.True(recovered.IsSuccess, recovered.ErrorMessage);
            Assert.Equal(
                crashStage !=
                    DesignConversionLocalPromotionJournalRotationStage.PendingDeleted,
                recovered.Value);
            Assert.True(read.IsSuccess, read.ErrorMessage);
            Assert.False(File.Exists(Path.Combine(
                root,
                DesignConversionLocalPromotionJournalSet.PendingFileName)));
            Assert.Single(read.Value!.OperationLines);
            Assert.Single(read.Value.ProjectionLines);
            if (crashStage >=
                DesignConversionLocalPromotionJournalRotationStage.SealPublished)
            {
                Assert.Equal(1, read.Value.ActiveGeneration);
                Assert.False(read.Value.OperationLines[0].IsActive);
                Assert.False(read.Value.ProjectionLines[0].IsActive);
            }
            else
            {
                Assert.Equal(0, read.Value.ActiveGeneration);
                Assert.True(read.Value.OperationLines[0].IsActive);
                Assert.True(read.Value.ProjectionLines[0].IsActive);
                Assert.False(File.Exists(Path.Combine(
                    root,
                    "training-intake-local-promotion-operations.g0000000000.jsonl")));
                Assert.False(File.Exists(Path.Combine(
                    root,
                    "training-intake-local-promotions.g0000000000.jsonl")));
            }
        }
        finally
        {
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }


    [Fact]
    public async Task LocalPromotionJournalSet_SealChainCorruptionFailsClosed()
    {
        if (!OperatingSystem.IsWindows())
            return;
        var root = Path.Combine(
            Path.GetTempPath(),
            Guid.NewGuid().ToString("N"),
            "local-promotion-journal-seal-chain-corruption");
        const string operationLeaf = "training-intake-local-promotion-operations.jsonl";
        const string projectionLeaf = "training-intake-local-promotions.jsonl";
        var mutationLeaf = projectionLeaf + ".mutation.lock";
        var operationLine = "{\"recordSha256\":\"sha256:" + new string('e', 64) + "\"}";
        try
        {
            Directory.CreateDirectory(root);
            await File.WriteAllTextAsync(
                Path.Combine(root, operationLeaf),
                operationLine + "\r\n",
                new System.Text.UTF8Encoding(false));
            await using var mutationLease =
                AcquireLocalPromotionJournalMutationLeaseForTesting(
                    root,
                    mutationLeaf);
            var journal = new DesignConversionLocalPromotionJournalSet(
                root,
                operationLeaf,
                projectionLeaf,
                mutationLeaf,
                operationActiveMaximumBytes: 256,
                projectionActiveMaximumBytes: 256);
            using var binding = journal.BindMutationLease(mutationLease);
            var rotated = await journal.EnsureCapacityAsync(
                200,
                0,
                "TEST_QUOTA",
                "test quota",
                CancellationToken.None);
            Assert.True(rotated.IsSuccess, rotated.ErrorMessage);
            var sealPath = Path.Combine(
                root,
                "training-intake-local-promotion-journals.g0000000000.seal.json");
            var sealBytes = await File.ReadAllBytesAsync(sealPath);
            sealBytes[^2] ^= 1;
            await File.WriteAllBytesAsync(sealPath, sealBytes);

            var corrupted = await journal.ReadAsync(CancellationToken.None);
            Assert.False(corrupted.IsSuccess);
            Assert.Equal(
                "DESIGN_CONVERSION_TRAINING_INTAKE_PROMOTE_LOCAL_OPERATION_STATE_INVALID",
                corrupted.ErrorCode);

            await File.WriteAllBytesAsync(sealPath, sealBytes.Select(
                (value, index) => index == sealBytes.Length - 2
                    ? (byte)(value ^ 1)
                    : value).ToArray());
            var appended = await journal.AppendLineAsync(
                DesignConversionLocalPromotionJournalKind.Operation,
                operationLine,
                CancellationToken.None);
            Assert.True(appended.IsSuccess, appended.ErrorMessage);
            var secondRotation = await journal.EnsureCapacityAsync(
                200,
                0,
                "TEST_QUOTA",
                "test quota",
                CancellationToken.None);
            Assert.True(secondRotation.IsSuccess, secondRotation.ErrorMessage);
            var secondSealPath = Path.Combine(
                root,
                "training-intake-local-promotion-journals.g0000000001.seal.json");
            var firstSeal = await File.ReadAllBytesAsync(sealPath);
            var secondSeal = await File.ReadAllBytesAsync(secondSealPath);
            await File.WriteAllBytesAsync(sealPath, secondSeal);
            await File.WriteAllBytesAsync(secondSealPath, firstSeal);

            var reordered = await journal.ReadAsync(CancellationToken.None);
            Assert.False(reordered.IsSuccess);
            Assert.Equal(
                "DESIGN_CONVERSION_TRAINING_INTAKE_PROMOTE_LOCAL_OPERATION_STATE_INVALID",
                reordered.ErrorCode);
        }
        finally
        {
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }


