    [Fact]
    public async Task LocalPromotionJournalSet_SimultaneousPendingLeavesFailBeforeMutation()
    {
        if (!OperatingSystem.IsWindows())
            return;
        var root = Path.Combine(
            Path.GetTempPath(),
            Guid.NewGuid().ToString("N"),
            "local-promotion-simultaneous-pending");
        const string operationLeaf = "training-intake-local-promotion-operations.jsonl";
        const string projectionLeaf = "training-intake-local-promotions.jsonl";
        var mutationLeaf = projectionLeaf + ".mutation.lock";
        var activePath = Path.Combine(root, projectionLeaf);
        var sourceBytes = System.Text.Encoding.UTF8.GetBytes(
            "{\"source\":true}\r\n");
        try
        {
            Directory.CreateDirectory(root);
            await File.WriteAllBytesAsync(activePath, sourceBytes);
            await using var mutationLease =
                AcquireLocalPromotionJournalMutationLeaseForTesting(
                    root,
                    mutationLeaf);
            var crashing = new DesignConversionLocalPromotionJournalSet(
                root,
                operationLeaf,
                projectionLeaf,
                mutationLeaf,
                operationActiveMaximumBytes: 512,
                projectionActiveMaximumBytes: 512,
                appendObserver: _ =>
                    throw new InvalidOperationException("simulated append crash"));
            using (crashing.BindMutationLease(mutationLease))
            {
                await Assert.ThrowsAsync<InvalidOperationException>(() =>
                    crashing.AppendLineAsync(
                        DesignConversionLocalPromotionJournalKind.Projection,
                        "{\"next\":true}",
                        CancellationToken.None));
            }
            await File.WriteAllTextAsync(
                Path.Combine(
                    root,
                    DesignConversionLocalPromotionJournalSet.PendingFileName),
                "hostile-simultaneous-pending");
            var appendPendingBytes = await File.ReadAllBytesAsync(Path.Combine(
                root,
                DesignConversionLocalPromotionJournalSet.AppendPendingFileName));

            var recoveredJournal = new DesignConversionLocalPromotionJournalSet(
                root,
                operationLeaf,
                projectionLeaf,
                mutationLeaf,
                operationActiveMaximumBytes: 512,
                projectionActiveMaximumBytes: 512);
            using var binding = recoveredJournal.BindMutationLease(mutationLease);
            var recovered = await recoveredJournal.RecoverAsync(
                CancellationToken.None);

            Assert.False(recovered.IsSuccess);
            Assert.Equal(sourceBytes, await File.ReadAllBytesAsync(activePath));
            Assert.Equal(appendPendingBytes, await File.ReadAllBytesAsync(Path.Combine(
                root,
                DesignConversionLocalPromotionJournalSet.AppendPendingFileName)));
            Assert.True(File.Exists(Path.Combine(
                root,
                DesignConversionLocalPromotionJournalSet.PendingFileName)));
        }
        finally
        {
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }


    [Theory]
    [InlineData("rotation-pending")]
    [InlineData("append-pending")]
    [InlineData("operation-segment")]
    [InlineData("projection-segment")]
    [InlineData("seal")]
    public async Task LocalPromotionJournalSet_TruncatedTransactionStagesRecoverSafely(
        string stageKind)
    {
        if (!OperatingSystem.IsWindows())
            return;
        var root = Path.Combine(
            Path.GetTempPath(),
            Guid.NewGuid().ToString("N"),
            $"local-promotion-truncated-stage-{stageKind}");
        const string operationLeaf = "training-intake-local-promotion-operations.jsonl";
        const string projectionLeaf = "training-intake-local-promotions.jsonl";
        const string stageSuffix = ".transaction-stage.tmp";
        var mutationLeaf = projectionLeaf + ".mutation.lock";
        var operationLine = "{\"recordSha256\":\"sha256:" +
                            new string('9', 64) + "\"}";
        try
        {
            Directory.CreateDirectory(root);
            await using var mutationLease =
                AcquireLocalPromotionJournalMutationLeaseForTesting(
                    root,
                    mutationLeaf);
            var needsDurableRotationPending = stageKind is
                "operation-segment" or "projection-segment" or "seal";
            if (needsDurableRotationPending)
            {
                await File.WriteAllTextAsync(
                    Path.Combine(root, operationLeaf),
                    operationLine + "\r\n",
                    new System.Text.UTF8Encoding(false));
                await File.WriteAllTextAsync(
                    Path.Combine(root, projectionLeaf),
                    "{\"projection\":true}\r\n",
                    new System.Text.UTF8Encoding(false));
                var crashing = new DesignConversionLocalPromotionJournalSet(
                    root,
                    operationLeaf,
                    projectionLeaf,
                    mutationLeaf,
                    operationActiveMaximumBytes: 256,
                    projectionActiveMaximumBytes: 256,
                    rotationObserver: stage =>
                    {
                        if (stage ==
                            DesignConversionLocalPromotionJournalRotationStage
                                .PendingPublished)
                        {
                            throw new InvalidOperationException(
                                "simulated crash after durable pending");
                        }
                    });
                using (crashing.BindMutationLease(mutationLease))
                {
                    await Assert.ThrowsAsync<InvalidOperationException>(() =>
                        crashing.EnsureCapacityAsync(
                            200,
                            0,
                            "TEST_QUOTA",
                            "test quota",
                            CancellationToken.None));
                }
            }

            var destinationLeaf = stageKind switch
            {
                "rotation-pending" =>
                    DesignConversionLocalPromotionJournalSet.PendingFileName,
                "append-pending" =>
                    DesignConversionLocalPromotionJournalSet.AppendPendingFileName,
                "operation-segment" =>
                    "training-intake-local-promotion-operations.g0000000000.jsonl",
                "projection-segment" =>
                    "training-intake-local-promotions.g0000000000.jsonl",
                _ =>
                    "training-intake-local-promotion-journals.g0000000000.seal.json"
            };
            var stagePath = Path.Combine(root, destinationLeaf + stageSuffix);
            await File.WriteAllBytesAsync(stagePath, [0x7b, 0x22, 0x74]);

            var recovering = new DesignConversionLocalPromotionJournalSet(
                root,
                operationLeaf,
                projectionLeaf,
                mutationLeaf,
                operationActiveMaximumBytes: 256,
                projectionActiveMaximumBytes: 256);
            using var binding = recovering.BindMutationLease(mutationLease);
            var recovered = await recovering.RecoverAsync(CancellationToken.None);

            Assert.True(recovered.IsSuccess, recovered.ErrorMessage);
            Assert.Equal(needsDurableRotationPending, recovered.Value);
            Assert.False(File.Exists(stagePath));
            Assert.False(File.Exists(Path.Combine(
                root,
                DesignConversionLocalPromotionJournalSet.PendingFileName)));
            Assert.False(File.Exists(Path.Combine(
                root,
                DesignConversionLocalPromotionJournalSet.AppendPendingFileName)));
            if (needsDurableRotationPending)
            {
                Assert.True(File.Exists(Path.Combine(root, operationLeaf)));
                Assert.True(File.Exists(Path.Combine(root, projectionLeaf)));
            }
        }
        finally
        {
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }


    [Fact]
    public async Task LocalPromotionJournalSet_ZeroByteLegacyProjectionAppendsAndIgnoresUnrelatedDirectory()
    {
        if (!OperatingSystem.IsWindows())
            return;
        var root = Path.Combine(
            Path.GetTempPath(),
            Guid.NewGuid().ToString("N"),
            "local-promotion-journal-zero-projection-append");
        const string operationLeaf = "training-intake-local-promotion-operations.jsonl";
        const string projectionLeaf = "training-intake-local-promotions.jsonl";
        var mutationLeaf = projectionLeaf + ".mutation.lock";
        try
        {
            Directory.CreateDirectory(root);
            Directory.CreateDirectory(Path.Combine(root, "unrelated-artifact-directory"));
            await File.WriteAllBytesAsync(Path.Combine(root, projectionLeaf), []);
            await using var mutationLease =
                AcquireLocalPromotionJournalMutationLeaseForTesting(
                    root,
                    mutationLeaf);
            var cancellation = new CancellationTokenSource();
            var publicationStarted = 0;
            var journal = new DesignConversionLocalPromotionJournalSet(
                root,
                operationLeaf,
                projectionLeaf,
                mutationLeaf,
                operationActiveMaximumBytes: 512,
                projectionActiveMaximumBytes: 512,
                appendPendingPublicationStartedObserver: () =>
                {
                    Interlocked.Increment(ref publicationStarted);
                    cancellation.Cancel();
                });
            using var binding = journal.BindMutationLease(mutationLease);

            var appended = await journal.AppendLineAsync(
                DesignConversionLocalPromotionJournalKind.Projection,
                "{\"legacy\":true}",
                cancellation.Token);
            var read = await journal.ReadAsync(CancellationToken.None);

            Assert.True(appended.IsSuccess, appended.ErrorMessage);
            Assert.Equal(1, publicationStarted);
            Assert.True(cancellation.IsCancellationRequested);
            Assert.True(read.IsSuccess, read.ErrorMessage);
            var projection = Assert.Single(read.Value!.ProjectionLines);
            Assert.Equal("{\"legacy\":true}", projection.Text);
            Assert.Equal(0, projection.Generation);
            Assert.True(projection.IsActive);
            Assert.False(File.Exists(Path.Combine(
                root,
                DesignConversionLocalPromotionJournalSet.AppendPendingFileName)));
        }
        finally
        {
            if (Directory.Exists(root))
                Directory.Delete(root, recursive: true);
        }
    }


