    private static void AssertSeededModelStateUnchanged(
        SeededModelStateSnapshot snapshot)
    {
        var entries = snapshot.Model.GetCheckpointParameterEntries();
        Assert.Equal(snapshot.Parameters.Length, entries.Count);
        for (var index = 0; index < entries.Count; index++)
        {
            var expected = snapshot.Parameters[index];
            var parameter = entries[index].Parameter;
            var tensor = parameter.Value;
            var gradient = tensor.Grad;
            Assert.Equal(expected.Key, entries[index].Key);
            Assert.Same(expected.Parameter, parameter);
            Assert.Same(expected.Tensor, tensor);
            Assert.Same(expected.Storage, tensor.Storage);
            Assert.Same(expected.Data, tensor.Data);
            Assert.Equal(expected.Shape, tensor.Shape.Dimensions);
            Assert.Equal(
                expected.ValueBits,
                tensor.Data.Select(BitConverter.SingleToInt32Bits).ToArray());
            Assert.Equal(expected.RequiresGrad, tensor.RequiresGrad);
            Assert.Equal(expected.Gradient is null, gradient is null);
            Assert.Same(expected.Gradient, gradient);
            if (expected.Gradient is not null)
            {
                Assert.NotNull(gradient);
                Assert.Same(expected.GradientStorage, gradient!.Storage);
                Assert.Same(expected.GradientData, gradient.Data);
                Assert.Equal(expected.GradientShape, gradient.Shape.Dimensions);
                Assert.Equal(
                    expected.GradientValueBits,
                    gradient.Data.Select(BitConverter.SingleToInt32Bits).ToArray());
                Assert.Equal(
                    expected.GradientRequiresGrad,
                    gradient.RequiresGrad);
            }
        }
        var adapters = Enumerable.Range(0, snapshot.Model.Config.NumLayers)
            .SelectMany(blockIndex => new[] { "q_proj", "v_proj" }
                .Select(projection => Assert.IsType<LoRA.LoraLinear>(
                    snapshot.Model.GetAttachedProjectionAdapter(
                        blockIndex,
                        projection))))
            .ToArray();
        Assert.Equal(snapshot.Adapters.Length, adapters.Length);
        for (var index = 0; index < adapters.Length; index++)
        {
            Assert.Same(snapshot.Adapters[index], adapters[index]);
            Assert.Equal(snapshot.RandomSeeds[index], adapters[index].RandomSeeds);
        }
    }


    private static DesignConversionDpoTrainingRecord MarkLegacyTeacherRefsOnly(
        DesignConversionDpoTrainingRecord record)
    {
        var metadata = new Dictionary<string, string>(
            record.Provenance.Metadata,
            StringComparer.Ordinal)
        {
            ["runtime_teacher_authored_candidate"] = bool.TrueString,
            ["runtime_teacher_selected_preference"] = bool.TrueString
        };
        return record with
        {
            Provenance = record.Provenance with { Metadata = metadata },
            PayloadCustodySecret = null
        };
    }


    private static async Task RewriteTrainingIntakeForPreflightBlockAsync(
        string root,
        string intakeId)
    {
        var path = Path.Combine(root, "training-intake-requests.jsonl");
        var records = (await File.ReadAllLinesAsync(path))
            .Where(line => !string.IsNullOrWhiteSpace(line))
            .Select(line => JsonSerializer.Deserialize<
                DesignConversionTrainingIntakeRecord>(
                line,
                DesignConversionCheckpointJsonOptions.Standard)!)
            .ToArray();
        Assert.Contains(records, record => string.Equals(
            record.IntakeId,
            intakeId,
            StringComparison.Ordinal));
        records = records.Select(record => string.Equals(
                record.IntakeId,
                intakeId,
                StringComparison.Ordinal)
                ? record with { TrainingNotStarted = false }
                : record)
            .ToArray();
        await File.WriteAllLinesAsync(
            path,
            records.Select(record =>
                System.Text.Encoding.UTF8.GetString(SerializeCompact(record))));
    }


    private static SeededModelStateSnapshot SnapshotSeededModelState(LlmModel model)
    {
        var parameters = model.GetCheckpointParameterEntries()
            .Select(entry =>
            {
                var tensor = entry.Parameter.Value;
                var gradient = tensor.Grad;
                return new SeededModelParameterStateSnapshot(
                    entry.Key,
                    entry.Parameter,
                    tensor,
                    tensor.Storage,
                    tensor.Data,
                    tensor.Shape.Dimensions.ToArray(),
                    tensor.Data.Select(BitConverter.SingleToInt32Bits).ToArray(),
                    tensor.RequiresGrad,
                    gradient,
                    gradient?.Storage,
                    gradient?.Data,
                    gradient?.Shape.Dimensions.ToArray(),
                    gradient?.Data.Select(BitConverter.SingleToInt32Bits).ToArray(),
                    gradient?.RequiresGrad);
            })
            .ToArray();
        var adapters = Enumerable.Range(0, model.Config.NumLayers)
            .SelectMany(blockIndex => new[] { "q_proj", "v_proj" }
                .Select(projection => Assert.IsType<LoRA.LoraLinear>(
                    model.GetAttachedProjectionAdapter(blockIndex, projection))))
            .ToArray();
        return new SeededModelStateSnapshot(
            model,
            parameters,
            adapters,
            adapters.Select(adapter => adapter.RandomSeeds).ToArray());
    }


    private sealed class AmbiguousPostSendPromotionHttpHandler : HttpMessageHandler
    {
        public int SendCount { get; private set; }
        public bool RequestBodyRead { get; private set; }

        protected override async Task<HttpResponseMessage> SendAsync(
            HttpRequestMessage request,
            CancellationToken cancellationToken)
        {
            SendCount++;
            if (request.Content is not null)
            {
                await request.Content.ReadAsByteArrayAsync(cancellationToken);
                RequestBodyRead = true;
            }
            throw new HttpRequestException(
                "simulated connection loss after the remote request was sent");
        }
    }


    private sealed class CoherentPromotionHttpHandler : HttpMessageHandler
    {
        private readonly List<string> _idempotencyKeys = [];

        public int SendCount { get; private set; }
        public bool RequestBodyRead { get; private set; }
        public IReadOnlyList<string> IdempotencyKeys => _idempotencyKeys;
        public string? MetadataIdempotencyKey { get; private set; }

        protected override async Task<HttpResponseMessage> SendAsync(
            HttpRequestMessage request,
            CancellationToken cancellationToken)
        {
            SendCount++;
            RequestBodyRead = true;
            Assert.True(request.Headers.TryGetValues(
                DesignConversionModelServerPromotionHttpUploader
                    .IdempotencyHeaderName,
                out var idempotencyValues));
            var idempotencyKey = Assert.Single(idempotencyValues!);
            _idempotencyKeys.Add(idempotencyKey);
            var multipart = Assert.IsType<MultipartFormDataContent>(
                request.Content);
            var metadataPart = Assert.Single(multipart, part => string.Equals(
                part.Headers.ContentDisposition?.Name?.Trim('"'),
                "metadata",
                StringComparison.Ordinal));
            using var metadata = JsonDocument.Parse(
                await metadataPart.ReadAsByteArrayAsync(cancellationToken));
            var root = metadata.RootElement;
            MetadataIdempotencyKey = root.GetProperty(
                "idempotencyKey").GetString();
            var artifacts = root.GetProperty("artifacts")
                .EnumerateArray()
                .Select(artifact => new
                {
                    role = artifact.GetProperty("role").GetString(),
                    length = artifact.GetProperty("length").GetInt64(),
                    sha256 = artifact.GetProperty("sha256").GetString()
                })
                .ToArray();
            var responseBody = JsonSerializer.Serialize(
                new
                {
                    uploadId = "production-http-restart-upload",
                    remoteRef =
                        "https://promotion.example/receipts/production-http-restart-upload",
                    uploadedAtUtc = DateTimeOffset.Parse(
                        "2026-08-10T10:00:00Z",
                        System.Globalization.CultureInfo.InvariantCulture),
                    tenantId = root.GetProperty("tenantId").GetString(),
                    manifestId = root.GetProperty("manifestId").GetString(),
                    machineId = root.GetProperty("machineId").GetString(),
                    domainTag = root.GetProperty("domainTag").GetString(),
                    version = root.GetProperty("version").GetString(),
                    idempotencyKey = MetadataIdempotencyKey,
                    artifacts
                },
                new JsonSerializerOptions(JsonSerializerDefaults.Web));
            return new HttpResponseMessage(System.Net.HttpStatusCode.Created)
            {
                Content = new StringContent(
                    responseBody,
                    System.Text.Encoding.UTF8,
                    "application/json")
            };
        }
    }


    private sealed class DeliberatelyUnboundedPromotionUploader
        : IDesignConversionPromotionUploader
    {
        private int _count;

        public int Count => Interlocked.CompareExchange(ref _count, 0, 0);

        public Task<OperationResult<DesignConversionPromotionUploadReceipt>> UploadAsync(
            DesignConversionTrainingManifest manifest,
            DesignConversionPromotionGateReport gateReport,
            CancellationToken ct = default)
        {
            Interlocked.Increment(ref _count);
            throw new InvalidOperationException(
                "The unbounded test uploader must be rejected before invocation.");
        }
    }


    private sealed class LyingBoundedPromotionUploader
        : IDesignConversionBoundedPromotionUploader,
          IDesignConversionPromotionUploaderPreflight
    {
        public int Count { get; private set; }
        public int MaximumSerializedReceiptUtf8Bytes => 128;
        public OperationResult<string> PreflightConfigurationFingerprintSha256()
            => OperationResult<string>.Ok("sha256:" + new string('b', 64));

        public Task<OperationResult<DesignConversionPromotionUploadReceipt>>
            UploadAsync(
                DesignConversionTrainingManifest manifest,
                DesignConversionPromotionGateReport gateReport,
                CancellationToken ct = default)
        {
            Count++;
            return Task.FromResult(
                OperationResult<DesignConversionPromotionUploadReceipt>.Ok(
                    new DesignConversionPromotionUploadReceipt(
                        $"{manifest.ManifestId}:lying-bound",
                        DesignConversionPromotedLocalModelLoader
                            .LocalOnlyPromotionRefPrefix +
                        Uri.EscapeDataString(manifest.ManifestId),
                        DateTimeOffset.UtcNow,
                        ["LYING_BOUNDED_RECEIPT_EVIDENCE"])
                    {
                        PublicationKind =
                            DesignConversionPromotionPublicationKind
                                .LocalOnlyNoRemoteAttempt,
                        PublicationStatus =
                            DesignConversionPromotionPublicationStatus
                                .NotUploaded
                    }));
        }
    }


    private sealed class LyingRemoteReceiptPromotionUploader
        : IDesignConversionBoundedPromotionUploader,
          IDesignConversionPromotionUploaderPreflight
    {
        public int Count { get; private set; }
        public int MaximumSerializedReceiptUtf8Bytes => 64 * 1024;
        public DesignConversionLocalReceiptOnlyPromotionUploadAuthority Authority
        {
            get
            {
                var issued =
                    DesignConversionLocalReceiptOnlyPromotionUploadAuthority
                        .Issue(
                            this,
                            "DESIGN_CONVERSION_TEST_REMOTE_RECEIPT_REJECTED_BY_LOCAL_AUTHORITY");
                if (!issued.IsSuccess)
                    throw new InvalidOperationException(issued.ErrorMessage);
                return issued.Value!;
            }
        }

        public OperationResult<string> PreflightConfigurationFingerprintSha256()
            => OperationResult<string>.Ok("sha256:" + new string('c', 64));

        public Task<OperationResult<DesignConversionPromotionUploadReceipt>>
            UploadAsync(
                DesignConversionTrainingManifest manifest,
                DesignConversionPromotionGateReport gateReport,
                CancellationToken ct = default)
        {
            Count++;
            return Task.FromResult(
                OperationResult<DesignConversionPromotionUploadReceipt>.Ok(
                    new DesignConversionPromotionUploadReceipt(
                        $"{manifest.ManifestId}:remote-while-local-only",
                        "https://model.example.test/design-conversion/local-authority-rejected-remote-receipt",
                        DateTimeOffset.UtcNow,
                        ["REMOTE_RECEIPT_MUST_NOT_PASS_LOCAL_RECEIPT_AUTHORITY"])
                    {
                        PublicationKind =
                            DesignConversionPromotionPublicationKind
                                .VerifiedModelServerUpload,
                        UploadAttempted = true,
                        UploadSucceeded = true,
                        VerificationSucceeded = true,
                        PublicationStatus =
                            DesignConversionPromotionPublicationStatus
                                .UploadedVerified,
                        ProvenanceRef =
                            "local-authority-rejected-remote-receipt"
                    }));
        }
    }


