    private sealed class SharedStateTestRemoteUnitLocator(
        SharedStateTestRemoteUnitRegistry registry) : IRemoteUnitLocator
    {
        public OperationResult<string> PreflightStableConfigurationIdentitySha256()
            => OperationResult<string>.Ok(
                registry.StableConfigurationIdentitySha256);

        public Task<OperationResult<RemoteUnitManifest>> LocateAsync(
            string unitId,
            CancellationToken ct = default)
        {
            if (ct.IsCancellationRequested)
            {
                return Task.FromResult(
                    OperationResult<RemoteUnitManifest>.Fail(
                        "Unit lookup was cancelled.",
                        "UNIT_LOOKUP_CANCELLED"));
            }

            return registry.Manifests.TryGetValue(unitId, out var manifest)
                ? Task.FromResult(OperationResult<RemoteUnitManifest>.Ok(manifest))
                : Task.FromResult(OperationResult<RemoteUnitManifest>.Fail(
                    $"Remote unit not registered: {unitId}",
                    "REMOTE_UNIT_NOT_FOUND"));
        }

        public Task<OperationResult<bool>> RegisterAsync(
            RemoteUnitManifest manifest,
            CancellationToken ct = default)
        {
            if (ct.IsCancellationRequested)
            {
                return Task.FromResult(OperationResult<bool>.Fail(
                    "Unit registration was cancelled.",
                    "UNIT_REGISTER_CANCELLED"));
            }

            registry.Manifests[manifest.UnitId] = manifest;
            return Task.FromResult(OperationResult<bool>.Ok(true));
        }
    }


    private sealed class SharedStateTestRemoteUnitRegistry(
        string stableConfigurationIdentitySha256)
    {
        public string StableConfigurationIdentitySha256 { get; } =
            stableConfigurationIdentitySha256;

        public Dictionary<string, RemoteUnitManifest> Manifests { get; } =
            new(StringComparer.Ordinal);
    }

    private sealed class CountingPostEvaluationStateStore(
        IDesignConversionPostEvaluationStateStore inner)
        : IDesignConversionPostEvaluationStateStore
    {
        private int _listCallCount;

        public int ListCallCount => Volatile.Read(ref _listCallCount);

        public void ResetListCallCount()
            => Interlocked.Exchange(ref _listCallCount, 0);

        public Task<OperationResult<DesignConversionPostEvaluationState>>
            WriteAsync(
                DesignConversionPostEvaluationState state,
                CancellationToken cancellationToken = default)
            => inner.WriteAsync(state, cancellationToken);

        public Task<OperationResult<DesignConversionPostEvaluationState?>>
            ReadAsync(
                string stateRef,
                CancellationToken cancellationToken = default)
            => inner.ReadAsync(stateRef, cancellationToken);

        public Task<OperationResult<IReadOnlyList<
            DesignConversionPostEvaluationState>>> ListAsync(
                CancellationToken cancellationToken = default)
        {
            Interlocked.Increment(ref _listCallCount);
            return inner.ListAsync(cancellationToken);
        }

        public Task<OperationResult<DesignConversionPostEvaluationState>>
            DenyTrainingEligibilityAsync(
                string stateRef,
                string expectedArtifactRecordId,
                string errorCode,
                CancellationToken cancellationToken = default)
            => inner.DenyTrainingEligibilityAsync(
                stateRef,
                expectedArtifactRecordId,
                errorCode,
                cancellationToken);

        public Task<OperationResult<DesignConversionPostEvaluationState>>
            ReleaseTrainingEligibilityDenialAsync(
                string stateRef,
                string expectedArtifactRecordId,
                CancellationToken cancellationToken = default)
            => inner.ReleaseTrainingEligibilityDenialAsync(
                stateRef,
                expectedArtifactRecordId,
                cancellationToken);
    }

    private static IReadOnlyDictionary<string, string> BuildLocalPromotionAdmission(
        string scope)
        => new Dictionary<string, string>(StringComparer.Ordinal)
        {
            ["training_intake_tenant_id_ref"] = $"tenant:{scope}",
            ["training_intake_idempotency_key_ref"] = $"idempotency:{scope}"
        };

    private static Task<OperationResult<DesignConversionTrainingIntakeLocalPromotionResult>>
        RunLocalPromotionWithAdmissionAsync(
            JsonlDesignConversionLocalArtifactDb db,
            PromotionReadyIntakeFixture fixture,
            string output,
            IReadOnlyDictionary<string, string> admission,
            CancellationToken ct = default)
        => DesignConversionTrainingIntakeRouteAdmissionContext.RunAsync(
            admission,
            () => db.RunTrainingIntakeAndPromoteLocalAsync(
                fixture.Intake.IntakeId,
                output,
                fixture.Options,
                ct));

    private static async Task<IReadOnlyList<int>>
        ReadLocalPromotionOperationPhaseNumbersAsync(string path)
    {
        var lines = (await File.ReadAllLinesAsync(path))
            .Where(line => !string.IsNullOrWhiteSpace(line))
            .ToArray();
        return lines.Select(line =>
        {
            using var document = JsonDocument.Parse(line);
            return document.RootElement.GetProperty("phase").GetInt32();
        }).ToArray();
    }

    private static async Task<JsonlDesignConversionLocalArtifactDb
        .LocalPromotionOperationJournalRecord[]>
        ReadLocalPromotionOperationRecordsAsync(string path)
        => (await File.ReadAllLinesAsync(path))
            .Where(line => !string.IsNullOrWhiteSpace(line))
            .Select(line => JsonSerializer.Deserialize<
                JsonlDesignConversionLocalArtifactDb
                    .LocalPromotionOperationJournalRecord>(
                line,
                DesignConversionCheckpointJsonOptions.Standard)!)
            .ToArray();

    private static JsonlDesignConversionLocalArtifactDb
        .LocalPromotionOperationJournalRecord[]
        RelinkLocalPromotionOperationRecords(
            IReadOnlyList<JsonlDesignConversionLocalArtifactDb
                .LocalPromotionOperationJournalRecord> records)
    {
        var relinked = records.ToArray();
        var previous = string.Empty;
        for (var index = 0; index < relinked.Length; index++)
        {
            relinked[index] = relinked[index] with
            {
                PreviousRecordSha256 = previous,
                RecordSha256 = string.Empty
            };
            relinked[index] = relinked[index] with
            {
                RecordSha256 = JsonlDesignConversionLocalArtifactDb
                    .BuildLocalPromotionOperationRecordSha256(relinked[index])
            };
            previous = relinked[index].RecordSha256;
        }
        return relinked;
    }

    private static async Task<IReadOnlyList<
        DesignConversionTrainingIntakeLocalPromotionResult>>
        ReadLocalPromotionProjectionRecordsAsync(string path)
